def homm3_town_name_tokens(identity: dict[str, Any]) -> list[str]:
    faction_sid = identity["factionSid"]
    names = HOMM3_TOWN_NAMES_BY_FACTION.get(faction_sid)
    count = len(names) if names else 20
    return [f"{identity['citySid']}_name_{index}" for index in range(1, count + 1)]


def homm3_town_name_lang_rows(identity: dict[str, Any], display_name: str) -> list[dict[str, str]]:
    names = HOMM3_TOWN_NAMES_BY_FACTION.get(identity["factionSid"])
    if not names:
        names = tuple(f"{display_name} {index}" for index in range(1, 21))
    return [
        {"sid": f"{identity['citySid']}_name_{index}", "text": name}
        for index, name in enumerate(names, start=1)
    ]


def load_custom_faction_manifest(faction_sid: str) -> dict[str, Any]:
    path = DEFAULT_MANIFEST_DIR / f"{faction_sid}.json"
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def load_custom_faction_manifests() -> tuple[dict[str, Any], ...]:
    manifests: list[dict[str, Any]] = []
    for path in sorted(DEFAULT_MANIFEST_DIR.glob("homm3_*.json")):
        with path.open("r", encoding="utf-8") as f:
            data = json.load(f)
        identity = data.get("identity") if isinstance(data, dict) else None
        if not isinstance(identity, dict) or not isinstance(identity.get("factionSid"), str):
            # Skip non-faction catalogs such as tools/homm3_import/faction_concepts/homm3_neutral.json.
            continue
        manifests.append(data)
    return tuple(manifests)


def strip_json_comments(text: str) -> str:
    result: list[str] = []
    in_string = False
    escape = False
    index = 0
    while index < len(text):
        char = text[index]
        nxt = text[index + 1] if index + 1 < len(text) else ""
        if in_string:
            result.append(char)
            if escape:
                escape = False
            elif char == "\\":
                escape = True
            elif char == '"':
                in_string = False
            index += 1
            continue
        if char == '"':
            in_string = True
            result.append(char)
            index += 1
            continue
        if char == "/" and nxt == "/":
            while index < len(text) and text[index] not in "\r\n":
                index += 1
            continue
        result.append(char)
        index += 1
    return "".join(result)


def load_jsonc(path: Path) -> Any:
    text = strip_json_comments(path.read_text(encoding="utf-8-sig"))
    text = re.sub(r",\s*([}\]])", r"\1", text)
    return json.loads(text)


def unit_lines_from_manifest(faction_sid: str) -> tuple[dict[str, Any], ...]:
    manifest = load_custom_faction_manifest(faction_sid)
    identity = manifest.get("identity") or {}
    default_donor_faction = identity.get("donorFactionSid")
    lines: list[dict[str, Any]] = []
    for line in manifest_all_unit_lines(manifest):
        base_sid = line["baseSid"]
        lines.append(
            {
                "base": base_sid,
                "donor_faction": line.get("donorFactionSid", default_donor_faction),
                "donor": line["donorBaseSid"],
                "donor_variant_factions": dict(line.get("donorVariantFactionSids") or {}),
                "donor_variant_sids": dict(line.get("donorVariantSids") or {}),
                "names": tuple(line["names"]),
                "tier": line["tier"],
            }
        )
    return tuple(lines)


def manifest_direct_city_sid(manifest: dict[str, Any]) -> str:
    overlay = manifest.get("coreOverlay") or {}
    identity = manifest.get("identity") or {}
    return overlay.get("directCityMapObject") or identity["citySid"]


