HOMM3_BOTTOM_CENTER_GATE_CITY_INDEX = 7
HOMM3_CITY_INTERACTION_LAYOUT_CORNER_LEFT = 1


def is_homm3_town_city_object_sid(sid: Any) -> bool:
    """True for stock/landon town map objects such as homm3_castle_city."""
    if not isinstance(sid, str):
        return False
    text = sid.strip()
    return bool(re.fullmatch(r"homm3_(?:landon_)?[a-z0-9]+_city", text))


def apply_homm3_bottom_center_gate_to_city_row(row: dict[str, Any]) -> dict[str, Any]:
    """Force a 3x3 town ObjectConfig onto south-center GATE (index 7)."""
    if not isinstance(row, dict):
        raise TypeError("city ObjectConfig row must be a dict")
    size_x = int(row.get("sizeX") or 0)
    size_z = int(row.get("sizeZ") or 0)
    if size_x != 3 or size_z != 3:
        raise ValueError(
            f"homm3 town ObjectConfig {row.get('id')!r} must remain 3x3 for bottom-center GATE; "
            f"got sizeX={size_x} sizeZ={size_z}"
        )
    row["nodes"] = list(HOMM3_BOTTOM_CENTER_GATE_CITY_NODES)
    row["canBeMirrored"] = False
    row["generatorConfig"] = {
        "buildingSizeX": 1,
        "buildingSizeZ": 1,
        "buildingLeftBottomX": 1,
        "buildingLeftBottomZ": size_z - 1,
        "buildingInteractionLayout": HOMM3_CITY_INTERACTION_LAYOUT_CORNER_LEFT,
    }
    return row


def normalize_homm3_town_city_bottom_center_gates(
    release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]
) -> None:
    """Rewrite every homm3_*_city ObjectConfig onto the bottom-center GATE contract."""
    map_name = "DB/map/objects/4_interactables.json"
    try:
        map_doc = json.loads(output[map_name].decode("utf-8-sig")) if map_name in output else read_json(release_zip, map_name)
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append("warn missing interactables for homm3 town GATE normalize: " + str(ex))
        return

    rows = map_doc.get("array")
    if not isinstance(rows, list):
        notes.append("warn interactables array missing for homm3 town GATE normalize")
        return

    changed = 0
    for row in rows:
        if not isinstance(row, dict) or not is_homm3_town_city_object_sid(row.get("id")):
            continue
        before = json.dumps(
            {
                "nodes": row.get("nodes"),
                "canBeMirrored": row.get("canBeMirrored"),
                "generatorConfig": row.get("generatorConfig"),
            },
            sort_keys=True,
            ensure_ascii=False,
        )
        apply_homm3_bottom_center_gate_to_city_row(row)
        after = json.dumps(
            {
                "nodes": row.get("nodes"),
                "canBeMirrored": row.get("canBeMirrored"),
                "generatorConfig": row.get("generatorConfig"),
            },
            sort_keys=True,
            ensure_ascii=False,
        )
        if before != after:
            changed += 1

    if changed:
        output[map_name] = write_json(map_doc)
        notes.append(
            f"normalize {changed} homm3 town ObjectConfig(s) to bottom-center GATE "
            f"(nodes index {HOMM3_BOTTOM_CENTER_GATE_CITY_INDEX})"
        )


def manifest_direct_dwelling_sid(manifest: dict[str, Any], tier: int) -> str:
    return (manifest.get("coreOverlay") or {})["directDwellingPrefix"] + str(tier)


def manifest_primary_donor_dwelling_sid(manifest: dict[str, Any], tier: int) -> str:
    prefixes = (manifest.get("runtime") or {})["dwellingDonorPrefixes"]
    return prefixes[0] + str(tier)


def manifest_recruitment_bindings(manifest: dict[str, Any]) -> tuple[dict[str, Any], ...]:
    bindings: list[dict[str, Any]] = []
    for tier, line in enumerate(manifest_primary_unit_lines(manifest), start=1):
        bindings.append(
            {
                "line": line,
                "tier": tier,
                "lineId": None,
                "recruitmentSlotSid": f"Tier_{tier}",
                "cityBuildingSid": f"Build_Tier_{tier}",
                "directDwellingSid": manifest_direct_dwelling_sid(manifest, tier),
                "donorDwellingSid": None,
                "dwellingBillboardImage": (manifest.get("runtime") or {})["dwellingBillboardImages"][tier - 1],
                "isAdditional": False,
            }
        )
    for line in manifest_additional_recruitment_lines(manifest):
        bindings.append(
            {
                "line": line,
                "tier": line["tier"],
                "lineId": line["lineId"],
                "recruitmentSlotSid": line["recruitmentSlotSid"],
                "cityBuildingSid": line["cityBuildingSid"],
                "directDwellingSid": line["directDwellingSid"],
                "donorDwellingSid": line["donorDwellingSid"],
                "dwellingBillboardImage": line["dwellingBillboardImage"],
                "isAdditional": True,
            }
        )
    return tuple(bindings)


def cloned_map_object_prefs(row: dict[str, Any]) -> list[Any] | None:
    prefs = row.get("prefs")
    if isinstance(prefs, list) and prefs:
        return json.loads(json.dumps(prefs, ensure_ascii=False))
    return None


def manifest_core_member(manifest: dict[str, Any], key: str) -> str:
    return (manifest.get("coreOverlay") or {})[key]


def manifest_hero_sid(manifest: dict[str, Any], index: int) -> str:
    return (manifest.get("heroes") or {})["heroPrefix"] + str(index)


def manifest_hero_icon_sid(manifest: dict[str, Any], index: int) -> str:
    return (manifest.get("heroes") or {})["iconPrefix"] + str(index)


def manifest_hero_names(manifest: dict[str, Any]) -> dict[int, str]:
    names = (manifest.get("heroes") or {}).get("names") or []
    return {index: name for index, name in enumerate(names, start=1)}


