HOMM3_HERO_BIO_ALIASES = {
    "jaegar": "jaeger",
}


def hero_bio_key(name: str) -> str:
    key = re.sub(r"[^a-z0-9]+", "", name.lower())
    return HOMM3_HERO_BIO_ALIASES.get(key, key)


def clean_homm3_hero_bio(text: str) -> str:
    text = text.strip()
    if len(text) >= 2 and text[0] == '"' and text[-1] == '"':
        text = text[1:-1]
    return text.replace('""', '"').replace("\r\n", "\n").strip()


def read_homm3_hero_bio_lines(path: Path) -> list[str]:
    for encoding in ("utf-8-sig", "cp1252"):
        try:
            return path.read_text(encoding=encoding).splitlines()
        except UnicodeDecodeError:
            continue
    return path.read_text(encoding="utf-8-sig", errors="replace").splitlines()


def iter_hota_hero_texts(doc: Any) -> list[dict[str, Any]]:
    if not isinstance(doc, dict):
        return []
    direct = doc.get("texts")
    if isinstance(direct, dict):
        return [direct]
    result: list[dict[str, Any]] = []
    for value in doc.values():
        if isinstance(value, dict) and isinstance(value.get("texts"), dict):
            result.append(value["texts"])
    return result


_HOMM3_SOURCE_HERO_BIOS: dict[str, str] | None = None


def load_homm3_source_hero_bios() -> dict[str, str]:
    global _HOMM3_SOURCE_HERO_BIOS
    if _HOMM3_SOURCE_HERO_BIOS is not None:
        return _HOMM3_SOURCE_HERO_BIOS
    bios: dict[str, str] = {}
    bio_path = REPO_ROOT / "tools" / "extracted" / "HeroBios.txt"
    if bio_path.exists():
        lines = read_homm3_hero_bio_lines(bio_path)
        for name, line in zip(HOMM3_HERO_BIO_ORDER, lines):
            bio = clean_homm3_hero_bio(line)
            if bio and bio != "Just a portrait":
                bios.setdefault(hero_bio_key(name), bio)

    hota_roots = [
        REPO_ROOT / "vcmi" / "Mods" / "hota" / "mods" / "cove" / "Content" / "config" / "hota" / "cove" / "heroes",
        REPO_ROOT / "vcmi" / "Mods" / "hota" / "mods" / "heroes" / "Content" / "config",
    ]
    for root in hota_roots:
        if not root.exists():
            continue
        for path in sorted(root.rglob("*.json")):
            try:
                doc = json.loads(path.read_text(encoding="utf-8-sig"))
            except (json.JSONDecodeError, UnicodeDecodeError):
                continue
            for texts in iter_hota_hero_texts(doc):
                english = texts.get("english") if isinstance(texts.get("english"), dict) else texts
                name = english.get("name") if isinstance(english, dict) else None
                biography = english.get("biography") if isinstance(english, dict) else None
                if isinstance(name, str) and isinstance(biography, str) and biography.strip():
                    bios[hero_bio_key(name)] = clean_homm3_hero_bio(biography)

    _HOMM3_SOURCE_HERO_BIOS = bios
    return bios


def custom_hero_override_entry(faction_sid: str, hero_sid: str) -> dict[str, Any] | None:
    override = load_hero_override(faction_sid)
    hero_overrides = override.get("heroOverrides") if isinstance(override, dict) else None
    if not isinstance(hero_overrides, dict):
        return None
    entry = hero_overrides.get(hero_sid)
    return entry if isinstance(entry, dict) else None


def custom_hero_display_name(manifest: dict[str, Any], index: int) -> str | None:
    faction_sid = manifest["identity"]["factionSid"]
    hero_sid = manifest_hero_sid(manifest, index)
    names = manifest_hero_names(manifest)
    if isinstance(names.get(index), str) and names[index].strip():
        return names[index].strip()
    entry = custom_hero_override_entry(faction_sid, hero_sid)
    name = entry.get("nameText") if isinstance(entry, dict) else None
    return name.strip() if isinstance(name, str) and name.strip() else None


def manifest_hero_class_name(manifest: dict[str, Any], class_type: str) -> str:
    heroes = manifest.get("heroes") or {}
    if class_type == "magic":
        return heroes.get("magicClassName") or "Magic"
    return heroes.get("mightClassName") or "Might"


def manifest_hero_specialization_title(manifest: dict[str, Any], index: int) -> str:
    heroes = manifest.get("heroes") or {}
    names = heroes.get("specializationTitles")
    if isinstance(names, list) and 1 <= index <= len(names) and names[index - 1]:
        return str(names[index - 1])
    return str(heroes.get("specializationTitle") or "Faction Specialist")


def manifest_hero_specialization_description(manifest: dict[str, Any], class_type: str) -> str:
    heroes = manifest.get("heroes") or {}
    if class_type == "magic":
        return str(heroes.get("magicSpecializationDescription") or "Improves this magic hero while leading the custom faction.")
    return str(heroes.get("mightSpecializationDescription") or "Improves this might hero while leading the custom faction.")


def manifest_faction_skill_sid(manifest: dict[str, Any]) -> str:
    return (manifest.get("skillsAndLaws") or {})["factionSkillSid"]


def manifest_law_prefix(manifest: dict[str, Any]) -> str:
    return (manifest.get("skillsAndLaws") or {})["lawPrefix"]


def manifest_unit_variants(manifest: dict[str, Any]) -> tuple[str, ...]:
    return tuple(manifest.get("unitVariants") or ["", "_upg", "_upg_alt"])


def manifest_primary_unit_lines(manifest: dict[str, Any]) -> tuple[dict[str, Any], ...]:
    lines = manifest.get("unitLines")
    faction_sid = (manifest.get("identity") or {}).get("factionSid", "<unknown>")
    if not isinstance(lines, list):
        raise RuntimeError(f"{faction_sid}: unitLines must be a list")
    if any(not isinstance(line, dict) for line in lines):
        raise RuntimeError(f"{faction_sid}: unitLines entries must be objects")
    return tuple(lines)


def manifest_additional_recruitment_lines(manifest: dict[str, Any]) -> tuple[dict[str, Any], ...]:
    lines = manifest.get("additionalRecruitmentLines")
    if lines is None:
        return ()
    faction_sid = (manifest.get("identity") or {}).get("factionSid", "<unknown>")
    if not isinstance(lines, list):
        raise RuntimeError(f"{faction_sid}: additionalRecruitmentLines must be a list")
    if any(not isinstance(line, dict) for line in lines):
        raise RuntimeError(f"{faction_sid}: additionalRecruitmentLines entries must be objects")
    return tuple(lines)


def manifest_all_unit_lines(manifest: dict[str, Any]) -> tuple[dict[str, Any], ...]:
    return manifest_primary_unit_lines(manifest) + manifest_additional_recruitment_lines(manifest)


def manifest_unit_sid_for_variant(line: dict[str, Any], suffix: str) -> str:
    variant_sids = line.get("variantSids")
    if isinstance(variant_sids, dict):
        sid = variant_sids.get(suffix)
        if isinstance(sid, str) and sid:
            return sid
    return line["baseSid"] + suffix


def manifest_unit_sids(manifest: dict[str, Any]) -> tuple[str, ...]:
    variants = manifest_unit_variants(manifest)
    return tuple(manifest_unit_sid_for_variant(line, suffix) for line in manifest_all_unit_lines(manifest) for suffix in variants)


def humanize_custom_sid(sid: str) -> str:
    value = sid
    for prefix in ("h3_", "homm3_"):
        if value.startswith(prefix):
            value = value[len(prefix):]
            break
    value = value.replace("_upg_alt", "").replace("_upg", "")
    words = [word for word in re.split(r"[_\s]+", value) if word]
    return " ".join(word.capitalize() for word in words) or sid


def manifest_unit_line_name(manifest: dict[str, Any], line: dict[str, Any]) -> str:
    names = line.get("names")
    if isinstance(names, list) and names and isinstance(names[0], str) and names[0].strip():
        return names[0].strip()
    variants = manifest_unit_variants(manifest)
    base_sid = manifest_unit_sid_for_variant(line, variants[0] if variants else "")
    return humanize_custom_sid(base_sid)


def custom_hero_specialization_count(manifest: dict[str, Any]) -> int:
    return int((manifest.get("heroes") or {}).get("count") or len(manifest_hero_names(manifest)) or 18)


def custom_hero_common_specialization_bonuses(class_type: str) -> list[dict[str, Any]]:
    ability = "skill_mage_ability" if class_type == "magic" else "skill_warrior_ability"
    return [
        {"type": "heroBattleAbility", "parameters": [ability, "0"]},
        {
            "type": "heroBattleAbility",
            "battleType": "forCity",
            "receiverRole": "attacker",
            "parameters": ["attack_siege_ability", "0"],
        },
        {"type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "1", "0"]},
        {"activationLevel": 4, "type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "2", "0"]},
        {"activationLevel": 8, "type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "3", "0"]},
        {"activationLevel": 12, "type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "4", "0"]},
    ]


def custom_creature_specialization_bonuses(manifest: dict[str, Any], line: dict[str, Any]) -> list[dict[str, Any]]:
    variants = manifest_unit_variants(manifest)
    receivers = [manifest_unit_sid_for_variant(line, suffix) for suffix in variants]
    base_sid = manifest_unit_sid_for_variant(line, variants[0] if variants else "")
    return [
        {"type": "cityUnitsIncrement", "parameters": [base_sid, "1"]},
        {"type": "unitStat", "receivers": receivers, "parameters": ["speed", "1"]},
        {"type": "unitStat", "receivers": receivers, "parameters": ["initiative", "1"]},
        {"type": "unitStat", "receivers": receivers, "parameters": ["hpPerc", "0.2"]},
        {
            "type": "unitStat",
            "receivers": receivers,
            "parameters": ["offence", "0"],
            "upgrade": {"increment": 1, "levelStep": 3},
        },
        {
            "type": "unitStat",
            "receivers": receivers,
            "parameters": ["defence", "0"],
            "upgrade": {"increment": 1, "levelStep": 3},
        },
        {
            "type": "unitStat",
            "receiverAllegiance": "enemy",
            "receivers": receivers,
            "parameters": ["offence", "0"],
            "upgrade": {"increment": -1, "levelStep": 3},
        },
        {
            "type": "unitStat",
            "receiverAllegiance": "enemy",
            "receivers": receivers,
            "parameters": ["defence", "0"],
            "upgrade": {"increment": -1, "levelStep": 3},
        },
    ]


def custom_hero_profile_pattern(index: int) -> tuple[str, int | None]:
    patterns: tuple[tuple[str, int | None], ...] = (
        ("logistics", None),
        ("scouting", None),
        ("creature", 0),
        ("creature", 1),
        ("leadership", None),
        ("estates", None),
        ("creature", 2),
        ("fortune", None),
        ("sorcery", None),
        ("mysticism", None),
        ("creature", 3),
        ("offense", None),
        ("creature", 4),
        ("pathfinding", None),
        ("creature", 5),
        ("armorer", None),
        ("creature", 6),
        ("tactics", None),
    )
    return patterns[(index - 1) % len(patterns)]


