def creature_specialty_icon_key_from_source_key(source_key: Any) -> str | None:
    if not isinstance(source_key, str):
        return None
    source_key = source_key.strip()
    if not source_key.startswith("creature:"):
        return None
    unit_sid = source_key.split(":", 1)[1].strip()
    return unit_sid if is_runtime_icon_key(unit_sid) else None


def custom_hero_specialization_icon_key(manifest: dict[str, Any], index: int) -> str:
    masterful_override = masterful_spell_override_for_manifest_index(manifest, index)
    if masterful_override is not None:
        assigned_spell, _spec_override = masterful_override
        return assigned_spell
    unit_lines = list(manifest_all_unit_lines(manifest))
    kind, unit_line_index = custom_hero_profile_pattern(index)
    if kind == "creature" and unit_lines:
        line = unit_lines[(unit_line_index or 0) % len(unit_lines)]
        variants = manifest_unit_variants(manifest)
        return manifest_unit_sid_for_variant(line, variants[0] if variants else "")
    return specialization_icon_key_for_kind(kind, fallback=f"{manifest_hero_sid(manifest, index)}_specialization_icon")


def custom_hero_specialization_text(manifest: dict[str, Any], index: int) -> tuple[str, str]:
    name, description, _bonuses = custom_hero_specialization_profile(manifest, index)
    return name, description


def make_custom_faction_specializations_doc(manifest: dict[str, Any]) -> Any:
    rows: list[Any] = []
    for index in range(1, custom_hero_specialization_count(manifest) + 1):
        hero_sid = manifest_hero_sid(manifest, index)
        class_type = "might" if index <= 8 else "magic"
        _name, _description, bonuses = custom_hero_specialization_profile(manifest, index)
        rows.append(
            {
                "id": f"{hero_sid}_specialization",
                "name": f"{hero_sid}_spec_name",
                "desc": f"{hero_sid}_spec_description",
                "icon": custom_hero_specialization_icon_key(manifest, index),
                "bonuses": bonuses + custom_hero_common_specialization_bonuses(class_type),
            }
        )
    return {"array": rows}


def unit_view_config_path(units_res_path: str | None) -> str | None:
    if not isinstance(units_res_path, str) or not units_res_path.strip():
        return None
    path = units_res_path.strip().replace("\\", "/").removesuffix(".prefab")
    if path.startswith("units/"):
        path = path[len("units/") :]
    return path


def load_homm3_import_map_meshes() -> dict[str, str]:
    try:
        table = json.loads(HOMM3_IMPORT_TABLE.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    entries = table.get("entries") if isinstance(table, dict) else None
    if not isinstance(entries, list):
        return {}
    result: dict[str, str] = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        map_mesh = unit_view_config_path(entry.get("mapResPath"))
        if not map_mesh:
            continue
        for sid in entry.get("gameUnitSids") or []:
            if isinstance(sid, str) and sid:
                result.setdefault(sid, map_mesh)
    return result


