def manifest_donor_unit_sid_for_variant(line: dict[str, Any], suffix: str) -> str | None:
    variant_sids = line.get("donorVariantSids")
    if isinstance(variant_sids, dict):
        sid = variant_sids.get(suffix)
        if isinstance(sid, str) and sid:
            return sid
    donor_base = line.get("donorBaseSid")
    if isinstance(donor_base, str) and donor_base:
        return donor_base + suffix
    return None


def manifest_donor_faction_sid_for_variant(
    line: dict[str, Any],
    suffix: str,
    default_donor_faction: str | None = None,
) -> str | None:
    variant_factions = line.get("donorVariantFactionSids")
    if isinstance(variant_factions, dict):
        faction_sid = variant_factions.get(suffix)
        if isinstance(faction_sid, str) and faction_sid:
            return faction_sid
    faction_sid = line.get("donorFactionSid", default_donor_faction)
    return faction_sid if isinstance(faction_sid, str) and faction_sid else None


def unit_display_name_for_variant(line: dict[str, Any], suffix_index: int) -> str | None:
    names = line.get("names")
    if isinstance(names, list) and suffix_index < len(names):
        name = names[suffix_index]
        if isinstance(name, str) and name:
            return name
    return None


def manifest_squad_unit_replacements(manifest: dict[str, Any]) -> dict[str, str]:
    replacements = dict((manifest.get("squadTree") or {}).get("unitReplacements") or {})
    variants = manifest_unit_variants(manifest)
    for line in manifest_all_unit_lines(manifest):
        for suffix in variants:
            donor_sid = manifest_donor_unit_sid_for_variant(line, suffix)
            if donor_sid:
                replacements.setdefault(donor_sid, manifest_unit_sid_for_variant(line, suffix))
    return replacements


def manifest_release_scaffold(manifest: dict[str, Any]) -> dict[str, Any]:
    return manifest.get("releaseScaffold") or {}


def manifest_custom_city_scene_name(manifest: dict[str, Any]) -> str:
    """Return the native donor city scene name emitted for a custom HoMM3 city."""

    scaffold = manifest_release_scaffold(manifest)
    scene_name = scaffold.get("citySceneName")
    if not isinstance(scene_name, str) or not scene_name:
        raise ValueError(f"{manifest_identity(manifest)} missing releaseScaffold.citySceneName")
    return scene_name

def manifest_core_overlay_enabled(manifest: dict[str, Any]) -> bool:
    validation = manifest.get("validation") or {}
    value = validation.get("coreOverlayEnabled")
    if isinstance(value, bool):
        return value
    if validation.get("releasePromotionBlocked") is True:
        return False
    return True


def manifest_donor_core_faction_sid(manifest: dict[str, Any]) -> str:
    overlay = manifest.get("coreOverlay") or {}
    identity = manifest.get("identity") or {}
    return overlay.get("donorFactionCoreSid") or identity["donorFactionSid"]


