def manifest_search_tokens(manifest: dict[str, Any]) -> tuple[str, ...]:
    identity = manifest.get("identity") or {}
    heroes = manifest.get("heroes") or {}
    skills_and_laws = manifest.get("skillsAndLaws") or {}
    tokens: list[str] = [
        identity["factionSid"],
        identity["citySid"],
        identity["displayNameToken"],
        identity["descriptionToken"],
        heroes["heroPrefix"].rstrip("_"),
        heroes["iconPrefix"].rstrip("_"),
        skills_and_laws["lawPrefix"].rstrip("_"),
        skills_and_laws["factionSkillSid"],
    ]
    tokens.extend(line["baseSid"] for line in manifest_all_unit_lines(manifest))
    tokens.extend(manifest.get("searchTokens") or [])
    return tuple(dict.fromkeys(token for token in tokens if token))


def manifest_donor_faction_skill_sids(manifest: dict[str, Any]) -> tuple[str, ...]:
    identity = manifest.get("identity") or {}
    donor_values = (
        identity.get("donorFactionSid"),
        manifest_donor_core_faction_sid(manifest),
        manifest_donor_fraction_sid(manifest),
        manifest_donor_skill_table_prefix(manifest),
    )
    return tuple(
        dict.fromkeys(
            f"skill_faction_{value}"
            for value in donor_values
            if isinstance(value, str) and value.strip()
        )
    )

def manifest_skill_table_sid(manifest: dict[str, Any], class_type: str, arena: bool = False) -> str:
    prefix = "arenaGame_" if arena else ""
    return f"{prefix}{manifest['identity']['factionSid']}_{class_type}_skills_table"


def manifest_donor_skill_table_sid(manifest: dict[str, Any], class_type: str, arena: bool = False) -> str:
    prefix = "arenaGame_" if arena else ""
    return f"{prefix}{manifest_donor_skill_table_prefix(manifest)}_{class_type}_skills_table"


