HOMM3_RESOURCE_SID_MAP = {
    "gold": "gold",
    "wood": "wood",
    "ore": "ore",
    "mercury": "mercury",
    # Olden Era has no sulfur resource. Fold HoMM3 sulfur into mercury.
    "sulfur": "mercury",
    "crystal": "crystals",
    "gems": "gemstones",
    "dust": "dust",
}


def homm3_costs(**resources: int) -> list[dict[str, Any]]:
    folded: dict[str, int] = {}
    for h3_name, amount in resources.items():
        if not amount:
            continue
        oe_name = HOMM3_RESOURCE_SID_MAP[h3_name]
        folded[oe_name] = folded.get(oe_name, 0) + amount
    return [
        {"name": name, "cost": folded[name]}
        for name in ("gold", "wood", "ore", "mercury", "crystals", "gemstones", "dust")
        if name in folded
    ]


def prev_buildings(*requirements: tuple[str, int]) -> list[dict[str, Any]]:
    return [{"sid": sid, "level": level} for sid, level in requirements]

