def homm3_dwelling_tree_for_faction(faction_sid: str) -> dict[str, list[dict[str, Any]]] | None:
    costs_by_tier = HOMM3_DWELLING_COSTS_BY_FACTION.get(faction_sid)
    if costs_by_tier is None:
        return None
    return {
        f"Build_Tier_{tier}": [
            {
                "prevBuildings": prev_buildings(),
                "costs": homm3_costs(**base_costs),
            },
            {
                "prevBuildings": prev_buildings((f"Build_Tier_{tier}", 1)),
                "costs": homm3_costs(
                    **upgrade_costs,
                    dust=HOMM3_DWELLING_DUST_COST_BY_TIER[tier],
                ),
            },
        ]
        for tier, (base_costs, upgrade_costs) in enumerate(costs_by_tier, start=1)
    }

