def removed_custom_hero_members() -> set[str]:
    members: set[str] = set()
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        count = custom_hero_specialization_count(manifest)
        for index in range(count + 1, 19):
            hero_sid = manifest_hero_sid(manifest, index)
            members.add(f"DB/heroes/{faction_sid}/{hero_sid}.json")
    return members


def mentions_custom_faction(value: Any) -> bool:
    text = json.dumps(value, ensure_ascii=False) if not isinstance(value, str) else value
    lowered = text.lower()
    return any(token.lower() in lowered for token in CUSTOM_FACTION_TOKENS) and not any(
        token in lowered for token in EXCLUDED_TOKENS
    )


def read_zip_text(zf: zipfile.ZipFile, name: str) -> str | None:
    if Path(name).suffix.lower() not in TEXT_EXTS:
        return None
    try:
        return zf.read(name).decode("utf-8-sig")
    except UnicodeDecodeError:
        try:
            return zf.read(name).decode("utf-16")
        except UnicodeDecodeError:
            return None


def member_mentions_tokens(zf: zipfile.ZipFile, name: str, tokens: tuple[str, ...]) -> bool:
    lowered_name = name.lower()
    if any(token.lower() in lowered_name for token in tokens):
        return True
    text = read_zip_text(zf, name)
    if text is None:
        return False
    lowered_text = text.lower()
    return any(token.lower() in lowered_text for token in tokens)


def should_copy_added_member(name: str, play_zip: zipfile.ZipFile) -> bool:
    lowered = name.lower()
    if any(token in lowered for token in EXCLUDED_TOKENS):
        return False
    if any(token.lower() in lowered for token in CUSTOM_FACTION_TOKENS):
        return True
    if not name.lower().endswith(".json") and not name.lower().endswith(".script"):
        return False
    try:
        data = play_zip.read(name)
    except KeyError:
        return False
    try:
        text = data.decode("utf-8-sig").lower()
    except UnicodeDecodeError:
        return False
    return any(token.lower() in text for token in CUSTOM_FACTION_TOKENS) and not any(
        token in text for token in EXCLUDED_TOKENS
    )


def merge_json(release_value: Any, play_value: Any) -> Any:
    if isinstance(release_value, dict) and isinstance(play_value, dict):
        merged = dict(release_value)
        for key, play_item in play_value.items():
            if key not in merged:
                if mentions_custom_faction({key: play_item}):
                    merged[key] = play_item
                continue
            merged[key] = merge_json(merged[key], play_item)
        return merged

    if isinstance(release_value, list) and isinstance(play_value, list):
        merged = list(release_value)
        serialized_existing = {json.dumps(item, sort_keys=True, ensure_ascii=False) for item in merged}
        for item in play_value:
            if not mentions_custom_faction(item):
                continue
            serialized = json.dumps(item, sort_keys=True, ensure_ascii=False)
            if serialized not in serialized_existing:
                merged.append(item)
                serialized_existing.add(serialized)
        return merged

    return release_value


def merge_data_json(release_value: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(release_value, dict):
        raise RuntimeError("DB/data.json root must be an object")
    merged = dict(release_value)
    all_custom_factions = set(CUSTOM_FACTION_MANIFEST_BY_SID)
    enabled_custom_factions = set(CORE_ENABLED_FACTION_SIDS)
    for key in ("fractions", "availableFractions"):
        source_values = merged.get(key)
        if not isinstance(source_values, list) or any(not isinstance(value, str) for value in source_values):
            raise RuntimeError(f"DB/data.json {key} must be a string list")
        values: list[str] = []
        for faction_sid in source_values:
            if faction_sid in all_custom_factions and faction_sid not in enabled_custom_factions:
                continue
            if faction_sid not in values:
                values.append(faction_sid)
        for faction_sid in CORE_ENABLED_FACTION_SIDS:
            if faction_sid not in values:
                values.append(faction_sid)
        merged[key] = values
    return merged


def normalize_biomes_info_json(value: Any, notes: list[str]) -> Any:
    if not isinstance(value, dict):
        return value
    mapping = value.get("fractionsByBiome")
    rows = mapping.get("data") if isinstance(mapping, dict) else None
    if not isinstance(rows, list):
        return value
    seen: set[str] = set()
    normalized: list[Any] = []
    changed = False
    for row in rows:
        key = row.get("key") if isinstance(row, dict) else None
        if isinstance(key, str):
            if key in seen:
                notes.append(f"drop duplicate biome mapping {key!r} from DB/biomes_info.json")
                changed = True
                continue
            seen.add(key)
        normalized.append(row)
    if changed:
        result = dict(value)
        result["fractionsByBiome"] = dict(mapping)
        result["fractionsByBiome"]["data"] = normalized
        return result
    return value


