def icon_for_unit_view_card(row: dict[str, Any], bucket: str) -> str:
    name = row.get("name")
    if isinstance(name, str):
        mapped = UNIT_VIEW_ICON_BY_NAME.get(name)
        if mapped:
            return mapped
        if name.startswith("base_passive_immunity_magic_"):
            return "sub_skill_resistance_1_icon"
        if name.endswith("_stunning_blow_name"):
            return "wasp_debuff_icon"
        if name.endswith("_stone_gaze_name"):
            return "neutral_magic_second_sight"
        if name.endswith("_poison_decay_name"):
            return "magic_fatal_decay_effect_icon"
        if name.endswith("_attack_defense_debuff_name"):
            return "magic_shorten_shadow_effect_icon"
        if name.endswith("_disrupting_ray_name") or name.endswith("_weakness_ray_name") or name.endswith("_after_shot_weakness_name"):
            return "magic_vulnerability_effect_icon"
        if name.endswith("_curse_name"):
            return "magic_unnatural_calm_effect_icon"
        if name.endswith("_magnetic_slow_name") or name.endswith("_misfortune_name") or name.endswith("_fearsome_name"):
            return "magic_nairas_kiss_effect_icon"
        if name.endswith("_blind_name") or name.endswith("_death_stare_name"):
            return "neutral_magic_second_sight"
        if name.endswith("_thunderbolt_name"):
            return "primal_1_magic_thunderbolt"
        if name.endswith("_mana_transfer_name"):
            return "magic_inner_light_effect_icon"
        if name.endswith("_bless_spell_name"):
            return "magic_favorable_wind_effect_icon"
        if name.endswith("_repair_name") or name.endswith("_animate_dead_name"):
            return "magic_healing_water_effect_icon"

    ability_type = row.get("abilityType")
    if isinstance(ability_type, str):
        mapped = UNIT_VIEW_ICON_BY_ABILITY_KIND.get(ability_type)
        if mapped:
            return mapped

    if bucket == "defaultAttacks":
        return "sub_skill_siege_1_icon" if "projectile" in row else "sub_skill_assault_1_icon"
    if bucket == "alternativeAttacks":
        return "sub_skill_assault_1_icon"
    if bucket == "counterAttacks":
        return "sub_skill_assault_1_icon"
    return "skill_tactics"


def enforced_icon_for_unit_view_card(row: dict[str, Any]) -> str | None:
    name = row.get("name")
    if not isinstance(name, str):
        return None
    mapped = UNIT_VIEW_ICON_BY_NAME.get(name)
    if mapped:
        return mapped
    if name.startswith("base_passive_immunity_magic_"):
        return "sub_skill_resistance_1_icon"
    return None


def ensure_unit_view_card_icons(item: dict[str, Any]) -> int:
    changed = 0
    for bucket in UNIT_VIEW_CARD_BUCKETS:
        cards = item.get(bucket)
        if not isinstance(cards, list):
            continue
        for row in cards:
            if not isinstance(row, dict):
                continue
            enforced = enforced_icon_for_unit_view_card(row)
            current = row.get("icon")
            if enforced is not None:
                if current != enforced:
                    row["icon"] = enforced
                    changed += 1
                continue
            if isinstance(current, str) and current.strip():
                continue
            row["icon"] = icon_for_unit_view_card(row, bucket)
            changed += 1
    return changed


def dedupe_unit_view_card_rows(item: dict[str, Any]) -> int:
    removed = 0
    for bucket in UNIT_VIEW_CARD_BUCKETS:
        cards = item.get(bucket)
        if not isinstance(cards, list):
            continue
        seen: set[str] = set()
        kept: list[Any] = []
        for row in cards:
            if not isinstance(row, dict):
                kept.append(row)
                continue
            key = json.dumps(row, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
            if key in seen:
                removed += 1
                continue
            seen.add(key)
            kept.append(row)
        if len(kept) != len(cards):
            item[bucket] = kept
    return removed


def ensure_custom_unit_view_icons_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    icon_members = 0
    changed_cards = 0
    deduped_members = 0
    deduped_cards = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                continue
            item = first_array_item(doc)
            if not isinstance(item, dict):
                continue
            changed = ensure_unit_view_card_icons(item)
            deduped = dedupe_unit_view_card_rows(item)
            if changed or deduped:
                output[name] = write_json(doc)
                if changed:
                    icon_members += 1
                changed_cards += changed
                if deduped:
                    deduped_members += 1
                deduped_cards += deduped
    if changed_cards:
        notes.append(f"add explicit custom UnitView ability icons ({changed_cards} cards across {icon_members} rows)")
    if deduped_cards:
        notes.append(f"dedupe custom UnitView ability cards ({deduped_cards} duplicate cards across {deduped_members} rows)")


def normalize_custom_unit_view_map_meshes(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    import_map_meshes = load_homm3_import_map_meshes()
    if not import_map_meshes:
        notes.append("warn missing homm3_import map mesh table; custom UnitView mapMesh standardization skipped")
        return

    changed = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            expected = import_map_meshes.get(custom_sid)
            if not expected:
                continue
            name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                continue
            item = first_array_item(doc)
            if not isinstance(item, dict):
                continue
            if item.get("mapMesh") == expected:
                continue
            item["mapMesh"] = expected
            audit = item.get("xHomm3ImplementationAudit")
            if isinstance(audit, dict):
                audit["implementedData"] = "Donor-safe preview mesh, faction-unique synthetic mapMesh, baseline attack role"
            output[name] = write_json(doc)
            changed += 1

    if changed:
        notes.append(f"standardize custom UnitView mapMesh to homm3_import synthetic paths ({changed})")


UNIT_MOVE_SPEED_NORMALIZATION = REPO_ROOT / "custom_factions" / "unit_move_speed_normalization.json"


def normalize_custom_unit_view_move_speeds(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
    only_sids: set[str] | None = None,
) -> None:
    """Write each adopted walker's normalized battle ground speed (UnitViewConfig.moveSpeed) into its view row.

    The table (custom_factions/unit_move_speed_normalization.json, gate tools/validate_unit_move_speed_normalization_contract.py)
    pins the mean moveSpeed of the unit's vanilla OE references; stride_match_glb.py matches the Move stride to the same
    value. A donor-inherited moveSpeed is not a speed decision. An adopted sid without a view row fails the overlay."""
    sys.path.insert(0, str(REPO_ROOT / "tools"))
    from validate_unit_move_speed_normalization_contract import adopted_targets

    targets = adopted_targets(UNIT_MOVE_SPEED_NORMALIZATION)
    if only_sids is not None:
        # Explicit subset (the neutral donors); every requested sid still needs its row below.
        targets = {sid: t for sid, t in targets.items() if sid in only_sids}
    changed = 0
    for sid, t in sorted(targets.items()):
        suffix = f"/{sid}_v.json"
        names = sorted({n for n in output if n.startswith("DB/units/units_views/") and n.endswith(suffix)}
                       | {n for n in release_zip.namelist() if n.startswith("DB/units/units_views/") and n.endswith(suffix)})
        if len(names) != 1:
            raise RuntimeError(f"move speed normalization: {sid} needs exactly one units_views row, found {names}")
        name = names[0]
        doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
        item = first_array_item(doc)
        if not isinstance(item, dict) or item.get("id") != sid:
            raise RuntimeError(f"move speed normalization: {name} first row is not {sid}")
        if item.get("moveSpeed") != t["targetMoveSpeed"]:
            item["moveSpeed"] = t["targetMoveSpeed"]
            output[name] = write_json(doc)
            changed += 1
    notes.append(f"normalize custom UnitView moveSpeed to vanilla OE references ({changed} of {len(targets)} adopted rows changed)")


def load_homm3_import_skinned_preview_meshes() -> dict[str, dict[str, str]]:
    """Map game SID → synthetic mesh/mapMesh when the import row is an OwnedSkinned prefab."""
    try:
        table = json.loads(HOMM3_IMPORT_TABLE.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError):
        return {}
    entries = table.get("entries") if isinstance(table, dict) else None
    if not isinstance(entries, list):
        return {}
    result: dict[str, dict[str, str]] = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        battle_prefab = str(entry.get("battlePrefabAssetPath") or "").replace("\\", "/")
        map_prefab = str(entry.get("mapPrefabAssetPath") or "").replace("\\", "/")
        if "/OwnedSkinned/" not in battle_prefab:
            continue
        if "/OwnedSkinned/" not in map_prefab:
            continue
        mesh = unit_view_config_path(entry.get("battleResPath"))
        map_mesh = unit_view_config_path(entry.get("mapResPath"))
        if not mesh or not map_mesh:
            raise RuntimeError(
                "OwnedSkinned import row is missing battleResPath/mapResPath: " + battle_prefab
            )
        for sid in entry.get("gameUnitSids") or []:
            if isinstance(sid, str) and sid:
                result[sid] = {"mesh": mesh, "mapMesh": map_mesh, "labPrefab": battle_prefab}
    return result


def normalize_custom_unit_view_skinned_preview_meshes(
    release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]
) -> None:
    """Point UnitViewConfig.mesh/mapMesh at the skinned homm3_import paths like vanilla units."""
    skinned = load_homm3_import_skinned_preview_meshes()
    if not skinned:
        return
    changed = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            expected = skinned.get(custom_sid)
            if not expected:
                continue
            name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                continue
            item = first_array_item(doc)
            if not isinstance(item, dict):
                continue
            if item.get("mesh") == expected["mesh"] and item.get("mapMesh") == expected["mapMesh"]:
                continue
            item["mesh"] = expected["mesh"]
            item["mapMesh"] = expected["mapMesh"]
            audit = item.get("xHomm3ImplementationAudit")
            if isinstance(audit, dict):
                audit["implementedData"] = (
                    "Skinned-mesh preview + adventure-map idle at homm3_import paths; "
                    "donor UnitViewConfig.scale kept"
                )
            output[name] = write_json(doc)
            changed += 1
    if changed:
        notes.append(
            f"point custom UnitView mesh/mapMesh at OwnedSkinned homm3_import paths ({changed})"
        )


def apply_vanilla_death_fade_to_custom_unit_views(
    release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]
) -> None:
    """Write VANILLA_DEATH_FADE_BY_UNIT_SID onto the custom UnitViewConfig rows (fail closed on a missing row)."""
    found: set[str] = set()
    changed = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            spec = VANILLA_DEATH_FADE_BY_UNIT_SID.get(custom_sid)
            if not spec:
                continue
            name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                raise RuntimeError(f"death fade: unit view {name} unreadable: {ex}") from ex
            item = first_array_item(doc)
            if not isinstance(item, dict) or item.get("id") != custom_sid:
                raise RuntimeError(f"death fade: unit view {name} has no row for {custom_sid}")
            found.add(custom_sid)
            if all(item.get(k) == v for k, v in spec.items()):
                continue
            item.update(spec)
            output[name] = write_json(doc)
            changed += 1
    missing = sorted(set(VANILLA_DEATH_FADE_BY_UNIT_SID) - found)
    if missing:
        raise RuntimeError(f"death fade: no core-enabled custom unit view for {missing}")
    if changed:
        notes.append(f"set native no-corpse death fade on custom UnitViews ({changed})")


def normalize_custom_unit_view_unsafe_donor_meshes(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    changed = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                continue
            item = first_array_item(doc)
            if not isinstance(item, dict):
                continue
            mesh = item.get("mesh")
            replacement = UNSAFE_CUSTOM_UNIT_VIEW_MESH_REPLACEMENTS.get(mesh)
            if not replacement:
                continue
            item["mesh"] = replacement
            audit = item.get("xHomm3ImplementationAudit")
            if isinstance(audit, dict):
                audit["implementedData"] = "Donor-safe preview mesh, faction-unique synthetic mapMesh, baseline attack role"
            output[name] = write_json(doc)
            changed += 1

    if changed:
        notes.append(f"replace unsafe custom UnitView donor battle mesh paths ({changed})")


def normalize_cyclops_shooter_battle_shells(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    """Force Cyclops views onto ranged Blade Dancer shells so shoot projectiles can present."""
    changed = 0
    faction_sid = "homm3_stronghold"
    for custom_sid, shell in CYCLOPS_SHOOTER_BATTLE_SHELL_BY_SID.items():
        name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
        try:
            doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
            continue
        item = first_array_item(doc)
        if not isinstance(item, dict):
            continue
        before = {key: copy.deepcopy(item.get(key)) for key in shell}
        for key, value in shell.items():
            item[key] = copy.deepcopy(value)
        after = {key: copy.deepcopy(item.get(key)) for key in shell}
        if before == after:
            continue
        audit = item.get("xHomm3ImplementationAudit")
        if isinstance(audit, dict):
            audit["implementedData"] = (
                "Donor-safe Blade Dancer shooter battle shell (Hydra logic donor retained); "
                "faction-unique synthetic mapMesh; shoot projectile presentation"
            )
        output[name] = write_json(doc)
        changed += 1
    if changed:
        notes.append(f"retarget Cyclops UnitView battle shells to Blade Dancer shooters ({changed})")


def merge_arena_pick_content(release_value: Any) -> tuple[Any, bool]:
    if not isinstance(release_value, dict):
        return release_value, False
    content = release_value.get("content")
    if not isinstance(content, list):
        return release_value, False

    from homm3_neutral_catalog import pool_eligible_unit_sids

    pool_sids = tuple(dict.fromkeys([*CORE_ENABLED_GAME_UNIT_SIDS, *pool_eligible_unit_sids()]))

    for bucket in content:
        if not isinstance(bucket, dict) or bucket.get("sid") != "units":
            continue
        rows = bucket.get("array")
        if not isinstance(rows, list):
            rows = []
            bucket["array"] = rows
        existing = {row.get("sid") for row in rows if isinstance(row, dict)}
        changed = False
        for sid in pool_sids:
            if sid in existing:
                continue
            rows.append({"sid": sid, "val": 100})
            existing.add(sid)
            changed = True
        return release_value, changed

    content.append(
        {
            "sid": "units",
            "array": [
                {"sid": sid, "val": 100}
                for sid in pool_sids
            ],
        }
    )
    return release_value, True


def merge_lang_rows(release_rows: list[Any], source_rows: list[Any]) -> tuple[list[Any], bool]:
    merged: list[Any] = []
    by_sid: dict[str, int] = {}
    changed = False
    for row in release_rows:
        merged.append(row)
        if not isinstance(row, dict):
            continue
        sid = row.get("sid")
        if not isinstance(sid, str) or not sid:
            continue
        if sid in by_sid:
            existing_index = by_sid[sid]
            if merged[existing_index] != row:
                changed = True
            merged[existing_index] = row
            merged.pop()
            changed = True
        else:
            by_sid[sid] = len(merged) - 1

    for row in source_rows:
        if not isinstance(row, dict) or not mentions_custom_faction(row):
            continue
        sid = row.get("sid")
        if not isinstance(sid, str) or not sid:
            continue
        if sid in by_sid:
            index = by_sid[sid]
            if merged[index] != row:
                merged[index] = row
                changed = True
        else:
            by_sid[sid] = len(merged)
            merged.append(row)
            changed = True

    return merged, changed


def merge_lang_json(release_value: Any, source_value: Any) -> tuple[Any, bool]:
    if not isinstance(source_value, dict):
        return release_value, False

    merged = dict(release_value) if isinstance(release_value, dict) else {}
    changed = False
    for key in LANG_TOKEN_LIST_KEYS:
        source_rows = source_value.get(key)
        if not isinstance(source_rows, list):
            continue
        release_rows = merged.get(key)
        if not isinstance(release_rows, list):
            release_rows = []
        merged_rows, rows_changed = merge_lang_rows(release_rows, source_rows)
        if rows_changed:
            merged[key] = merged_rows
            changed = True

    return merged, changed


def read_json(zf: zipfile.ZipFile, name: str) -> Any:
    return json.loads(zf.read(name).decode("utf-8-sig"))


def find_array_doc_by_id(zf: zipfile.ZipFile, prefix: str, row_id: str) -> tuple[str, Any]:
    for info in zf.infolist():
        name = normalize_name(info.filename)
        if info.is_dir() or not name.startswith(prefix) or not name.endswith(".json"):
            continue
        try:
            doc = read_json(zf, name)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
            continue
        rows = doc.get("array") if isinstance(doc, dict) else None
        if isinstance(rows, list) and any(isinstance(item, dict) and item.get("id") == row_id for item in rows):
            return name, doc
    raise KeyError(f"no {prefix} JSON row id {row_id!r}")


def write_json(value: Any) -> bytes:
    return (json.dumps(value, ensure_ascii=False, indent="\t") + "\n").encode("utf-8")


def upsert_array_row(doc: dict[str, Any], row: dict[str, Any], id_key: str = "id") -> bool:
    rows = doc.get("array")
    if not isinstance(rows, list):
        rows = []
        doc["array"] = rows
    row_id = row.get(id_key)
    if not isinstance(row_id, str):
        return False
    for index, existing in enumerate(rows):
        if isinstance(existing, dict) and existing.get(id_key) == row_id:
            if existing == row:
                return False
            rows[index] = row
            return True
    rows.append(row)
    return True


def remove_array_rows_by_id(doc: dict[str, Any], row_ids: set[str], id_key: str = "id") -> bool:
    rows = doc.get("array")
    if not isinstance(rows, list):
        return False
    output = [
        row
        for row in rows
        if not (isinstance(row, dict) and isinstance(row.get(id_key), str) and row[id_key] in row_ids)
    ]
    if len(output) == len(rows):
        return False
    doc["array"] = output
    return True


def dedupe_array_rows_by_id(doc: dict[str, Any], id_key: str = "id") -> bool:
    rows = doc.get("array")
    if not isinstance(rows, list):
        return False
    seen: set[str] = set()
    output: list[Any] = []
    changed = False
    for row in reversed(rows):
        if isinstance(row, dict) and isinstance(row.get(id_key), str):
            row_id = row[id_key]
            if row_id in seen:
                changed = True
                continue
            seen.add(row_id)
        output.append(row)
    if changed:
        output.reverse()
        doc["array"] = output
    return changed


