def first_array_item(value: Any) -> dict[str, Any] | None:
    if not isinstance(value, dict):
        return None
    array = value.get("array")
    if not isinstance(array, list) or not array or not isinstance(array[0], dict):
        return None
    return array[0]


def resolve_hero_row(hero_doc: dict[str, Any], hero_sid: str) -> dict[str, Any] | None:
    rows = hero_doc.get("array")
    if not isinstance(rows, list) or not rows:
        return None
    matches = [row for row in rows if isinstance(row, dict) and row.get("id") == hero_sid]
    if matches:
        return matches[-1]
    first = rows[0]
    return first if isinstance(first, dict) else None


def finalize_hero_doc(hero_doc: dict[str, Any], hero: dict[str, Any]) -> None:
    """Ship one hero row per file; duplicate ids break armyValue and portrait binding."""
    if isinstance(hero, dict) and hero.get("id"):
        hero_doc["array"] = [hero]
        return
    if dedupe_array_rows_by_id(hero_doc):
        rows = hero_doc.get("array")
        if isinstance(rows, list) and rows and isinstance(rows[-1], dict):
            hero_doc["array"] = [rows[-1]]


