def normalize_release_tower_unit_views(
    release_zip: zipfile.ZipFile,
    overlay: dict[str, bytes],
    notes: list[str],
) -> None:
    """Keep Tower UnitViewConfig native-safe in Steam release.

    Stronghold's working release contract keeps UnitViewConfig.mesh/mapMesh on
    known-good donor prefab paths and lets homm3_import gameUnitSids replace the
    visible model later. Tower must follow the same contract. Pointing release
    Core.zip directly at homm3_import/tower/* sends native preview/combat code
    through missing synthetic resources before our overlay hooks can recover.
    """

    suffixes = ("", "_upg", "_upg_alt")
    for donor_base, h3_base in TOWER_DONOR_TO_H3_UNIT_BASE.items():
        for suffix in suffixes:
            donor_name = f"DB/units/units_views/humans/{donor_base}{suffix}_v.json"
            target_name = f"DB/units/units_views/homm3_tower/{h3_base}{suffix}_v.json"
            try:
                donor_json = read_json(release_zip, donor_name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                notes.append("warn missing donor view " + donor_name)
                continue

            if target_name in overlay:
                try:
                    target_json = json.loads(overlay[target_name].decode("utf-8-sig"))
                except (json.JSONDecodeError, UnicodeDecodeError):
                    notes.append("warn unreadable target view " + target_name)
                    continue
            else:
                try:
                    target_json = read_json(release_zip, target_name)
                except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                    notes.append("warn missing target view " + target_name)
                    continue

            donor_item = first_array_item(donor_json)
            target_item = first_array_item(target_json)
            if donor_item is None or target_item is None:
                notes.append("warn malformed unit view " + target_name)
                continue

            changed = False
            for field in UNIT_VIEW_DONOR_FIELDS:
                if field in donor_item and target_item.get(field) != donor_item[field]:
                    target_item[field] = donor_item[field]
                    changed = True
                elif field not in donor_item and field in target_item:
                    del target_item[field]
                    changed = True
            sid = str(target_item.get("id") or f"{h3_base}{suffix}")
            if sid in VANILLA_PROJECTILE_SPECS_BY_UNIT_SID:
                for attack in target_item.get("defaultAttacks") or []:
                    if isinstance(attack, dict):
                        before = dict(attack)
                        apply_vanilla_projectile(attack, sid)
                        changed = changed or attack != before
            try:
                current_json = read_json(release_zip, target_name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                current_json = None

            if target_json != current_json:
                overlay[target_name] = write_json(target_json)
                notes.append("normalize release unit view " + target_name)
            elif target_name in overlay:
                del overlay[target_name]


def prune_release_tower_unimplemented_passive_cards(
    release_zip: zipfile.ZipFile,
    overlay: dict[str, bytes],
    notes: list[str],
) -> None:
    """Remove unsupported inherited Tower cards without changing view assets or logic."""
    removed: list[str] = []
    for sid, unsupported_cards in TOWER_UNIMPLEMENTED_PASSIVE_VIEW_NAME_SIDS.items():
        target_name = f"DB/units/units_views/homm3_tower/{sid}_v.json"
        if target_name in overlay:
            try:
                target_json = json.loads(overlay[target_name].decode("utf-8-sig"))
            except (json.JSONDecodeError, UnicodeDecodeError):
                notes.append("warn unreadable target view " + target_name)
                continue
        else:
            try:
                target_json = read_json(release_zip, target_name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                notes.append("warn missing target view " + target_name)
                continue
        target_item = first_array_item(target_json)
        if target_item is None:
            notes.append("warn malformed unit view " + target_name)
            continue
        passives = target_item.get("passives")
        if not isinstance(passives, list):
            continue
        kept = [
            row for row in passives
            if not (isinstance(row, dict) and row.get("name") in unsupported_cards)
        ]
        if len(kept) == len(passives):
            continue
        target_item["passives"] = kept
        overlay[target_name] = write_json(target_json)
        removed.append(sid)
    if removed:
        notes.append(f"remove unsupported inherited Tower passive cards ({len(removed)} units)")


def remap_string_tokens(value: Any, replacements: dict[str, str]) -> Any:
    if isinstance(value, str):
        result = value
        for old, new in replacements.items():
            result = result.replace(old, new)
        return result
    if isinstance(value, list):
        return [remap_string_tokens(item, replacements) for item in value]
    if isinstance(value, dict):
        return {key: remap_string_tokens(item, replacements) for key, item in value.items()}
    return value


def normalize_fortress_squad_doc(value: Any, donor_faction_sid: str, faction_sid: str) -> Any:
    if isinstance(value, str):
        if value in FORTRESS_SQUAD_UNIT_REPLACEMENTS:
            return FORTRESS_SQUAD_UNIT_REPLACEMENTS[value]
        if value == donor_faction_sid:
            return faction_sid
        return value.replace(f"squad_{donor_faction_sid}", f"squad_{faction_sid}").replace(
            f"squads_{donor_faction_sid}",
            f"squads_{faction_sid}",
        )
    if isinstance(value, list):
        return [normalize_fortress_squad_doc(item, donor_faction_sid, faction_sid) for item in value]
    if isinstance(value, dict):
        return {key: normalize_fortress_squad_doc(item, donor_faction_sid, faction_sid) for key, item in value.items()}
    return value


def add_release_fortress_squads(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = load_custom_faction_manifest("homm3_fortress")
    identity = manifest["identity"]
    donor_faction_sid = identity["donorFactionSid"]
    faction_sid = identity["factionSid"]
    source_prefix = f"DB/squads/squads_{donor_faction_sid}/"
    target_prefix = manifest_core_member(manifest, "squadTree")
    changed = 0
    for info in release_zip.infolist():
        source_name = normalize_name(info.filename)
        if info.is_dir() or not source_name.startswith(source_prefix) or not source_name.endswith(".json"):
            continue
        target_name = target_prefix + source_name[len(source_prefix) :].replace(
            f"squad_{donor_faction_sid}",
            f"squad_{faction_sid}",
        )
        try:
            doc = normalize_fortress_squad_doc(read_json(release_zip, source_name), donor_faction_sid, faction_sid)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing Fortress squad donor {source_name}: {ex}")
            continue
        data = write_json(doc)
        if output.get(target_name) == data:
            continue
        output[target_name] = data
        changed += 1
    if changed:
        notes.append(f"generate Fortress squad tree from Nature donor ({changed})")


def trim_building_levels(building: dict[str, Any], level_count: int) -> None:
    for key in ("icons", "names", "descriptions", "narrativeDescriptions", "backgroundImages", "parametersPerLevel"):
        value = building.get(key)
        if isinstance(value, list) and len(value) > level_count:
            building[key] = value[:level_count]


# Castle-parity cityFactory compositor only owns BhBuilding art for SIDs present in
# town_scene_refs/<faction>/layers/building_layer_map.json nativeLevels. Constructing
# Intelligence Academy / Training Range without that join activates unbound Castle
# donor slots. Do not alias those SIDs onto other slots and do not invent Gantry slots.
OWNED_WORLD_UNBOUND_CASTLE_SLOT_BUILDING_SIDS: tuple[str, ...] = (
    "Build_Intelligence_Academy",
    "Build_Training_Range",
)


# Every owned cityFactory world is the cityHuman2 donor graph (LoadScene donor -> Move), so native
# BhBuildingsManager resolves a city building's BhBuildingSlot by the *cityHuman2* slot string.
# These are the vanilla human_city.json sceneSlot values (source/static, installed Golden Era Core).
# Peers cloned from another donor city (nature_city: "Build_Main", "Build_Tavern", ...; demon/undead:
# "Wall") keep that donor's slot strings, which no cityFactory slot carries: the building never binds,
# the town hall never activates, and the owned presentation waits forever (Conflux, 2026-09-26).
# tools/validate_custom_faction_manifests.py re-derives the expected values from Core's human_city.json.
OWNED_WORLD_CITY_FACTORY_SCENE_SLOT_BY_SID: dict[str, str] = {
    "Build_Main": "Main",
    "Build_Tavern": "Tavern",
    "Build_Market": "Market",
    "Build_Artifact_Market": "Artifact_Market",
    "Build_Tier_1": "Tier_1",
    "Build_Tier_2": "Tier_2",
    "Build_Tier_3": "Tier_3",
    "Build_Tier_4": "Tier_4",
    "Build_Tier_5": "Tier_5",
    "Build_Tier_6": "Tier_6",
    "Build_Tier_7": "Tier_7",
    "Build_Magic_Guild": "Magic_Guild",
    "Build_Bank": "Bank",
    "Build_Treasury": "Treasury",
    "Build_Resource_Depot": "Resource_Depot",
    "Build_Resource_Depot_level_2": "Resource_Depot_2",
    "Build_Wall": "Walls",
    "Build_Intelligence_Academy": "Intelligence_Academy",
    "Build_Training_Range": "Training_Range",
    "Build_Golden_Calf": "Golden_Calf",
}


def align_owned_world_city_scene_slots(
    doc: Any,
    manifest: dict[str, Any],
    notes: list[str] | None = None,
) -> Any:
    """Point Castle-parity building rows of an owned cityFactory city at the cityHuman2 slots.

    Only SIDs that cityHuman2 has a slot for are rewritten; faction-special buildings keep their
    slot string (no cityFactory slot exists for them, and none is invented here).
    """
    try:
        scene_name = manifest_custom_city_scene_name(manifest)
    except ValueError:
        return doc
    if scene_name != "cityFactory":
        return doc
    changed: list[str] = []
    for row in collect_city_building_config_rows(doc):
        sid = row.get("sid")
        slot = OWNED_WORLD_CITY_FACTORY_SCENE_SLOT_BY_SID.get(sid) if isinstance(sid, str) else None
        if slot is None or row.get("sceneSlot") == slot:
            continue
        changed.append(f"{sid}:{row.get('sceneSlot')!r}->{slot!r}")
        row["sceneSlot"] = slot
    if changed and notes is not None:
        faction_sid = (manifest.get("identity") or {}).get("factionSid")
        notes.append(f"align cityFactory sceneSlots for {faction_sid}: " + ", ".join(changed))
    return doc


def owned_world_building_layer_map_path(faction_sid: str) -> Path:
    return (
        DEFAULT_SOURCE_PLUGIN_ROOT
        / "homm3_runtime_assets"
        / "town_scene_refs"
        / faction_sid
        / "layers"
        / "building_layer_map.json"
    )


def load_owned_world_native_level_sids(faction_sid: str) -> set[str]:
    path = owned_world_building_layer_map_path(faction_sid)
    if not path.is_file():
        raise FileNotFoundError(
            f"{faction_sid}: owned-world cityFactory peer missing building_layer_map.json at {path}"
        )
    layer_map = json.loads(path.read_text(encoding="utf-8-sig"))
    native_levels = layer_map.get("nativeLevels")
    if not isinstance(native_levels, dict) or not native_levels:
        raise ValueError(
            f"{faction_sid}: building_layer_map.json must include non-empty nativeLevels "
            "before constructible city rows are emitted"
        )
    return {sid for sid in native_levels if isinstance(sid, str) and sid}


def scrub_prev_buildings_for_removed_sids(row: dict[str, Any], removed_sids: set[str]) -> None:
    levels = row.get("parametersPerLevel")
    if not isinstance(levels, list):
        return
    for level in levels:
        if not isinstance(level, dict):
            continue
        prev = level.get("prevBuildings")
        if not isinstance(prev, list):
            continue
        level["prevBuildings"] = [
            entry
            for entry in prev
            if not (isinstance(entry, dict) and entry.get("sid") in removed_sids)
        ]


def strip_unbound_castle_slot_buildings_from_owned_world_city(
    doc: Any,
    manifest: dict[str, Any],
    notes: list[str] | None = None,
) -> Any:
    """Remove IA/Training from constructible city rows when nativeLevels lack those SIDs.

    Fail-closed for owned cityFactory peers: constructing must not activate unbound
    Castle BhBuilding slots. Peers that later gain nativeLevels entries keep the rows.

    Retention exception (explicit, not a silent fallback): if source_mechanics declares the
    SID in a building surface currentRows entry (Tower Library / Workshop Yard), keep the
    constructible city row. Those peers still lack compositor art until nativeLevels gains
    the SID; do not invent aliases onto other slots.
    """
    identity = manifest.get("identity") or {}
    faction_sid = identity.get("factionSid")
    if not isinstance(faction_sid, str) or not faction_sid:
        return doc
    try:
        scene_name = manifest_custom_city_scene_name(manifest)
    except ValueError:
        return doc
    if scene_name != "cityFactory":
        return doc

    native_sids = load_owned_world_native_level_sids(faction_sid)
    to_strip = set()
    retained_for_mechanics: list[str] = []
    for sid in OWNED_WORLD_UNBOUND_CASTLE_SLOT_BUILDING_SIDS:
        if sid in native_sids:
            continue
        # source_mechanic_for_building is defined later; resolve at call time.
        if source_mechanic_for_building(faction_sid, sid) is not None:
            retained_for_mechanics.append(sid)
            continue
        to_strip.add(sid)
    if retained_for_mechanics and notes is not None:
        notes.append(
            "retain Castle-slot buildings required by source_mechanics currentRows for "
            + faction_sid
            + ": "
            + ", ".join(sorted(retained_for_mechanics))
            + " (nativeLevels still lack compositor art)"
        )
    if not to_strip:
        return doc

    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc

    removed: list[str] = []
    for key, section in list(item.items()):
        if not isinstance(section, list):
            continue
        kept: list[Any] = []
        for row in section:
            if isinstance(row, dict) and row.get("sid") in to_strip:
                removed.append(str(row["sid"]))
                continue
            if isinstance(row, dict):
                scrub_prev_buildings_for_removed_sids(row, to_strip)
            kept.append(row)
        item[key] = kept

    if removed and notes is not None:
        unique = sorted(set(removed))
        notes.append(
            "strip unbound Castle-slot buildings lacking nativeLevels for "
            + faction_sid
            + ": "
            + ", ".join(unique)
        )
    return doc


def fortress_unit_sids_for_line(line: dict[str, Any]) -> list[str]:
    return [line["base"], line["base"] + "_upg", line["base"] + "_upg_alt"]


def normalize_unit_hire_payload(payload: Any, line: dict[str, Any]) -> None:
    if not isinstance(payload, dict):
        return
    sids = fortress_unit_sids_for_line(line)
    units = payload.get("units")
    if isinstance(units, list):
        for row in units:
            if isinstance(row, dict):
                row["sids"] = list(sids)


def normalize_fortress_special_building_rows(city: dict[str, Any]) -> None:
    hero_bonus_banks = city.get("heroBonusBanks")
    if isinstance(hero_bonus_banks, list):
        for row in hero_bonus_banks:
            if isinstance(row, dict) and row.get("sid") == "Build_Gymnasium":
                row["sid"] = "Build_Mother_Nature"

    artifact_changers = city.get("artifactChangers")
    if isinstance(artifact_changers, list):
        remaining: list[Any] = []
        mycelium_row: dict[str, Any] | None = None
        for row in artifact_changers:
            if isinstance(row, dict) and row.get("sid") == "Build_Lyceum":
                mycelium_row = copy.deepcopy(row)
                mycelium_row["sid"] = "Build_Mycelium_Roots"
                mycelium_row.pop("artifacts", None)
            else:
                remaining.append(row)
        if mycelium_row is not None:
            city["artifactChangers"] = remaining
            roots = city.setdefault("myceliumRoots", [])
            if isinstance(roots, list):
                roots[:] = [
                    row
                    for row in roots
                    if not (isinstance(row, dict) and row.get("sid") == "Build_Mycelium_Roots")
                ]
                roots.append(mycelium_row)


def apply_building_parameter_overrides(building: dict[str, Any], overrides: list[dict[str, Any]] | None) -> None:
    params = building.get("parametersPerLevel")
    if not overrides or not isinstance(params, list):
        return
    if len(params) != len(overrides):
        raise RuntimeError(f"{building.get('sid')}: expected {len(overrides)} level parameter rows, found {len(params)}")
    for row, override in zip(params, overrides):
        row["prevBuildings"] = copy.deepcopy(override["prevBuildings"])
        row["costs"] = copy.deepcopy(override["costs"])


def apply_homm3_dwelling_cost_tree(city: dict[str, Any], manifest: dict[str, Any]) -> None:
    dwelling_tree = homm3_dwelling_tree_for_faction(manifest["identity"]["factionSid"])
    if not dwelling_tree:
        return
    for section in city.values():
        if not isinstance(section, list):
            continue
        for building in section:
            if not isinstance(building, dict):
                continue
            sid = building.get("sid")
            if isinstance(sid, str):
                apply_building_parameter_overrides(building, dwelling_tree.get(sid))


def apply_fortress_building_tree(city: dict[str, Any]) -> None:
    normalize_fortress_special_building_rows(city)

    for section in city.values():
        if not isinstance(section, list):
            continue
        for building in section:
            if not isinstance(building, dict):
                continue
            sid = building.get("sid")
            if not isinstance(sid, str):
                continue
            special = FORTRESS_SPECIAL_BUILDING_TREE.get(sid)
            if special:
                apply_building_parameter_overrides(building, [special])
                if "bonuses" in special:
                    building["bonuses"] = copy.deepcopy(special["bonuses"])

    for build_order in city.get("buildOrders") or []:
        order = build_order.get("order") if isinstance(build_order, dict) else None
        if not isinstance(order, list):
            continue
        for entry in order:
            if not isinstance(entry, dict):
                continue
            if entry.get("sid") == "Build_Gymnasium":
                entry["sid"] = "Build_Mother_Nature"
            elif entry.get("sid") == "Build_Lyceum":
                entry["sid"] = "Build_Mycelium_Roots"
        order[:] = [
            entry
            for entry in order
            if not (
                isinstance(entry, dict)
                and entry.get("sid") == "Build_Magic_Guild"
                and int(entry.get("level", 0) or 0) > 3
            )
        ]
        for prerequisite_sid, dependent_sid in (
            ("Build_Mother_Nature", "Build_Bank"),
            ("Build_Mother_Nature", "Build_Mycelium_Roots"),
        ):
            prerequisite_index = next(
                (
                    index
                    for index, entry in enumerate(order)
                    if isinstance(entry, dict) and entry.get("sid") == prerequisite_sid
                ),
                None,
            )
            dependent_index = next(
                (
                    index
                    for index, entry in enumerate(order)
                    if isinstance(entry, dict) and entry.get("sid") == dependent_sid
                ),
                None,
            )
            if prerequisite_index is None or dependent_index is None or prerequisite_index < dependent_index:
                continue
            prerequisite = order.pop(prerequisite_index)
            dependent_index = next(
                (
                    index
                    for index, entry in enumerate(order)
                    if isinstance(entry, dict) and entry.get("sid") == dependent_sid
                ),
                len(order),
            )
            order.insert(dependent_index, prerequisite)


def normalize_fortress_city_doc(doc: Any, manifest: dict[str, Any]) -> Any:
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = identity["citySid"]
        item["sceneName"] = manifest_custom_city_scene_name(manifest)
        item["fraction"] = identity["factionSid"]
        apply_fortress_building_tree(item)
        apply_homm3_dwelling_cost_tree(item, manifest)
        normalize_fortress_city_building_presentation(doc)
        apply_homm3_special_building_node_pos(doc, manifest)
        for section in item.values():
            if not isinstance(section, list):
                continue
            for row in section:
                if not isinstance(row, dict):
                    continue
                if row.get("sid") == "Build_Magic_Guild":
                    trim_building_levels(row, 3)
                if isinstance(row.get("sid"), str) and row["sid"].startswith("Build_Tier_"):
                    try:
                        tier = int(row["sid"].rsplit("_", 1)[1])
                    except ValueError:
                        continue
                    if 1 <= tier <= len(FORTRESS_UNIT_LINES):
                        normalize_unit_hire_payload(row.get("unitsHire"), FORTRESS_UNIT_LINES[tier - 1])
        apply_city_building_mechanics(doc, manifest)
        align_owned_world_city_scene_slots(doc, manifest)
        strip_unbound_castle_slot_buildings_from_owned_world_city(doc, manifest)
        apply_homm3_city_building_tree(doc, manifest)
    return doc


def make_fortress_fraction_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> dict[str, Any]:
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    _, doc = find_array_doc_by_id(release_zip, "DB/fractions/", identity["donorFactionSid"])
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = identity["factionSid"]
        item["name"] = identity["displayNameToken"]
        item["desc"] = identity["descriptionToken"]
        item["narrativeDesc"] = identity["descriptionToken"]
        item["icon"] = scaffold["factionIcon"]
        item["iconFractionLaws"] = scaffold["factionLawIcon"]
        item["biome"] = scaffold["biome"]
        item["resourceName"] = "wood"
        item["cityNames"] = homm3_town_name_tokens(identity)
        item["fractionLawsLines"] = remap_string_tokens(
            item.get("fractionLawsLines"),
            {f"fraction_law_{identity['donorFactionSid']}_": (manifest.get("skillsAndLaws") or {})["lawPrefix"]},
        )
    return doc


def normalize_fortress_unit_logic(doc: Any, custom_sid: str, line: dict[str, Any], suffix_index: int, faction_sid: str) -> Any:
    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc
    scaffold = manifest_release_scaffold(CUSTOM_FACTION_MANIFEST_BY_SID[faction_sid])
    item["id"] = custom_sid
    item["fraction"] = faction_sid
    item["nativeBiome"] = scaffold["biome"]
    item["tier"] = line["tier"]
    if suffix_index == 0:
        item.pop("baseSid", None)
    else:
        item["baseSid"] = line["base"] if suffix_index == 1 else line["base"] + "_upg"
    tags = item.get("tags")
    if isinstance(tags, list):
        item["tags"] = [faction_sid if tag in {"human", "humans", "nature", "dungeon"} else tag for tag in tags]
        if faction_sid not in item["tags"]:
            item["tags"].append(faction_sid)
    if suffix_index == 0:
        item["upgradeSid"] = line["base"] + "_upg"
    elif suffix_index == 1:
        item["upgradeSid"] = line["base"] + "_upg_alt"
    else:
        item.pop("upgradeSid", None)
    apply_fortress_unit_target_stats(item, custom_sid)
    normalize_fortress_logic_behavior(item, custom_sid)
    item["xHomm3FortressQuality"] = {
        "source": "docs/homm3_faction_plans/fortress.md",
        "implementedData": "HotA/VCMI stats, cost, squad value, faction/native biome, baseline attack role, sourced native mechanics",
    }
    return doc


def normalize_fortress_city_building_presentation(doc: Any) -> Any:
    source_levels = generic_building_source_levels(CUSTOM_FACTION_MANIFEST_BY_SID["homm3_fortress"])

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            sid = value.get("sid")
            icons = value.get("icons")
            if isinstance(sid, str) and sid.startswith("Build_") and isinstance(icons, list):
                names = value.get("names")
                descriptions = value.get("descriptions")
                count = max(
                    len(icons),
                    len(names) if isinstance(names, list) else 0,
                    len(descriptions) if isinstance(descriptions, list) else 0,
                )
                if sid in source_levels:
                    value["icons"] = [fortress_building_icon_key(sid, index + 1) for index in range(count)]
                value["names"] = [fortress_building_text_key(sid, "name", index + 1, count) for index in range(count)]
                value["descriptions"] = [
                    fortress_building_text_key(sid, "description", index + 1, count)
                    for index in range(count)
                ]
                value["narrativeDescriptions"] = [
                    fortress_building_text_key(sid, "narrativeDescription", index + 1, count)
                    for index in range(count)
                ]
            for item in value.values():
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(doc)
    return doc


def apply_fortress_unit_target_stats(item: dict[str, Any], custom_sid: str) -> None:
    target = FORTRESS_UNIT_TARGET_STATS.get(custom_sid)
    if not target:
        return
    stats = item.get("stats")
    if not isinstance(stats, dict):
        raise RuntimeError(f"{custom_sid}: balance adjustment target stats is missing or malformed")
    for key in ("hp", "offence", "defence", "damageMin", "damageMax", "initiative", "speed"):
        stats[key] = target[key]
    ammo = target.get("ammo")
    if isinstance(ammo, int) and ammo > 0:
        stats["ammo"] = ammo
    elif isinstance(stats.get("ammo"), int):
        stats["ammo"] = 0
    if "squadValue" in target:
        item["squadValue"] = target["squadValue"]
    cost = target.get("cost")
    if isinstance(cost, dict):
        item["unitCost"] = {
            "costResArray": [{"name": resource, "cost": value} for resource, value in cost.items()]
        }
    apply_homm3_unit_balance_logic_adjustment(item, custom_sid)


def fortress_behavior_for_sid(custom_sid: str) -> dict[str, Any]:
    base_sid = custom_sid.removesuffix("_upg_alt").removesuffix("_upg")
    behavior = dict(FORTRESS_UNIT_BASELINE_BEHAVIOR.get(base_sid, {"attack": "melee", "passives": ()}))
    override = FORTRESS_UNIT_VARIANT_BEHAVIOR_OVERRIDES.get(custom_sid)
    if override:
        behavior.update(override)
    return behavior


def as_attack_list(value: Any) -> list[dict[str, Any]]:
    if isinstance(value, list):
        return [item for item in value if isinstance(item, dict)]
    if isinstance(value, dict):
        return [value]
    return []


def find_attack(row: dict[str, Any], attack_type: str) -> dict[str, Any] | None:
    for key in ("defaultAttacks", "alternativeAttacks", "counterAttacks"):
        for attack in as_attack_list(row.get(key)):
            if attack.get("attackType_") == attack_type:
                return json.loads(json.dumps(attack, ensure_ascii=False))
    return None


def fallback_melee_attack(trigger_counter: bool) -> dict[str, Any]:
    return {
        "attackType_": "melee",
        "selfMechanics": [],
        "damageDealer": {
            "tags": ["melee_attack", "normal_damage", "basic_attack"],
            "triggerCounter": trigger_counter,
            "attackPatternSid": "attack_single_x100",
            "castTargetParams": {
                "targetTags": "unit attackable_object",
                "castTarget_": "enemy",
                "targetCondition_": "alive",
                "selection": "object",
            },
            "affectTargetParams": {
                "targetTags": "unit attackable_object",
                "castTarget_": "enemy",
                "targetCondition_": "alive",
                "selection": "object",
            },
            "damageTarget_": "enemy",
            "damageType_": "normal",
            "statDmgMult": 1.0,
            "targetMechanics": [],
        },
    }


def scaled_fallback_melee_attack(trigger_counter: bool, stat_dmg_mult: float) -> dict[str, Any]:
    attack = fallback_melee_attack(trigger_counter)
    dealer = attack.get("damageDealer")
    if isinstance(dealer, dict):
        dealer["statDmgMult"] = stat_dmg_mult
    return attack


def fallback_shoot_attack() -> dict[str, Any]:
    attack = fallback_melee_attack(False)
    attack["attackType_"] = "shoot"
    dealer = attack.get("damageDealer")
    if isinstance(dealer, dict):
        dealer["tags"] = ["shoot_attack", "normal_damage", "basic_attack"]
        dealer["shootRange"] = CUSTOM_RANGED_SHOOT_RANGE
        dealer["shootThreshold"] = CUSTOM_RANGED_SHOOT_THRESHOLD
        dealer["shootRedCount"] = CUSTOM_RANGED_SHOOT_RED_COUNT
    return attack


def normalize_damage_dealer(
    attack: dict[str, Any],
    trigger_counter: bool,
    *,
    melee: bool,
    stat_dmg_mult: float = 1.0,
) -> None:
    """Fail-closed baseline for default/counter/alt basic attacks.

    Clears donor attack geometry (reach/breath/swirl patterns and noself affect
    targeting) down to single-hex enemy hits. Intentional multi-hex shapes must be
    re-applied afterward via allowlisted helpers (breath/swirl/tri-reach/long-reach).
    Does not touch Focus rows in abilities[].
    """
    dealer = attack.get("damageDealer")
    if not isinstance(dealer, dict):
        return
    dealer["triggerCounter"] = trigger_counter
    dealer["damageTarget_"] = "enemy"
    dealer["damageType_"] = "normal"
    dealer["statDmgMult"] = stat_dmg_mult
    dealer["targetMechanics"] = []
    dealer["attackPatternSid"] = "attack_single_x100"
    dealer.pop("buffTarget_", None)
    dealer.pop("buff", None)
    for params_key in ("castTargetParams", "affectTargetParams"):
        params = dealer.setdefault(params_key, {})
        if isinstance(params, dict):
            params["targetTags"] = ["unit", "attackable_object"]
            params["castTarget_"] = "enemy"
            params["targetCondition_"] = "alive"
            params["selection"] = "object"
    if melee:
        dealer.pop("projectile", None)
        dealer.pop("shootRange", None)
        dealer.pop("shootThreshold", None)
        dealer.pop("shootRedCount", None)
        dealer.pop("shootDmgBuff", None)
        tags = dealer.get("tags")
        if not isinstance(tags, list):
            tags = ["melee_attack", "normal_damage", "basic_attack"]
        tags = [tag for tag in tags if isinstance(tag, str) and not tag.startswith("armed_ability_") and "shoot" not in tag]
        for required in ("melee_attack", "normal_damage", "basic_attack"):
            if required not in tags:
                tags.append(required)
        dealer["tags"] = tags
    else:
        dealer["shootRange"] = CUSTOM_RANGED_SHOOT_RANGE
        dealer.setdefault("shootThreshold", CUSTOM_RANGED_SHOOT_THRESHOLD)
        dealer.setdefault("shootRedCount", CUSTOM_RANGED_SHOOT_RED_COUNT)
        tags = dealer.get("tags")
        if not isinstance(tags, list):
            tags = ["shoot_attack", "normal_damage", "basic_attack"]
        tags = [tag for tag in tags if isinstance(tag, str) and "melee" not in tag]
        for required in ("shoot_attack", "normal_damage", "basic_attack"):
            if required not in tags:
                tags.append(required)
        dealer["tags"] = tags


