def append_unique_passive(passives: list[Any], passive: dict[str, Any]) -> None:
    encoded = json.dumps(passive, sort_keys=True, ensure_ascii=False)
    for existing in passives:
        if json.dumps(existing, sort_keys=True, ensure_ascii=False) == encoded:
            return
    passives.append(passive)


def append_unique_view_passive(passives: list[dict[str, str]], name: str, description: str, **extra: str) -> None:
    passive = {"name": name, "description": description}
    passive.update(extra)
    if passive not in passives:
        passives.append(passive)


