def add_sequence_effect(item: dict[str, Any], effect: str) -> None:
    passives = item.setdefault("passives", [])
    if isinstance(passives, list):
        append_unique_passive(passives, sequence_effect_passive(effect))


def apply_countershot_attack_geometry(item: dict[str, Any], *, melee_stat_dmg_mult: float = 0.5) -> None:
    """Medusa-style shoot + melee counterAttacks. Shoot retal keeps full ranged strength."""
    shoot = copy.deepcopy(find_attack(item, "shoot") or fallback_shoot_attack())
    shoot["attackType_"] = "shoot"
    normalize_damage_dealer(shoot, False, melee=False, stat_dmg_mult=1.0)
    shoot_dealer = shoot.get("damageDealer")
    if isinstance(shoot_dealer, dict):
        shoot_dealer["triggerCounter"] = False
    melee = copy.deepcopy(
        next(
            (
                attack
                for attack in as_attack_list(item.get("counterAttacks")) + as_attack_list(item.get("alternativeAttacks"))
                if isinstance(attack, dict) and attack.get("attackType_") == "melee"
            ),
            None,
        )
        or fallback_melee_attack(False)
    )
    melee["attackType_"] = "melee"
    normalize_damage_dealer(melee, False, melee=True, stat_dmg_mult=melee_stat_dmg_mult)
    item["counterAttacks"] = [shoot, melee]


def countershot_view_attacks(custom_sid: str) -> list[dict[str, Any]]:
    return [view_attack(0, custom_sid=custom_sid), view_attack(1)]


def set_ranged_no_distance_penalty(item: dict[str, Any]) -> None:
    for attack in as_attack_list(item.get("defaultAttacks")) + as_attack_list(item.get("alternativeAttacks")) + as_attack_list(item.get("counterAttacks")):
        dealer = attack.get("damageDealer")
        if isinstance(dealer, dict) and attack.get("attackType_") == "shoot":
            dealer["shootDmgBuff"] = 0.0


def set_damage_dealer_multi_target(
    attack: dict[str, Any],
    *,
    pattern: str,
    trigger_counter: bool,
    stat_dmg_mult: float,
    damage_target: str = "enemy",
    affect_target: str = "enemy",
) -> None:
    dealer = attack.get("damageDealer")
    if not isinstance(dealer, dict):
        return
    dealer["attackPatternSid"] = pattern
    dealer["triggerCounter"] = trigger_counter
    dealer["statDmgMult"] = stat_dmg_mult
    dealer["damageTarget_"] = damage_target
    affect = dealer.setdefault("affectTargetParams", {})
    if isinstance(affect, dict):
        affect["castTarget_"] = affect_target
        affect["targetTags"] = ["unit", "attackable_object"]
        affect["targetCondition_"] = "alive"
        affect["selection"] = "object"


def apply_hydra_attack_geometry(item: dict[str, Any]) -> None:
    melee = find_attack(item, "melee") or fallback_melee_attack(False)
    melee["attackType_"] = "melee"
    normalize_damage_dealer(melee, False, melee=True)
    set_damage_dealer_multi_target(
        melee,
        pattern="attack_swipe_x100_x100",
        trigger_counter=False,
        stat_dmg_mult=1.0,
    )
    alt = find_attack(item, "melee") or fallback_melee_attack(False)
    alt["attackType_"] = "melee"
    normalize_damage_dealer(alt, False, melee=True, stat_dmg_mult=0.5)
    set_damage_dealer_multi_target(
        alt,
        pattern="attack_swirl_with_target_x100",
        trigger_counter=False,
        stat_dmg_mult=0.5,
    )
    counter = find_attack(item, "melee") or fallback_melee_attack(False)
    counter["attackType_"] = "melee"
    normalize_damage_dealer(counter, False, melee=True)
    set_damage_dealer_multi_target(
        counter,
        pattern="attack_swipe_x100_x100",
        trigger_counter=False,
        stat_dmg_mult=1.0,
    )
    item["defaultAttacks"] = [melee]
    item["alternativeAttacks"] = [alt]
    item["counterAttacks"] = [counter]


def apply_tri_reach_attack_geometry(item: dict[str, Any], *, trigger_counter: bool) -> None:
    melee = find_attack(item, "melee") or fallback_melee_attack(trigger_counter)
    melee["attackType_"] = "melee"
    normalize_damage_dealer(melee, trigger_counter, melee=True)
    set_damage_dealer_multi_target(
        melee,
        pattern="attack_reach_x2_x100_x100_x100_with_delay",
        trigger_counter=trigger_counter,
        stat_dmg_mult=1.0,
        damage_target="all",
        affect_target="noself",
    )
    counter = find_attack(item, "melee") or fallback_melee_attack(False)
    counter["attackType_"] = "melee"
    normalize_damage_dealer(counter, False, melee=True)
    item["defaultAttacks"] = [melee]
    item["alternativeAttacks"] = []
    item["counterAttacks"] = [counter]


def apply_breath_attack_geometry(attack: dict[str, Any], *, trigger_counter: bool) -> None:
    attack["attackType_"] = "melee"
    normalize_damage_dealer(attack, trigger_counter, melee=True)
    set_damage_dealer_multi_target(
        attack,
        pattern="attack_reach_x1_x100_x100_with_delay",
        trigger_counter=trigger_counter,
        stat_dmg_mult=1.0,
        damage_target="all",
        affect_target="noself",
    )


