def fortress_active_damage_dealer(
    *,
    tags: list[str],
    pattern: str = "attack_single_x100",
    cast_target: str = "enemy",
    affect_target: str = "enemy",
    damage_target: str = "none",
    damage_type: str = "none",
    stat_dmg_mult: float | None = 0.0,
    trigger_counter: bool = False,
    target_mechanics: list[dict[str, Any]] | None = None,
    buff_sid: str | None = None,
    buff_duration: int = 1,
) -> dict[str, Any]:
    dealer: dict[str, Any] = {
        "tags": tags,
        "triggerCounter": trigger_counter,
        "attackPatternSid": pattern,
        "castTargetParams": {
            "targetTags": ["unit"],
            "castTarget_": cast_target,
            "targetCondition_": "alive",
            "selection": "object",
        },
        "affectTargetParams": {
            "targetTags": ["unit"],
            "castTarget_": affect_target,
            "targetCondition_": "alive",
            "selection": "object",
        },
        "damageTarget_": damage_target,
        "damageType_": damage_type,
        "targetMechanics": target_mechanics or [],
    }
    if stat_dmg_mult is not None:
        dealer["statDmgMult"] = stat_dmg_mult
    if buff_sid:
        dealer["buffTarget_"] = "enemy"
        dealer["buff"] = {"sid": buff_sid, "duration": buff_duration}
    return dealer


