def fortress_active_ability(kind: str) -> dict[str, Any]:
    if kind == "dispel_positive":
        return {
            "attackType_": "melee",
            "rank": 1,
            "selfMechanics": [],
            "cd": 1,
            "actionCost": 0,
            "energyLevel": 1,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability", "dispel_ability"],
                damage_target="enemy",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=True,
                target_mechanics=[{"mech": "dispel", "values": ["positive"]}],
            ),
        }
    if kind == "weakening_dispel":
        return {
            "attackType_": "melee",
            "rank": 1,
            "selfMechanics": [],
            "cd": 1,
            "actionCost": 0,
            "energyLevel": 1,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability", "dispel_ability"],
                damage_target="enemy",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=True,
                target_mechanics=[{"mech": "dispel", "values": ["positive"]}],
                buff_sid="magic_shorten_shadow_effect_1",
                buff_duration=1,
            ),
        }
    if kind == "stone_gaze":
        return {
            "attackType_": "melee",
            "rank": 2,
            "selfMechanics": [],
            "cd": 2,
            "actionCost": 0,
            "energyLevel": 2,
            "damageDealer": fortress_active_damage_dealer(
                tags=["ability", "dragon_immunities", "embodiment_immunities"],
                buff_sid="medusa_stone",
                buff_duration=1,
            ),
        }
    if kind == "death_stare":
        return {
            "attackType_": "melee",
            "rank": 2,
            "selfMechanics": [],
            "cd": 2,
            "energyLevel": 2,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability"],
                pattern="attack_single_x100",
                damage_target="enemy",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=True,
                target_mechanics=[{"mech": "kill_stacks", "values": ["1", "7"]}],
            ),
        }
    if kind == "poison_max_health":
        return {
            "attackType_": "melee",
            "rank": 1,
            "selfMechanics": [],
            "cd": 1,
            "energyLevel": 1,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability", "poison"],
                damage_target="enemy",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=True,
                buff_sid="magic_fatal_decay_effect_1",
                buff_duration=1,
            ),
        }
    if kind == "poison_dot":
        return {
            "attackType_": "melee",
            "rank": 1,
            "selfMechanics": [],
            "cd": 1,
            "energyLevel": 1,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability", "poison"],
                damage_target="enemy",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=True,
                buff_sid="frog_poison",
                buff_duration=2,
            ),
        }
    if kind == "acid_debuff":
        return {
            "attackType_": "melee",
            "rank": 1,
            "selfMechanics": [],
            "cd": 1,
            "energyLevel": 1,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability", "acid"],
                damage_target="enemy",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=True,
                buff_sid="pet_debuff",
                buff_duration=2,
            ),
        }
    if kind == "double_strike":
        return {
            "attackType_": "melee",
            "rank": 1,
            "selfMechanics": [],
            "cd": 1,
            "energyLevel": 1,
            "damageDealer": fortress_active_damage_dealer(
                tags=["melee_attack", "normal_damage", "basic_attack", "ability"],
                pattern="attack_reach_x2_x100_x100_x100_with_delay",
                damage_target="all",
                damage_type="normal",
                stat_dmg_mult=1.0,
                trigger_counter=False,
            ),
        }
    raise ValueError(f"unknown Fortress active ability kind: {kind}")


def apply_fortress_active_override(ability: dict[str, Any], custom_sid: str, kind: str) -> dict[str, Any]:
    override = FORTRESS_ACTIVE_OVERRIDES_BY_SID.get(custom_sid, {}).get(kind)
    if not isinstance(override, dict):
        return ability
    if isinstance(override.get("cd"), int):
        ability["cd"] = override["cd"]
    if isinstance(override.get("energyLevel"), int):
        ability["energyLevel"] = override["energyLevel"]
    if isinstance(override.get("rank"), int):
        ability["rank"] = override["rank"]
    if isinstance(override.get("actionCost"), int):
        ability["actionCost"] = override["actionCost"]
    dealer = ability.get("damageDealer")
    if isinstance(dealer, dict):
        if "statDmgMult" in override:
            dealer["statDmgMult"] = override["statDmgMult"]
        if isinstance(override.get("targetMechanics"), list):
            dealer["targetMechanics"] = copy.deepcopy(override["targetMechanics"])
        buff = dealer.get("buff")
        if isinstance(buff, dict) and isinstance(override.get("buffDuration"), int):
            buff["duration"] = override["buffDuration"]
    return ability


def fortress_active_override_lang_rows() -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for custom_sid, by_kind in sorted(FORTRESS_ACTIVE_OVERRIDES_BY_SID.items()):
        for kind, override in sorted(by_kind.items()):
            if isinstance(override.get("name"), str):
                rows.append({"sid": f"{custom_sid}_{kind}_name", "text": str(override["name"])})
            if isinstance(override.get("description"), str):
                rows.append({"sid": f"{custom_sid}_{kind}_description", "text": str(override["description"])})
    return rows


def fortress_start_turn_regeneration(percent: float) -> dict[str, Any]:
    return {
        "actions": [
            {
                "trigger": "start_turn",
                "triggerConditions": [{"checkFunction": "allegiance", "values": ["self"]}],
                "damageDealer": {
                    "tags": ["passive", "heal_damage"],
                    "triggerCounter": False,
                    "damageTarget_": "none",
                    "statDmgMult": 0.0,
                    "attackPatternSid": "attack_single_x100",
                    "castTargetParams": {
                        "targetTags": ["unit"],
                        "castTarget_": "self",
                        "selection": "object",
                    },
                    "affectTargetParams": {
                        "targetTags": ["unit"],
                        "castTarget_": "self",
                        "selection": "object",
                    },
                    "targetMechanics": [
                        {
                            "mech": "heal_percent",
                            "values": ["without respawn", "max_unit", f"{percent:.2f}", "0.00", "true"],
                        }
                    ],
                },
            }
        ]
    }


def normalize_fortress_logic_behavior(item: dict[str, Any], custom_sid: str) -> None:
    behavior = fortress_behavior_for_sid(custom_sid)
    mode = behavior.get("attack", "melee")
    stats = item.setdefault("stats", {})
    if isinstance(stats, dict):
        if behavior.get("moveType") == "fly":
            stats["moveType"] = "fly"
        else:
            stats.pop("moveType", None)
        stats["numCounters"] = behavior.get("numCounters", 1)

    item["abilities"] = [
        apply_fortress_active_override(fortress_active_ability(kind), custom_sid, kind)
        for kind in behavior.get("abilities", ())
    ]
    item["passives"] = []
    if behavior.get("doubleRanged"):
        add_sequence_effect(item, "add_attack_after_counter_shoot")
    if behavior.get("regeneration"):
        item["passives"].append(fortress_start_turn_regeneration(float(behavior["regeneration"])))
    item.pop("aura", None)
    item.pop("globalPassives", None)

    if mode == "shoot":
        shoot = find_attack(item, "shoot")
        melee = find_attack(item, "melee") or fallback_melee_attack(True)
        if shoot is not None:
            normalize_damage_dealer(shoot, True, melee=False)
            item["defaultAttacks"] = [shoot]
        normalize_damage_dealer(melee, True, melee=True, stat_dmg_mult=0.5)
        item["alternativeAttacks"] = [melee]
        counter = find_attack(item, "melee") or fallback_melee_attack(False)
        counter["attackType_"] = "melee"
        normalize_damage_dealer(counter, False, melee=True, stat_dmg_mult=0.5)
        item["counterAttacks"] = [counter]
        if behavior.get("noRangePenalty"):
            set_ranged_no_distance_penalty(item)
        return

    trigger_counter = mode != "melee_no_retaliation"
    melee = find_attack(item, "melee") or fallback_melee_attack(trigger_counter)
    melee["attackType_"] = "melee"
    normalize_damage_dealer(melee, trigger_counter, melee=True)
    if mode == "melee_no_retaliation":
        apply_hydra_attack_geometry(item)
        return
    counter = find_attack(item, "melee") or fallback_melee_attack(False)
    counter["attackType_"] = "melee"
    normalize_damage_dealer(counter, False, melee=True)
    item["defaultAttacks"] = [melee]
    item["alternativeAttacks"] = []
    item["counterAttacks"] = [counter]


def vanilla_projectile_spec(custom_sid: str) -> dict[str, Any] | None:
    spec = VANILLA_PROJECTILE_SPECS_BY_UNIT_SID.get(custom_sid)
    return copy.deepcopy(spec) if spec else None


def apply_vanilla_projectile(attack: dict[str, Any], custom_sid: str) -> None:
    spec = vanilla_projectile_spec(custom_sid)
    if not spec:
        return
    for key in ("projectile", "projectileSpeed", "trajectory", "maxHeight"):
        if key in spec:
            attack[key] = spec[key]
        else:
            attack.pop(key, None)


def view_attack(animation_index: int = 0, *, custom_sid: str | None = None) -> dict[str, Any]:
    attack = {"animationIndex": animation_index}
    if custom_sid:
        apply_vanilla_projectile(attack, custom_sid)
    return attack


def ranged_melee_view_attack(animation_index: int = 1) -> dict[str, Any]:
    attack = view_attack(animation_index)
    attack.update(
        {
            "name": "h3_common_melee_attack_name",
            "description": "h3_common_melee_attack_description",
            "abilityType": "Ability_type_attack_alt",
            "infoDescription": "ability_no_energy",
            "canShowOnUI": True,
            "useExpandTooltip": "false",
        }
    )
    return attack


def long_reach_view_attack(animation_index: int = 1) -> dict[str, Any]:
    attack = view_attack(animation_index)
    attack.update(
        {
            "name": "base_passive_remote_attack_name",
            "description": "base_passive_remote_attack_description",
            "abilityType": "Ability_type_attack_alt",
            "infoDescription": "ability_no_energy",
            "canShowOnUI": True,
            "useExpandTooltip": "false",
        }
    )
    return attack


