def castle_unit_sids_for_line(line: dict[str, Any]) -> list[str]:
    return [line["base"], line["base"] + "_upg", line["base"] + "_upg_alt"]


def castle_behavior_for_sid(custom_sid: str) -> dict[str, Any]:
    base_sid = custom_sid.removesuffix("_upg_alt").removesuffix("_upg")
    behavior: dict[str, Any] = {"attack": "melee", "moveType": "ground", "numCounters": 1, "debt": ()}
    if base_sid in {"h3_archer", "h3_monk"}:
        behavior.update({"attack": "shoot", "meleePenalty": 0.5, "debt": ("ammunition limits", "range penalties")})
    if base_sid in {"h3_griffin", "h3_angel"}:
        behavior.update({"moveType": "fly"})
    if custom_sid == "h3_griffin":
        behavior.update({"numCounters": 2, "debt": ("retaliation capacity live validation",)})
    if custom_sid == "h3_griffin_upg":
        behavior.update({"numCounters": 999, "debt": ("unlimited retaliation live validation",)})
    if custom_sid == "h3_swordsman_upg_alt":
        behavior.update({"numCounters": 2, "debt": ("additional retaliation live validation",)})
    if custom_sid in {"h3_monk_upg", "h3_monk_upg_alt"}:
        behavior.update({"meleePenalty": 1.0, "debt": ("HotA attack-mode UI",)})
    castle_debt = {
        "h3_pikeman": ("jousting immunity",),
        "h3_pikeman_upg": ("jousting immunity",),
        "h3_pikeman_upg_alt": ("charge/jousting immunity",),
        "h3_archer_upg": ("double ranged attack", "ammunition limits"),
        "h3_archer_upg_alt": ("no-range penalty", "Defense reduction on attack"),
        "h3_griffin_upg_alt": ("Battle Griffin double attack/ferocity timing",),
        "h3_swordsman_upg": ("Crusader second-strike timing",),
        "h3_monk_upg_alt": ("Priest Bless creature spell action",),
        "h3_cavalier": ("per-hex jousting damage",),
        "h3_cavalier_upg": ("per-hex jousting damage",),
        "h3_cavalier_upg_alt": ("per-hex jousting damage", "Attack reduction on attack"),
        "h3_angel": ("Devil hatred", "persistent army morale"),
        "h3_angel_upg": ("Archangel resurrection", "Devil hatred", "persistent army morale"),
        "h3_angel_upg_alt": ("Seraph Prayer creature spell action", "extended hatred", "persistent army morale"),
    }.get(custom_sid)
    if castle_debt:
        behavior["debt"] = tuple(dict.fromkeys(tuple(behavior.get("debt", ())) + castle_debt))
    return behavior


def apply_castle_unit_target_stats(item: dict[str, Any], custom_sid: str) -> None:
    target = CASTLE_UNIT_TARGET_STATS.get(custom_sid)
    if not target:
        return
    stats = item.get("stats")
    if not isinstance(stats, dict):
        raise RuntimeError(f"{custom_sid}: balance adjustment target stats is missing or malformed")
    for key in ("hp", "offence", "defence", "damageMin", "damageMax", "initiative", "speed"):
        stats[key] = target[key]
    if "squadValue" in target:
        item["squadValue"] = target["squadValue"]
    cost = target.get("cost")
    if isinstance(cost, dict):
        item["unitCost"] = {
            "costResArray": [{"name": resource, "cost": value} for resource, value in cost.items()]
        }
    apply_homm3_unit_balance_logic_adjustment(item, custom_sid)


def castle_implemented_mechanics(custom_sid: str) -> list[str]:
    implemented: list[str] = []
    if custom_sid == "h3_angel_upg":
        implemented.append("2-focus Rewind Life creature action")
    if custom_sid == "h3_archer_upg":
        implemented.append("double ranged attack")
    if custom_sid in {"h3_swordsman_upg", "h3_griffin_upg_alt"}:
        implemented.append("double melee attack")
    if custom_sid == "h3_archer_upg_alt":
        implemented.append("no range or obstacle penalty")
    if custom_sid in {"h3_griffin", "h3_griffin_upg", "h3_swordsman_upg_alt"}:
        implemented.append("retaliation capacity")
    return implemented


def remaining_castle_source_differences(custom_sid: str) -> list[str]:
    differences = list(castle_behavior_for_sid(custom_sid).get("debt", ()))
    implemented = castle_implemented_mechanics(custom_sid)
    if "2-focus Rewind Life creature action" in implemented:
        differences = [item for item in differences if item != "Archangel resurrection"]
    if "double ranged attack" in implemented:
        differences = [item for item in differences if item != "double ranged attack"]
    if "double melee attack" in implemented:
        differences = [item for item in differences if item not in {"Crusader second-strike timing", "Battle Griffin double attack/ferocity timing"}]
    if "no range or obstacle penalty" in implemented:
        differences = [item for item in differences if item not in {"no-range penalty", "range penalties"}]
    if "retaliation capacity" in implemented:
        differences = [item for item in differences if "retaliation" not in item]
    return differences


def normalize_castle_logic_behavior(item: dict[str, Any], custom_sid: str) -> None:
    behavior = castle_behavior_for_sid(custom_sid)
    mode = behavior.get("attack", "melee")
    stats = item.setdefault("stats", {})
    if isinstance(stats, dict):
        if behavior.get("moveType") == "fly":
            stats["moveType"] = "fly"
        else:
            stats.pop("moveType", None)
        stats["numCounters"] = behavior.get("numCounters", 1)
    item["abilities"] = []
    item["passives"] = []
    item.pop("aura", None)
    item.pop("globalPassives", None)
    if custom_sid == "h3_angel_upg":
        item["abilities"].append(make_rewind_life_creature_ability())
    if custom_sid == "h3_archer_upg":
        item["passives"].append(sequence_effect_passive("add_attack_after_counter_shoot"))
    if custom_sid in {"h3_swordsman_upg", "h3_griffin_upg_alt"}:
        item["passives"].append(sequence_effect_passive("add_attack_after_counter_melee"))
    if mode == "shoot":
        shoot = find_attack(item, "shoot")
        melee = find_attack(item, "melee") or fallback_melee_attack(True)
        if shoot is not None:
            normalize_damage_dealer(shoot, True, melee=False)
            item["defaultAttacks"] = [shoot]
        normalize_damage_dealer(melee, True, melee=True, stat_dmg_mult=float(behavior.get("meleePenalty", 0.5)))
        item["alternativeAttacks"] = [melee]
        counter = find_attack(item, "melee") or fallback_melee_attack(False)
        counter["attackType_"] = "melee"
        normalize_damage_dealer(counter, False, melee=True, stat_dmg_mult=float(behavior.get("meleePenalty", 0.5)))
        item["counterAttacks"] = [counter]
        if custom_sid == "h3_archer_upg_alt":
            set_ranged_no_distance_penalty(item)
        return
    melee = find_attack(item, "melee") or fallback_melee_attack(True)
    melee["attackType_"] = "melee"
    normalize_damage_dealer(melee, True, melee=True)
    counter = find_attack(item, "melee") or fallback_melee_attack(False)
    counter["attackType_"] = "melee"
    normalize_damage_dealer(counter, False, melee=True)
    item["defaultAttacks"] = [melee]
    item["alternativeAttacks"] = []
    item["counterAttacks"] = [counter]


def normalize_castle_unit_logic(doc: Any, custom_sid: str, line: dict[str, Any], suffix_index: int, faction_sid: str) -> Any:
    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc
    scaffold = manifest_release_scaffold(CASTLE_MANIFEST)
    item["id"] = custom_sid
    item["fraction"] = faction_sid
    item["nativeBiome"] = scaffold["biome"]
    item["tier"] = line["tier"]
    if suffix_index == 0:
        item.pop("baseSid", None)
    else:
        item["baseSid"] = line["base"] if suffix_index == 1 else line["base"] + "_upg"
    if suffix_index == 0:
        item["upgradeSid"] = line["base"] + "_upg"
    elif suffix_index == 1:
        item["upgradeSid"] = line["base"] + "_upg_alt"
    else:
        item.pop("upgradeSid", None)
    tags = item.get("tags")
    if isinstance(tags, list):
        item["tags"] = [faction_sid if tag in {"human", "humans"} else tag for tag in tags]
        if faction_sid not in item["tags"]:
            item["tags"].append(faction_sid)
    apply_castle_unit_target_stats(item, custom_sid)
    normalize_castle_logic_behavior(item, custom_sid)
    item["xHomm3CastleQuality"] = {
        "source": "docs/homm3_faction_plans/castle.md",
        "implementedData": "HotA/ToA stats, cost, squad value, faction/native biome, baseline attack role, upgrade chain",
        "implementedMechanics": castle_implemented_mechanics(custom_sid),
    }
    return doc


def normalize_castle_view_behavior(item: dict[str, Any], custom_sid: str) -> None:
    behavior = castle_behavior_for_sid(custom_sid)
    mode = behavior.get("attack", "melee")
    passives: list[dict[str, str]] = []
    if mode == "shoot":
        passives.append({"name": "h3_common_ranged_attack_name", "description": "h3_common_ranged_attack_description"})
    else:
        passives.append({"name": "h3_common_melee_attack_name", "description": "h3_common_melee_attack_description"})
    if behavior.get("moveType") == "fly":
        passives.append({"name": "base_passive_flyer_name", "description": "base_passive_flyer_description"})
    if behavior.get("numCounters", 1) > 1:
        if behavior.get("numCounters", 1) >= 999:
            passives.append({"name": "base_passive_aware_2_name", "description": "base_passive_aware_2_description"})
        else:
            passives.append({"name": "base_passive_aware_1_name", "description": "base_passive_aware_1_description"})
    if custom_sid in {"h3_cavalier", "h3_cavalier_upg", "h3_cavalier_upg_alt"}:
        passives.append(
            {
                "name": "h3_castle_passive_jousting_charge_name",
                "description": "h3_castle_passive_jousting_charge_description",
            }
        )
    if custom_sid == "h3_archer_upg":
        passives.append({"name": "base_passive_double_strike_ranged_attack_name", "description": "base_passive_double_strike_ranged_attack_description"})
    if custom_sid in {"h3_swordsman_upg", "h3_griffin_upg_alt"}:
        passives.append({"name": "base_passive_double_strike_name", "description": "base_passive_double_strike_description"})
    if mode == "shoot" and float(behavior.get("meleePenalty", 0.5)) >= 1.0:
        passives.append({"name": "base_passive_duelist_name", "description": "base_passive_duelist_description"})
    if custom_sid == "h3_archer_upg_alt":
        passives.append({"name": "base_passive_sharpshooter_name", "description": "base_passive_sharpshooter_description"})
    item["abilities"] = []
    if custom_sid == "h3_angel_upg":
        item["abilities"].append(
            {
                "name": "h3_castle_ability_rewind_life_name",
                "abilityType": "Ability_type_heal",
                "description": "h3_castle_ability_rewind_life_description",
                "animationIndex": 2,
                "useExpandTooltip": "false",
            }
        )
    item["passives"] = passives
    item["defaultAttacks"] = [view_attack(0, custom_sid=custom_sid if mode == "shoot" else None)]
    item["counterAttacks"] = [view_attack(0)]
    item["alternativeAttacks"] = [ranged_melee_view_attack(1)] if mode == "shoot" else []
    item["xHomm3CastleQuality"] = {
        "source": "docs/homm3_faction_plans/castle.md",
        "implementedData": "HotA/ToA stats, baseline attack role, honest preview text",
        "implementedMechanics": castle_implemented_mechanics(custom_sid),
    }


def normalize_castle_unit_view(doc: Any, custom_sid: str) -> Any:
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = custom_sid
        normalize_castle_view_behavior(item, custom_sid)
    return doc


def normalize_castle_city_building_presentation(doc: Any) -> Any:
    source_levels = generic_building_source_levels(CASTLE_MANIFEST)

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            sid = value.get("sid")
            icons = value.get("icons")
            if isinstance(sid, str) and sid.startswith("Build_") and isinstance(icons, list):
                names = value.get("names")
                descriptions = value.get("descriptions")
                count = max(
                    len(icons),
                    len(names) if isinstance(names, list) else 0,
                    len(descriptions) if isinstance(descriptions, list) else 0,
                )
                if sid in source_levels:
                    value["icons"] = [castle_building_icon_key(sid, index + 1) for index in range(count)]
                value["names"] = [castle_building_text_key(sid, "name", index + 1, count) for index in range(count)]
                value["descriptions"] = [
                    castle_building_text_key(sid, "description", index + 1, count)
                    for index in range(count)
                ]
                value["narrativeDescriptions"] = [
                    castle_building_text_key(sid, "narrativeDescription", index + 1, count)
                    for index in range(count)
                ]
            for item in value.values():
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(doc)
    return doc


def normalize_castle_city_doc(doc: Any, manifest: dict[str, Any]) -> Any:
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = identity["citySid"]
        item["sceneName"] = manifest_custom_city_scene_name(manifest)
        item["fraction"] = identity["factionSid"]
        apply_homm3_dwelling_cost_tree(item, manifest)
        normalize_castle_city_building_presentation(doc)
        apply_homm3_special_building_node_pos(doc, manifest)
        for section in item.values():
            if not isinstance(section, list):
                continue
            for row in section:
                if not isinstance(row, dict):
                    continue
                if row.get("sid") == "Build_Magic_Guild":
                    trim_building_levels(row, 4)
                if isinstance(row.get("sid"), str) and row["sid"].startswith("Build_Tier_"):
                    try:
                        tier = int(row["sid"].rsplit("_", 1)[1])
                    except ValueError:
                        continue
                    if 1 <= tier <= len(CASTLE_UNIT_LINES):
                        normalize_unit_hire_payload(row.get("unitsHire"), CASTLE_UNIT_LINES[tier - 1])
        apply_city_building_mechanics(doc, manifest)
        align_owned_world_city_scene_slots(doc, manifest)
        strip_unbound_castle_slot_buildings_from_owned_world_city(doc, manifest)
        apply_homm3_city_building_tree(doc, manifest)
    return doc


def make_castle_fraction_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> dict[str, Any]:
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    donor_core_faction_sid = manifest_donor_core_faction_sid(manifest)
    _, doc = find_array_doc_by_id(release_zip, "DB/fractions/", donor_core_faction_sid)
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = identity["factionSid"]
        item["name"] = identity["displayNameToken"]
        item["desc"] = identity["descriptionToken"]
        item["narrativeDesc"] = identity["descriptionToken"]
        item["icon"] = scaffold["factionIcon"]
        item["iconFractionLaws"] = scaffold["factionLawIcon"]
        item["biome"] = scaffold["biome"]
        item["resourceName"] = "wood"
        item["cityNames"] = homm3_town_name_tokens(identity)
        item["fractionLawsLines"] = remap_string_tokens(
            item.get("fractionLawsLines"),
            {f"fraction_law_{donor_core_faction_sid}_": manifest_law_prefix(manifest)},
        )
    return doc


def add_release_castle_units(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = CASTLE_MANIFEST
    faction_sid = manifest["identity"]["factionSid"]
    changed = 0
    for line in CASTLE_UNIT_LINES:
        donor_faction = line["donor_faction"]
        donor_base = line["donor"]
        for suffix_index, suffix in enumerate(CASTLE_SUFFIXES):
            donor_sid = donor_base + suffix
            custom_sid = line["base"] + suffix
            logic_name = f"DB/units/units_logics/{donor_faction}/{donor_sid}_l.json"
            view_name = f"DB/units/units_views/{donor_faction}/{donor_sid}_v.json"
            target_logic = f"DB/units/units_logics/{faction_sid}/{custom_sid}_l.json"
            target_view = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                logic = normalize_castle_unit_logic(read_json(release_zip, logic_name), custom_sid, line, suffix_index, faction_sid)
                view = normalize_castle_unit_view(read_json(release_zip, view_name), custom_sid)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing Castle donor {donor_sid}: {ex}")
                continue
            output[target_logic] = write_json(logic)
            output[target_view] = write_json(view)
            changed += 2
    if changed:
        notes.append(f"generate Castle unit logic/view rows ({changed})")


def normalize_castle_squad_doc(value: Any, donor_faction_sid: str, faction_sid: str) -> Any:
    if isinstance(value, str):
        if value in CASTLE_SQUAD_UNIT_REPLACEMENTS:
            return CASTLE_SQUAD_UNIT_REPLACEMENTS[value]
        if value == donor_faction_sid:
            return faction_sid
        return value.replace(f"squad_{donor_faction_sid}", f"squad_{faction_sid}").replace(
            f"squads_{donor_faction_sid}",
            f"squads_{faction_sid}",
        )
    if isinstance(value, list):
        return [normalize_castle_squad_doc(item, donor_faction_sid, faction_sid) for item in value]
    if isinstance(value, dict):
        return {key: normalize_castle_squad_doc(item, donor_faction_sid, faction_sid) for key, item in value.items()}
    return value


def add_release_castle_squads(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = CASTLE_MANIFEST
    identity = manifest["identity"]
    donor_faction_sid = manifest_donor_core_faction_sid(manifest)
    faction_sid = identity["factionSid"]
    source_prefix = f"DB/squads/squads_{donor_faction_sid}/"
    target_prefix = manifest_core_member(manifest, "squadTree")
    changed = 0
    for info in release_zip.infolist():
        source_name = normalize_name(info.filename)
        if info.is_dir() or not source_name.startswith(source_prefix) or not source_name.endswith(".json"):
            continue
        target_name = target_prefix + source_name[len(source_prefix) :].replace(
            f"squad_{donor_faction_sid}",
            f"squad_{faction_sid}",
        )
        try:
            doc = normalize_castle_squad_doc(read_json(release_zip, source_name), donor_faction_sid, faction_sid)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing Castle squad donor {source_name}: {ex}")
            continue
        output[target_name] = write_json(doc)
        changed += 1
    if changed:
        notes.append(f"generate Castle squad tree from Human donor ({changed})")


def make_castle_laws_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> dict[str, Any]:
    donor_fraction_sid = manifest_donor_fraction_sid(manifest)
    law_prefix = manifest_law_prefix(manifest)
    donor_doc = read_json(release_zip, f"DB/fractions_laws/fractions_laws_table_{donor_fraction_sid}.json")
    rows = donor_doc.get("array") if isinstance(donor_doc, dict) else None
    if not isinstance(rows, list):
        raise RuntimeError(f"Castle donor law table {donor_fraction_sid} is missing array rows")
    donor_by_index: dict[int, dict[str, Any]] = {}
    for row in rows:
        if not isinstance(row, dict):
            raise RuntimeError(f"Castle donor law table {donor_fraction_sid} contains a non-object row")
        donor_id = str(row.get("id") or "")
        suffix = donor_id.removeprefix(f"fraction_law_{donor_fraction_sid}_")
        if suffix.isdigit():
            donor_by_index[int(suffix)] = row

    indices, _omitted_indices = custom_law_indices_to_emit(manifest, len(rows))
    output_rows: list[dict[str, Any]] = []
    for index in indices:
        copied = copy.deepcopy(donor_by_index.get(index, {}))
        override_definition = None if index in RESOURCE_RICHES_LAW_ICONS else custom_law_override_definition(manifest, index)
        name, desc, levels = override_definition or custom_law_definition(manifest, index)
        copied.update(
            {
                "id": f"{law_prefix}{index}",
                "icon": custom_law_icon(manifest, rows, index),
                "name": f"{law_prefix}{index}_name",
                "desc": f"{law_prefix}{index}_desc",
                "parametersPerLevel": levels,
            }
        )
        stamp_no_compromise_law_target_metadata(copied, copied["id"])
        if override_definition is not None:
            copied["xHomm3LawOverride"] = True
        output_rows.append(copied)
    return {"array": output_rows}


def normalize_castle_skill_refs(value: Any, manifest: dict[str, Any]) -> Any:
    if isinstance(value, str):
        return generic_skill_ref_replacements(manifest).get(value, value)
    if isinstance(value, list):
        return [normalize_castle_skill_refs(item, manifest) for item in value]
    if isinstance(value, dict):
        return {key: normalize_castle_skill_refs(item, manifest) for key, item in value.items()}
    return value

def make_castle_subclasses_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> Any:
    donor_faction_sid = manifest_donor_core_faction_sid(manifest)
    faction_sid = manifest["identity"]["factionSid"]
    doc = read_json(release_zip, f"DB/heroes_sub_classes/sub_classes_{donor_faction_sid}.json")
    rows = doc.get("array") if isinstance(doc, dict) else None
    if not isinstance(rows, list):
        return doc
    counts: dict[str, int] = {"might": 0, "magic": 0}
    castle_rows: list[Any] = []
    for donor in rows:
        if not isinstance(donor, dict):
            continue
        class_type = str(donor.get("classType") or "might").strip().lower()
        if class_type not in counts:
            class_type = "might"
        counts[class_type] += 1
        subclass_sid = f"sub_class_{faction_sid}_{class_type}_{counts[class_type]}"
        row = json.loads(json.dumps(donor, ensure_ascii=False))
        row["id"] = subclass_sid
        row["icon"] = subclass_sid + "_icon"
        row["name"] = subclass_sid + "_name"
        row["desc"] = subclass_sid + "_desc"
        row["faction"] = faction_sid
        row["classType"] = class_type
        castle_rows.append(normalize_castle_skill_refs(row, manifest))
    return {"array": castle_rows}


def make_castle_specializations_doc(manifest: dict[str, Any]) -> Any:
    return make_custom_faction_specializations_doc(manifest)


def add_release_castle_map_objects(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = CASTLE_MANIFEST
    identity = manifest["identity"]
    faction_sid = identity["factionSid"]
    donor_faction_sid = identity["donorFactionSid"]
    donor_city_sid = identity["donorCitySid"]
    direct_city_sid = manifest_direct_city_sid(manifest)
    map_name = "DB/map/objects/4_interactables.json"
    hires_name = "DB/objects_logic/hires/barracks.json"
    try:
        map_doc = json.loads(output[map_name].decode("utf-8-sig")) if map_name in output else read_json(release_zip, map_name)
        hires_doc = json.loads(output[hires_name].decode("utf-8-sig")) if hires_name in output else read_json(release_zip, hires_name)
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append("warn missing Castle dwelling target: " + str(ex))
        return

    map_changed = False
    hire_changed = False
    donor_city = next((row for row in map_doc.get("array", []) if isinstance(row, dict) and row.get("id") == donor_city_sid), None)
    if donor_city is not None:
        row = json.loads(json.dumps(donor_city, ensure_ascii=False))
        row["id"] = direct_city_sid
        donor_prefs = cloned_map_object_prefs(donor_city)
        if donor_prefs is not None:
            row["prefs"] = donor_prefs
        map_changed = upsert_array_row(map_doc, row) or map_changed

    for tier, line in enumerate(CASTLE_UNIT_LINES, start=1):
        donor_dwelling_sid = manifest_primary_donor_dwelling_sid(manifest, tier)
        direct_dwelling_sid = manifest_direct_dwelling_sid(manifest, tier)
        donor_map = next((row for row in map_doc.get("array", []) if isinstance(row, dict) and row.get("id") == donor_dwelling_sid), None)
        if donor_map is not None:
            row = json.loads(json.dumps(donor_map, ensure_ascii=False))
            row["id"] = direct_dwelling_sid
            row["prefs"] = [f"barracks/{donor_dwelling_sid}"]
            map_changed = upsert_array_row(map_doc, row) or map_changed

        donor_hire = next((row for row in hires_doc.get("array", []) if isinstance(row, dict) and row.get("id") == donor_dwelling_sid), None)
        if donor_hire is not None:
            row = remap_string_tokens(json.loads(json.dumps(donor_hire, ensure_ascii=False)), {donor_faction_sid: faction_sid})
            row["id"] = direct_dwelling_sid
            row["fraction"] = faction_sid
            normalize_unit_hire_payload(row.get("unitsData"), line)
            for bonus in row.get("bonuses", []) if isinstance(row.get("bonuses"), list) else []:
                if isinstance(bonus, dict) and bonus.get("type") == "cityUnitsIncrementFromBarrack":
                    parameters = bonus.get("parameters")
                    if isinstance(parameters, list) and parameters:
                        parameters[0] = line["base"]
            for guard in row.get("guardUnits", []) if isinstance(row.get("guardUnits"), list) else []:
                if isinstance(guard, dict):
                    guard["sid"] = line["base"]
            hire_changed = upsert_array_row(hires_doc, row) or hire_changed

    map_changed = dedupe_array_rows_by_id(map_doc) or map_changed
    hire_changed = dedupe_array_rows_by_id(hires_doc) or hire_changed
    if map_changed:
        output[map_name] = write_json(map_doc)
        notes.append("merge Castle city and external barracks map objects")
    if hire_changed:
        output[hires_name] = write_json(hires_doc)
        notes.append("merge Castle external barracks hire rows")


def add_release_castle_heroes_and_tables(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = CASTLE_MANIFEST
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    faction_sid = identity["factionSid"]
    hero_sources = donor_hero_sources(release_zip, manifest)
    if not hero_sources:
        notes.append(f"warn missing Castle hero donors for {manifest_donor_fraction_sid(manifest)}")
    changed = 0
    for index in range(1, 19):
        if not hero_sources:
            break
        hero_sid = manifest_hero_sid(manifest, index)
        source_name = hero_sources[(index - 1) % len(hero_sources)]
        target_name = f"DB/heroes/{faction_sid}/{hero_sid}.json"
        try:
            doc = read_json(release_zip, source_name)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing Castle hero donor {source_name}: {ex}")
            continue
        item = first_array_item(doc)
        if isinstance(item, dict):
            item["id"] = hero_sid
            item["icon"] = manifest_hero_icon_sid(manifest, index)
            item["fraction"] = faction_sid
            item["nativeBiome"] = scaffold["biome"]
            item["classType"] = "might" if index <= 8 else "magic"
            item["className"] = manifest_hero_class_name(manifest, item["classType"])
            item["classIcon"] = f"sub_class_{faction_sid}_{item['classType']}_1_icon"
            item["skillsRollVariant"] = manifest_skill_table_sid(manifest, item["classType"])
            item["name"] = f"{hero_sid}_name"
            item["specialization"] = f"{hero_sid}_specialization"
            item["startSquad"] = [
                {"sid": "h3_pikeman", "min": 14, "max": 20},
                {"sid": "h3_archer", "min": 8, "max": 12},
                {"sid": "h3_griffin", "min": 3, "max": 5},
            ]
            item["startSquadAlt"] = [{"sid": "h3_pikeman", "min": 1, "max": 1}]
            item["startSkills"] = prepend_custom_start_faction_skill(
                [
                    {"sid": "skill_leadership" if index <= 8 else "skill_magic_primal", "skillLevel": 1},
                ],
                manifest,
            )
        output[target_name] = write_json(normalize_castle_skill_refs(doc, manifest))
        changed += 1

    table_pairs = tuple(
        (
            f"DB/heroes_skills/skills_by_level_tables/{manifest_donor_skill_table_sid(manifest, class_type, arena)}.json",
            f"DB/heroes_skills/skills_by_level_tables/{manifest_skill_table_sid(manifest, class_type, arena)}.json",
        )
        for arena in (False, True)
        for class_type in ("might", "magic")
    )
    for source_name, target_name in table_pairs:
        try:
            output[target_name] = write_json(normalize_castle_skill_refs(read_json(release_zip, source_name), manifest))
            changed += 1
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing Castle skill table donor {source_name}: {ex}")
    try:
        output[manifest_core_member(manifest, "heroSubClasses")] = write_json(make_castle_subclasses_doc(release_zip, manifest))
        changed += 1
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append(f"warn missing Castle subclass donor: {ex}")
    output[manifest_core_member(manifest, "heroSpecializations")] = write_json(make_castle_specializations_doc(manifest))
    changed += 1
    if changed:
        notes.append(f"generate Castle hero/skill-table rows ({changed})")


def add_release_castle_lang(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = CASTLE_MANIFEST
    identity = manifest["identity"]
    law_prefix = manifest_law_prefix(manifest)
    faction_rows = [
        {"sid": identity["displayNameToken"], "text": "Castle (HoMM3)"},
        {"sid": identity["descriptionToken"], "text": "The Castle fields disciplined human armies led by knights and clerics, combining archers, griffins, cavalry, morale support, and angelic power."},
        {"sid": f"{identity['citySid']}_name", "text": "Castle"},
    ]
    faction_rows += homm3_town_name_lang_rows(identity, "Castle")
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/fractions.json", faction_rows, notes)
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/factionLaws.json", custom_law_lang_rows(manifest, release_zip), notes)
    unit_rows: list[dict[str, str]] = []
    for line in CASTLE_UNIT_LINES:
        for suffix, name in zip(CASTLE_SUFFIXES, line["names"]):
            sid = line["base"] + suffix
            unit_rows.append({"sid": sid + "_name", "text": name})
            unit_rows.append(
                {
                    "sid": sid + "_narrativeDescription",
                    "text": CASTLE_UNIT_NARRATIVE_DESCRIPTIONS.get(sid, name + " serves the HoMM3 Castle line."),
                }
            )
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/units.json", unit_rows, notes)
    add_lang_overlay_rows(
        release_zip,
        output,
        "Lang/english/texts/unitsAbility.json",
        [
            {"sid": "h3_castle_ability_rewind_life_name", "text": "Rewind Life"},
            {"sid": "h3_castle_ability_rewind_life_description", "text": "Spend 2 Focus to revive an allied stack using the native Rewind Life effect."},
        ],
        notes,
    )
    building_rows: list[dict[str, str]] = []
    for building_sid, levels in CASTLE_BUILDING_TEXT.items():
        level_count = len(levels)
        for level, (name, description) in enumerate(levels, start=1):
            building_rows.append({"sid": castle_building_text_key(building_sid, "name", level, level_count), "text": name})
            building_rows.append({"sid": castle_building_text_key(building_sid, "description", level, level_count), "text": description})
            building_rows.append({"sid": castle_building_text_key(building_sid, "narrativeDescription", level, level_count), "text": description})
    try:
        ensure_city_building_lang_rows(
            building_rows,
            manifest,
            normalize_castle_city_doc(read_json(release_zip, f"DB/objects_logic/cities/{identity['donorCitySid']}.json"), manifest),
            castle_building_text_key,
            CASTLE_BUILDING_TEXT,
        )
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
        pass
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/cities.json", building_rows, notes)
    map_object_rows: list[dict[str, str]] = []
    for tier, (name, description) in enumerate(CASTLE_EXTERNAL_DWELLING_TEXT, start=1):
        dwelling_sid = manifest_direct_dwelling_sid(manifest, tier)
        map_object_rows.append({"sid": f"{dwelling_sid}_name", "text": name})
        map_object_rows.append({"sid": f"{dwelling_sid}_description", "text": description})
        map_object_rows.append({"sid": f"{dwelling_sid}_narrativeDescription", "text": description})
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/mapObjects.json", map_object_rows, notes)
    hero_rows = [{"sid": f"{manifest_hero_sid(manifest, index)}_name", "text": CASTLE_HERO_NAMES[index]} for index in sorted(CASTLE_HERO_NAMES)]
    hero_rows += [
        {"sid": f"{manifest_hero_sid(manifest, index)}_specialization", "text": custom_hero_specialization_text(manifest, index)[0]}
        for index in sorted(CASTLE_HERO_NAMES)
    ]
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroes.json", hero_rows, notes)
    hero_info_rows: list[dict[str, str]] = []
    for index in sorted(CASTLE_HERO_NAMES):
        hero_sid = manifest_hero_sid(manifest, index)
        spec_name, spec_description = custom_hero_specialization_text(manifest, index)
        hero_info_rows.append({"sid": f"{hero_sid}_spec_name", "text": spec_name})
        hero_info_rows.append({"sid": f"{hero_sid}_spec_description", "text": spec_description})
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroInfo.json", hero_info_rows, notes)
    subclass_rows: list[dict[str, str]] = []
    skill_sid = manifest_faction_skill_sid(manifest)
    skill_name, skill_desc, rank_descs = GENERIC_FACTION_SKILL_TEXT[identity["factionSid"]]
    subclass_rows.append({"sid": f"{skill_sid}_name", "text": skill_name})
    subclass_rows.append({"sid": f"{skill_sid}_desc", "text": skill_desc})
