def apply_homm3_mage_guild_level_5_extension(doc: Any, manifest: dict[str, Any]) -> Any:
    faction_sid = manifest["identity"]["factionSid"]
    if faction_sid not in HOMM3_MAGE_GUILD_EXTEND_TO_LEVEL_5_FACTIONS:
        return doc
    if manifest["identity"]["donorCitySid"] != "human_city":
        raise RuntimeError(f"{faction_sid}: Mage Guild level-5 extension expects the human_city donor")
    for row in collect_city_building_config_rows(doc):
        if row.get("sid") != "Build_Magic_Guild":
            continue
        levels = row.get("parametersPerLevel")
        if not isinstance(levels, list) or len(levels) != 4:
            raise RuntimeError(f"{faction_sid}: Mage Guild level-5 extension expects 4 donor levels")
        levels.append({"prevBuildings": [{"sid": "Build_Magic_Guild", "level": 4}], "costs": [dict(cost) for cost in HOMM3_MAGE_GUILD_LEVEL_5_COSTS]})
        chances = row.get("rollChances")
        if not isinstance(chances, list):
            raise RuntimeError(f"{faction_sid}: Mage Guild has no rollChances")
        present = {chance.get("sid") for chance in chances if isinstance(chance, dict)}
        chances.extend({"sid": sid, "chance": chance} for sid, chance in HOMM3_MAGE_GUILD_LEVEL_5_HUMAN_DONOR_ROLL_CHANCES if sid not in present)
        # icons are rebuilt per level by normalize_generic_city_building_presentation.
        for key in ("names", "descriptions", "narrativeDescriptions", "backgroundImages"):
            value = row.get(key)
            if not isinstance(value, list) or len(value) < 5:
                raise RuntimeError(f"{faction_sid}: Mage Guild {key} has no level-5 entry")
    return doc


def apply_homm3_city_building_tree(doc: Any, manifest: dict[str, Any]) -> Any:
    """Own every prevBuildings, nodePos and buildOrders entry of a HoMM3 city.

    Runs last in each city normalizer, after every row has been added, trimmed or
    stripped, so the canonical HoMM3 tree covers exactly the levels the city ships.
    Fails closed when a level has no canonical entry or the tree cannot be drawn.
    """
    faction_sid = manifest["identity"]["factionSid"]
    if faction_sid not in HOMM3_CITY_TREE_FACTIONS:
        raise RuntimeError(f"{faction_sid}: no canonical HoMM3 building tree in homm3_city_building_tree.py")
    item = first_array_item(doc)
    if not isinstance(item, dict):
        raise RuntimeError(f"{faction_sid}: city document has no array item for the building tree")
    try:
        apply_canonical_city_building_tree(item, faction_sid)
    except ValueError as ex:
        raise RuntimeError(f"{faction_sid}: canonical HoMM3 building tree does not apply: {ex}") from ex
    assert_city_construction_tree_node_pos_unique(doc, faction_sid)
    assert_city_construction_tree_layout(doc, faction_sid)
    return doc


def refresh_homm3_derived_city_docs(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Re-derive campaign city clones (homm3_landon_*_city) from the stock city just built.

    The campaign installer clones the installed stock city row with only its id changed
    (experiments/campaign_port_poc/approach_cell/surface_emit.py clone_core_object_row).
    Re-deriving here keeps those clones on the same building tree as the stock city
    instead of the tree that was installed when the campaign was last emitted.
    """
    names = set(release_zip.namelist())
    for clone_sid, donor_sid in sorted(DERIVED_HOMM3_CITY_DONORS.items()):
        clone_member = f"DB/objects_logic/cities/{clone_sid}.json"
        donor_member = f"DB/objects_logic/cities/{donor_sid}.json"
        if clone_member not in names and clone_member not in output:
            continue
        if donor_member not in output:
            raise RuntimeError(f"{clone_sid}: stock donor {donor_sid} was not generated by this overlay")
        doc = json.loads(output[donor_member].decode("utf-8-sig"))
        item = first_array_item(doc)
        if not isinstance(item, dict) or item.get("id") != donor_sid:
            raise RuntimeError(f"{clone_sid}: generated donor row id mismatch for {donor_sid}")
        item["id"] = clone_sid
        output[clone_member] = write_json(doc)
        notes.append(f"re-derive {clone_sid} from generated {donor_sid} (id only differs)")
def ensure_city_building_lang_rows(
    rows: list[dict[str, str]],
    manifest: dict[str, Any],
    city_doc: Any,
    key_func: Any,
    text_by_building: dict[str, list[tuple[str, str]]] | None = None,
) -> None:
    existing = {row["sid"] for row in rows if isinstance(row.get("sid"), str)}
    for row in collect_city_building_rows(city_doc):
        building_sid = row["sid"]
        level_count = max(
            len(row.get("names")) if isinstance(row.get("names"), list) else 0,
            len(row.get("descriptions")) if isinstance(row.get("descriptions"), list) else 0,
            len(row.get("narrativeDescriptions")) if isinstance(row.get("narrativeDescriptions"), list) else 0,
            1,
        )
        for level in range(1, level_count + 1):
            known = (text_by_building or {}).get(building_sid)
            if known and level <= len(known):
                name, description = known[level - 1]
            else:
                name, description = generic_building_text(manifest, building_sid, level)
            for kind, text in (
                ("name", name),
                ("description", description),
                ("narrativeDescription", description),
            ):
                sid = key_func(building_sid, kind, level, level_count)
                if sid not in existing:
                    rows.append({"sid": sid, "text": text})
                    existing.add(sid)


