CANONICAL_RESOURCE_SIDS = {"gold", "wood", "ore", "mercury", "crystals", "gemstones", "dust"}


def canonical_resource_sid(resource: str) -> str:
    resource = resource.strip().lower()
    if resource in CANONICAL_RESOURCE_SIDS:
        return resource
    return HOMM3_RESOURCE_SID_MAP[resource]


def manifest_growth_receivers(manifest: dict[str, Any], tier: int, suffixes: tuple[str, ...]) -> list[str]:
    for line in manifest.get("unitLines", []):
        if int(line.get("tier") or 0) != tier:
            continue
        return [manifest_unit_sid_for_variant(line, suffix) for suffix in suffixes]
    return []


def city_building_mechanic_spec(manifest: dict[str, Any], building_sid: str) -> dict[str, Any] | None:
    return CITY_BUILDING_MECHANICS_BY_FACTION.get(manifest["identity"]["factionSid"], {}).get(building_sid)


_SOURCE_MECHANICS_CACHE: dict[str, dict[str, Any] | None] = {}


def load_source_mechanics(faction_sid: str) -> dict[str, Any] | None:
    if faction_sid in _SOURCE_MECHANICS_CACHE:
        return _SOURCE_MECHANICS_CACHE[faction_sid]
    path = SOURCE_MECHANICS_DIR / f"{faction_sid}.json"
    if not path.exists():
        _SOURCE_MECHANICS_CACHE[faction_sid] = None
        return None
    with path.open("r", encoding="utf-8-sig") as f:
        value = json.load(f)
    result = value if isinstance(value, dict) else None
    _SOURCE_MECHANICS_CACHE[faction_sid] = result
    return result


def source_mechanic_for_building(faction_sid: str, building_sid: str) -> dict[str, Any] | None:
    return source_mechanic_for_surface_row(faction_sid, "building", building_sid)


def source_mechanic_for_surface_row(faction_sid: str, surface: str, row_sid: str) -> dict[str, Any] | None:
    contract = load_source_mechanics(faction_sid)
    if not isinstance(contract, dict):
        return None
    mechanics = contract.get("mechanics")
    if not isinstance(mechanics, list):
        return None
    for mechanic in mechanics:
        if not isinstance(mechanic, dict) or mechanic.get("surface") != surface:
            continue
        rows = mechanic.get("currentRows")
        if isinstance(rows, list) and row_sid in rows:
            return mechanic
    return None


def stamp_city_building_source_mechanics_metadata(doc: Any, manifest: dict[str, Any]) -> Any:
    faction_sid = manifest["identity"]["factionSid"]
    for row in collect_city_building_config_rows(doc):
        building_sid = row.get("sid")
        if not isinstance(building_sid, str):
            continue
        source_mechanic = source_mechanic_for_building(faction_sid, building_sid)
        if source_mechanic is None:
            continue
        row["xHomm3SourceMechanic"] = source_mechanic.get("id")
        row["xHomm3MechanicsStatus"] = source_mechanic.get("status")
        if source_mechanic.get("status") == "exact":
            row.setdefault("xHomm3MechanicsSource", f"{source_mechanic.get('sourceName')} ({source_mechanic.get('id')})")
            row.setdefault("xHomm3ImplementedMechanics", source_mechanic.get("reason"))
    return doc


def city_building_mechanic_bonuses(manifest: dict[str, Any], spec: dict[str, Any]) -> list[dict[str, Any]]:
    bonuses: list[dict[str, Any]] = []
    for bonus in spec.get("raw_bonuses", ()):
        if isinstance(bonus, dict):
            bonuses.append(json.loads(json.dumps(bonus, ensure_ascii=False)))
    for stat, amount in spec.get("hero_stats", ()):
        bonuses.append({"type": "heroStat", "parameters": [str(stat), str(amount)]})
    for resource, amount in spec.get("resources", ()):
        bonuses.append({"type": "sideRes", "parameters": [canonical_resource_sid(str(resource)), int(amount)]})
    for growth in spec.get("growth", ()):
        if not isinstance(growth, dict):
            continue
        amount = str(int(growth["amount"]))
        suffixes = tuple(str(suffix) for suffix in growth.get("suffixes", ("",)))
        for receiver in manifest_growth_receivers(manifest, int(growth["tier"]), suffixes):
            bonuses.append({"type": "cityUnitsIncrement", "parameters": [receiver, amount]})
    return bonuses


def ensure_city_building_mechanic_rows(doc: Any, manifest: dict[str, Any]) -> Any:
    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc
    specs = CITY_BUILDING_MECHANICS_BY_FACTION.get(manifest["identity"]["factionSid"], {})
    if not specs:
        return doc
    existing = {row["sid"] for row in collect_city_building_config_rows(item)}
    if specs.keys() <= existing:
        return doc

    templates = {row["sid"]: row for row in collect_city_building_config_rows(item)}
    fallback = templates.get("Build_Resource_Depot_level_2") or templates.get("Build_Resource_Depot")
    if fallback is None:
        return doc
    target_section = item.setdefault("banks", [])
    if not isinstance(target_section, list):
        return doc
    faction_sid = manifest["identity"]["factionSid"]
    source_levels = generic_building_source_levels(manifest)
    for building_sid in specs:
        if building_sid in existing:
            continue
        row = json.loads(json.dumps(fallback, ensure_ascii=False))
        row["sid"] = building_sid
        row["isConstructedOnStart"] = False
        row["levelOnStart"] = 1
        row["sceneSlot"] = building_sid.removeprefix("Build_")
        row["names"] = [generic_building_text_key(manifest, building_sid, "name", 1, 1)]
        row["descriptions"] = [generic_building_text_key(manifest, building_sid, "description", 1, 1)]
        row["narrativeDescriptions"] = [generic_building_text_key(manifest, building_sid, "narrativeDescription", 1, 1)]
        if building_sid in source_levels:
            row["icons"] = [generic_building_icon_key(faction_sid, building_sid, 1)]
        target_section.append(row)
        existing.add(building_sid)
    return doc


def apply_city_building_mechanics(doc: Any, manifest: dict[str, Any]) -> Any:
    stamp_city_building_source_mechanics_metadata(doc, manifest)
    for row in collect_city_building_config_rows(doc):
        building_sid = row.get("sid")
        if not isinstance(building_sid, str):
            continue
        spec = city_building_mechanic_spec(manifest, building_sid)
        if spec is None:
            continue
        row["bonuses"] = city_building_mechanic_bonuses(manifest, spec)
        row["xHomm3ImplementedMechanics"] = spec["implemented"]
        row["xHomm3MechanicsSource"] = spec["source"]
    apply_homm3_native_city_building_bonuses(doc, manifest)
    return doc


# Bonus types each city-building section really applies (2026-10-01). Banks and
# cityBonusBanks add their bonuses to the city's CityBonuses, which keeps only sideRes /
# cityUnitsIncrementPer / citySideExp / cityRadiusView / magic-guild rows: flat
# cityUnitsIncrement and heroStat there are dropped (Demo CityBonuses.Add; vanilla Core
# banks carry only sideRes, vanilla walls put cityUnitsIncrementPer in the same container).
# heroBonusBanks grant each visiting hero heroStat / heroExp once (vanilla Core: Beelzebub's
# Hand, Gymnasium, Mother Nature, Endless Library). myceliumRoots has no bonuses field in
# the live interop (BuildingMyceliumRootsConfig). Doc: docs/homm3_city_building_descriptions.md.
NATIVE_CITY_BUILDING_BONUS_TYPES: dict[str, frozenset[str]] = {
    "banks": frozenset({"sideRes", "cityUnitsIncrementPer"}),
    "cityBonusBanks": frozenset({"sideRes", "cityUnitsIncrementPer"}),
    "heroBonusBanks": frozenset({"heroStat", "heroExp"}),
}


def growth_percent_for_flat(flat: int, weekly: int) -> str:
    """Per-dwelling percent that yields exactly +flat on the base weekly growth.

    Native growth is (int)(weekly * (1 + sum of percents)) + flat side bonuses, so the
    HoMM3 flat horde bonus is carried as weekly * p, with p rounded up to 4 decimals from
    (flat + 0.01) / weekly. The product lands 0.01..0.02 above weekly + flat, which keeps
    the float truncation exact and does not add a unit under the +50%/+100% wall percents
    (7 Griffins + Bastion: 10; with Citadel 13; with Castle 17, as in HoMM3).
    """
    if flat <= 0 or weekly <= 0:
        raise ValueError(f"growth percent needs positive flat/weekly, got {flat}/{weekly}")
    value = math.ceil((flat + 0.01) / weekly * 10000) / 10000
    if not (weekly + flat <= weekly * (1 + value) < weekly + flat + 0.5):
        raise ValueError(f"growth percent {value} does not reproduce +{flat} on {weekly}")
    return f"{value:.4f}".rstrip("0").rstrip(".")


def city_hire_line_for_unit(item: dict[str, Any], unit_sid: str) -> dict[str, Any]:
    matches = [
        line
        for row in (item.get("hires") or [])
        if isinstance(row, dict)
        for line in ((row.get("unitsHire") or {}).get("units") or [])
        if isinstance(line, dict) and unit_sid in (line.get("sids") or [])
    ]
    if len(matches) != 1:
        raise RuntimeError(f"{item.get('id')}: growth receiver {unit_sid} is in {len(matches)} hire lines, expected 1")
    return matches[0]


def homm3_native_growth_bonuses(item: dict[str, Any], manifest: dict[str, Any], spec: dict[str, Any]) -> list[dict[str, Any]]:
    """HoMM3 flat horde growth as per-dwelling cityUnitsIncrementPer rows (one per hire line)."""
    bonuses: list[dict[str, Any]] = []
    seen: set[str] = set()
    for growth in spec.get("growth", ()):
        suffixes = tuple(str(suffix) for suffix in growth.get("suffixes", ("",)))
        receivers = manifest_growth_receivers(manifest, int(growth["tier"]), suffixes)
        if not receivers:
            raise RuntimeError(f"{item.get('id')}: growth spec tier {growth['tier']} has no unit line")
        line = city_hire_line_for_unit(item, receivers[0])
        key = str(line["sids"][0])
        if key in seen:
            raise RuntimeError(f"{item.get('id')}: growth spec names hire line {key} twice")
        seen.add(key)
        weekly = int(line.get("weeklyIncrement") or 0)
        bonuses.append(
            {"type": "cityUnitsIncrementPer", "parameters": [key, growth_percent_for_flat(int(growth["amount"]), weekly)]}
        )
    return bonuses


def native_city_building_section_for_spec(spec: dict[str, Any]) -> str:
    hero = bool(spec.get("hero_stats"))
    city = bool(spec.get("growth") or spec.get("resources"))
    if hero == city:
        raise RuntimeError(f"city building spec {spec.get('name')!r} must be either hero stats or city income/growth")
    return "heroBonusBanks" if hero else "banks"


def move_city_building_row(item: dict[str, Any], building_sid: str, target: str) -> dict[str, Any]:
    found: list[tuple[str, dict[str, Any]]] = []
    for section, rows in item.items():
        if isinstance(rows, list):
            found.extend((section, row) for row in rows if isinstance(row, dict) and row.get("sid") == building_sid)
    if len(found) != 1:
        raise RuntimeError(f"{item.get('id')}: building {building_sid} found {len(found)} times")
    section, row = found[0]
    if section != target:
        item[section] = [r for r in item[section] if r is not row]
        item.setdefault(target, []).append(row)
    return row


def retarget_homm3_units_converter(item: dict[str, Any]) -> None:
    """Bone Foundry converts any creature into the HoMM3 Necropolis creature of its tier.

    Native ConvertUnitsUtility: a unit converts when a pair has its tier and it is neither
    fraction 'undead' nor in bannedUnits. The HoMM3 Necropolis line is fraction
    homm3_necropolis, so every one of its sids is banned (no Skeleton -> Skeleton loop).
    Tier 8 has no HoMM3 Necropolis creature, so it has no pair.
    """
    converters = [r for r in (item.get("unitsConverters") or []) if isinstance(r, dict)]
    if not converters:
        return
    pairs: list[dict[str, Any]] = []
    banned: list[str] = []
    for tier in range(1, 8):
        rows = [r for r in (item.get("hires") or []) if isinstance(r, dict) and r.get("sid") == f"Build_Tier_{tier}"]
        lines = [l for r in rows for l in ((r.get("unitsHire") or {}).get("units") or []) if isinstance(l, dict)]
        if len(lines) != 1 or not lines[0].get("sids"):
            raise RuntimeError(f"{item.get('id')}: units converter needs exactly one tier-{tier} hire line")
        sids = [str(sid) for sid in lines[0]["sids"]]
        pairs.append({"tier": tier, "sid": sids[0]})
        banned.extend(sids)
    for row in converters:
        row["conversionPairs"] = copy.deepcopy(pairs)
        row["bannedUnits"] = list(dict.fromkeys(banned))


def apply_homm3_native_city_building_bonuses(doc: Any, manifest: dict[str, Any]) -> Any:
    """Put every HoMM3 building bonus on the section and bonus type the game applies (2026-10-01).

    Spec growth becomes per-dwelling cityUnitsIncrementPer on a bank, spec hero stats move
    to heroBonusBanks, every Blacksmith (Build_Treasury) becomes the vanilla Treasury, and
    the units converter targets the faction's own creatures. Gate:
    validate_homm3_city_building_descriptions_contract.py.
    """
    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc
    specs = CITY_BUILDING_MECHANICS_BY_FACTION.get(manifest["identity"]["factionSid"], {})
    present = {row.get("sid") for row in collect_city_building_config_rows(item)}
    for building_sid, spec in specs.items():
        if building_sid not in present:
            continue
        row = move_city_building_row(item, building_sid, native_city_building_section_for_spec(spec))
        row.pop("trainingStats", None)  # a Training Range turned bonus bank keeps no click-to-train table
        bonuses = city_building_mechanic_bonuses(manifest, {**spec, "growth": ()})
        bonuses.extend(homm3_native_growth_bonuses(item, manifest, spec))
        row["bonuses"] = bonuses
    for row in collect_city_building_config_rows(item):
        if row.get("sid") == "Build_Treasury":
            row["bonuses"] = copy.deepcopy(VANILLA_TREASURY_BONUSES)
            for level in row.get("parametersPerLevel") or []:
                if isinstance(level, dict):
                    level["costs"] = copy.deepcopy(VANILLA_TREASURY_COSTS)
    if manifest["identity"]["factionSid"] == "homm3_necropolis":
        retarget_homm3_units_converter(item)
    return doc


def normalize_stronghold_special_building_rows(doc: Any) -> Any:
    """Mess Hall cannot keep bonuses on artifactChangers; move it to cityBonusBanks."""
    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc
    artifact_changers = item.get("artifactChangers")
    if not isinstance(artifact_changers, list):
        return doc
    mess_hall = None
    remaining: list[Any] = []
    for building in artifact_changers:
        if isinstance(building, dict) and building.get("sid") == "Build_Lyceum":
            mess_hall = copy.deepcopy(building)
        else:
            remaining.append(building)
    if mess_hall is None:
        return doc
    mess_hall.pop("artifacts", None)
    item["artifactChangers"] = remaining
    banks = item.setdefault("cityBonusBanks", [])
    if not isinstance(banks, list):
        item["cityBonusBanks"] = [mess_hall]
        return doc
    item["cityBonusBanks"] = [
        row for row in banks if not (isinstance(row, dict) and row.get("sid") == "Build_Lyceum")
    ]
    item["cityBonusBanks"].append(mess_hall)
    return doc


def city_building_text_for_spec(manifest: dict[str, Any], building_sid: str) -> tuple[str, str] | None:
    spec = city_building_mechanic_spec(manifest, building_sid)
    if spec is None:
        return None
    return str(spec["name"]), str(spec["description"])


def faction_canonical_building_text(manifest: dict[str, Any], building_sid: str, level: int) -> tuple[str, str] | None:
    levels = GENERIC_FACTION_BUILDING_TEXT.get(manifest["identity"]["factionSid"], {}).get(building_sid)
    if not levels:
        return None
    index = min(max(level, 1), len(levels)) - 1
    return levels[index]


def generic_building_text(manifest: dict[str, Any], building_sid: str, level: int) -> tuple[str, str]:
    display_name = manifest["identity"]["factionSid"].removeprefix("homm3_").replace("_", " ").title()
    canonical = faction_canonical_building_text(manifest, building_sid, level)
    if canonical is not None:
        return canonical
    if level == 1:
        known = city_building_text_for_spec(manifest, building_sid)
        if known is not None:
            return known
    additional_line = next(
        (line for line in manifest_additional_recruitment_lines(manifest) if line["cityBuildingSid"] == building_sid),
        None,
    )
    if additional_line is not None:
        names = additional_line.get("names") or []
        if not names:
            raise RuntimeError(f"{manifest['identity']['factionSid']}: additional recruitment building {building_sid} has no names")
        creature = names[min(max(level, 1), len(names)) - 1]
        suffix = "Dwelling" if level == 1 else "Upgrade"
        return f"{creature} {suffix}", f"Allows recruitment of {creature} line creatures."
    if building_sid == "Build_Main":
        names = ("Village Hall", "Town Hall", "City Hall", "Capitol")
        name = names[min(max(level, 1), len(names)) - 1]
        return name, f"The {name} is the administrative center of the {display_name} town."
    if building_sid == "Build_Wall":
        names = ("Fort", "Citadel", "Castle")
        name = names[min(max(level, 1), len(names)) - 1]
        return name, f"The {name} improves town defenses and creature growth."
    if building_sid == "Build_Magic_Guild":
        return f"Mage Guild Level {level}", "Allows visiting heroes to learn spells from this town."
    if building_sid.startswith("Build_Tier_"):
        try:
            tier = int(building_sid.rsplit("_", 1)[1])
        except ValueError:
            tier = 0
        unit_lines = manifest.get("unitLines") or []
        line = unit_lines[tier - 1] if 1 <= tier <= len(unit_lines) else {}
        names = line.get("names") if isinstance(line, dict) else None
        creature = names[min(max(level, 1), len(names)) - 1] if isinstance(names, list) and names else f"Tier {tier}"
        suffix = "Dwelling" if level == 1 else "Upgrade"
        return f"{creature} {suffix}", f"Allows recruitment of {creature} line creatures."
    name = GENERIC_SHARED_BUILDING_NAMES.get(building_sid) or building_sid.removeprefix("Build_").replace("_", " ").title()
    return name, GENERIC_SHARED_BUILDING_DESCRIPTIONS.get(
        building_sid,
        "A special town building for this faction.",
    )


def generic_external_dwelling_text(manifest: dict[str, Any], tier: int) -> tuple[str, str]:
    base_creature, description = external_dwelling_creature_text(manifest, tier)

    building_sid = f"Build_Tier_{tier}"
    canonical = faction_canonical_building_text(manifest, building_sid, 1)
    if canonical is not None:
        dwelling_name = canonical[0]
    else:
        dwelling_name = f"{base_creature} Dwelling"
    return dwelling_name, description


def unit_line_external_dwelling_text(manifest: dict[str, Any], line: dict[str, Any]) -> tuple[str, str]:
    faction_display_name = str(
        (manifest.get("runtime") or {}).get("displayName")
        or manifest["identity"]["factionSid"].removeprefix("homm3_").title()
    )
    names = line.get("names")
    if isinstance(names, list) and names:
        base_creature = str(names[0])
    elif isinstance(line.get("baseSid"), str):
        base_creature = line["baseSid"].removeprefix("h3_").removeprefix("hota_cove_").replace("_", " ").title()
    else:
        raise RuntimeError(f"{manifest['identity']['factionSid']}: recruitment line has no base creature identity")
    return base_creature, f"An external dwelling that provides {base_creature} recruits for {faction_display_name} armies."


def external_dwelling_creature_text(manifest: dict[str, Any], tier: int) -> tuple[str, str]:
    lines = manifest_primary_unit_lines(manifest)
    line = lines[tier - 1]
    return unit_line_external_dwelling_text(manifest, line)


def recruitment_binding_dwelling_text(manifest: dict[str, Any], binding: dict[str, Any]) -> tuple[str, str]:
    if not binding["isAdditional"]:
        return generic_external_dwelling_text(manifest, binding["tier"])
    _base_creature, description = unit_line_external_dwelling_text(manifest, binding["line"])
    dwelling_name = generic_building_text(manifest, binding["cityBuildingSid"], 1)[0]
    return dwelling_name, description


def add_custom_external_dwelling_creature_lang_rows_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    rows: list[dict[str, str]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        for binding in manifest_recruitment_bindings(manifest):
            dwelling_sid = binding["directDwellingSid"]
            _name, description = recruitment_binding_dwelling_text(manifest, binding)
            rows.append({"sid": f"{dwelling_sid}_description", "text": description})
            rows.append({"sid": f"{dwelling_sid}_narrativeDescription", "text": description})
    add_lang_overlay_rows(release_zip, output, "Lang/english/texts/mapObjects.json", rows, notes)


def normalize_generic_city_building_presentation(doc: Any, manifest: dict[str, Any]) -> Any:
    faction_sid = manifest["identity"]["factionSid"]
    source_levels = generic_building_source_levels(manifest)

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            sid = value.get("sid")
            icons = value.get("icons")
            if isinstance(sid, str) and sid.startswith("Build_") and isinstance(icons, list):
                names = value.get("names")
                descriptions = value.get("descriptions")
                count = max(
                    len(icons),
                    len(names) if isinstance(names, list) else 0,
                    len(descriptions) if isinstance(descriptions, list) else 0,
                )
                if sid in source_levels:
                    value["icons"] = [generic_building_icon_key(faction_sid, sid, index + 1) for index in range(count)]
                value["names"] = [generic_building_text_key(manifest, sid, "name", index + 1, count) for index in range(count)]
                value["descriptions"] = [
                    generic_building_text_key(manifest, sid, "description", index + 1, count)
                    for index in range(count)
                ]
                value["narrativeDescriptions"] = [
                    generic_building_text_key(manifest, sid, "narrativeDescription", index + 1, count)
                    for index in range(count)
                ]
            for item in value.values():
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(doc)
    return doc


def add_generic_city_building_lang_rows(
    release_zip: zipfile.ZipFile,
    manifest: dict[str, Any],
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    rows: list[dict[str, str]] = []
    try:
        city_doc = normalize_generic_city_doc(
            read_json(release_zip, f"DB/objects_logic/cities/{manifest['identity']['donorCitySid']}.json"),
            manifest,
        )
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
        city_doc = None
    for row in collect_city_building_rows(city_doc):
        building_sid = row["sid"]
        level_count = max(
            len(row.get("names")) if isinstance(row.get("names"), list) else 0,
            len(row.get("descriptions")) if isinstance(row.get("descriptions"), list) else 0,
            len(row.get("narrativeDescriptions")) if isinstance(row.get("narrativeDescriptions"), list) else 0,
            1,
        )
        for level in range(1, level_count + 1):
            name, description = generic_building_text(manifest, building_sid, level)
            rows.append({"sid": generic_building_text_key(manifest, building_sid, "name", level, level_count), "text": name})
            rows.append({"sid": generic_building_text_key(manifest, building_sid, "description", level, level_count), "text": description})
            rows.append({"sid": generic_building_text_key(manifest, building_sid, "narrativeDescription", level, level_count), "text": description})
    if rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/cities.json", rows, notes)


def city_building_text_key_for_manifest(
    manifest: dict[str, Any],
    building_sid: str,
    kind: str,
    level: int,
    level_count: int,
) -> str:
    faction_sid = manifest["identity"]["factionSid"]
    if faction_sid == "homm3_castle":
        return castle_building_text_key(building_sid, kind, level, level_count)
    if faction_sid == "homm3_fortress":
        return fortress_building_text_key(building_sid, kind, level, level_count)
    return generic_building_text_key(manifest, building_sid, kind, level, level_count)


def homm3_city_building_description_rows(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
) -> dict[str, str]:
    """Derived description + narrativeDescription text for every homm3 city building level.

    Source of truth for that text (tools/release_port/homm3_city_building_descriptions.py);
    the per-faction tables above only supply building names.
    """
    units_name = "Lang/english/texts/units.json"
    units_doc = json.loads(output[units_name].decode("utf-8-sig")) if units_name in output else read_json(release_zip, units_name)
    unit_names = {
        row["sid"]: row.get("text")
        for list_name in ("tokens", "array")
        for row in (units_doc.get(list_name) or [])
        if isinstance(row, dict) and isinstance(row.get("sid"), str)
    }

    def unit_name(unit_sid: str) -> str:
        text = unit_names.get(f"{unit_sid}_name")
        if not isinstance(text, str) or not text.strip():
            raise RuntimeError(f"city building description: unit {unit_sid} has no English name row")
        return text

    rows: dict[str, str] = {}
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        city_name = manifest_core_member(manifest, "cityLogic")
        city_doc = json.loads(output[city_name].decode("utf-8-sig")) if city_name in output else read_json(release_zip, city_name)
        item = first_array_item(city_doc)
        if not isinstance(item, dict):
            raise RuntimeError(f"{city_name}: no city row for building descriptions")
        derived = derive_city_description_rows(item, unit_name)
        for key, text in derived.items():
            problems = city_building_text_problems(text, key, kind="description")
            if problems:
                raise RuntimeError("; ".join(problems))
            if key in rows and rows[key] != text:
                raise RuntimeError(f"city building description key {key} derived twice with different text")
            rows[key] = text
    return rows


def apply_homm3_city_building_descriptions(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Rewrite every homm3 city building English description from its final generated config row.

    Runs after the last city-row mutation that feeds text and before multilingual sync.
    The other 15 locales are written after sync by
    apply_homm3_city_building_description_locales.
    """
    derived = homm3_city_building_description_rows(release_zip, output)
    english = "Lang/english/texts/cities.json"
    add_lang_overlay_rows(
        release_zip, output, english, [{"sid": key, "text": text} for key, text in sorted(derived.items())], notes
    )
    notes.append(f"derive {len(derived)} homm3 city building description rows from final city rows")


def _lang_doc_texts(release_zip: zipfile.ZipFile, output: dict[str, bytes], name: str) -> dict[str, str]:
    doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
    return {
        row["sid"]: row["text"]
        for list_name in ("tokens", "array")
        for row in (doc.get(list_name) or [] if isinstance(doc, dict) else [])
        if isinstance(row, dict) and isinstance(row.get("sid"), str) and isinstance(row.get("text"), str)
    }


def homm3_city_building_locale_rows(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
) -> dict[str, dict[str, str]]:
    """{locale: {key: text}} for every derived homm3 city building description and renamed name.

    Descriptions render from the same sentences as English (homm3_city_building_descriptions);
    unit names come from that locale's units.json, fixed vanilla sentences from that locale's
    vanilla cities.json rows. Names whose English text is in BUILDING_NAMES (Blacksmith,
    Alchemic Depot, Spirits of the Forebears) get that locale's name.
    """
    english_cities = _lang_doc_texts(release_zip, output, "Lang/english/texts/cities.json")
    city_items: list[dict[str, Any]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        city_name = manifest_core_member(manifest, "cityLogic")
        city_doc = json.loads(output[city_name].decode("utf-8-sig")) if city_name in output else read_json(release_zip, city_name)
        item = first_array_item(city_doc)
        if not isinstance(item, dict):
            raise RuntimeError(f"{city_name}: no city row for building descriptions")
        city_items.append(item)
    out: dict[str, dict[str, str]] = {}
    for lang in city_building_locales.LOCALES:
        units = _lang_doc_texts(release_zip, output, f"Lang/{lang}/texts/units.json")
        vanilla = {
            k: v
            for k, v in _lang_doc_texts(release_zip, output, f"Lang/{lang}/texts/cities.json").items()
            if not k.startswith("Homm3")
        }

        def unit_name(unit_sid: str, units: dict[str, str] = units, lang: str = lang) -> str:
            text = units.get(f"{unit_sid}_name")
            if not isinstance(text, str) or not text.strip():
                raise RuntimeError(f"city building description: unit {unit_sid} has no {lang} name row")
            return text

        def vanilla_text(key: str, vanilla: dict[str, str] = vanilla, lang: str = lang) -> str:
            text = vanilla.get(key)
            if not isinstance(text, str) or not text.strip():
                raise RuntimeError(f"city building description: vanilla {lang} row {key} missing")
            return text

        rows: dict[str, str] = {}
        for item in city_items:
            for key, sentences in derive_city_description_sentences(item).items():
                text = render_city_building_sentences(lang, sentences, unit_name, vanilla_text)
                problems = city_building_locale_text_problems(lang, text, english_cities.get(key), key)
                if problems:
                    raise RuntimeError("; ".join(problems))
                if key in rows and rows[key] != text:
                    raise RuntimeError(f"{lang} city building description key {key} derived twice with different text")
                rows[key] = text
            for row in collect_city_building_config_rows(item):
                for name_key in row.get("names") or []:
                    english_name = english_cities.get(name_key) if isinstance(name_key, str) else None
                    names = city_building_locales.BUILDING_NAMES.get(english_name or "")
                    if names is not None:
                        rows[name_key] = names[lang]
        out[lang] = rows
    return out


def apply_homm3_city_building_description_locales(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Write the 15 non-English locales of every derived homm3 city building row.

    Runs after multilingual sync (and the landon mirror), so sync drafts or phrasebook
    refreshes cannot replace these rows. Only the derived description/narrative keys and
    the renamed building names are written; every other locale row is left as it is.
    """
    by_lang = homm3_city_building_locale_rows(release_zip, output)
    total = 0
    for lang, rows in sorted(by_lang.items()):
        add_lang_overlay_rows(
            release_zip,
            output,
            f"Lang/{lang}/texts/cities.json",
            [{"sid": key, "text": text} for key, text in sorted(rows.items())],
            notes,
        )
        total += len(rows)
    notes.append(f"localize {total} homm3 city building rows into {len(by_lang)} locales")


def add_city_building_mechanics_lang_rows_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    rows: list[dict[str, str]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        specs = CITY_BUILDING_MECHANICS_BY_FACTION.get(manifest["identity"]["factionSid"])
        if not specs:
            continue
        city_name = manifest_core_member(manifest, "cityLogic")
        try:
            city_doc = json.loads(output[city_name].decode("utf-8-sig")) if city_name in output else read_json(release_zip, city_name)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
            city_doc = None
        level_counts: dict[str, int] = {}
        for row in collect_city_building_config_rows(city_doc):
            sid = row.get("sid")
            if not isinstance(sid, str):
                continue
            level_counts[sid] = max(
                len(row.get("names")) if isinstance(row.get("names"), list) else 0,
                len(row.get("descriptions")) if isinstance(row.get("descriptions"), list) else 0,
                len(row.get("narrativeDescriptions")) if isinstance(row.get("narrativeDescriptions"), list) else 0,
                1,
            )
        for building_sid, spec in specs.items():
            level_count = level_counts.get(building_sid, 1)
            name = str(spec["name"])
            description = str(spec["description"])
            for kind, text in (
                ("name", name),
                ("description", description),
                ("narrativeDescription", description),
            ):
                rows.append(
                    {
                        "sid": city_building_text_key_for_manifest(manifest, building_sid, kind, 1, level_count),
                        "text": text,
                    }
                )
    if rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/cities.json", rows, notes)


def add_additional_recruitment_city_rows(doc: Any, manifest: dict[str, Any]) -> None:
    additional_lines = manifest_additional_recruitment_lines(manifest)
    if not additional_lines:
        return
    item = first_array_item(doc)
    hires = item.get("hires") if isinstance(item, dict) else None
    faction_sid = manifest["identity"]["factionSid"]
    if not isinstance(hires, list):
        raise RuntimeError(f"{faction_sid}: city document has no hires list for additional recruitment lines")
    building_sids = {row.get("sid") for row in hires if isinstance(row, dict)}
    for line in additional_lines:
        source_sid = f"Build_Tier_{line['tier']}"
        source_rows = [row for row in hires if isinstance(row, dict) and row.get("sid") == source_sid]
        if len(source_rows) != 1:
            raise RuntimeError(f"{faction_sid}: expected one primary city building {source_sid}, got {len(source_rows)}")
        building_sid = line["cityBuildingSid"]
        if building_sid in building_sids:
            raise RuntimeError(f"{faction_sid}: duplicate city recruitment building {building_sid}")
        row = json.loads(json.dumps(source_rows[0], ensure_ascii=False))
        row["sid"] = building_sid
        row["sceneSlot"] = line["recruitmentSlotSid"]
        icons = row.get("icons")
        if not isinstance(icons, list) or not icons:
            raise RuntimeError(f"{faction_sid}: primary city building {source_sid} has no icon levels to bind")
        row["icons"] = [generic_building_icon_key(faction_sid, building_sid, level) for level in range(1, len(icons) + 1)]
        for level in row.get("parametersPerLevel", []) if isinstance(row.get("parametersPerLevel"), list) else []:
            for previous in level.get("prevBuildings", []) if isinstance(level, dict) and isinstance(level.get("prevBuildings"), list) else []:
                if isinstance(previous, dict) and previous.get("sid") == source_sid:
                    previous["sid"] = building_sid
        generic_unit_hire_payload(
            row.get("unitsHire"),
            line,
            manifest_unit_variants(manifest),
            f"{faction_sid}: additional recruitment city building {building_sid}",
        )
        hires.append(row)
        building_sids.add(building_sid)


def normalize_generic_city_doc(doc: Any, manifest: dict[str, Any]) -> Any:
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    variants = manifest_unit_variants(manifest)
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = identity["citySid"]
        item["sceneName"] = manifest_custom_city_scene_name(manifest)
        item["fraction"] = identity["factionSid"]
        if identity["factionSid"] == "homm3_stronghold":
            normalize_stronghold_special_building_rows(doc)
        ensure_city_building_mechanic_rows(doc, manifest)
        apply_homm3_dwelling_cost_tree(item, manifest)
        add_additional_recruitment_city_rows(doc, manifest)
        apply_homm3_special_building_node_pos(doc, manifest)
        apply_homm3_mage_guild_level_cap(doc, manifest)
        apply_homm3_mage_guild_level_5_extension(doc, manifest)
        normalize_generic_city_building_presentation(doc, manifest)
        assert_city_construction_tree_node_pos_unique(doc, identity["factionSid"])
        for section in item.values():
            if not isinstance(section, list):
                continue
            for row in section:
                if not isinstance(row, dict):
                    continue
                if isinstance(row.get("sid"), str) and row["sid"].startswith("Build_Tier_"):
                    try:
                        tier = int(row["sid"].rsplit("_", 1)[1])
                    except ValueError:
                        continue
                    unit_lines = manifest.get("unitLines") or []
                    if 1 <= tier <= len(unit_lines):
                        generic_unit_hire_payload(
                            row.get("unitsHire"),
                            unit_lines[tier - 1],
                            variants,
                            f"{identity['factionSid']}: primary city building {row['sid']}",
                        )
        apply_city_building_mechanics(doc, manifest)
        align_owned_world_city_scene_slots(doc, manifest)
        strip_unbound_castle_slot_buildings_from_owned_world_city(doc, manifest)
        apply_homm3_city_building_tree(doc, manifest)
    return doc


def make_generic_fraction_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> dict[str, Any]:
    identity = manifest["identity"]
    scaffold = manifest_release_scaffold(manifest)
    donor_fraction_sid = manifest_donor_fraction_sid(manifest)
    _, doc = find_array_doc_by_id(release_zip, "DB/fractions/", donor_fraction_sid)
    item = first_array_item(doc)
    if isinstance(item, dict):
        item["id"] = identity["factionSid"]
        item["name"] = identity["displayNameToken"]
        item["desc"] = identity["descriptionToken"]
        item["narrativeDesc"] = identity["descriptionToken"]
        item["icon"] = scaffold["factionIcon"]
        item["iconFractionLaws"] = scaffold["factionLawIcon"]
        item["biome"] = scaffold["biome"]
        item["cityNames"] = homm3_town_name_tokens(identity)
        item["fractionLawsLines"] = remap_string_tokens(
            item.get("fractionLawsLines"),
            {f"fraction_law_{donor_fraction_sid}_": manifest_law_prefix(manifest)},
        )
    return doc


def generic_skill_ref_replacements(manifest: dict[str, Any]) -> dict[str, str]:
    donor_fraction_sid = manifest_donor_fraction_sid(manifest)
    donor_runtime_sid = manifest_donor_core_faction_sid(manifest)
    replacements = {
        f"skill_faction_{donor_fraction_sid}": manifest_faction_skill_sid(manifest),
        f"skill_faction_{donor_runtime_sid}": manifest_faction_skill_sid(manifest),
        manifest_donor_skill_table_sid(manifest, "might"): manifest_skill_table_sid(manifest, "might"),
        manifest_donor_skill_table_sid(manifest, "magic"): manifest_skill_table_sid(manifest, "magic"),
        manifest_donor_skill_table_sid(manifest, "might", arena=True): manifest_skill_table_sid(manifest, "might", arena=True),
        manifest_donor_skill_table_sid(manifest, "magic", arena=True): manifest_skill_table_sid(manifest, "magic", arena=True),
    }
    for donor_skill_sid in manifest_donor_faction_skill_sids(manifest):
        replacements[donor_skill_sid] = manifest_faction_skill_sid(manifest)
    return replacements


def normalize_generic_skill_refs(value: Any, manifest: dict[str, Any]) -> Any:
    replacements = generic_skill_ref_replacements(manifest)
    if isinstance(value, str):
        return replacements.get(value, value)
    if isinstance(value, list):
        return [normalize_generic_skill_refs(item, manifest) for item in value]
    if isinstance(value, dict):
        return {key: normalize_generic_skill_refs(item, manifest) for key, item in value.items()}
    return value


def custom_start_faction_skill_sid(manifest: dict[str, Any]) -> str:
    return manifest_faction_skill_sid(manifest)


def prepend_custom_start_faction_skill(skills: list[dict[str, Any]], manifest: dict[str, Any]) -> list[dict[str, Any]]:
    """Build Core startSkills as faction Basic + at most one HoMM3 Basic skill.

    Advanced/Expert secondary starts grant a free subskill pick and read as a third
    starting skill in the hero panel. Clamp non-faction ranks to Basic and keep only
    the first authored secondary so VCMI dual-skill rows cannot leak through.
    """
    required_sid = custom_start_faction_skill_sid(manifest)
    normalized: list[dict[str, Any]] = [{"sid": required_sid, "skillLevel": 1}]
    for skill in skills:
        sid = skill.get("sid")
        if not isinstance(sid, str) or sid.startswith("skill_faction_"):
            continue
        row = dict(skill)
        row["sid"] = sid
        row["skillLevel"] = 1
        normalized.append(row)
        break
    return normalized


def normalize_start_skill_rows_for_manifest(skills: list[dict[str, Any]], manifest: dict[str, Any]) -> list[dict[str, Any]]:
    replacements = generic_skill_ref_replacements(manifest)
    normalized: list[dict[str, Any]] = []
    for skill in skills:
        row = dict(skill)
        sid = row.get("sid")
        if isinstance(sid, str):
            row["sid"] = replacements.get(sid, sid)
        normalized.append(row)
    return prepend_custom_start_faction_skill(normalized, manifest)


def remove_skill_from_level_table(doc: Any, skill_sid: str) -> Any:
    if not isinstance(doc, dict):
        return doc
    for row in doc.get("array", []) if isinstance(doc.get("array"), list) else []:
        if not isinstance(row, dict):
            continue
        for list_key in ("defaultList", "specialList"):
            for bucket in row.get(list_key, []) if isinstance(row.get(list_key), list) else []:
                if not isinstance(bucket, dict):
                    continue
                chances = bucket.get("rollChances")
                if isinstance(chances, list):
                    bucket["rollChances"] = [
                        chance
                        for chance in chances
                        if not (isinstance(chance, dict) and chance.get("sid") == skill_sid)
                    ]
    return doc


def make_generic_laws_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> dict[str, Any]:
    return make_release_custom_laws_doc(release_zip, manifest)


def infer_generic_unit_baseline(item: dict[str, Any]) -> tuple[bool, bool]:
    stats = item.get("stats") if isinstance(item.get("stats"), dict) else {}
    is_flyer = stats.get("moveType") == "fly"
    is_shooter = find_attack(item, "shoot") is not None
    return is_shooter, is_flyer


def read_lod_entry(lod_path: Path, want_name: str) -> bytes | None:
    if not lod_path.is_file():
        return None
    want = want_name.lower().encode("ascii")
    data = lod_path.read_bytes()
    if data[:4] != b"LOD\0":
        return None
    total = struct.unpack_from("<I", data, 8)[0]
    off = 92
    rows = []
    for _ in range(total):
        raw = data[off : off + 16]
        off += 16
        nul = raw.find(b"\0")
        name = (raw[:nul] if nul >= 0 else raw).lower()
        file_off, file_size, _u, file_csize = struct.unpack_from("<IIII", data, off)
        off += 16
        rows.append((name, file_off, file_size, file_csize))
    for name, file_off, file_size, file_csize in rows:
        if name != want:
            continue
        blob = data[file_off : file_off + file_csize] if file_csize else data[file_off : file_off + file_size]
        return zlib.decompress(blob) if file_csize else blob
    return None


def parse_resource_cost(source: dict[str, Any]) -> dict[str, int]:
    result: dict[str, int] = {}
    for source_name, target_name in RESOURCE_NAME_MAP.items():
        value = source.get(source_name)
        try:
            amount = int(value)
        except (TypeError, ValueError):
            continue
        if amount:
            result[target_name] = amount
    return result


def stats_from_vcmi_creature(data: dict[str, Any], source: str) -> dict[str, Any] | None:
    damage = data.get("damage")
    if not isinstance(damage, dict):
        return None
    cost = data.get("cost")
    if not isinstance(cost, dict):
        cost = {}
    try:
        result: dict[str, Any] = {
            "hp": int(data["hitPoints"]),
            "offence": int(data["attack"]),
            "defence": int(data["defense"]),
            "damageMin": int(damage["min"]),
            "damageMax": int(damage["max"]),
            "initiative": int(data["speed"]),
            "speed": int(data["speed"]),
            "squadValue": int(data.get("aiValue", data.get("fightValue", 0))),
            "growth": int(data.get("growth", 0)),
            "source": source,
        }
    except (KeyError, TypeError, ValueError):
        return None
    result["shots"] = int(data.get("shots") or 0)
    abilities = data.get("abilities")
    ability_text = json.dumps(abilities, ensure_ascii=False).upper() if isinstance(abilities, dict) else ""
    result["isShooter"] = result["shots"] > 0 or "SHOOTER" in ability_text
    result["isFlyer"] = "FLYING" in ability_text
    result["cost"] = {RESOURCE_NAME_MAP.get(str(resource).capitalize(), str(resource)): int(amount) for resource, amount in cost.items() if int(amount)}
    return result


def load_homm3_crtraits_stats() -> dict[str, dict[str, Any]]:
    blob = read_lod_entry(HOMM3_BITMAP_LOD, "CRTRAITS.TXT")
    if blob is None:
        return {}
    text = blob.decode("cp1252", errors="replace")
    reader = csv.reader(io.StringIO(text), delimiter="\t")
    try:
        next(reader)
        header = next(reader)
    except StopIteration:
        return {}
    result: dict[str, dict[str, Any]] = {}
    def cell(values: list[str], index: int) -> str:
        return values[index] if index < len(values) else ""

    def flags(value: str) -> set[str]:
        return {part for part in re.split(r"[^A-Z0-9_]+", value.upper()) if part}

    for values in reader:
        row = dict(zip(header, values))
        name = cell(values, 0).strip()
        if not name:
            continue
        ability_flags = flags(cell(values, 24))
        try:
            result[name.casefold()] = {
                "hp": int(cell(values, 13)),
                "offence": int(cell(values, 15)),
                "defence": int(cell(values, 16)),
                "damageMin": int(cell(values, 17)),
                "damageMax": int(cell(values, 18)),
                "initiative": int(cell(values, 14)),
                "speed": int(cell(values, 14)),
                "squadValue": int(cell(values, 10)),
                "growth": int(cell(values, 11)),
                "shots": int(cell(values, 19) or 0),
                "cost": parse_resource_cost(row),
                "isShooter": int(cell(values, 19) or 0) > 0 or "SHOOTING_ARMY" in ability_flags,
                "isFlyer": "FLYING_ARMY" in ability_flags,
                "source": "vcmi/Data/H3bitmap.lod:CRTRAITS.TXT",
            }
        except (KeyError, TypeError, ValueError):
            continue
    return result


def parse_markdown_cost(value: str) -> dict[str, int]:
    result: dict[str, int] = {}
    for part in value.split(","):
        bits = part.strip().split()
        if len(bits) != 2:
            continue
        resource, amount = bits
        resource = RESOURCE_NAME_MAP.get(resource.capitalize(), resource.lower())
        try:
            parsed = int(amount)
        except ValueError:
            continue
        if parsed:
            result[resource] = parsed
    return result


def load_tears_of_ashan_stats() -> dict[str, dict[str, Any]]:
    if not TEARS_OF_ASHAN_CREATURE_SPECS.is_file():
        return {}
    result: dict[str, dict[str, Any]] = {}
    for raw_line in TEARS_OF_ASHAN_CREATURE_SPECS.read_text(encoding="utf-8").splitlines():
        if not raw_line.startswith("| ") or " | " not in raw_line or "/lvl" not in raw_line:
            continue
        cells = [cell.strip() for cell in raw_line.strip().strip("|").split("|")]
        if len(cells) < 13 or cells[0] == "Source":
            continue
        name = cells[2]
        attack_defence = cells[4].split("/")
        damage = cells[5].split("-")
        if len(attack_defence) != 2 or len(damage) != 2:
            continue
        try:
            result[name.casefold()] = {
                "hp": int(cells[6]),
                "offence": int(attack_defence[0]),
                "defence": int(attack_defence[1]),
                "damageMin": int(damage[0]),
                "damageMax": int(damage[1]),
                "initiative": int(cells[7]),
                "speed": int(cells[7]),
                "squadValue": 0,
                "growth": int(cells[8]),
                "shots": int(cells[9]) if cells[9] else 0,
                "cost": parse_markdown_cost(cells[10]),
                "isShooter": bool(cells[9]) or "SHOOTER" in cells[12],
                "isFlyer": any(token in cells[12] for token in ("FLYING", "movementFlying", "movementTeleporting")),
                "source": f"docs/homm3_tears_of_ashan_creature_specs.md:{cells[0]}",
            }
        except ValueError:
            continue
    return result


def load_cove_creature_stats() -> dict[str, dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    if not COVE_CREATURE_CONFIG_ROOT.is_dir():
        return result
    for path in sorted(COVE_CREATURE_CONFIG_ROOT.glob("*.json")):
        try:
            doc = load_jsonc(path)
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue
        for creature_id, data in doc.items():
            if isinstance(creature_id, str) and isinstance(data, dict):
                stats = stats_from_vcmi_creature(data, f"{path.relative_to(REPO_ROOT).as_posix()}:{creature_id}")
                if stats is not None:
                    result[creature_id.casefold()] = stats
    return result



def load_homm3_unit_balance_adjustments() -> dict[str, dict[str, Any]]:
    if not HOMM3_UNIT_BALANCE_ADJUSTMENTS_PATH.is_file():
        raise RuntimeError(f"missing HoMM3 unit balance adjustment contract: {HOMM3_UNIT_BALANCE_ADJUSTMENTS_PATH}")
    doc = json.loads(HOMM3_UNIT_BALANCE_ADJUSTMENTS_PATH.read_text(encoding="utf-8-sig"))
    if not isinstance(doc, dict) or doc.get("schemaVersion") != 1:
        raise RuntimeError("HoMM3 unit balance adjustment contract has an unsupported schemaVersion")
    entries = doc.get("entries")
    if not isinstance(entries, list):
        raise RuntimeError("HoMM3 unit balance adjustment contract is missing entries[]")
    result: dict[str, dict[str, Any]] = {}
    for index, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise RuntimeError(f"HoMM3 unit balance adjustment entry {index} is not an object")
        unit_sid = entry.get("unitSid")
        if not isinstance(unit_sid, str) or not unit_sid:
            raise RuntimeError(f"HoMM3 unit balance adjustment entry {index} has no unitSid")
        if unit_sid in result:
            raise RuntimeError(f"duplicate HoMM3 unit balance adjustment entry for {unit_sid}")
        overrides = entry.get("statOverrides")
        if overrides is not None and not isinstance(overrides, dict):
            raise RuntimeError(f"HoMM3 unit balance adjustment entry {unit_sid} has invalid statOverrides")
        result[unit_sid] = entry
    return result


