def ensure_homm3_balance_damage_modifier(stats: dict[str, Any], mod_set: str, damage_type: str, value: float) -> bool:
    mods = stats.get(mod_set)
    if not isinstance(mods, dict):
        raise RuntimeError(f"balance stat modifier target {mod_set} is missing or malformed")
    rows = mods.get("list")
    if not isinstance(rows, list):
        raise RuntimeError(f"balance stat modifier target {mod_set}.list is missing or malformed")
    for row in rows:
        if isinstance(row, dict) and row.get("t") == damage_type:
            if row.get("v") == value:
                return False
            row["v"] = value
            return True
    rows.append({"t": damage_type, "v": value})
    return True


def merge_homm3_balance_cost_override(item: dict[str, Any], custom_sid: str, cost: dict[str, Any]) -> bool:
    """Replace unitCost.costResArray with the exact override map.

    Partial merge previously left stale rare resources on alternate upgrades when
    aligning costs to the standard upgrade sibling. Fail closed: the override is
    the entire paid cost.
    """
    if not cost:
        raise RuntimeError(f"{custom_sid}: balance override cost must be a non-empty object")
    unit_cost = item.get("unitCost")
    if not isinstance(unit_cost, dict):
        raise RuntimeError(f"{custom_sid}: balance cost override target unitCost is missing or malformed")
    for resource, value in cost.items():
        if not isinstance(resource, str) or not isinstance(value, int) or value < 0:
            raise RuntimeError(f"{custom_sid}: balance override cost contains invalid resource entries")
    new_rows = [{"name": resource, "cost": value} for resource, value in cost.items()]
    old_rows = unit_cost.get("costResArray")
    if old_rows == new_rows:
        return False
    unit_cost["costResArray"] = new_rows
    return True


def apply_homm3_unit_balance_logic_adjustment(item: dict[str, Any], custom_sid: str) -> bool:
    entry = HOMM3_UNIT_BALANCE_ADJUSTMENTS.get(custom_sid)
    if not isinstance(entry, dict):
        return False
    changed = False
    overrides = entry.get("statOverrides")
    mechanics = entry.get("mechanicOverrides")
    stats = item.get("stats")
    if not isinstance(stats, dict):
        raise RuntimeError(f"{custom_sid}: balance adjustment target stats is missing or malformed")
    if isinstance(overrides, dict):
        for key in ("hp", "offence", "defence", "damageMin", "damageMax", "initiative", "speed"):
            if key in overrides:
                value = overrides[key]
                if not isinstance(value, int):
                    raise RuntimeError(f"{custom_sid}: balance override {key} must be an integer")
                changed = changed or stats.get(key) != value
                stats[key] = value
        if "squadValue" in overrides:
            value = overrides["squadValue"]
            if not isinstance(value, int):
                raise RuntimeError(f"{custom_sid}: balance override squadValue must be an integer")
            changed = changed or item.get("squadValue") != value
            item["squadValue"] = value
        cost = overrides.get("cost")
        if cost is not None:
            if not isinstance(cost, dict):
                raise RuntimeError(f"{custom_sid}: balance override cost must be an object")
            changed = merge_homm3_balance_cost_override(item, custom_sid, cost) or changed
    if isinstance(mechanics, dict):
        force_ai = mechanics.get("forceAi")
        if force_ai is not None:
            if force_ai not in {"melee_type", "range_type"}:
                raise RuntimeError(f"{custom_sid}: unsupported balance forceAi {force_ai!r}")
            changed = changed or item.get("ai") != force_ai
            item["ai"] = force_ai
        modifiers = mechanics.get("statModifiers")
        if isinstance(modifiers, list):
            for modifier in modifiers:
                if not isinstance(modifier, dict):
                    raise RuntimeError(f"{custom_sid}: balance stat modifier must be an object")
                mod_set = modifier.get("set")
                damage_type = modifier.get("tag")
                value = modifier.get("value")
                if mod_set not in {"inDmgMods", "outDmgMods"} or not isinstance(damage_type, str) or not isinstance(value, (int, float)):
                    raise RuntimeError(f"{custom_sid}: invalid balance stat modifier {modifier!r}")
                changed = ensure_homm3_balance_damage_modifier(stats, mod_set, damage_type, float(value)) or changed
    if isinstance(overrides, dict) or isinstance(mechanics, dict):
        item["xHomm3BalanceRecommendation20260625"] = {
            "source": "docs/homm3_custom_unit_balance_recommendations_20260625.md",
            "unitName": entry.get("unitName"),
            "implementationTarget": entry.get("implementationTarget"),
            "statOverrides": overrides if isinstance(overrides, dict) else {},
            "mechanicOverrides": mechanics if isinstance(mechanics, dict) else {},
            "runtimeValidation": "pending",
        }
        changed = True
    return changed


def apply_homm3_unit_balance_view_adjustment(item: dict[str, Any], custom_sid: str) -> bool:
    entry = HOMM3_UNIT_BALANCE_ADJUSTMENTS.get(custom_sid)
    if not isinstance(entry, dict):
        return False
    mechanics = entry.get("mechanicOverrides")
    if not isinstance(mechanics, dict):
        return False
    changed = False
    remove_passives = mechanics.get("removeViewPassives")
    if isinstance(remove_passives, list):
        names_to_remove = {name for name in remove_passives if isinstance(name, str) and name}
        if len(names_to_remove) != len(remove_passives):
            raise RuntimeError(f"{custom_sid}: balance removeViewPassives must be a non-empty string list")
        bucket = item.get("passives")
        if not isinstance(bucket, list):
            raise RuntimeError(f"{custom_sid}: balance removeViewPassives requires a view passives list")
        kept = [passive for passive in bucket if not (isinstance(passive, dict) and passive.get("name") in names_to_remove)]
        removed = len(bucket) - len(kept)
        if removed != len(names_to_remove):
            raise RuntimeError(f"{custom_sid}: balance removeViewPassives could not remove all requested passives {sorted(names_to_remove)!r}")
        if removed:
            item["passives"] = kept
            changed = True
    passives = mechanics.get("viewPassives")
    if isinstance(passives, list):
        bucket = item.get("passives")
        if not isinstance(bucket, list):
            raise RuntimeError(f"{custom_sid}: balance viewPassives requires a view passives list")
        for passive in passives:
            if not isinstance(passive, dict):
                raise RuntimeError(f"{custom_sid}: balance view passive must be an object")
            name = passive.get("name")
            description = passive.get("description")
            icon = passive.get("icon")
            if not isinstance(name, str) or not isinstance(description, str):
                raise RuntimeError(f"{custom_sid}: balance view passive is missing name/description")
            before_len = len(bucket)
            if isinstance(icon, str):
                append_unique_view_passive(bucket, name, description, icon=icon)
            else:
                append_unique_view_passive(bucket, name, description)
            changed = changed or len(bucket) != before_len
    if changed:
        item["xHomm3BalanceRecommendation20260625"] = {
            "source": "docs/homm3_custom_unit_balance_recommendations_20260625.md",
            "unitName": entry.get("unitName"),
            "implementationTarget": entry.get("implementationTarget"),
            "mechanicOverrides": mechanics,
            "runtimeValidation": "pending",
        }
    return changed


HOMM3_MELEE_ANIMATION_SLOT = 0
HOMM3_SHOT_ANIMATION_SLOT = 1


def assign_homm3_attack_animation_slots(output: dict[str, bytes], notes: list[str]) -> None:
    """Single owner of h3_* view animation slots (validator: tools/validate_homm3_owned_attack_animation_slots.py).

    Native UnitDrawer.OnStartAttack plays "Attack Tree 2" at attackVariant {0,.2,.4,.6,.8,1}[animationIndex];
    the owned skinned lab build maps 14.Attack (index 0) -> Unit_AttackFront and 15.Skill_1 (index 1) ->
    Unit_ShootFront, else Unit_AttackFront. Vanilla shooters that keep melee and counter on one slot and the
    shot on another (crossbowman, lightweaver, aqualotl, arbitrator) use exactly this split, so: projectile
    attacks/abilities -> 1, projectile-less attacks -> 0, and a shooter's projectile-less ability leaves the
    shot slot for 0. Runs after every generator has written its h3_* view rows.
    """
    changed_rows = 0
    for name in sorted(output):
        if not (name.startswith("DB/units/units_views/") and name.endswith("_v.json")
                and Path(name).name.startswith("h3_")):
            continue
        doc = json.loads(output[name].decode("utf-8-sig"))
        changed = False
        for row in doc.get("array") or []:
            if not isinstance(row, dict) or not str(row.get("id", "")).startswith("h3_"):
                continue
            lists = [as_attack_list(row.get(k)) for k in ("defaultAttacks", "alternativeAttacks", "counterAttacks")]
            abilities = as_attack_list(row.get("abilities"))
            shoots = any(a.get("projectile") for group in (*lists, abilities) for a in group)
            row_changed = False
            for attack in (a for group in lists for a in group):
                want = HOMM3_SHOT_ANIMATION_SLOT if attack.get("projectile") else HOMM3_MELEE_ANIMATION_SLOT
                if attack.get("animationIndex", 0) != want:
                    attack["animationIndex"] = want
                    row_changed = True
            for ability in abilities:
                index = ability.get("animationIndex", 0)
                if ability.get("projectile"):
                    want = HOMM3_SHOT_ANIMATION_SLOT
                elif shoots and index == HOMM3_SHOT_ANIMATION_SLOT:
                    want = HOMM3_MELEE_ANIMATION_SLOT
                else:
                    continue
                if index != want:
                    ability["animationIndex"] = want
                    row_changed = True
            changed_rows += row_changed
            changed = changed or row_changed
        if changed:
            output[name] = write_json(doc)
    notes.append(f"assign h3_* attack animation slots (shot 1, melee/counter 0): {changed_rows} view row(s) changed")


HOMM3_AI_BASES = ("melee_type", "reach_type", "range_type")


def assign_homm3_battle_ai_types(
    release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]
) -> None:
    """Single owner of h3_* logic `ai` kind (validator: tools/validate_unit_battle_ai_contract.py).

    Vanilla invariant (0 exceptions in the release Core): a unit whose defaultAttacks shoot has a range_type*
    ai, and every other unit a melee_type*/reach_type* ai. h3_* rows inherit `ai` from their donor, so a
    shooter built on a melee donor (Factory halflings on esquire) ran melee battle AI and a melee unit built
    on a shooter donor (HoMM3 angels, rocs, wyverns) ran ranged AI. The kind is taken from the resolved
    defaultAttacks; a special family (_grouping, _eater) is kept when the other kind has it in DB/ai_battle,
    otherwise the plain base id is used. An explicit balance forceAi that contradicts the attack fails closed.
    Runs after every generator and the balance adjustments have written h3_* logic rows.
    """
    members = set(release_zip.namelist()) | set(output)
    ai_ids: set[str] = set()
    for name in members:
        if name.startswith("DB/ai_battle/") and name.endswith(".json"):
            raw = output[name] if name in output else release_zip.read(name)
            ai_ids.update(re.findall(r'"id"\s*:\s*"([^"]+)"', raw.decode("utf-8-sig", "replace")))
    difficulties = sorted(i[len("default_"):] for i in ai_ids if i.startswith("default_"))
    if not difficulties:
        raise RuntimeError("assign h3 battle ai: no DB/ai_battle default_<difficulty> rows found")

    def family_exists(ai: str) -> bool:
        return all(f"{ai}_{d}" in ai_ids for d in difficulties)

    changed: list[str] = []
    for name in sorted(members):
        if not (name.startswith("DB/units/units_logics/") and name.endswith("_l.json")
                and Path(name).name.startswith("h3_")):
            continue
        doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
        doc_changed = False
        for row in doc.get("array") or []:
            if not isinstance(row, dict) or not str(row.get("id", "")).startswith("h3_") or "ai" not in row:
                continue
            sid = str(row["id"])
            ai = row.get("ai")
            if not isinstance(ai, str) or not family_exists(ai):
                raise RuntimeError(f"{sid}: ai {ai!r} has no DB/ai_battle row for every difficulty {difficulties}")
            shoots = any(a.get("attackType_") == "shoot" for a in as_attack_list(row.get("defaultAttacks")))
            is_range = ai.startswith("range_type")
            if shoots == is_range:
                continue
            forced = (((HOMM3_UNIT_BALANCE_ADJUSTMENTS.get(sid) or {}).get("mechanicOverrides") or {}).get("forceAi"))
            if forced is not None:
                raise RuntimeError(
                    f"{sid}: balance forceAi {forced!r} contradicts defaultAttacks "
                    f"({'shoot' if shoots else 'melee'}); fix the adjustment or the attack"
                )
            base = next((b for b in HOMM3_AI_BASES if ai == b or ai.startswith(b + "_")), None)
            if base is None:
                raise RuntimeError(f"{sid}: ai {ai!r} is not a melee_type/reach_type/range_type family")
            suffix = ai[len(base):]
            target_base = "range_type" if shoots else "melee_type"
            new_ai = target_base + suffix if suffix and family_exists(target_base + suffix) else target_base
            row["ai"] = new_ai
            changed.append(f"{sid}:{ai}->{new_ai}")
            doc_changed = True
        if doc_changed:
            output[name] = write_json(doc)
    notes.append(
        f"assign h3_* battle ai kind from defaultAttacks: {len(changed)} row(s) changed"
        + (f" ({', '.join(changed)})" if changed else "")
    )


def apply_homm3_unit_balance_adjustments_to_output(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    changed_logic = 0
    changed_view = 0
    members = set(release_zip.namelist()) | set(output)
    logic_expected = sorted(
        unit_sid
        for unit_sid, entry in HOMM3_UNIT_BALANCE_ADJUSTMENTS.items()
        if isinstance(entry.get("statOverrides"), dict) or isinstance(entry.get("mechanicOverrides"), dict)
    )
    view_expected = sorted(
        unit_sid
        for unit_sid, entry in HOMM3_UNIT_BALANCE_ADJUSTMENTS.items()
        if isinstance(entry.get("mechanicOverrides"), dict) and (
            isinstance(entry.get("mechanicOverrides", {}).get("viewPassives"), list)
            or isinstance(entry.get("mechanicOverrides", {}).get("removeViewPassives"), list)
        )
    )
    logic_seen: set[str] = set()
    view_seen: set[str] = set()
    for name in sorted(members):
        if name.startswith("DB/units/units_logics/") and name.endswith("_l.json"):
            custom_sid = Path(name).name.removesuffix("_l.json")
            entry = HOMM3_UNIT_BALANCE_ADJUSTMENTS.get(custom_sid)
            if not isinstance(entry, dict) or (not isinstance(entry.get("statOverrides"), dict) and not isinstance(entry.get("mechanicOverrides"), dict)):
                continue
            logic_seen.add(custom_sid)
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                raise RuntimeError(f"{custom_sid}: cannot read unit logic row for balance adjustment: {ex}") from ex
            item = first_array_item(doc)
            if not isinstance(item, dict):
                raise RuntimeError(f"{custom_sid}: malformed unit logic row for balance adjustment")
            if apply_homm3_unit_balance_logic_adjustment(item, custom_sid):
                output[name] = write_json(doc)
                changed_logic += 1
        elif name.startswith("DB/units/units_views/") and name.endswith("_v.json"):
            custom_sid = Path(name).name.removesuffix("_v.json")
            entry = HOMM3_UNIT_BALANCE_ADJUSTMENTS.get(custom_sid)
            mechanics = entry.get("mechanicOverrides") if isinstance(entry, dict) else None
            if not isinstance(mechanics, dict) or (
                not isinstance(mechanics.get("viewPassives"), list)
                and not isinstance(mechanics.get("removeViewPassives"), list)
            ):
                continue
            view_seen.add(custom_sid)
            try:
                doc = json.loads(output[name].decode("utf-8-sig")) if name in output else read_json(release_zip, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                raise RuntimeError(f"{custom_sid}: cannot read unit view row for balance adjustment: {ex}") from ex
            item = first_array_item(doc)
            if not isinstance(item, dict):
                raise RuntimeError(f"{custom_sid}: malformed unit view row for balance adjustment")
            if apply_homm3_unit_balance_view_adjustment(item, custom_sid):
                output[name] = write_json(doc)
                changed_view += 1
    if sorted(logic_seen) != logic_expected:
        missing = sorted(set(logic_expected) - logic_seen)
        raise RuntimeError(f"missing generated unit logic rows for HoMM3 balance adjustments: {missing[:12]}")
    if sorted(view_seen) != view_expected:
        missing = sorted(set(view_expected) - view_seen)
        raise RuntimeError(f"missing generated unit view rows for HoMM3 balance adjustments: {missing[:12]}")
    if changed_logic or changed_view:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/unitsAbility.json", list(HOMM3_UNIT_BALANCE_LANG_ROWS), notes)
        notes.append(f"apply HoMM3 unit balance adjustment contract ({changed_logic} logic rows, {changed_view} view rows)")
HOMM3_CRTRAITS_STATS = load_homm3_crtraits_stats()
TEARS_OF_ASHAN_TARGET_STATS = load_tears_of_ashan_stats()
COVE_CREATURE_TARGET_STATS = load_cove_creature_stats()
HOMM3_UNIT_BALANCE_ADJUSTMENTS = load_homm3_unit_balance_adjustments()


def generic_unit_target_stats(custom_sid: str, line: dict[str, Any], suffix_index: int, manifest: dict[str, Any]) -> dict[str, Any] | None:
    source_stats = line.get("sourceStats")
    variants = manifest_unit_variants(manifest)
    variant_suffix = variants[suffix_index] if suffix_index < len(variants) else ""
    if isinstance(source_stats, dict):
        target = source_stats.get(variant_suffix)
        if isinstance(target, dict):
            return target
    source_config = line.get("sourceConfig")
    if manifest["identity"]["factionSid"] == "homm3_cove" and isinstance(source_config, list) and suffix_index < len(source_config):
        source_key = source_config[suffix_index]
        if isinstance(source_key, str):
            target = COVE_CREATURE_TARGET_STATS.get(source_key.casefold())
            if target is not None:
                return target
    name = unit_display_name_for_variant(line, suffix_index)
    if not name:
        return None
    if suffix_index == 2:
        target = TEARS_OF_ASHAN_TARGET_STATS.get(name.casefold())
        if target is not None:
            return target
    return HOMM3_CRTRAITS_STATS.get(name.casefold())


def apply_generic_unit_target_stats(item: dict[str, Any], target: dict[str, Any] | None) -> str | None:
    if not target:
        return None
    stats = item.get("stats")
    if not isinstance(stats, dict):
        raise RuntimeError(f"{custom_sid}: balance adjustment target stats is missing or malformed")
    for key in ("hp", "offence", "defence", "damageMin", "damageMax", "initiative", "speed"):
        stats[key] = target[key]
    shots = target.get("shots")
    if isinstance(shots, int) and shots > 0:
        stats["ammo"] = shots
    elif isinstance(stats.get("ammo"), int):
        stats["ammo"] = 0
    if target.get("squadValue"):
        item["squadValue"] = target["squadValue"]
    cost = target.get("cost")
    if isinstance(cost, dict) and cost:
        item["unitCost"] = {
            "costResArray": [{"name": resource, "cost": value} for resource, value in cost.items()]
        }
    return target.get("source") if isinstance(target.get("source"), str) else None


