def append_unique_json(items: list[Any], item: Any) -> bool:
    encoded = json.dumps(item, sort_keys=True, ensure_ascii=False)
    for existing in items:
        if json.dumps(existing, sort_keys=True, ensure_ascii=False) == encoded:
            return False
    items.append(item)
    return True


