def strong_vanilla_active_lang_rows() -> list[dict[str, str]]:
    rows = list(STRONG_VANILLA_LANG_ROWS)
    for custom_sid, by_kind in sorted(ACTIVE_DISPLAY_OVERRIDES_BY_SID.items()):
        for kind, override in sorted(by_kind.items()):
            name = override.get("name")
            description = override.get("description")
            if isinstance(name, str):
                rows.append({"sid": f"{custom_sid}_{kind}_name", "text": name})
            if isinstance(description, str):
                rows.append({"sid": f"{custom_sid}_{kind}_description", "text": description})
    ray_rows = {row.get("id"): row for row in make_homm3_cove_disrupting_ray_buff_rows()}
    for custom_sid, buff_sid in sorted(COVE_AFTER_SHOT_WEAKNESS_BY_SID.items()):
        percent = COVE_AFTER_SHOT_WEAKNESS_PERCENT_BY_BUFF_SID.get(buff_sid)
        if percent is None:
            raise RuntimeError(f"{custom_sid}: no description strength for Cove after-shot buff {buff_sid}")
        ray_sid = COVE_AFTER_SHOT_WEAKNESS_DUPLICATE_RAY_BY_BUFF_SID.get(buff_sid)
        if ray_sid is None:
            raise RuntimeError(f"{custom_sid}: no Disrupting Ray mapping for Cove after-shot buff {buff_sid}")
        ray_row = ray_rows.get(ray_sid)
        ray_stats = ray_row.get("data", {}).get("stats", {}) if isinstance(ray_row, dict) else {}
        defence = ray_stats.get("defence") if isinstance(ray_stats, dict) else None
        if (
            not isinstance(defence, int)
            or isinstance(defence, bool)
            or defence >= 0
            or ray_row.get("infinite") is not True
            or ray_row.get("addition") != "data"
        ):
            raise RuntimeError(f"{custom_sid}: malformed configured Disrupting Ray row {ray_sid}")
        defence_penalty = -defence
        rows.append(
            {
                "sid": f"{custom_sid}_after_shot_weakness_description",
                "text": (
                    f"Ranged attacks reduce the target's normal damage by {percent}% for "
                    f"{COVE_AFTER_SHOT_WEAKNESS_DURATION} rounds after damage is dealt. If the target is already "
                    f"affected by Weakness, the attack instead applies Disrupting Ray, reducing its Defense by "
                    f"{defence_penalty}; this Defense reduction stacks."
                ),
            }
        )
    return rows


