def note_strong_vanilla_implemented(item: dict[str, Any], implemented: list[str]) -> None:
    if not implemented:
        return
    audit = item.setdefault("xHomm3ImplementationAudit", {})
    if not isinstance(audit, dict):
        return
    current = audit.setdefault("implementedMechanics", [])
    if isinstance(current, list):
        for entry in implemented:
            if entry not in current:
                current.append(entry)
    audit["strongVanillaMatchSource"] = "docs/mechanics_audit/user edit of faction mechanics.csv"


def apply_tower_attack_role_guard_to_logic(item: dict[str, Any], custom_sid: str) -> list[str]:
    if custom_sid in TOWER_MELEE_ONLY_GUARD_SIDS:
        melee = find_attack(item, "melee") or fallback_melee_attack(True)
        melee["attackType_"] = "melee"
        normalize_damage_dealer(melee, True, melee=True)
        counter = find_attack(item, "melee") or fallback_melee_attack(False)
        counter["attackType_"] = "melee"
        normalize_damage_dealer(counter, False, melee=True)
        item["defaultAttacks"] = [melee]
        item["alternativeAttacks"] = []
        item["counterAttacks"] = [counter]
        return ["Tower melee-only unit guard"]
    if custom_sid in TOWER_SHOOTER_GUARD_SIDS:
        shoot = find_attack(item, "shoot") or fallback_shoot_attack()
        shoot["attackType_"] = "shoot"
        normalize_damage_dealer(shoot, True, melee=False)
        melee = find_attack(item, "melee") or fallback_melee_attack(True)
        melee["attackType_"] = "melee"
        normalize_damage_dealer(melee, True, melee=True, stat_dmg_mult=0.5)
        counter = find_attack(item, "melee") or fallback_melee_attack(False)
        counter["attackType_"] = "melee"
        normalize_damage_dealer(counter, False, melee=True, stat_dmg_mult=0.5)
        item["defaultAttacks"] = [shoot]
        item["alternativeAttacks"] = [melee]
        item["counterAttacks"] = [counter]
        return ["Tower shooter upgrade guard"]
    return []


def apply_tower_attack_role_guard_to_view(item: dict[str, Any], custom_sid: str) -> list[str]:
    if custom_sid in TOWER_MELEE_ONLY_GUARD_SIDS:
        item["defaultAttacks"] = [view_attack(0)]
        item["counterAttacks"] = [view_attack(0)]
        item["alternativeAttacks"] = []
        return ["Tower melee-only unit guard"]
    if custom_sid in TOWER_SHOOTER_GUARD_SIDS:
        item["defaultAttacks"] = [view_attack(0, custom_sid=custom_sid)]
        item["counterAttacks"] = [view_attack(0)]
        item["alternativeAttacks"] = [ranged_melee_view_attack(1)]
        return ["Tower shooter upgrade guard"]
    return []


def apply_generic_mechanics_to_logic(item: dict[str, Any], custom_sid: str, is_shooter: bool, faction_sid: str = "") -> list[str]:
    implemented: list[str] = []
    melee_multiplier = 1.0 if custom_sid in GENERIC_FULL_MELEE_SHOOTER_SIDS else 0.5
    no_retaliation = custom_sid in GENERIC_NO_RETALIATION_SIDS
    stats = item.setdefault("stats", {})
    if isinstance(stats, dict):
        if custom_sid in GENERIC_SHARPSHOOTER_SIDS:
            stats["ignoreShootDmgBuff"] = True
            stats["ignoreShootingBlock"] = True
            implemented.append("no range or obstacle penalty")
        elif custom_sid in GENERIC_NO_OBSTACLE_SHOOTER_SIDS:
            stats["ignoreShootingBlock"] = True
            # Free Shooting is adjacent-block immunity only; clear donor Sharpshooter range flags.
            stats.pop("ignoreShootDmgBuff", None)
            implemented.append("no obstacle penalty")
        if custom_sid in GENERIC_TELEPORT_MOVE_SIDS:
            stats["moveType"] = "teleport"
            implemented.append("teleporting movement")
        if custom_sid in GENERIC_UNLIMITED_RETALIATION_SIDS:
            stats["numCounters"] = 999
            implemented.append("unlimited retaliation")
        armor_pen = GENERIC_ARMOR_PEN_BY_SID.get(custom_sid)
        if armor_pen is not None:
            stats["armorPen"] = float(armor_pen)
            implemented.append(f"{int(round(armor_pen * 100))}% Defense pierce")
        if custom_sid in GENERIC_POSITIVE_LUCK_SIDS:
            stats["luckMin"] = 1
            implemented.append("positive luck floor")
        if custom_sid in GENERIC_ELEMENTAL_MORALE_LOCK_SIDS or custom_sid in GENERIC_CONSTRUCT_PROFILE_SIDS or faction_sid == "homm3_necropolis":
            stats["moral"] = 0
            stats["moralMin"] = 0
            stats["moralMax"] = 0
        if custom_sid in GENERIC_CONSTRUCT_PROFILE_SIDS:
            stats["luckMin"] = 0
            stats["luckMax"] = 0
            implemented.append("construct morale profile")
        elif faction_sid == "homm3_necropolis":
            implemented.append("undead morale profile")
        elif custom_sid in GENERIC_ELEMENTAL_MORALE_LOCK_SIDS:
            implemented.append("elemental morale lock")
    if is_shooter:
        for attack in as_attack_list(item.get("alternativeAttacks")) + as_attack_list(item.get("counterAttacks")):
            dealer = attack.get("damageDealer")
            if isinstance(dealer, dict):
                dealer["statDmgMult"] = melee_multiplier
        if custom_sid in GENERIC_FULL_MELEE_SHOOTER_SIDS:
            implemented.append("full-strength shooter melee")
    if custom_sid in GENERIC_COUNTERSHOT_SIDS:
        apply_countershot_attack_geometry(item, melee_stat_dmg_mult=melee_multiplier)
        implemented.append("ranged countershot")
    if custom_sid in GENERIC_SWIRL_ATTACK_SIDS:
        apply_hydra_attack_geometry(item)
    elif custom_sid in GENERIC_TRI_REACH_ATTACK_SIDS:
        apply_tri_reach_attack_geometry(item, trigger_counter=not no_retaliation)
    if custom_sid in GENERIC_ALTERNATIVE_BREATH_ATTACK_SIDS:
        breath = find_attack(item, "melee") or fallback_melee_attack(not no_retaliation)
        apply_breath_attack_geometry(breath, trigger_counter=not no_retaliation)
        alternatives = item.setdefault("alternativeAttacks", [])
        if isinstance(alternatives, list) and append_unique_json(alternatives, breath):
            implemented.append("two-hex breath attack")
    for attack in as_attack_list(item.get("defaultAttacks")) + as_attack_list(item.get("alternativeAttacks")):
        dealer = attack.get("damageDealer")
        if not isinstance(dealer, dict):
            continue
        if no_retaliation:
            dealer["triggerCounter"] = False
        if custom_sid in GENERIC_SWIRL_ATTACK_SIDS:
            set_damage_dealer_multi_target(
                attack,
                pattern=dealer.get("attackPatternSid") or "attack_swipe_x100_x100",
                trigger_counter=False,
                stat_dmg_mult=float(dealer.get("statDmgMult", 1.0)),
            )
        if custom_sid in GENERIC_BREATH_ATTACK_SIDS:
            dealer["attackPatternSid"] = "attack_reach_x1_x100_x100_with_delay"
            affect = dealer.setdefault("affectTargetParams", {})
            if isinstance(affect, dict):
                affect["castTarget_"] = "noself"
                affect["targetTags"] = ["unit", "attackable_object"]
                affect["targetCondition_"] = "alive"
                affect["selection"] = "object"
            dealer["damageTarget_"] = "all"
    for attack in as_attack_list(item.get("counterAttacks")):
        dealer = attack.get("damageDealer")
        if isinstance(dealer, dict) and custom_sid in GENERIC_SWIRL_ATTACK_SIDS:
            set_damage_dealer_multi_target(
                attack,
                pattern=dealer.get("attackPatternSid") or "attack_swipe_x100_x100",
                trigger_counter=False,
                stat_dmg_mult=float(dealer.get("statDmgMult", 1.0)),
            )
        if isinstance(dealer, dict) and custom_sid in GENERIC_BREATH_ATTACK_SIDS:
            dealer["attackPatternSid"] = "attack_reach_x1_x100_x100_with_delay"
            affect = dealer.setdefault("affectTargetParams", {})
            if isinstance(affect, dict):
                affect["castTarget_"] = "noself"
                affect["targetTags"] = ["unit", "attackable_object"]
                affect["targetCondition_"] = "alive"
                affect["selection"] = "object"
            dealer["damageTarget_"] = "all"
    if no_retaliation:
        implemented.append("no retaliation")
    if custom_sid in GENERIC_BREATH_ATTACK_SIDS:
        implemented.append("two-hex breath attack")
    if custom_sid in GENERIC_LONG_REACH_SIDS:
        long_reach = {
            "attackType_": "range",
            "rank": 1,
            "dontUseEnergy": True,
            "cd": -1,
            "selfMechanics": [],
            "damageDealer": {
                "tags": ["range_attack", "normal_damage", "basic_attack", "armed_ability", "no_counter", f"armed_ability_{custom_sid}"],
                "triggerCounter": False,
                "attackPatternSid": "attack_single_x100",
                "castTargetParams": {
                    "targetTags": ["unit", "attackable_object"],
                    "castTarget_": "enemy",
                    "targetCondition_": "alive",
                    "selection": "object",
                },
                "affectTargetParams": {
                    "targetTags": ["unit", "attackable_object"],
                    "castTarget_": "enemy",
                    "targetCondition_": "alive",
                    "selection": "object",
                },
                "damageTarget_": "enemy",
                "damageType_": "normal",
                "statDmgMult": 1.0,
                "targetMechanics": [],
            },
        }
        alternatives = item.setdefault("alternativeAttacks", [])
        if isinstance(alternatives, list) and append_unique_json(alternatives, long_reach):
            implemented.append("long-reach attack")
    if custom_sid in GENERIC_SWIRL_ATTACK_SIDS:
        implemented.append("all-adjacent attack")
    if custom_sid in GENERIC_TRI_REACH_ATTACK_SIDS:
        implemented.append("tri-reach attack")
    if custom_sid in GENERIC_SHARPSHOOTER_SIDS:
        set_ranged_no_distance_penalty(item)
    passives = item.setdefault("passives", [])
    if custom_sid in GENERIC_DENDROID_BINDING_SIDS:
        changed_binding = False
        for attack in as_attack_list(item.get("defaultAttacks")) + as_attack_list(item.get("counterAttacks")):
            if attack.get("attackType_") == "melee":
                changed_binding = apply_native_root_to_attack(attack, duration=2) or changed_binding
        if changed_binding:
            implemented.append("native root on melee attack")
    if isinstance(passives, list):
        if custom_sid in GENERIC_DOUBLE_RANGED_SIDS:
            append_unique_passive(passives, sequence_effect_passive("add_attack_after_counter_shoot"))
            implemented.append("double ranged attack")
        if custom_sid in GENERIC_DOUBLE_MELEE_SIDS:
            append_unique_passive(passives, sequence_effect_passive("add_attack_after_counter_melee"))
            implemented.append("double melee attack")
        if custom_sid in GENERIC_PARRY_COUNTER_FIRST_SIDS:
            append_unique_passive(passives, sequence_effect_passive("counter_before_attack"))
            implemented.append("parry counter-first")
    if custom_sid == "h3_sea_dog":
        abilities = item.setdefault("abilities", [])
        if isinstance(abilities, list) and append_unique_json(abilities, make_guillotine_creature_ability()):
            implemented.append("Guillotine-based Accurate Shot focus action")
    if custom_sid == "h3_pixie_upg_alt":
        abilities = item.setdefault("abilities", [])
        if isinstance(abilities, list) and append_unique_json(abilities, make_leeching_hop_creature_ability()):
            implemented.append("Leeching Hop mana transfer action")
    if isinstance(passives, list):
        immunity_level = GENERIC_MAGIC_LEVEL_IMMUNITY_BY_SID.get(custom_sid)
        if immunity_level is not None:
            append_unique_passive(passives, magic_level_immunity_passive(immunity_level))
            implemented.append(f"spell-level {immunity_level} immunity")
        if custom_sid in GENERIC_ICE_DAMAGE_IMMUNITY_SIDS:
            append_unique_passive(passives, ice_damage_immunity_passive())
            implemented.append("ice spell damage immunity")
        attack_pen = GENERIC_ATTACK_PEN_BY_SID.get(custom_sid)
        if attack_pen is not None:
            append_unique_passive(passives, attack_pen_passive(attack_pen))
            implemented.append("enemy Attack ignore")
        if custom_sid in GENERIC_PHOENIX_REBIRTH_SIDS:
            append_unique_passive(passives, phoenix_rebirth_passive(custom_sid))
            implemented.append("Grove Phoenix rebirth scaffold")
        if custom_sid in GENERIC_COVE_FEARLESS_SIDS:
            append_unique_passive(passives, cove_fearless_passive())
            implemented.append("Cove Fearsome effect immunity")
        if custom_sid in GENERIC_SWASHBUCKLER_GOLD_SIDS:
            implemented.append("Swashbuckler side day-start gold production")
        if custom_sid in GENERIC_CONSTRUCT_PROFILE_SIDS:
            append_unique_passive(passives, construct_profile_passive())
            append_unique_passive(passives, poison_blood_profile_passive())
        if faction_sid == "homm3_necropolis":
            append_unique_passive(passives, undead_profile_passive())
            append_unique_passive(passives, poison_blood_profile_passive())
    if custom_sid in COVE_AFTER_SHOT_WEAKNESS_BY_SID:
        changed = False
        for attack in as_attack_list(item.get("defaultAttacks")):
            if attack.get("attackType_") not in {"shoot", "range"}:
                continue
            dealer = attack.get("damageDealer")
            if not isinstance(dealer, dict):
                continue
            before = json.dumps(dealer, sort_keys=True, ensure_ascii=False)
            dealer["buffTarget_"] = "enemy"
            dealer["buff"] = {
                "sid": COVE_AFTER_SHOT_WEAKNESS_BY_SID[custom_sid],
                "duration": COVE_AFTER_SHOT_WEAKNESS_DURATION,
            }
            changed = changed or json.dumps(dealer, sort_keys=True, ensure_ascii=False) != before
        if changed:
            implemented.append("Cove after-shot Weakness")
    if custom_sid in BULWARK_AFTER_SHOT_ICE_BY_SID:
        changed = False
        for attack in as_attack_list(item.get("defaultAttacks")):
            if attack.get("attackType_") not in {"shoot", "range"}:
                continue
            dealer = attack.get("damageDealer")
            if not isinstance(dealer, dict):
                continue
            before = json.dumps(dealer, sort_keys=True, ensure_ascii=False)
            dealer["buffTarget_"] = "enemy"
            dealer["buff"] = {"sid": BULWARK_AFTER_SHOT_ICE_BY_SID[custom_sid], "duration": 1}
            changed = changed or json.dumps(dealer, sort_keys=True, ensure_ascii=False) != before
        if changed:
            implemented.append("Bulwark after-shot Ice Bolt mark")
    if custom_sid == "h3_sea_witch_upg_alt":
        abilities = item.setdefault("abilities", [])
        if isinstance(abilities, list) and append_unique_json(abilities, make_cove_summon_fangarms_ability()):
            implemented.append(HOMM3_COVE_SUMMON_FANGARMS_MECHANIC)
    return implemented


def remaining_generic_source_differences(line: dict[str, Any], custom_sid: str, implemented: list[str]) -> list[str]:
    differences = [str(item) for item in (line.get("mechanicsDebt") or [])]
    differences = [
        item
        for item in differences
        if custom_sid in VARIANT_SPECIFIC_MECHANICS_DEBT_SIDS.get(item, {custom_sid})
    ]
    differences = [GENERIC_MECHANICS_DEBT_LABEL_RENAMES.get(item, item) for item in differences]
    if "full-strength shooter melee" in implemented:
        differences = [item for item in differences if item != "No melee penalty"]
    if "no retaliation" in implemented:
        differences = [item for item in differences if item != "No retaliation"]
    if "Guillotine-based Accurate Shot focus action" in implemented:
        differences = [item for item in differences if item != "Accurate Shot focus conversion"]
    if "double ranged attack" in implemented:
        differences = [item for item in differences if item != "Double ranged attack"]
    if "double melee attack" in implemented:
        differences = [item for item in differences if item not in {"Double melee attack", "Additional attack"}]
    if "all-adjacent attack" in implemented:
        differences = [
            item
            for item in differences
            if item not in {"All-adjacent no retaliation", "Faerie all-adjacent no retaliation", "Three-headed attack"}
            and "heat stroke" not in item.lower()
        ]
    if "tri-reach attack" in implemented:
        differences = [item for item in differences if item != "Three-headed attack"]
    if "unlimited retaliation" in implemented:
        differences = [item for item in differences if "unlimited retaliat" not in item.lower()]
    if "parry counter-first" in implemented:
        differences = [item for item in differences if "first-counter" not in item.lower() and "first strike" not in item.lower() and "swift" not in item.lower()]
    if "ranged countershot" in implemented:
        differences = [item for item in differences if "ranged retal" not in item.lower() and "countershot" not in item.lower()]
    if "positive luck floor" in implemented:
        differences = [item for item in differences if "positive luck" not in item.lower()]
    if "teleporting movement" in implemented:
        differences = [item for item in differences if item != "Teleporting movement"]
    if "ice spell damage immunity" in implemented:
        differences = [item for item in differences if item != "Ice Bolt/Frost Ring/Freezing Shot immunity"]
    if "two-hex breath attack" in implemented:
        differences = [item for item in differences if "breath" not in item.lower()]
    if "enemy Attack ignore" in implemented:
        differences = [item for item in differences if item != "Enemy Attack ignore must be implemented in the damage formula"]
    if "native root focus active" in implemented:
        differences = [item for item in differences if item != "Nix Praetorian Bind focus conversion"]
    if "Cove Fearsome effect immunity" in implemented:
        differences = [item for item in differences if item != "Abyss Serpent exact Fearless/Skeleton Transformer behavior"]
    if "Swashbuckler side day-start gold production" in implemented:
        differences = [item for item in differences if item != "Swashbuckler daily gold economy trace"]
    if HOMM3_COVE_SUMMON_FANGARMS_MECHANIC in implemented:
        differences = [item for item in differences if item != "Tidecaller Summon Fangarms trace"]
    if "undead morale profile" in implemented:
        differences = [item for item in differences if item != "Undead profile"]
    if "construct morale profile" in implemented:
        differences = [item for item in differences if item != "Golem/unliving profile"]
    if "elemental morale lock" in implemented:
        differences = [item for item in differences if item != "Elemental morale lock"]
    if "no range or obstacle penalty" in implemented or "no obstacle penalty" in implemented:
        differences = [item for item in differences if item not in {"No wall penalty", "No distance/wall penalty", "No range or obstacle penalty"}]
    return differences


def strip_stale_inferno_donor_conditional_passives(item: dict[str, Any]) -> None:
    passives = item.get("conditionalPassives")
    if not isinstance(passives, list):
        passives = [passives] if isinstance(passives, dict) else []
    kept: list[dict[str, Any]] = []
    for passive in passives:
        if not isinstance(passive, dict):
            continue
        condition = passive.get("condition")
        if (
            isinstance(condition, list)
            and len(condition) >= 3
            and condition[0] == "unique_units_count"
            and condition[1] == "ally"
            and condition[2] in {"demon", "demons"}
        ):
            continue
        kept.append(passive)
    item["conditionalPassives"] = kept


def normalize_generic_unit_logic(
    doc: Any,
    custom_sid: str,
    line: dict[str, Any],
    suffix_index: int,
    variants: tuple[str, ...],
    manifest: dict[str, Any],
) -> tuple[Any, bool, bool]:
    item = first_array_item(doc)
    if not isinstance(item, dict):
        return doc, False, False
    faction_sid = manifest["identity"]["factionSid"]
    scaffold = manifest_release_scaffold(manifest)
    is_shooter, is_flyer = infer_generic_unit_baseline(item)
    target_stats = generic_unit_target_stats(custom_sid, line, suffix_index, manifest)
    if target_stats:
        # Manifest sourceStats may omit explicit role flags; derive them fail-closed
        # from shots / isShooter / isFlyer so HotA shooters and flyers are not
        # silently collapsed to donor melee/ground baselines.
        shots = target_stats.get("shots")
        is_shooter = bool(target_stats.get("isShooter")) or (isinstance(shots, int) and shots > 0)
        is_flyer = bool(target_stats.get("isFlyer"))
    if custom_sid in GENERIC_FORCE_GROUND_SIDS or custom_sid in GENERIC_TELEPORT_MOVE_SIDS:
        is_flyer = False
    elif custom_sid in GENERIC_FORCE_FLYER_SIDS:
        is_flyer = True
    item["id"] = custom_sid
    item["fraction"] = faction_sid
    item["nativeBiome"] = scaffold["biome"]
    item["tier"] = line["tier"]
    if suffix_index == 0:
        item.pop("baseSid", None)
    else:
        item["baseSid"] = manifest_unit_sid_for_variant(line, variants[suffix_index - 1])
    if suffix_index + 1 < len(variants):
        item["upgradeSid"] = manifest_unit_sid_for_variant(line, variants[suffix_index + 1])
    else:
        item.pop("upgradeSid", None)
    tags = item.get("tags")
    if isinstance(tags, list):
        donor_tags = {"human", "humans", "demon", "demons", "undead", "necros", "nature", "dungeon", "unfrozen"}
        item["tags"] = [faction_sid if tag in donor_tags else tag for tag in tags]
        if faction_sid not in item["tags"]:
            item["tags"].append(faction_sid)
    if faction_sid == "homm3_inferno":
        strip_stale_inferno_donor_conditional_passives(item)
    stats = item.setdefault("stats", {})
    if isinstance(stats, dict):
        if is_flyer:
            stats["moveType"] = "fly"
        else:
            stats.pop("moveType", None)
    stats_source = apply_generic_unit_target_stats(item, target_stats)
    apply_homm3_unit_balance_logic_adjustment(item, custom_sid)
    stats = item.setdefault("stats", {})
    if isinstance(stats, dict):
        if is_flyer:
            stats["moveType"] = "fly"
        else:
            stats.pop("moveType", None)
    item["abilities"] = []
    item["passives"] = []
    item.pop("aura", None)
    item.pop("globalPassives", None)
    if is_shooter:
        shoot = find_attack(item, "shoot") or fallback_shoot_attack()
        melee = find_attack(item, "melee") or fallback_melee_attack(True)
        normalize_damage_dealer(shoot, True, melee=False)
        item["defaultAttacks"] = [shoot]
        normalize_damage_dealer(melee, True, melee=True, stat_dmg_mult=0.5)
        item["alternativeAttacks"] = [melee]
        counter = find_attack(item, "melee") or fallback_melee_attack(False)
        normalize_damage_dealer(counter, False, melee=True, stat_dmg_mult=0.5)
        item["counterAttacks"] = [counter]
    else:
        melee = find_attack(item, "melee") or fallback_melee_attack(True)
        normalize_damage_dealer(melee, True, melee=True)
        counter = find_attack(item, "melee") or fallback_melee_attack(False)
        normalize_damage_dealer(counter, False, melee=True)
        item["defaultAttacks"] = [melee]
        item["alternativeAttacks"] = []
        item["counterAttacks"] = [counter]
    implemented_mechanics = apply_generic_mechanics_to_logic(item, custom_sid, is_shooter, faction_sid)
    item["xHomm3ImplementationAudit"] = {
        "source": f"custom_factions/{faction_sid}.json",
        "implementedData": "Faction identity, source-backed basic stats/costs where available, donor-safe baseline attack role, native biome, upgrade chain, city recruitment, direct map object routing",
        "statsSource": stats_source or "missing source stat row; donor stats retained and this row must be fixed before final release",
        "implementedMechanics": implemented_mechanics,
    }
    return doc, is_shooter, is_flyer


def generic_view_ability(name: str, ability_type: str, description: str, animation_index: int = 1) -> dict[str, Any]:
    return {
        "name": name,
        "abilityType": ability_type,
        "description": description,
        "animationIndex": animation_index,
        "useExpandTooltip": "false",
    }


