def normalize_generic_unit_view(
    doc: Any,
    custom_sid: str,
    line: dict[str, Any],
    is_shooter: bool,
    is_flyer: bool,
    manifest: dict[str, Any],
) -> Any:
    item = first_array_item(doc)
    if isinstance(item, dict):
        faction_sid = manifest["identity"]["factionSid"]
        item["id"] = custom_sid
        item["abilities"] = []
        passives: list[dict[str, str]] = [
            {
                "name": "h3_common_ranged_attack_name" if is_shooter else "h3_common_melee_attack_name",
                "description": "h3_common_ranged_attack_description" if is_shooter else "h3_common_melee_attack_description",
            }
        ]
        if is_flyer:
            passives.append({"name": "base_passive_flyer_name", "description": "base_passive_flyer_description"})
        implemented_mechanics = apply_generic_mechanics_to_view(item, custom_sid, passives)
        if custom_sid in GENERIC_CONSTRUCT_PROFILE_SIDS:
            item["baseClass"] = {"name": "base_class_construct", "description": "base_class_construct_description"}
        elif faction_sid == "homm3_necropolis":
            item["baseClass"] = {"name": "base_class_undead", "description": "base_class_undead_description"}
        item["passives"] = passives
        item["defaultAttacks"] = [view_attack(0, custom_sid=custom_sid if is_shooter else None)]
        item["counterAttacks"] = [view_attack(0)]
        item["alternativeAttacks"] = [ranged_melee_view_attack(1)] if is_shooter else []
        if custom_sid in GENERIC_SWIRL_ATTACK_SIDS:
            item["alternativeAttacks"] = [hydra_alternative_view_attack(1)]
        if custom_sid in GENERIC_ALTERNATIVE_BREATH_ATTACK_SIDS:
            item["alternativeAttacks"] = [hydra_alternative_view_attack(1)]
        if custom_sid in GENERIC_LONG_REACH_SIDS:
            item["alternativeAttacks"] = [long_reach_view_attack(1)]
        if custom_sid in GENERIC_COUNTERSHOT_SIDS:
            item["counterAttacks"] = countershot_view_attacks(custom_sid)
        item["xHomm3ImplementationAudit"] = {
            "source": f"custom_factions/{faction_sid}.json",
            "implementedData": "Donor-safe preview mesh/mapMesh, baseline attack role",
            "implementedMechanics": implemented_mechanics,
        }
    return doc


def apply_stronghold_source_unit_mechanics(item: dict[str, Any], custom_sid: str, section: str) -> list[str]:
    spec = STRONGHOLD_SOURCE_UNIT_MECHANICS.get(custom_sid, {}).get(section)
    if not isinstance(spec, dict):
        return []
    changed = False
    if "stats" in spec:
        stats_spec = spec["stats"]
        if not isinstance(stats_spec, dict):
            raise RuntimeError(f"{custom_sid}: Stronghold {section} stats source must be an object")
        if "stats" not in item:
            stats = item.setdefault("stats", {})
        else:
            stats = item["stats"]
        if not isinstance(stats, dict):
            raise RuntimeError(f"{custom_sid}: Stronghold {section} target stats must be an object")
        for key, value in stats_spec.items():
            if stats.get(key) != value:
                stats[key] = copy.deepcopy(value)
                changed = True
    for key in ("abilities", "passives", "alternativeAttacks"):
        rows = spec.get(key)
        if not isinstance(rows, list) or not rows:
            continue
        bucket = item.setdefault(key, [])
        if not isinstance(bucket, list):
            continue
        for row in rows:
            changed = append_unique_json(bucket, copy.deepcopy(row)) or changed
    return ["Stronghold source unit mechanics"] if changed else []


def apply_strong_vanilla_logic_mechanics(item: dict[str, Any], custom_sid: str) -> list[str]:
    implemented: list[str] = []
    abilities = item.setdefault("abilities", [])
    if isinstance(abilities, list):
        for kind in STRONG_VANILLA_ACTIVE_BY_SID.get(custom_sid, ()):
            if append_unique_json(abilities, make_strong_vanilla_active_ability(kind, custom_sid)):
                implemented.append(str(STRONG_VANILLA_ACTIVE_SPECS[kind]["implemented"]))
        for kind in MVP_DONOR_ACTIVE_BY_SID.get(custom_sid, ()):
            if append_unique_json(abilities, make_strong_vanilla_active_ability(kind, custom_sid)):
                implemented.append(str(STRONG_VANILLA_ACTIVE_SPECS[kind]["implemented"]))

    implemented.extend(apply_stronghold_source_unit_mechanics(item, custom_sid, "logic"))

    if custom_sid in STRONG_VANILLA_REGENERATION_SIDS:
        passives = item.setdefault("passives", [])
        if isinstance(passives, list) and append_unique_json(passives, fortress_start_turn_regeneration(0.10)):
            implemented.append("native heal-percent regeneration")

    if custom_sid in STRONG_VANILLA_LIFE_DRAIN_SIDS:
        vampirism = {"mech": "vampirism", "values": ["0", "0.4", "self", "until start amount"], "afterAttack": True}
        changed = False
        for attack in as_attack_list(item.get("defaultAttacks")) + as_attack_list(item.get("counterAttacks")):
            if attack.get("attackType_") != "melee":
                continue
            self_mechanics = attack.setdefault("selfMechanics", [])
            if isinstance(self_mechanics, list):
                changed = append_unique_json(self_mechanics, vampirism) or changed
            dealer = attack.get("damageDealer")
            if isinstance(dealer, dict) and dealer.get("triggerCounter") is not False:
                dealer["triggerCounter"] = False
                changed = True
        if changed:
            implemented.append("Vampire life drain")

    if custom_sid in STRONG_VANILLA_DEATH_CLOUD_SIDS:
        changed = False
        for attack in as_attack_list(item.get("defaultAttacks")) + as_attack_list(item.get("alternativeAttacks")):
            if attack.get("attackType_") not in {"shoot", "range"}:
                continue
            dealer = attack.get("damageDealer")
            if not isinstance(dealer, dict):
                continue
            before = json.dumps(dealer, sort_keys=True, ensure_ascii=False)
            dealer["attackPatternSid"] = "attack_rumble_x1_x100"
            dealer["damageTarget_"] = "enemy"
            affect = dealer.setdefault("affectTargetParams", {})
            if isinstance(affect, dict):
                affect["targetTags"] = ["unit", "attackable_object"]
                affect["castTarget_"] = "enemy"
                affect["targetCondition_"] = "alive"
                affect["selection"] = "object"
            changed = changed or json.dumps(dealer, sort_keys=True, ensure_ascii=False) != before
        if changed:
            implemented.append("native Lich death-cloud attack geometry")

    note_strong_vanilla_implemented(item, implemented)
    return implemented


