def read_overlay_or_release_json(release_zip: zipfile.ZipFile, output: dict[str, bytes], name: str) -> Any:
    if name in output:
        return json.loads(output[name].decode("utf-8-sig"))
    return read_json(release_zip, name)


LOCALIZED_DEBT_TEXT_RE = re.compile(
    r"MVP|proxy|staticTraceDebt|trace_required|mechanics debt|ÃƒÂÃ‚Â¿Ãƒâ€˜Ã¢â€šÂ¬ÃƒÂÃ‚Â¾ÃƒÂÃ‚ÂºÃƒâ€˜Ã‚Â",
    re.IGNORECASE,
)

def lang_doc_tokens(doc: Any) -> list[Any]:
    if not isinstance(doc, dict):
        return []
    tokens = doc.get("tokens")
    if isinstance(tokens, list):
        return tokens
    array = doc.get("array")
    return array if isinstance(array, list) else []


def clean_multilingual_custom_ability_debt_text(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Replace stale localized custom ability debt wording from clean English rows."""
    target_suffix = "/texts/unitsAbility.json"
    english_name = "Lang/english/texts/unitsAbility.json"
    try:
        english_doc = read_overlay_or_release_json(release_zip, output, english_name)
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
        return

    clean_text_by_sid: dict[str, str] = {}
    for token in lang_doc_tokens(english_doc):
        if not isinstance(token, dict):
            continue
        sid = token.get("sid")
        text = token.get("text")
        if (
            isinstance(sid, str)
            and sid.startswith(("h3_", "homm3_"))
            and isinstance(text, str)
            and not LOCALIZED_DEBT_TEXT_RE.search(text)
        ):
            clean_text_by_sid[sid] = text

    if not clean_text_by_sid:
        return

    member_names = sorted(
        name
        for name in set(release_zip.namelist()) | set(output)
        if name.startswith("Lang/") and name.endswith(target_suffix) and name != english_name
    )
    changed_members = 0
    changed_tokens = 0
    for name in member_names:
        try:
            doc = read_overlay_or_release_json(release_zip, output, name)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
            continue
        changed = False
        for token in lang_doc_tokens(doc):
            if not isinstance(token, dict):
                continue
            sid = token.get("sid")
            if not isinstance(sid, str) or not sid.startswith(("h3_", "homm3_")):
                continue
            replacement = clean_text_by_sid.get(sid)
            if not replacement:
                continue
            for key, value in list(token.items()):
                if key == "sid" or not isinstance(value, str):
                    continue
                if LOCALIZED_DEBT_TEXT_RE.search(value):
                    token[key] = replacement
                    changed = True
                    changed_tokens += 1
        if changed:
            output[name] = write_json(doc)
            changed_members += 1
    if changed_members:
        notes.append(f"clean stale localized custom ability debt text ({changed_tokens} tokens in {changed_members} files)")


def apply_strong_vanilla_mechanics_to_custom_unit_rows(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    changed_logic = 0
    changed_view = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            if custom_sid not in STRONG_VANILLA_MECHANIC_SIDS:
                continue
            logic_name = f"DB/units/units_logics/{faction_sid}/{custom_sid}_l.json"
            view_name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                logic_doc = read_overlay_or_release_json(release_zip, output, logic_name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing strong-vanilla logic {logic_name}: {ex}")
                logic_doc = None
            if logic_doc is not None:
                before = json.dumps(logic_doc, sort_keys=True, ensure_ascii=False)
                logic_item = first_array_item(logic_doc)
                if isinstance(logic_item, dict):
                    implemented = apply_strong_vanilla_logic_mechanics(logic_item, custom_sid)
                    if faction_sid == "homm3_tower":
                        tower_implemented = apply_tower_attack_role_guard_to_logic(logic_item, custom_sid)
                        note_strong_vanilla_implemented(logic_item, [entry for entry in tower_implemented if entry not in implemented])
                    if custom_sid in GENERIC_DATA_MECHANIC_SIDS or faction_sid == "homm3_necropolis":
                        generic_implemented = apply_generic_mechanics_to_logic(
                            logic_item,
                            custom_sid,
                            find_attack(logic_item, "shoot") is not None,
                            faction_sid,
                        )
                        note_strong_vanilla_implemented(logic_item, [entry for entry in generic_implemented if entry not in implemented])
                if json.dumps(logic_doc, sort_keys=True, ensure_ascii=False) != before:
                    output[logic_name] = write_json(logic_doc)
                    changed_logic += 1

            try:
                view_doc = read_overlay_or_release_json(release_zip, output, view_name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing strong-vanilla view {view_name}: {ex}")
                view_doc = None
            if view_doc is not None:
                before = json.dumps(view_doc, sort_keys=True, ensure_ascii=False)
                view_item = first_array_item(view_doc)
                if isinstance(view_item, dict):
                    implemented = apply_strong_vanilla_view_mechanics(view_item, custom_sid)
                    if faction_sid == "homm3_tower":
                        tower_implemented = apply_tower_attack_role_guard_to_view(view_item, custom_sid)
                        note_strong_vanilla_implemented(view_item, [entry for entry in tower_implemented if entry not in implemented])
                    if custom_sid in GENERIC_DATA_MECHANIC_SIDS or faction_sid == "homm3_necropolis":
                        passives = view_item.setdefault("passives", [])
                        if isinstance(passives, list):
                            generic_implemented = apply_generic_mechanics_to_view(view_item, custom_sid, passives)
                            if custom_sid in GENERIC_CONSTRUCT_PROFILE_SIDS:
                                view_item["baseClass"] = {"name": "base_class_construct", "description": "base_class_construct_description"}
                            elif faction_sid == "homm3_necropolis":
                                view_item["baseClass"] = {"name": "base_class_undead", "description": "base_class_undead_description"}
                            if custom_sid in GENERIC_SWIRL_ATTACK_SIDS:
                                view_item["alternativeAttacks"] = [hydra_alternative_view_attack(1)]
                            if custom_sid in GENERIC_COUNTERSHOT_SIDS:
                                view_item["counterAttacks"] = countershot_view_attacks(custom_sid)
                            note_strong_vanilla_implemented(view_item, [entry for entry in generic_implemented if entry not in implemented])
                if json.dumps(view_doc, sort_keys=True, ensure_ascii=False) != before:
                    output[view_name] = write_json(view_doc)
                    changed_view += 1
    if changed_logic or changed_view:
        notes.append(f"apply strong-vanilla active mechanics to custom unit rows ({changed_logic} logic, {changed_view} view)")


def load_ability_override(faction_sid: str) -> dict[str, Any] | None:
    path = ABILITY_OVERRIDE_DIR / f"{faction_sid}.json"
    if not path.exists():
        return None
    with path.open("r", encoding="utf-8-sig") as f:
        value = json.load(f)
    return value if isinstance(value, dict) else None


def load_hero_override(faction_sid: str) -> dict[str, Any] | None:
    path = HERO_OVERRIDE_DIR / f"{faction_sid}.json"
    if not path.exists():
        return None
    with path.open("r", encoding="utf-8-sig") as f:
        value = json.load(f)
    return value if isinstance(value, dict) else None


def load_law_override(faction_sid: str) -> dict[str, Any] | None:
    path = _ACTIVE_LAW_OVERRIDE_DIR / f"{faction_sid}.json"
    if not path.exists():
        return None
    with path.open("r", encoding="utf-8-sig") as f:
        value = json.load(f)
    return value if isinstance(value, dict) else None


_CUSTOM_LAW_TARGETS_BY_SID: dict[str, dict[str, Any]] | None = None
_CUSTOM_LAW_TARGET_PACKET_BY_SID: dict[str, str] | None = None


def custom_law_targets_by_sid() -> dict[str, dict[str, Any]]:
    global _CUSTOM_LAW_TARGETS_BY_SID
    if _CUSTOM_LAW_TARGETS_BY_SID is not None:
        return _CUSTOM_LAW_TARGETS_BY_SID
    if not CUSTOM_LAW_TARGETS_PATH.exists():
        _CUSTOM_LAW_TARGETS_BY_SID = {}
        return _CUSTOM_LAW_TARGETS_BY_SID
    with CUSTOM_LAW_TARGETS_PATH.open("r", encoding="utf-8-sig") as f:
        doc = json.load(f)
    result: dict[str, dict[str, Any]] = {}
    packet_by_sid: dict[str, str] = {}
    families = doc.get("families") if isinstance(doc, dict) else None
    if isinstance(doc, dict):
        targets = doc.get("targets")
        if isinstance(targets, list):
            for target in targets:
                if not isinstance(target, dict):
                    continue
                law_sid = target.get("lawSid")
                if isinstance(law_sid, str) and law_sid:
                    result[law_sid] = target
                    law_index = target.get("lawIndex")
                    family_entry = families.get(str(law_index)) if isinstance(families, dict) else None
                    packet = family_entry.get("packet") if isinstance(family_entry, dict) else None
                    if isinstance(packet, str) and packet:
                        packet_by_sid[law_sid] = packet
    _CUSTOM_LAW_TARGETS_BY_SID = result
    global _CUSTOM_LAW_TARGET_PACKET_BY_SID
    _CUSTOM_LAW_TARGET_PACKET_BY_SID = packet_by_sid
    return result


def stamp_no_compromise_law_target_metadata(row: dict[str, Any], law_sid: str) -> None:
    target = custom_law_targets_by_sid().get(law_sid)
    if not isinstance(target, dict):
        return
    status = target.get("implementationStatus")
    packet = (_CUSTOM_LAW_TARGET_PACKET_BY_SID or {}).get(law_sid)
    row["xHomm3NoCompromiseTarget"] = True
    if isinstance(status, str) and status:
        row["xHomm3NoCompromiseStatus"] = status
    if isinstance(packet, str) and packet:
        row["xHomm3NoCompromisePacket"] = packet
    mechanic = target.get("targetMechanic")
    if isinstance(mechanic, str) and mechanic:
        row["xHomm3NoCompromiseTargetMechanic"] = mechanic


def custom_law_override_entry(manifest: dict[str, Any], index: int) -> dict[str, Any] | None:
    faction_sid = manifest["identity"]["factionSid"]
    override = load_law_override(faction_sid)
    law_overrides = override.get("lawOverrides") if isinstance(override, dict) else None
    if not isinstance(law_overrides, dict):
        return None
    law_prefix = manifest_law_prefix(manifest)
    for key in (f"{law_prefix}{index}", str(index)):
        entry = law_overrides.get(key)
        if isinstance(entry, dict):
            return entry
    return None


def custom_law_tracked_indices(manifest: dict[str, Any]) -> tuple[int, ...]:
    law_prefix = manifest_law_prefix(manifest)
    indices: set[int] = set()
    for law_sid in custom_law_targets_by_sid():
        if not law_sid.startswith(law_prefix):
            continue
        suffix = law_sid.removeprefix(law_prefix)
        if suffix.isdigit():
            indices.add(int(suffix))
    return tuple(sorted(indices))


def custom_law_override_indices(manifest: dict[str, Any]) -> tuple[int, ...]:
    faction_sid = manifest["identity"]["factionSid"]
    override = load_law_override(faction_sid)
    law_overrides = override.get("lawOverrides") if isinstance(override, dict) else None
    if not isinstance(law_overrides, dict):
        return ()
    law_prefix = manifest_law_prefix(manifest)
    indices: set[int] = set()
    for key in law_overrides:
        if not isinstance(key, str):
            continue
        suffix = key.removeprefix(law_prefix) if key.startswith(law_prefix) else key
        if suffix.isdigit():
            indices.add(int(suffix))
    return tuple(sorted(indices))


def custom_law_candidate_indices(manifest: dict[str, Any], donor_count: int) -> tuple[int, ...]:
    return tuple(
        sorted(
            set(range(1, donor_count + 1))
            | set(custom_law_tracked_indices(manifest))
            | set(custom_law_override_indices(manifest))
        )
    )


def custom_law_override_definition(manifest: dict[str, Any], index: int) -> tuple[str, str, list[dict[str, Any]]] | None:
    override = custom_law_override_entry(manifest, index)
    if not isinstance(override, dict) or override.get("enabled") is False:
        return None
    has_definition_fields = any(key in override for key in ("nameText", "descriptionText", "parametersPerLevel"))
    if not has_definition_fields:
        return None
    faction_sid = manifest["identity"]["factionSid"]
    law_prefix = manifest_law_prefix(manifest)
    law_sid = f"{law_prefix}{index}"
    name_text = override.get("nameText")
    desc_text = override.get("descriptionText")
    levels = override.get("parametersPerLevel")
    if not isinstance(name_text, str) or not name_text.strip():
        raise RuntimeError(f"{faction_sid}: enabled law override {law_sid} is missing nameText")
    if not isinstance(desc_text, str) or not desc_text.strip():
        raise RuntimeError(f"{faction_sid}: enabled law override {law_sid} is missing descriptionText")
    if not isinstance(levels, list) or not levels:
        raise RuntimeError(f"{faction_sid}: enabled law override {law_sid} is missing parametersPerLevel")
    return name_text.strip(), desc_text.strip(), copy.deepcopy(levels)


def resolve_unit_special_from_release(
    release_zip: zipfile.ZipFile,
    source_unit_sid: str,
    slot_kind: str,
    slot_index: int,
) -> tuple[dict[str, Any], dict[str, Any], str]:
    suffix = f"/{source_unit_sid}_l.json"
    for info in release_zip.infolist():
        logic_name = normalize_name(info.filename)
        if info.is_dir() or not logic_name.startswith("DB/units/units_logics/") or not logic_name.endswith(suffix):
            continue
        parts = logic_name.split("/")
        if len(parts) < 5:
            continue
        source_faction_sid = parts[3]
        view_name = f"DB/units/units_views/{source_faction_sid}/{source_unit_sid}_v.json"
        logic_item = first_array_item(read_json(release_zip, logic_name))
        view_item = first_array_item(read_json(release_zip, view_name))
        if not isinstance(logic_item, dict) or not isinstance(view_item, dict):
            continue
        logic_slots = logic_item.get(slot_kind)
        view_slots = view_item.get(slot_kind)
        if not isinstance(logic_slots, list) or not isinstance(view_slots, list):
            continue
        if slot_index < 0 or slot_index >= len(logic_slots) or slot_index >= len(view_slots):
            continue
        logic_special = logic_slots[slot_index]
        view_special = view_slots[slot_index]
        if isinstance(logic_special, dict) and isinstance(view_special, dict):
            return copy.deepcopy(logic_special), copy.deepcopy(view_special), source_faction_sid
    raise KeyError(f"no release unit special {source_unit_sid}:{slot_kind}:{slot_index}")


def parse_unit_special_key(value: Any) -> tuple[str, str, int] | None:
    if not isinstance(value, str):
        return None
    parts = value.split(":")
    if len(parts) != 3:
        return None
    try:
        index = int(parts[2])
    except ValueError:
        return None
    if not parts[0] or not parts[1]:
        return None
    return parts[0], parts[1], index


def parse_spell_effect_key(value: Any) -> tuple[str, int] | None:
    if not isinstance(value, str):
        return None
    marker = ":level:"
    if marker not in value:
        return None
    spell_sid, level_text = value.rsplit(marker, 1)
    try:
        level = int(level_text)
    except ValueError:
        return None
    if not spell_sid or level < 1:
        return None
    return spell_sid, level


def resolve_spell_effect_from_release(
    release_zip: zipfile.ZipFile,
    spell_sid: str,
    spell_level: int,
) -> tuple[dict[str, Any], dict[str, Any], int]:
    for info in release_zip.infolist():
        magic_name = normalize_name(info.filename)
        if info.is_dir() or not magic_name.startswith("DB/magics/") or not magic_name.endswith(".json"):
            continue
        doc = read_json(release_zip, magic_name)
        rows = doc.get("array") if isinstance(doc, dict) else None
        if not isinstance(rows, list):
            continue
        for row in rows:
            if not isinstance(row, dict) or row.get("id") != spell_sid:
                continue
            battle_magic = row.get("battleMagic")
            dealers = battle_magic.get("magicDealers") if isinstance(battle_magic, dict) else None
            if not isinstance(dealers, list):
                break
            dealer_indexes = battle_magic.get("dealersPerLevels")
            if not isinstance(dealer_indexes, list) or not dealer_indexes:
                dealer_indexes = list(range(len(dealers)))
            level_offset = spell_level - 1
            if level_offset < 0 or level_offset >= len(dealer_indexes):
                break
            dealer_index = dealer_indexes[level_offset]
            if not isinstance(dealer_index, int) or dealer_index < 0 or dealer_index >= len(dealers):
                break
            dealer = dealers[dealer_index]
            if isinstance(dealer, dict):
                return copy.deepcopy(row), copy.deepcopy(dealer), dealer_index
    raise KeyError(f"no release spell effect {spell_sid}:level:{spell_level}")


def replace_spell_power_tokens(value: Any, effective_spell_power: int | None) -> Any:
    if effective_spell_power is None:
        return value
    if isinstance(value, str):
        return str(effective_spell_power) if value == "spellPower" else value
    if isinstance(value, list):
        return [replace_spell_power_tokens(item, effective_spell_power) for item in value]
    if isinstance(value, dict):
        return {key: replace_spell_power_tokens(item, effective_spell_power) for key, item in value.items()}
    return value


def coerce_optional_int(value: Any) -> int | None:
    if isinstance(value, bool) or value is None or value == "":
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, str):
        try:
            return int(value)
        except ValueError:
            return None
    return None


def override_text_token(custom_sid: str, token_hint: Any, text: Any, suffix: str, lang_rows: list[dict[str, str]]) -> str | None:
    if isinstance(text, str) and text.strip():
        hint = token_hint if isinstance(token_hint, str) and token_hint.startswith(custom_sid + "_") else None
        token = hint or f"{custom_sid}_{suffix}"
        lang_rows.append({"sid": token, "text": text.strip()})
        return token
    return token_hint if isinstance(token_hint, str) and token_hint else None


def set_slot_entry(slots: list[Any], index: int | None, row: dict[str, Any]) -> bool:
    if index is not None and index >= 0:
        while len(slots) <= index:
            slots.append({})
        if slots[index] != row:
            slots[index] = row
            return True
        return False
    for existing_index, existing in enumerate(slots):
        if isinstance(existing, dict) and existing.get("xHomm3AbilityOverride") == row.get("xHomm3AbilityOverride"):
            if existing != row:
                slots[existing_index] = row
                return True
            return False
    slots.append(row)
    return True


def apply_ability_envelope_overrides(logic_row: dict[str, Any], view_row: dict[str, Any], fields: dict[str, Any]) -> None:
    attack_type = fields.get("attackType")
    if attack_type is None:
        attack_type = fields.get("attackType_")
    if isinstance(attack_type, str) and attack_type.strip():
        logic_row["attackType_"] = attack_type.strip()
    rank = coerce_optional_int(fields.get("rank"))
    if rank is not None:
        logic_row["rank"] = rank
    cooldown = coerce_optional_int(fields.get("cooldown"))
    if cooldown is not None:
        logic_row["cd"] = cooldown
    energy_level = coerce_optional_int(fields.get("energyLevel"))
    if energy_level is not None:
        logic_row["energyLevel"] = energy_level
    charges = coerce_optional_int(fields.get("charges"))
    if charges is not None:
        logic_row["charges"] = charges
    turn_behavior = fields.get("turnBehavior")
    if isinstance(turn_behavior, str):
        turn_behavior = turn_behavior.strip()
        if turn_behavior == "free":
            logic_row["actionCost"] = 0
        elif turn_behavior == "ends":
            logic_row.pop("actionCost", None)
    ability_type = fields.get("abilityType")
    if isinstance(ability_type, str) and ability_type.strip():
        view_row["abilityType"] = ability_type.strip()
    animation_index = coerce_optional_int(fields.get("animationIndex"))
    if animation_index is not None:
        view_row["animationIndex"] = animation_index


def apply_direct_state_native_shell(logic_row: dict[str, Any], fields: dict[str, Any]) -> None:
    shell = fields.get("directStateNativeShell")
    if not isinstance(shell, dict):
        return
    mode = shell.get("mode")
    if isinstance(mode, str):
        mode = mode.strip()
    else:
        mode = "stripForDirectState"

    reshape = shell.get("reshape")
    reshape_meta: dict[str, Any] | None = None

    if mode == "restoreNativeMechanic":
        # Keep / rewrite native targetMechanics so egd.bdpz can instantiate the live
        # PushUnit handler (ehh). Do not strip for MovementPush dual-writes.
        if isinstance(reshape, dict) and reshape:
            reshape_meta = apply_direct_state_native_shell_reshape(logic_row, reshape)
        dealer = logic_row.get("damageDealer")
        if not isinstance(dealer, dict):
            raise ValueError("restoreNativeMechanic requires damageDealer on the donor shell")
        mechanics = dealer.get("targetMechanics")
        if not isinstance(mechanics, list) or not mechanics:
            raise ValueError("restoreNativeMechanic requires non-empty damageDealer.targetMechanics after reshape")
        logic_row["xHomm3DirectStateNativeShell"] = {
            "mode": mode,
            "retainedMechanics": [
                item.get("mech")
                for item in mechanics
                if isinstance(item, dict) and isinstance(item.get("mech"), str)
            ],
            "removedCount": 0,
            **({"reshape": reshape_meta} if reshape_meta else {}),
        }
        return

    fixture_flag = shell.get("fixtureFlag")
    mechanics = shell.get("stripMechanics")
    required_count = coerce_optional_int(shell.get("requireExactRemovalCount"))
    if (
        not isinstance(fixture_flag, str)
        or not fixture_flag.strip()
        or not isinstance(mechanics, list)
        or not mechanics
        or any(not isinstance(value, str) or not value.strip() for value in mechanics)
        or required_count is None
        or required_count < 1
    ):
        raise ValueError(
            "directStateNativeShell stripForDirectState requires fixtureFlag, stripMechanics, "
            "and positive requireExactRemovalCount (or use mode=restoreNativeMechanic)"
        )

    normalized = {value.strip() for value in mechanics}

    def contains_token(value: Any) -> bool:
        if isinstance(value, str):
            return value in normalized
        if isinstance(value, list):
            return any(contains_token(item) for item in value)
        if isinstance(value, dict):
            return any(contains_token(item) for item in value.values())
        return False

    removed = 0

    def visit(value: Any) -> None:
        nonlocal removed
        if isinstance(value, dict):
            for key, child in list(value.items()):
                if key in {"targetMechanics", "selfMechanics"} and isinstance(child, list):
                    kept = []
                    for item in child:
                        if contains_token(item):
                            removed += 1
                        else:
                            visit(item)
                            kept.append(item)
                    value[key] = kept
                else:
                    visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(logic_row)
    if removed != required_count:
        raise ValueError(
            f"directStateNativeShell removed {removed} mechanics; expected exactly {required_count}"
        )

    if isinstance(reshape, dict) and reshape:
        reshape_meta = apply_direct_state_native_shell_reshape(logic_row, reshape)

    logic_row["xHomm3DirectStateNativeShell"] = {
        "mode": mode,
        "fixtureFlag": fixture_flag.strip(),
        "strippedMechanics": sorted(normalized),
        "removedCount": removed,
        **({"reshape": reshape_meta} if reshape_meta else {}),
    }


def apply_direct_state_native_shell_reshape(logic_row: dict[str, Any], reshape: dict[str, Any]) -> dict[str, Any]:
    """Force a stripped donor shell into a single-target attack envelope."""
    applied: dict[str, Any] = {}
    if reshape.get("removeMoveType") is True:
        logic_row.pop("moveType", None)
        applied["removeMoveType"] = True
    attack_type = reshape.get("attackType_")
    if isinstance(attack_type, str) and attack_type.strip():
        logic_row["attackType_"] = attack_type.strip()
        applied["attackType_"] = attack_type.strip()
    dealer = logic_row.get("damageDealer")
    if not isinstance(dealer, dict):
        dealer = {}
        logic_row["damageDealer"] = dealer
    dealer_reshape = reshape.get("damageDealer")
    if isinstance(dealer_reshape, dict):
        for key in (
            "attackPatternSid",
            "damageTarget_",
            "damageType_",
            "statDmgMult",
            "triggerCounter",
            "shootRange",
            "tags",
            "multitargetType",
            "numTargets",
        ):
            if key not in dealer_reshape:
                continue
            value = dealer_reshape[key]
            # Explicit null clears donor leftovers (e.g. frog shootRange=1 cast envelope).
            if value is None:
                dealer.pop(key, None)
                applied[key] = None
            else:
                dealer[key] = copy.deepcopy(value)
                applied[key] = dealer[key]
        for key in (
            "castTargetParams",
            "affectTargetParams",
            "orderedCastParams",
            "orderedAffectParams",
        ):
            params = dealer_reshape.get(key)
            if isinstance(params, dict) or isinstance(params, list):
                dealer[key] = copy.deepcopy(params)
                applied[key] = dealer[key]
        if "targetMechanics" in dealer_reshape:
            mechanics = dealer_reshape.get("targetMechanics")
            if mechanics is None:
                dealer.pop("targetMechanics", None)
                applied["targetMechanics"] = None
            elif isinstance(mechanics, list):
                dealer["targetMechanics"] = copy.deepcopy(mechanics)
                applied["targetMechanics"] = dealer["targetMechanics"]
            else:
                raise ValueError("damageDealer.targetMechanics reshape must be a list or null")
        # Drop AoE/hex-only targeting leftovers when reshaping to single-target melee.
        if dealer_reshape.get("clearTags") is True:
            for params_key in ("castTargetParams", "affectTargetParams"):
                params = dealer.get(params_key)
                if isinstance(params, dict) and "targetTags" in params and "targetTags" not in (
                    dealer_reshape.get(params_key) or {}
                ):
                    params["targetTags"] = ["unit", "attackable_object"]
    return applied


def is_runtime_icon_key(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    key = value.strip()
    if not key:
        return False
    if "@" in key or "/" in key or "\\" in key:
        return False
    lowered = key.lower()
    if lowered.endswith("_name") or lowered.endswith("_description"):
        return False
    return re.fullmatch(r"[A-Za-z0-9_.-]+", key) is not None


def select_runtime_icon_key(*candidates: Any) -> str | None:
    for candidate in candidates:
        if is_runtime_icon_key(candidate):
            return str(candidate).strip()
    return None


def donor_unit_special_icon_fallback(marker: dict[str, Any]) -> str | None:
    _ = marker
    return None


def apply_unit_special_rows(
    logic_item: dict[str, Any],
    view_item: dict[str, Any],
    custom_sid: str,
    target_slot_kind: str,
    target_slot_index: int | None,
    logic_special: dict[str, Any],
    view_special: dict[str, Any],
    marker: dict[str, Any],
    display: dict[str, Any],
    envelope: dict[str, Any],
    lang_rows: list[dict[str, str]],
) -> tuple[bool, bool]:
    logic_row = copy.deepcopy(logic_special)
    view_row = copy.deepcopy(view_special)
    logic_row["xHomm3AbilityOverride"] = marker
    view_row["xHomm3AbilityOverride"] = marker

    name_token = override_text_token(custom_sid, display.get("nameToken"), display.get("nameText"), marker["key"] + "_name", lang_rows)
    desc_token = override_text_token(
        custom_sid,
        display.get("descriptionToken"),
        display.get("descriptionText"),
        marker["key"] + "_description",
        lang_rows,
    )
    if name_token:
        view_row["name"] = name_token
    if desc_token:
        view_row["description"] = desc_token
    icon_key = select_runtime_icon_key(display.get("iconKey"), view_special.get("icon"), donor_unit_special_icon_fallback(marker))
    if icon_key:
        view_row["icon"] = icon_key
    apply_ability_envelope_overrides(logic_row, view_row, envelope)
    apply_direct_state_native_shell(logic_row, envelope)

    logic_slots = logic_item.setdefault(target_slot_kind, [])
    view_slots = view_item.setdefault(target_slot_kind, [])
    if not isinstance(logic_slots, list) or not isinstance(view_slots, list):
        return False, False
    logic_changed = set_slot_entry(logic_slots, target_slot_index, logic_row)
    view_changed = set_slot_entry(view_slots, target_slot_index, view_row)
    return logic_changed, view_changed


def apply_existing_special_display_overrides(
    logic_item: dict[str, Any],
    view_item: dict[str, Any],
    custom_sid: str,
    slot_kind: str,
    slot_index: int,
    display: dict[str, Any],
    fields: dict[str, Any],
    lang_rows: list[dict[str, str]],
) -> tuple[bool, bool]:
    logic_slots = logic_item.get(slot_kind)
    view_slots = view_item.get(slot_kind)
    if not isinstance(view_slots, list) or slot_index < 0 or slot_index >= len(view_slots):
        return False, False
    view_row = view_slots[slot_index]
    if not isinstance(view_row, dict):
        return False, False

    logic_row = None
    if isinstance(logic_slots, list) and 0 <= slot_index < len(logic_slots) and isinstance(logic_slots[slot_index], dict):
        logic_row = logic_slots[slot_index]

    logic_before = json.dumps(logic_row, sort_keys=True, ensure_ascii=False) if logic_row is not None else None
    view_before = json.dumps(view_row, sort_keys=True, ensure_ascii=False)
    marker_key = f"{slot_kind}_{slot_index}"
    name_token = override_text_token(custom_sid, display.get("nameToken"), display.get("nameText"), marker_key + "_name", lang_rows)
    desc_token = override_text_token(
        custom_sid,
        display.get("descriptionToken"),
        display.get("descriptionText"),
        marker_key + "_description",
        lang_rows,
    )
    if name_token:
        view_row["name"] = name_token
    if desc_token:
        view_row["description"] = desc_token
    icon_key = select_runtime_icon_key(display.get("iconKey"), view_row.get("icon"))
    if icon_key:
        view_row["icon"] = icon_key

    if slot_kind in {"abilities", "alternativeAttacks"} and logic_row is not None:
        apply_ability_envelope_overrides(logic_row, view_row, fields)
    else:
        ability_type = display.get("abilityType")
        if isinstance(ability_type, str) and ability_type.strip():
            view_row["abilityType"] = ability_type.strip()
        animation_index = coerce_optional_int(display.get("animationIndex"))
        if animation_index is not None:
            view_row["animationIndex"] = animation_index

    logic_changed = logic_row is not None and json.dumps(logic_row, sort_keys=True, ensure_ascii=False) != logic_before
    view_changed = json.dumps(view_row, sort_keys=True, ensure_ascii=False) != view_before
    if logic_changed and isinstance(logic_slots, list):
        logic_slots[slot_index] = logic_row
    view_slots[slot_index] = view_row
    return logic_changed, view_changed


BULWARK_SPELL_EFFECT_TRANSFORM_KEYS = frozenset({"targetMode", "orderedDistance", "fixedDuration"})
BULWARK_SPELL_EFFECT_PAYLOAD_KEYS = frozenset(
    {
        "spellSid",
        "spellLevel",
        "dealerIndex",
        "school",
        "spellTier",
        "buffSid",
        "buffCharges",
        "effectiveSpellPower",
        "targetMechanics",
        "attackType",
        "attackType_",
        "nameKey",
        "descriptionKey",
        "icon",
    }
) | BULWARK_SPELL_EFFECT_TRANSFORM_KEYS


def apply_spell_effect_target_mode(dealer: dict[str, Any], target_mode: str) -> None:
    mode = target_mode.strip()
    if mode not in {"ally", "enemy", "self", "all"}:
        raise KeyError(f"unsupported targetMode {target_mode!r}")
    for key in ("castTargetParams", "affectTargetParams"):
        params = dealer.get(key)
        if not isinstance(params, dict):
            params = {
                "targetTags": ["unit"],
                "selection": "object",
                "targetCondition_": "alive",
            }
            dealer[key] = params
        params["castTarget_"] = mode
        if mode != "all":
            params.setdefault("targetTags", ["unit"])
            params.setdefault("selection", "object")
            params.setdefault("targetCondition_", "alive")
    if isinstance(dealer.get("buff"), dict) or dealer.get("buffTarget_") not in (None, "none"):
        dealer["buffTarget_"] = mode


def apply_spell_effect_ordered_distance(dealer: dict[str, Any], distance: int) -> None:
    if distance < 1:
        raise KeyError(f"orderedDistance must be >= 1, got {distance}")
    dealer["multitargetType"] = "ordered"
    dealer.setdefault("numTargets", 2)
    for key in ("orderedCastParams", "orderedAffectParams"):
        rows = dealer.get(key)
        if not isinstance(rows, list) or not rows:
            dealer[key] = [
                {
                    "targetTags": [],
                    "castTarget_": "none",
                    "selection": "hex",
                    "distanceFromFirst": distance,
                }
            ]
            continue
        for row in rows:
            if isinstance(row, dict):
                row["distanceFromFirst"] = distance


def apply_spell_effect_fixed_duration(dealer: dict[str, Any], duration: int) -> None:
    if duration < 1:
        raise KeyError(f"fixedDuration must be >= 1, got {duration}")
    buff = dealer.get("buff")
    if not isinstance(buff, dict):
        raise KeyError("fixedDuration requires a native buff on the resolved dealer")
    buff["duration"] = duration
    for key in (
        "durationPerStack",
        "durationPerSpellPower",
        "durationSpellPower",
        "durationBonus",
        "durationScale",
    ):
        buff.pop(key, None)


def apply_bulwark_spell_effect_transforms(dealer: dict[str, Any], payload: dict[str, Any], selection: dict[str, Any]) -> None:
    unknown = sorted(key for key in payload.keys() if key not in BULWARK_SPELL_EFFECT_PAYLOAD_KEYS and key != "dealer")
    if unknown:
        raise KeyError(f"Bulwark spell-effect payload allows only native resolve fields and transforms; unknown keys: {unknown}")
    if "dealer" in payload:
        raise KeyError("Bulwark spell-effect overrides must not embed handwritten dealer objects")

    target_mode = selection.get("targetMode")
    if target_mode is None:
        target_mode = payload.get("targetMode")
    if isinstance(target_mode, str) and target_mode.strip():
        apply_spell_effect_target_mode(dealer, target_mode)

    ordered_distance = coerce_optional_int(selection.get("orderedDistance"))
    if ordered_distance is None:
        ordered_distance = coerce_optional_int(payload.get("orderedDistance"))
    if ordered_distance is not None:
        apply_spell_effect_ordered_distance(dealer, ordered_distance)

    fixed_duration = coerce_optional_int(selection.get("fixedDuration"))
    if fixed_duration is None:
        fixed_duration = coerce_optional_int(payload.get("fixedDuration"))
    if fixed_duration is not None:
        apply_spell_effect_fixed_duration(dealer, fixed_duration)


def build_spell_effect_rows(
    release_zip: zipfile.ZipFile,
    custom_sid: str,
    target_slot_kind: str,
    existing_logic_row: dict[str, Any] | None,
    existing_view_row: dict[str, Any] | None,
    selection: dict[str, Any],
    display: dict[str, Any],
    marker: dict[str, Any],
    lang_rows: list[dict[str, str]],
    faction_sid: str = "",
) -> tuple[dict[str, Any], dict[str, Any]]:
    payload = selection.get("effectPayload")
    payload = payload if isinstance(payload, dict) else {}
    spell_sid = selection.get("spellSid") if isinstance(selection.get("spellSid"), str) else payload.get("spellSid")
    spell_level = coerce_optional_int(selection.get("spellEffectLevel"))
    if spell_level is None:
        spell_level = coerce_optional_int(selection.get("spellLevel"))
    if spell_level is None:
        spell_level = coerce_optional_int(payload.get("spellLevel"))
    if (not spell_sid or spell_level is None) and isinstance(selection.get("effectKey"), str):
        parsed = parse_spell_effect_key(selection["effectKey"])
        if parsed is not None:
            spell_sid, spell_level = parsed
    if not isinstance(spell_sid, str) or spell_level is None:
        raise KeyError("missing spell effect selection")

    dealer = payload.get("dealer")
    spell_row: dict[str, Any]
    requested_dealer_index = coerce_optional_int(selection.get("dealerIndex"))
    if requested_dealer_index is None:
        requested_dealer_index = coerce_optional_int(payload.get("dealerIndex"))
    dealer_index = requested_dealer_index
    if faction_sid == "homm3_bulwark" and isinstance(dealer, dict):
        raise KeyError(f"{custom_sid}: Bulwark spell-effect overrides must resolve a native dealer (handwritten dealer forbidden)")
    if isinstance(dealer, dict):
        spell_row = {"id": spell_sid}
        dealer = copy.deepcopy(dealer)
    else:
        spell_row, dealer, dealer_index = resolve_spell_effect_from_release(release_zip, spell_sid, spell_level)
        if requested_dealer_index is not None and requested_dealer_index != dealer_index:
            battle_magic = spell_row.get("battleMagic") if isinstance(spell_row, dict) else None
            dealers = battle_magic.get("magicDealers") if isinstance(battle_magic, dict) else None
            if not isinstance(dealers, list) or requested_dealer_index < 0 or requested_dealer_index >= len(dealers):
                raise KeyError(f"no release spell dealer {spell_sid}:dealer:{requested_dealer_index}")
            selected_dealer = dealers[requested_dealer_index]
            if not isinstance(selected_dealer, dict):
                raise KeyError(f"release spell dealer is not an object {spell_sid}:dealer:{requested_dealer_index}")
            dealer = copy.deepcopy(selected_dealer)
            dealer_index = requested_dealer_index

    if faction_sid == "homm3_bulwark":
        apply_bulwark_spell_effect_transforms(dealer, payload, selection)

    duration = coerce_optional_int(selection.get("effectDuration"))
    if duration is None:
        duration = coerce_optional_int(selection.get("duration"))
    if duration is None:
        duration = coerce_optional_int(payload.get("duration"))
    fixed_duration = coerce_optional_int(selection.get("fixedDuration"))
    if fixed_duration is None:
        fixed_duration = coerce_optional_int(payload.get("fixedDuration"))
    if fixed_duration is not None:
        duration = fixed_duration
    buff = dealer.get("buff") if isinstance(dealer, dict) else None
    if duration is not None and isinstance(buff, dict):
        buff["duration"] = duration
    buff_sid = selection.get("buffSid") if isinstance(selection.get("buffSid"), str) else payload.get("buffSid")
    if isinstance(buff_sid, str) and buff_sid.strip() and isinstance(buff, dict):
        buff["sid"] = buff_sid.strip()
    buff_charges = coerce_optional_int(selection.get("buffCharges"))
    if buff_charges is None:
        buff_charges = coerce_optional_int(payload.get("buffCharges"))
    if buff_charges is not None and isinstance(buff, dict):
        buff["charges"] = buff_charges

    target_mechanics = selection.get("targetMechanics")
    if target_mechanics is None:
        target_mechanics = payload.get("targetMechanics")
    if isinstance(target_mechanics, list) and isinstance(dealer, dict):
        dealer["targetMechanics"] = copy.deepcopy(target_mechanics)

    effective_spell_power = coerce_optional_int(selection.get("effectiveSpellPower"))
    if effective_spell_power is None:
        effective_spell_power = coerce_optional_int(payload.get("effectiveSpellPower"))
    dealer = replace_spell_power_tokens(dealer, effective_spell_power)

    logic_row = copy.deepcopy(existing_logic_row) if isinstance(existing_logic_row, dict) else {}
    attack_type = selection.get("attackType")
    if attack_type is None:
        attack_type = selection.get("attackType_")
    if attack_type is None:
        attack_type = payload.get("attackType") or payload.get("attackType_")
    logic_row["attackType_"] = attack_type.strip() if isinstance(attack_type, str) and attack_type.strip() else "cast"
    logic_row.setdefault("rank", coerce_optional_int(selection.get("rank")) or coerce_optional_int(payload.get("spellTier")) or spell_row.get("rank") or 1)
    logic_row["rank"] = coerce_optional_int(selection.get("rank")) or logic_row.get("rank") or 1
    logic_row["selfMechanics"] = []
    if "cooldown" in selection:
        logic_row["cd"] = coerce_optional_int(selection.get("cooldown")) or 0
    else:
        logic_row.setdefault("cd", 2)
    if "energyLevel" in selection:
        logic_row["energyLevel"] = coerce_optional_int(selection.get("energyLevel")) or 0
    else:
        logic_row.setdefault("energyLevel", 2)
    charges = coerce_optional_int(selection.get("charges"))
    if charges is not None:
        logic_row["charges"] = charges
    turn_behavior = selection.get("turnBehavior")
    if isinstance(turn_behavior, str):
        turn_behavior = turn_behavior.strip()
        if turn_behavior == "free":
            logic_row["actionCost"] = 0
        elif turn_behavior == "ends":
            logic_row.pop("actionCost", None)
    logic_row["damageDealer"] = dealer
    logic_row["xHomm3SpellEffectSelection"] = {
        "spellSid": spell_sid,
        "spellLevel": spell_level,
        "dealerIndex": dealer_index,
        "effectDuration": duration,
        "effectiveSpellPower": effective_spell_power,
    }
    logic_row["xHomm3AbilityOverride"] = marker

    view_row = copy.deepcopy(existing_view_row) if isinstance(existing_view_row, dict) else {}
    name_token = override_text_token(
        custom_sid,
        display.get("nameToken") or payload.get("nameKey") or spell_row.get("name"),
        display.get("nameText"),
        marker["key"] + "_name",
        lang_rows,
    )
    desc_hint = display.get("descriptionToken") or payload.get("descriptionKey")
    if not desc_hint and isinstance(spell_row.get("description"), list) and spell_row["description"]:
        desc_hint = spell_row["description"][min(spell_level - 1, len(spell_row["description"]) - 1)]
    desc_token = override_text_token(
        custom_sid,
        desc_hint,
        display.get("descriptionText"),
        marker["key"] + "_description",
        lang_rows,
    )
    if name_token:
        view_row["name"] = name_token
    if desc_token:
        view_row["description"] = desc_token
    view_row["abilityType"] = display.get("abilityType") or view_row.get("abilityType") or "Ability_type_special"
    animation_index = coerce_optional_int(display.get("animationIndex"))
    view_row["animationIndex"] = animation_index if animation_index is not None else view_row.get("animationIndex", 2)
    view_row["useExpandTooltip"] = "false"
    view_row["canShowOnUI"] = True
    icon_key = select_runtime_icon_key(display.get("iconKey"), payload.get("icon"), spell_row.get("icon"), view_row.get("icon"))
    if icon_key:
        view_row["icon"] = icon_key
    view_row["xHomm3SpellEffectSelection"] = logic_row["xHomm3SpellEffectSelection"]
    view_row["xHomm3AbilityOverride"] = marker
    return logic_row, view_row


def apply_spell_effect_rows(
    release_zip: zipfile.ZipFile,
    logic_item: dict[str, Any],
    view_item: dict[str, Any],
    custom_sid: str,
    target_slot_kind: str,
    target_slot_index: int | None,
    selection: dict[str, Any],
    display: dict[str, Any],
    marker: dict[str, Any],
    lang_rows: list[dict[str, str]],
    faction_sid: str = "",
) -> tuple[bool, bool]:
    logic_slots = logic_item.setdefault(target_slot_kind, [])
    view_slots = view_item.setdefault(target_slot_kind, [])
    if not isinstance(logic_slots, list) or not isinstance(view_slots, list):
        return False, False
    existing_logic = logic_slots[target_slot_index] if isinstance(target_slot_index, int) and 0 <= target_slot_index < len(logic_slots) else None
    existing_view = view_slots[target_slot_index] if isinstance(target_slot_index, int) and 0 <= target_slot_index < len(view_slots) else None
    logic_row, view_row = build_spell_effect_rows(
        release_zip,
        custom_sid,
        target_slot_kind,
        existing_logic if isinstance(existing_logic, dict) else None,
        existing_view if isinstance(existing_view, dict) else None,
        selection,
        display,
        marker,
        lang_rows,
        faction_sid=faction_sid,
    )
    logic_changed = set_slot_entry(logic_slots, target_slot_index, logic_row)
    view_changed = set_slot_entry(view_slots, target_slot_index, view_row)
    return logic_changed, view_changed


def hero_override_text_token(hero_sid: str, token_hint: Any, text: Any, suffix: str, rows: list[dict[str, str]]) -> str | None:
    if isinstance(text, str) and text.strip():
        token = token_hint if isinstance(token_hint, str) and token_hint.startswith(hero_sid + "_") else f"{hero_sid}_{suffix}"
        cleaned = text.strip()
        rows.append({"sid": token, "text": cleaned})
        # Some live hero-name surfaces resolve the bare hero SID, others resolve *_name.
        if suffix == "name" and token != hero_sid:
            rows.append({"sid": hero_sid, "text": cleaned})
        return token
    return token_hint if isinstance(token_hint, str) and token_hint else None


def clean_start_squad_rows(rows: Any) -> list[dict[str, Any]] | None:
    if not isinstance(rows, list):
        return None
    clean = []
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get("sid"), str):
            continue
        clean.append({"sid": row["sid"], "min": coerce_optional_int(row.get("min")) or 1, "max": coerce_optional_int(row.get("max")) or coerce_optional_int(row.get("min")) or 1})
    return clean


def clean_start_skill_rows(rows: Any) -> list[dict[str, Any]] | None:
    if not isinstance(rows, list):
        return None
    clean = []
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, dict) or not isinstance(row.get("sid"), str):
            raise ValueError(f"hero override startSkills[{index}] must have a string sid")
        skill_level = coerce_optional_int(row.get("skillLevel"))
        if skill_level is None:
            raise ValueError(f"hero override startSkills[{index}] for {row['sid']!r} must have an integer skillLevel")
        clean.append({"sid": row["sid"], "skillLevel": skill_level})
    return clean

def find_specialization_row(release_zip: zipfile.ZipFile, output: dict[str, bytes], source_id: str) -> dict[str, Any] | None:
    if not isinstance(source_id, str) or not source_id:
        return None
    names = [normalize_name(info.filename) for info in release_zip.infolist()]
    for name in sorted(set(name for name in names if name.startswith("DB/heroes_specializations/") and name.endswith(".json"))):
        try:
            doc = read_overlay_or_release_json(release_zip, output, name)
        except Exception:
            continue
        rows = doc.get("array") if isinstance(doc, dict) else None
        for row in rows or []:
            if isinstance(row, dict) and row.get("id") == source_id:
                return copy.deepcopy(row)
    return None


CUSTOM_SPECIALIZATION_BONUS_TYPES = {
    "battleSubskillBonus",
    "cityUnitsIncrement",
    "heroMagicReplace",
    "heroStat",
    "heroStatBattle",
    "sideRes",
    "unitStat",
}


def default_specialization_common_bonuses(class_type: Any) -> list[dict[str, Any]]:
    ability_sid = "skill_mage_ability" if class_type == "magic" else "skill_warrior_ability"
    return [
        {"type": "heroBattleAbility", "parameters": [ability_sid, "0"]},
        {"type": "heroBattleAbility", "battleType": "forCity", "receiverRole": "attacker", "parameters": ["attack_siege_ability", "0"]},
        {"type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "1", "0"]},
        {"activationLevel": 4, "type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "2", "0"]},
        {"activationLevel": 8, "type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "3", "0"]},
        {"activationLevel": 12, "type": "heroStat", "parameters": ["magicSchoolSet", "neutral", "4", "0"]},
    ]


def custom_specialization_common_bonuses(current_row: dict[str, Any] | None, class_type: Any = None) -> list[dict[str, Any]]:
    bonuses = current_row.get("bonuses") if isinstance(current_row, dict) else None
    fallback = default_specialization_common_bonuses(class_type)
    common: list[dict[str, Any]] = [copy.deepcopy(fallback[0])]
    for bonus in bonuses or []:
        if not isinstance(bonus, dict):
            continue
        if bonus.get("type") == "heroBattleAbility":
            parameters = bonus.get("parameters") or []
            if parameters == ["attack_siege_ability", "0"]:
                common.append(copy.deepcopy(bonus))
            continue
        if bonus.get("type") == "heroStat" and (bonus.get("parameters") or [None])[0] == "magicSchoolSet":
            common.append(copy.deepcopy(bonus))
    seen = {json.dumps(bonus, sort_keys=True, ensure_ascii=False, separators=(",", ":")) for bonus in common}
    for bonus in fallback:
        signature = json.dumps(bonus, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
        if signature not in seen:
            common.append(copy.deepcopy(bonus))
            seen.add(signature)
    return common


def clean_custom_specialization_bonuses(hero_sid: str, bonuses: Any) -> list[dict[str, Any]]:
    if bonuses in (None, ""):
        return []
    if not isinstance(bonuses, list):
        raise ValueError(f"{hero_sid}: specialization bonuses must be a list")
    cleaned: list[dict[str, Any]] = []
    for index, bonus in enumerate(bonuses):
        if not isinstance(bonus, dict):
            raise ValueError(f"{hero_sid}: specialization bonus {index} must be an object")
        bonus_type = bonus.get("type")
        if bonus_type not in CUSTOM_SPECIALIZATION_BONUS_TYPES:
            raise ValueError(f"{hero_sid}: specialization bonus {index} has unsupported type {bonus_type!r}")
        if bonus_type == "heroStat" and "stat" in bonus and "parameters" not in bonus:
            stat = str(bonus.get("stat") or "")
            if not stat:
                raise ValueError(f"{hero_sid}: specialization heroStat bonus {index} is missing stat")
            base_value = coerce_optional_int(bonus.get("base")) or 0
            upgrade_value = coerce_optional_int(bonus.get("perLevel")) or 0
            level_value = coerce_optional_int(bonus.get("level")) or 1
            cleaned.append(
                {
                    "type": "heroStat",
                    "parameters": [stat, str(base_value)],
                    "upgrade": {"type": "levelMultiply", "parameters": [str(level_value), str(upgrade_value)]},
                }
            )
            continue
        cleaned.append(copy.deepcopy(bonus))
    return cleaned


def build_custom_specialization_row(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    hero_sid: str,
    current_row: dict[str, Any] | None,
    spec_override: dict[str, Any],
    lang_rows: list[dict[str, str]],
    class_type: Any = None,
) -> dict[str, Any]:
    if spec_override.get("mode") == "copy":
        source_spec_id = spec_override.get("sourceSpecId")
        row = find_specialization_row(release_zip, output, source_spec_id)
        if row is None:
            raise ValueError(f"{hero_sid}: copy specialization source row {source_spec_id!r} was not found")
    else:
        row = copy.deepcopy(current_row or {})
    row["id"] = f"{hero_sid}_specialization"
    name_token = hero_override_text_token(hero_sid, row.get("name"), spec_override.get("nameText"), "spec_name", lang_rows)
    desc_token = hero_override_text_token(hero_sid, row.get("desc"), spec_override.get("descriptionText"), "spec_description", lang_rows)
    row["name"] = name_token or f"{hero_sid}_spec_name"
    row["desc"] = desc_token or f"{hero_sid}_spec_description"
    icon = select_runtime_icon_key(
        creature_specialty_icon_key_from_source_key(spec_override.get("sourceSpecialtyKey")),
        spec_override.get("iconKey"),
        row.get("icon"),
    )
    if icon:
        row["icon"] = icon
    if spec_override.get("mode") != "copy":
        bonuses = clean_custom_specialization_bonuses(hero_sid, spec_override.get("bonuses"))
        if bonuses:
            change_disposition = spec_override.get("changeDisposition")
            row["bonuses"] = bonuses + custom_specialization_common_bonuses(current_row, class_type)
            row.pop("xHomm3MechanicsDebt", None)
            row.pop("xHomm3SourceDifference", None)
    source_spec_id = spec_override.get("sourceSpecId")
    if isinstance(source_spec_id, str) and source_spec_id.strip():
        row["xHomm3SourceSpecId"] = source_spec_id.strip()
    mode = spec_override.get("mode")
    if isinstance(mode, str) and mode.strip():
        row["xHomm3SpecializationMode"] = mode.strip()
    change_disposition = spec_override.get("changeDisposition")
    if isinstance(change_disposition, str) and change_disposition.strip():
        row["xHomm3ChangeDisposition"] = change_disposition.strip()
    source_specialty_key = spec_override.get("sourceSpecialtyKey")
    if isinstance(source_specialty_key, str) and source_specialty_key.strip():
        row["xHomm3SourceSpecialtyKey"] = source_specialty_key.strip()
    masterful_base_sid = spec_override.get("masterfulSpellBaseSid")
    if isinstance(masterful_base_sid, str) and masterful_base_sid.strip():
        row["xHomm3MasterfulSpellBaseSid"] = masterful_base_sid.strip()
    masterful_special_sid = spec_override.get("masterfulSpellSpecialSid")
    if isinstance(masterful_special_sid, str) and masterful_special_sid.strip():
        row["xHomm3MasterfulSpellSpecialSid"] = masterful_special_sid.strip()
    row["xHomm3HeroOverride"] = True
    return row


def apply_custom_hero_overrides(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    changed_heroes = 0
    changed_specs = 0
    hero_lang_rows: list[dict[str, str]] = []
    info_lang_rows: list[dict[str, str]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        override = load_hero_override(faction_sid)
        if not override:
            continue
        hero_overrides = override.get("heroOverrides")
        if not isinstance(hero_overrides, dict):
            continue
        spec_name = manifest_core_member(manifest, "heroSpecializations")
        try:
            spec_doc = read_overlay_or_release_json(release_zip, output, spec_name)
        except Exception as ex:
            notes.append(f"warn missing hero specialization override target {faction_sid}: {ex}")
            continue
        spec_rows = spec_doc.get("array") if isinstance(spec_doc, dict) else None
        if not isinstance(spec_rows, list):
            continue
        if dedupe_array_rows_by_id(spec_doc):
            changed_specs += 1
            spec_rows = spec_doc.get("array") if isinstance(spec_doc, dict) else None
            if not isinstance(spec_rows, list):
                continue
        for hero_sid, entry in hero_overrides.items():
            if not isinstance(hero_sid, str) or not isinstance(entry, dict) or entry.get("enabled") is False:
                continue
            hero_name = f"DB/heroes/{faction_sid}/{hero_sid}.json"
            try:
                hero_doc = read_overlay_or_release_json(release_zip, output, hero_name)
            except Exception as ex:
                notes.append(f"warn missing hero override target {hero_sid}: {ex}")
                continue
            hero = resolve_hero_row(hero_doc, hero_sid)
            if not isinstance(hero, dict):
                continue
            before = json.dumps(hero_doc, sort_keys=True, ensure_ascii=False)
            name_token = hero_override_text_token(hero_sid, hero.get("name"), entry.get("nameText"), "name", hero_lang_rows)
            desc_token = hero_override_text_token(hero_sid, hero.get("description"), entry.get("descriptionText"), "description", info_lang_rows)
            motto_token = hero_override_text_token(hero_sid, hero.get("motto"), entry.get("mottoText"), "motto", info_lang_rows)
            if name_token:
                hero["name"] = name_token
            if desc_token:
                hero["description"] = desc_token
            if motto_token:
                hero["motto"] = motto_token
            icon = select_runtime_icon_key(entry.get("iconKey"), hero.get("icon"))
            if icon:
                hero["icon"] = icon
            class_type = entry.get("classType")
            if class_type in {"might", "magic"}:
                hero["classType"] = class_type
                hero["skillsRollVariant"] = manifest_skill_table_sid(manifest, class_type)
            if isinstance(entry.get("className"), str) and entry["className"].strip():
                hero["className"] = entry["className"].strip()
            squad = clean_start_squad_rows(entry.get("startSquad"))
            if squad:
                hero["startSquad"] = squad
            squad_alt = clean_start_squad_rows(entry.get("startSquadAlt"))
            if squad_alt is not None:
                hero["startSquadAlt"] = squad_alt
            skills = clean_start_skill_rows(entry.get("startSkills"))
            if skills is not None:
                hero["startSkills"] = normalize_start_skill_rows_for_manifest(skills, manifest)
            hero["specialization"] = f"{hero_sid}_specialization"
            finalize_hero_doc(hero_doc, hero)
            if json.dumps(hero_doc, sort_keys=True, ensure_ascii=False) != before:
                output[hero_name] = write_json(hero_doc)
                changed_heroes += 1

            spec_override = entry.get("specialization") if isinstance(entry.get("specialization"), dict) else {}
            current_index = next((idx for idx, row in enumerate(spec_rows) if isinstance(row, dict) and row.get("id") == f"{hero_sid}_specialization"), None)
            current_row = spec_rows[current_index] if current_index is not None else None
            new_row = build_custom_specialization_row(
                release_zip,
                output,
                hero_sid,
                current_row,
                spec_override,
                info_lang_rows,
                entry.get("classType") or hero.get("classType"),
            )
            if current_index is None:
                spec_rows.append(new_row)
                changed_specs += 1
            elif spec_rows[current_index] != new_row:
                spec_rows[current_index] = new_row
                changed_specs += 1
        if changed_specs:
            output[spec_name] = write_json(spec_doc)
    if hero_lang_rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroes.json", hero_lang_rows, notes)
    if info_lang_rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroInfo.json", info_lang_rows, notes)
    if changed_heroes or changed_specs:
        notes.append(f"apply custom hero overrides heroes={changed_heroes} specializations={changed_specs}")


def ensure_manifest_hero_display_name_lang_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Guarantee manifest hero display-name tokens are canonical across Lang files."""
    rows_by_manifest: list[tuple[dict[str, Any], list[dict[str, str]]]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        hero_names = manifest_hero_names(manifest)
        if not hero_names:
            continue
        rows: list[dict[str, str]] = []
        for index in sorted(hero_names):
            hero_sid = manifest_hero_sid(manifest, index)
            display_name = hero_names[index]
            rows.append({"sid": hero_sid, "text": display_name})
            rows.append({"sid": f"{hero_sid}_name", "text": display_name})
        rows_by_manifest.append((manifest, rows))
    if rows_by_manifest:
        stale_sids: set[str] = set()
        for manifest, rows in rows_by_manifest:
            stale_sids.update(row["sid"] for row in rows)
            faction_sid = str((manifest.get("identity") or {}).get("factionSid") or "")
            if faction_sid == "homm3_tower":
                # Tower previously shipped 18 placeholder hero display tokens.
                # The manifest is now canonical; prune non-manifest slots too so
                # stale language buckets cannot shadow valid hero names.
                manifest_sids = {row["sid"] for row in rows}
                for index in range(1, 19):
                    hero_sid = manifest_hero_sid(manifest, index)
                    for sid in (hero_sid, f"{hero_sid}_name"):
                        if sid not in manifest_sids:
                            stale_sids.add(sid)
        remove_lang_overlay_rows_all_members(
            release_zip,
            output,
            stale_sids,
            notes,
        )
        sync_manifest_hero_display_name_lang_rows(
            release_zip,
            output,
            "Lang/english/texts/heroes.json",
            rows_by_manifest,
            notes,
        )
        sync_manifest_hero_display_name_lang_rows(
            release_zip,
            output,
            "Lang/english/texts/heroInfo.json",
            rows_by_manifest,
            notes,
        )


def apply_masterful_hero_specialization_assignments(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    def require_lang_text(target_name: str, sid: Any, expected: str, hero_sid: str) -> None:
        if not isinstance(sid, str) or not sid:
            raise RuntimeError(f"{hero_sid}: masterful spell specialization has invalid lang token {sid!r}")
        try:
            lang_doc = read_overlay_or_release_json(release_zip, output, target_name)
        except Exception as ex:
            raise RuntimeError(f"{hero_sid}: missing masterful specialization lang target {target_name}: {ex}") from ex
        tokens = lang_doc.get("tokens") if isinstance(lang_doc, dict) else None
        if not isinstance(tokens, list):
            raise RuntimeError(f"{hero_sid}: malformed masterful specialization lang target {target_name}")
        for token in tokens:
            if isinstance(token, dict) and token.get("sid") == sid:
                if token.get("text") != expected:
                    raise RuntimeError(f"{hero_sid}: lang token {sid!r}={token.get('text')!r}, expected {expected!r}")
                return
        raise RuntimeError(f"{hero_sid}: missing masterful specialization lang token {sid!r} in {target_name}")

    changed_heroes = 0
    validated_specs = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        override = load_hero_override(faction_sid)
        hero_overrides = override.get("heroOverrides") if isinstance(override, dict) else None
        if not isinstance(hero_overrides, dict):
            continue
        masterful_overrides: dict[str, tuple[str, dict[str, Any]]] = {}
        for hero_sid, entry in hero_overrides.items():
            if not isinstance(hero_sid, str) or not isinstance(entry, dict) or entry.get("enabled") is False:
                continue
            spec_override = entry.get("specialization")
            if not isinstance(spec_override, dict) or spec_override.get("changeDisposition") != "explicit_masterful_spell_variant":
                continue
            spell_sid = spec_override.get("masterfulSpellBaseSid")
            if not isinstance(spell_sid, str) or not spell_sid.strip():
                raise RuntimeError(f"{hero_sid}: masterful specialization override is missing masterfulSpellBaseSid")
            if spell_sid not in MASTERFUL_MAGIC_VARIANTS:
                raise RuntimeError(f"{hero_sid}: unknown masterful spell sid {spell_sid!r}")
            masterful_overrides[hero_sid] = (spell_sid.strip(), spec_override)
        if not masterful_overrides:
            continue
        spec_name = manifest_core_member(manifest, "heroSpecializations")
        try:
            spec_doc = read_overlay_or_release_json(release_zip, output, spec_name)
        except Exception as ex:
            raise RuntimeError(f"missing masterful specialization target {faction_sid}: {ex}") from ex
        spec_rows = spec_doc.get("array") if isinstance(spec_doc, dict) else None
        if not isinstance(spec_rows, list):
            raise RuntimeError(f"malformed masterful specialization target {spec_name}")
        specs_by_id = {row.get("id"): row for row in spec_rows if isinstance(row, dict)}
        for hero_sid, (spell_sid, spec_override) in masterful_overrides.items():
            hero_name = f"DB/heroes/{faction_sid}/{hero_sid}.json"
            try:
                hero_doc = read_overlay_or_release_json(release_zip, output, hero_name)
            except Exception as ex:
                raise RuntimeError(f"missing masterful hero target {hero_sid}: {ex}") from ex
            hero = first_array_item(hero_doc)
            if not isinstance(hero, dict):
                raise RuntimeError(f"malformed masterful hero target {hero_name}")
            hero_before = json.dumps(hero_doc, sort_keys=True, ensure_ascii=False)
            hero["startMagics"] = masterful_start_magic_rows(spell_sid, hero.get("startMagics"))
            if json.dumps(hero_doc, sort_keys=True, ensure_ascii=False) != hero_before:
                output[hero_name] = write_json(hero_doc)
                changed_heroes += 1
            row = specs_by_id.get(f"{hero_sid}_specialization")
            if not isinstance(row, dict):
                raise RuntimeError(f"{hero_sid}: masterful spell specialization must be owned by hero_overrides")
            _name, _description, expected_bonuses = masterful_magic_spec_profile(spell_sid)
            expected_bonuses = expected_bonuses + custom_specialization_common_bonuses(row, hero.get("classType"))
            expected_special_sid = masterful_magic_special_sid(spell_sid)
            override_source_spec_id = spec_override.get("sourceSpecId")
            if not isinstance(override_source_spec_id, str) or not override_source_spec_id.strip():
                raise RuntimeError(f"{hero_sid}: masterful spell override is missing sourceSpecId")
            override_name = spec_override.get("nameText")
            if not isinstance(override_name, str) or not override_name.strip():
                raise RuntimeError(f"{hero_sid}: masterful spell override is missing nameText")
            override_description = spec_override.get("descriptionText")
            if not isinstance(override_description, str) or not override_description.strip():
                raise RuntimeError(f"{hero_sid}: masterful spell override is missing descriptionText")
            expected_fields = {
                "icon": spell_sid,
                "xHomm3SpecializationMode": "changed",
                "xHomm3ChangeDisposition": "explicit_masterful_spell_variant",
                "xHomm3SourceSpecId": override_source_spec_id.strip(),
                "xHomm3SourceSpecialtyKey": str(spec_override.get("sourceSpecialtyKey") or "").strip(),
                "xHomm3MasterfulSpellBaseSid": spell_sid,
                "xHomm3MasterfulSpellSpecialSid": expected_special_sid,
                "xHomm3HeroOverride": True,
            }
            for key, expected in expected_fields.items():
                if row.get(key) != expected:
                    raise RuntimeError(f"{hero_sid}: masterful spell specialization {key}={row.get(key)!r}, expected {expected!r}")
            if row.get("bonuses") != expected_bonuses:
                raise RuntimeError(f"{hero_sid}: masterful spell specialization bonuses must be exactly {expected_bonuses!r}")
            require_lang_text("Lang/english/texts/heroInfo.json", row.get("name"), override_name.strip(), hero_sid)
            require_lang_text("Lang/english/texts/heroInfo.json", row.get("desc"), override_description.strip(), hero_sid)
            validated_specs += 1
    if changed_heroes or validated_specs:
        notes.append(f"validate masterful spell hero specializations ({validated_specs}) and apply start spells ({changed_heroes})")


def remove_slot_entry(item: dict[str, Any], slot_kind: str, index: int) -> bool:
    slots = item.get(slot_kind)
    if not isinstance(slots, list) or index < 0 or index >= len(slots):
        return False
    del slots[index]
    return True


def apply_custom_ability_overrides_to_custom_unit_rows(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    changed_logic = 0
    changed_view = 0
    skipped = 0
    unresolved_errors: list[str] = []
    lang_rows: list[dict[str, str]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        override = load_ability_override(faction_sid)
        if not override:
            continue
        unit_overrides = override.get("unitOverrides")
        if not isinstance(unit_overrides, dict):
            continue
        for custom_sid, unit_override in unit_overrides.items():
            if not isinstance(custom_sid, str) or not isinstance(unit_override, dict):
                continue
            logic_name = f"DB/units/units_logics/{faction_sid}/{custom_sid}_l.json"
            view_name = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                logic_doc = read_overlay_or_release_json(release_zip, output, logic_name)
                view_doc = read_overlay_or_release_json(release_zip, output, view_name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing ability override target {custom_sid}: {ex}")
                continue
            logic_item = first_array_item(logic_doc)
            view_item = first_array_item(view_doc)
            if not isinstance(logic_item, dict) or not isinstance(view_item, dict):
                continue

            logic_before = json.dumps(logic_doc, sort_keys=True, ensure_ascii=False)
            view_before = json.dumps(view_doc, sort_keys=True, ensure_ascii=False)
            branch_role = unit_override.get("branchRole")
            source_mechanic_id = unit_override.get("sourceMechanicId")
            decision_test = unit_override.get("decisionTest")
            if isinstance(branch_role, str) and branch_role.strip():
                logic_item["xHomm3BranchRole"] = branch_role.strip()
                view_item["xHomm3BranchRole"] = branch_role.strip()
            if isinstance(source_mechanic_id, str) and source_mechanic_id.strip():
                logic_item["xHomm3SourceMechanic"] = source_mechanic_id.strip()
                view_item["xHomm3SourceMechanic"] = source_mechanic_id.strip()
            if isinstance(decision_test, str) and decision_test.strip():
                logic_item["xHomm3DecisionTest"] = decision_test.strip()
                view_item["xHomm3DecisionTest"] = decision_test.strip()
            if unit_override.get("replaceExistingAbilities") is True:
                logic_item["abilities"] = []
                view_item["abilities"] = []
            existing_enabled_targets = {
                (special.get("slotKind"), special.get("index"))
                for special in unit_override.get("existingSpecials") or []
                if isinstance(special, dict) and special.get("enabled") is not False and special.get("effectKind") == "unit-special"
            }

            for special in unit_override.get("existingSpecials") or []:
                if not isinstance(special, dict):
                    continue
                slot_kind = special.get("slotKind")
                slot_index = special.get("index")
                if not isinstance(slot_kind, str) or not isinstance(slot_index, int):
                    continue
                if special.get("enabled") is False:
                    remove_slot_entry(logic_item, slot_kind, slot_index)
                    remove_slot_entry(view_item, slot_kind, slot_index)
                    continue
                display = {
                    "nameToken": special.get("nameKey"),
                    "descriptionToken": special.get("descriptionKey"),
                    "nameText": special.get("nameText"),
                    "descriptionText": special.get("descriptionText"),
                    "iconKey": special.get("iconKey"),
                    "abilityType": special.get("abilityType"),
                    "animationIndex": special.get("animationIndex"),
                }
                if special.get("effectKind") == "unit-special":
                    parsed = parse_unit_special_key(special.get("effectKey"))
                    if parsed is None:
                        unresolved_errors.append(f"{custom_sid}: invalid unit-special effectKey {special.get('effectKey')!r}")
                        continue
                    source_unit_sid, source_slot_kind, source_slot_index = parsed
                    try:
                        logic_special, view_special, source_faction_sid = resolve_unit_special_from_release(
                            release_zip,
                            source_unit_sid,
                            source_slot_kind,
                            source_slot_index,
                        )
                    except KeyError as ex:
                        unresolved_errors.append(f"{custom_sid}: unresolved unit-special {special.get('effectKey')!r}: {ex}")
                        continue
                    marker = {
                        "key": f"{slot_kind}_{slot_index}",
                        "sourceUnitSid": source_unit_sid,
                        "sourceFactionSid": source_faction_sid,
                        "sourceSlotKind": source_slot_kind,
                        "sourceSlotIndex": source_slot_index,
                    }
                    apply_unit_special_rows(
                        logic_item,
                        view_item,
                        custom_sid,
                        slot_kind,
                        slot_index,
                        logic_special,
                        view_special,
                        marker,
                        display,
                        special,
                        lang_rows,
                    )
                elif special.get("effectKind") == "spell-effect":
                    marker = {
                        "key": f"{slot_kind}_{slot_index}",
                        "sourceSpellEffectKey": special.get("effectKey"),
                    }
                    try:
                        apply_spell_effect_rows(
                            release_zip,
                            logic_item,
                            view_item,
                            custom_sid,
                            slot_kind,
                            slot_index,
                            special,
                            display,
                            marker,
                            lang_rows,
                            faction_sid=faction_sid,
                        )
                    except KeyError as ex:
                        unresolved_errors.append(f"{custom_sid}: unresolved spell-effect {special.get('effectKey')!r}: {ex}")
                else:
                    logic_changed, view_changed = apply_existing_special_display_overrides(
                        logic_item,
                        view_item,
                        custom_sid,
                        slot_kind,
                        slot_index,
                        display,
                        special,
                        lang_rows,
                    )
                    if not logic_changed and not view_changed:
                        skipped += 1
                    continue

            for ability in unit_override.get("abilities") or []:
                if not isinstance(ability, dict) or ability.get("enabled") is False:
                    continue
                fields = ability.get("fields")
                if not isinstance(fields, dict):
                    skipped += 1
                    continue
                if ability.get("templateId") == "focus_spell_effect":
                    marker = {
                        "key": str(ability.get("id") or "focus_spell_effect"),
                        "sourceSpellEffectKey": fields.get("spellEffectKey"),
                    }
                    display = {
                        "nameToken": fields.get("nameToken"),
                        "descriptionToken": fields.get("descriptionToken"),
                        "nameText": fields.get("displayName"),
                        "descriptionText": fields.get("description"),
                        "iconKey": fields.get("iconKey"),
                        "abilityType": fields.get("abilityType"),
                        "animationIndex": fields.get("animationIndex"),
                    }
                    selection = dict(fields)
                    selection["effectKey"] = fields.get("spellEffectKey")
                    try:
                        apply_spell_effect_rows(
                            release_zip,
                            logic_item,
                            view_item,
                            custom_sid,
                            "abilities",
                            None,
                            selection,
                            display,
                            marker,
                            lang_rows,
                            faction_sid=faction_sid,
                        )
                    except KeyError as ex:
                        unresolved_errors.append(f"{custom_sid}: unresolved focus spell effect {fields.get('spellEffectKey')!r}: {ex}")
                    continue
                if ability.get("templateId") != "copied_unit_special":
                    skipped += 1
                    continue
                parsed = parse_unit_special_key(fields.get("unitSpecialKey"))
                if parsed is None:
                    unresolved_errors.append(f"{custom_sid}: invalid copied_unit_special key {fields.get('unitSpecialKey')!r}")
                    continue
                source_unit_sid, source_slot_kind, source_slot_index = parsed
                if (source_slot_kind, source_slot_index) in existing_enabled_targets:
                    continue
                try:
                    logic_special, view_special, source_faction_sid = resolve_unit_special_from_release(
                        release_zip,
                        source_unit_sid,
                        source_slot_kind,
                        source_slot_index,
                    )
                except KeyError as ex:
                    unresolved_errors.append(f"{custom_sid}: unresolved copied_unit_special {fields.get('unitSpecialKey')!r}: {ex}")
                    continue
                marker = {
                    "key": str(ability.get("id") or f"{source_slot_kind}_{source_slot_index}"),
                    "sourceUnitSid": source_unit_sid,
                    "sourceFactionSid": source_faction_sid,
                    "sourceSlotKind": source_slot_kind,
                    "sourceSlotIndex": source_slot_index,
                }
                display = {
                    "nameToken": fields.get("nameToken"),
                    "descriptionToken": fields.get("descriptionToken"),
                    "nameText": fields.get("displayName"),
                    "descriptionText": fields.get("description"),
                    "iconKey": fields.get("iconKey"),
                    "abilityType": fields.get("abilityType"),
                    "animationIndex": fields.get("animationIndex"),
                }
                apply_unit_special_rows(
                    logic_item,
                    view_item,
                    custom_sid,
                    source_slot_kind,
                    source_slot_index,
                    logic_special,
                    view_special,
                    marker,
                    display,
                    fields,
                    lang_rows,
                )

            if json.dumps(logic_doc, sort_keys=True, ensure_ascii=False) != logic_before:
                output[logic_name] = write_json(logic_doc)
                changed_logic += 1
            if json.dumps(view_doc, sort_keys=True, ensure_ascii=False) != view_before:
                output[view_name] = write_json(view_doc)
                changed_view += 1

    if unresolved_errors:
        raise KeyError("unresolved enabled custom active ability override entries: " + "; ".join(unresolved_errors))
    if lang_rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/unitsAbility.json", lang_rows, notes)
    if changed_logic or changed_view:
        notes.append(f"apply custom ability overrides ({changed_logic} logic, {changed_view} view)")
    if skipped:
        notes.append(f"warn skipped unsupported custom ability override entries ({skipped})")


