# Machine translations (2026-10-05) of custom Lang rows that multilingual sync never
# reaches: rows whose English text lands after sync (artifacts, campaign cinematic and
# dialogue rows, heroes, heroInfo, magics) and the 44 own rows above. One file per
# non-English locale, shaped {"<LangFile>.json": {"<sid>": "<text>"}}.
CUSTOM_LANG_TRANSLATIONS_DIR = Path(__file__).with_name("localization_translations")


def _homm3_own_custom_lang_rows() -> dict[str, dict[str, str]]:
    """Lang file name -> {sid: English text} for the Warcries + missing-custom rows."""
    own: dict[str, dict[str, str]] = {
        "heroSkills.json": {row["sid"]: row["text"] for row in HOMM3_STRONGHOLD_WARCRIES_LANG_ROWS}
    }
    for target_name, rows in HOMM3_MISSING_CUSTOM_LANG_ROWS.items():
        own.setdefault(target_name.rsplit("/", 1)[1], {}).update({row["sid"]: row["text"] for row in rows})
    return own


def _lang_token_sids(doc: Any) -> set[str]:
    return {
        token["sid"]
        for token in lang_doc_tokens(doc)
        if isinstance(token, dict) and isinstance(token.get("sid"), str)
    }


def add_custom_lang_translations(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
    translations_dir: Path = CUSTOM_LANG_TRANSLATIONS_DIR,
) -> None:
    """Add translated custom rows to Lang/<locale>/texts/<file> for each locale file.

    Runs after every English custom row and after multilingual sync, so sync drafts
    cannot replace these rows. A sid missing from the locale file is added. A row
    this build inserted (absent from the release Core's locale file: a sync draft or
    English copy) is replaced by the translation. A row the release Core already
    carries is never touched, except the 44 own rows (_homm3_own_custom_lang_rows)
    whose text still equals the English fallback. A missing locale texts file is
    created from the English file's shape with empty row lists; locales with no
    Lang/<locale>/ folder in the Core are skipped.
    """
    paths = sorted(translations_dir.glob("*.json"))
    if not paths:
        raise RuntimeError(f"no custom Lang translations in {translations_dir}")
    release_names = set(release_zip.namelist())
    core_langs = {name.split("/")[1] for name in release_names | set(output) if name.startswith("Lang/") and name.count("/") >= 3}
    own = _homm3_own_custom_lang_rows()
    added_total = 0
    replaced_total = 0
    created = 0
    for path in paths:
        lang = path.stem
        if lang == "english":
            raise RuntimeError(f"custom Lang translations must not contain english: {path}")
        if lang not in core_langs:
            notes.append(f"skip custom Lang translations {lang} (no Lang/{lang}/ in Core)")
            continue
        data = json.loads(path.read_text(encoding="utf-8-sig"))
        if not isinstance(data, dict):
            raise RuntimeError(f"custom Lang translations {path} must be an object")
        for file_name, rows in sorted(data.items()):
            if not isinstance(rows, dict):
                raise RuntimeError(f"custom Lang translations {path}: {file_name} must be an object")
            target_name = f"Lang/{lang}/texts/{file_name}"
            english_name = f"Lang/english/texts/{file_name}"
            try:
                english_doc = read_overlay_or_release_json(release_zip, output, english_name)
            except KeyError:
                english_doc = None
            try:
                doc = read_overlay_or_release_json(release_zip, output, target_name)
            except KeyError:
                if not isinstance(english_doc, dict):
                    notes.append(f"skip custom Lang translations {target_name} (no english file)")
                    continue
                doc = {key: ([] if isinstance(value, list) else value) for key, value in english_doc.items()}
                doc.setdefault("tokens", [])
                created += 1
            if not isinstance(doc, dict) or not isinstance(doc.get("tokens"), list):
                raise RuntimeError(f"{target_name} has no tokens list")
            base_sids = _lang_token_sids(read_json(release_zip, target_name)) if target_name in release_names else set()
            english_text = {
                token["sid"]: token.get("text")
                for token in lang_doc_tokens(english_doc)
                if isinstance(token, dict) and isinstance(token.get("sid"), str)
            }
            own_rows = own.get(file_name, {})
            tokens: list[Any] = doc["tokens"]
            index = {
                token["sid"]: i
                for i, token in enumerate(tokens)
                if isinstance(token, dict) and isinstance(token.get("sid"), str)
            }
            changed_rows: list[dict[str, str]] = []
            for sid, text in rows.items():
                if not isinstance(text, str) or not text:
                    continue
                row = {"sid": sid, "text": text}
                if sid not in index:
                    index[sid] = len(tokens)
                    tokens.append(row)
                    changed_rows.append(row)
                    added_total += 1
                else:
                    current = tokens[index[sid]].get("text")
                    # Inserted by this build (sync draft / English copy), or an own row
                    # whose release-Core text is still the English fallback.
                    fallback = sid not in base_sids or (
                        sid in own_rows and current in (own_rows[sid], english_text.get(sid))
                    )
                    if current != text and fallback:
                        tokens[index[sid]] = {**tokens[index[sid]], "text": text}
                        changed_rows.append(row)
                        replaced_total += 1
            if changed_rows:
                # Keep a parallel "array" row list in step, as upsert_lang_rows does.
                upsert_lang_rows_into_list(doc, "array", changed_rows, create=False)
                output[target_name] = write_json(doc)
    notes.append(
        f"merge custom Lang translations ({len(paths)} locales: {added_total} added, "
        f"{replaced_total} fallbacks replaced, {created} files created)"
    )

NON_SHOOTER_STALE_RANGED_STAT_KEYS = ("ammo", "ignoreShootDmgBuff", "ignoreShootingBlock")

CUSTOM_UNIT_HIDDEN_STAT_STRIP_BY_SID: dict[str, tuple[str, ...]] = {
    # June 21 unvalidated source fix: these native stat mechanics were inherited
    # from donor units without matching visible unit passive/ability cards. Keep
    # this explicit; do not replace it with broad heuristics that could erase
    # intentional native mechanics such as Castle Cavalier charge or Tower Golem
    # magic resistance.
    "h3_centaur": ("damagePerHex",),
    "h3_centaur_captain": ("damagePerHex",),
    "h3_centaur_ranger_upg_alt": ("damagePerHex",),
    "h3_stormbird": ("numCounters",),
    "h3_ayssid": ("numCounters",),
    "h3_stormbird_upg_alt": ("numCounters",),
    "h3_nix": ("additionalActionChanceModifier",),
    "h3_nix_warrior": ("additionalActionChanceModifier",),
    "h3_nix_upg_alt": ("additionalActionChanceModifier",),
    "h3_harpy": ("crit",),
    "h3_minotaur": ("additionalActionChanceModifier",),
    "h3_manticore": ("numCounters",),
    "h3_gnoll": ("inDmgMods",),
    "h3_gorgon": ("additionalActionChanceModifier",),
    "h3_imp": ("damagePerDeltaLevel",),
    "h3_pit_fiend": ("damagePerDeltaLevelLower",),
    "h3_devil": ("outDamageIfLevelAbove", "outLevelAboveThreshold"),
    "h3_dwarf": ("inDmgMods",),
    "h3_battle_dwarf": ("inDmgMods",),
    "h3_dwarf_battlerager_upg_alt": ("inDmgMods",),
    "h3_war_unicorn": ("energyPerRound",),
    "h3_wolf_rider": ("crit",),
    "h3_ogre": ("additionalActionChanceModifier",),
    "h3_naga": ("additionalActionChanceModifier",),
}


def normalize_custom_unit_logic_redundant_flags(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    changed_members = 0
    removed_flags = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        for custom_sid in manifest_unit_sids(manifest):
            name = f"DB/units/units_logics/{faction_sid}/{custom_sid}_l.json"
            try:
                doc = read_overlay_or_release_json(release_zip, output, name)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
                continue
            item = first_array_item(doc)
            if not isinstance(item, dict):
                continue
            stats = item.get("stats")
            if not isinstance(stats, dict):
                continue
            changed = False
            has_shoot_attack = find_attack(item, "shoot") is not None or find_attack(item, "range") is not None
            if not has_shoot_attack:
                for key in NON_SHOOTER_STALE_RANGED_STAT_KEYS:
                    if key in stats:
                        stats.pop(key, None)
                        removed_flags += 1
                        changed = True
            abilities = item.get("abilities")
            has_abilities = isinstance(abilities, list) and any(isinstance(row, dict) for row in abilities)
            if not has_abilities and "free_energy_casts" in stats:
                stats.pop("free_energy_casts", None)
                removed_flags += 1
                changed = True
            for key in CUSTOM_UNIT_HIDDEN_STAT_STRIP_BY_SID.get(custom_sid, ()):
                if key in stats:
                    if key in ("inDmgMods", "outDmgMods"):
                        stats[key] = {"list": []}
                    else:
                        stats.pop(key, None)
                    removed_flags += 1
                    changed = True
            if changed:
                output[name] = write_json(doc)
                changed_members += 1
    if removed_flags:
        notes.append(f"remove/reset stale custom unit donor ability flags ({removed_flags} flags across {changed_members} logic rows)")


# HoMM3 neutral OE kits (catalog oeKit, docs/homm3_neutral_oe_kits.md). The donor row
# supplies the attack/animation shell only; everything that is kit identity is rebuilt
# here from library surfaces so no donor faction mechanic leaks into a neutral.
HOMM3_NEUTRAL_KIT_STRIP_STAT_KEYS = (
    "damagePerHex",
    "ignoreShootDmgBuff",
    "ignoreShootingBlock",
    "armorPen",
    "attackPen",
    "alwaysMinDmg",
    "alwaysTakeMinDmg",
)
# Donor view passives that describe the kept attack/movement shell, not donor identity.
HOMM3_NEUTRAL_KIT_SHELL_VIEW_PASSIVES = {
    "base_passive_melee_attack_name",
    "base_passive_ranged_attack_name",
    "h3_common_melee_attack_name",
    "h3_common_ranged_attack_name",
    "base_passive_flyer_name",
    "base_passive_strike_reach_1_name",
    "base_passive_ranged_attack_no_close_name",
    "base_passive_duelist_name",
}
HOMM3_NEUTRAL_KIT_PROFILES = ("living", "undead", "construct", "dragon", "native_donor", "hand_authored")
HOMM3_NEUTRAL_KIT_MECHANICS = (
    "positive_luck",
    "no_retaliation",
    "unlimited_retaliation",
    "sharpshooter",
    "free_shooting",
    "regeneration",
    "magic_resistance",
    "magic_level_immunity",
    "fearless",
    "luck_aura",
)
HOMM3_NEUTRAL_KIT_OWN_TEXT_MECHANICS = {"regeneration", "magic_resistance", "luck_aura"}
HOMM3_NEUTRAL_FORTUNE_BUFF_SID = "homm3_neutral_fortune_effect"


def homm3_neutral_kit_passive_sid(unit_sid: str, mech: str, part: str) -> str:
    return f"{unit_sid}_passive_{mech}_{part}"


def homm3_neutral_kit_active_sid(unit_sid: str, kind: str, part: str) -> str:
    return f"{unit_sid}_ability_{kind}_{part}"


def make_homm3_neutral_fortune_buff_row() -> dict[str, Any]:
    return {
        "id": HOMM3_NEUTRAL_FORTUNE_BUFF_SID,
        "aiValue": 4000,
        "aiValuePerDuration": 400,
        "icon": "sub_skill_luck_1_icon",
        "name_": "h3_common_ability_fortune_spell_name",
        "description_": f"{HOMM3_NEUTRAL_FORTUNE_BUFF_SID}_description",
        "tags": ["positive", HOMM3_NEUTRAL_FORTUNE_BUFF_SID],
        "isPositive": True,
        "addition": "duration",
        "data": {"stats": {"luck": 2}},
    }


def _homm3_neutral_shell_has_no_range_penalty(logic_row: dict[str, Any]) -> bool:
    for attack in as_attack_list(logic_row.get("defaultAttacks")):
        dealer = attack.get("damageDealer")
        if attack.get("attackType_") == "shoot" and isinstance(dealer, dict):
            if float(dealer.get("shootDmgBuff", -1.0) or 0.0) == 0.0:
                return True
    return False


def apply_homm3_neutral_oe_kit(
    unit: dict[str, Any],
    logic_row: dict[str, Any],
    view_row: dict[str, Any],
    donor_logic_row: dict[str, Any] | None,
    donor_view_row: dict[str, Any] | None,
) -> list[dict[str, str]]:
    """Rebuild one neutral's kit from its catalog oeKit block. Returns own Lang rows."""
    sid = str(unit["sid"])
    kit = unit.get("oeKit")
    if not isinstance(kit, dict):
        raise RuntimeError(f"homm3_neutral {sid}: catalog row has no oeKit")
    profile = str(kit.get("profile") or "")
    if profile not in HOMM3_NEUTRAL_KIT_PROFILES:
        raise RuntimeError(f"homm3_neutral {sid}: unknown oeKit profile {profile!r}")
    lang_rows: list[dict[str, str]] = []
    stats = logic_row.setdefault("stats", {})
    catalog_stats = unit["stats"]
    for key in ("hp", "offence", "defence", "damageMin", "damageMax", "initiative", "speed", "ammo", "moveType", "numCounters"):
        if key in catalog_stats:
            stats[key] = catalog_stats[key]
    logic_row["tier"] = int(unit["tier"])
    logic_row["squadValue"] = int(catalog_stats["squadValue"])
    logic_row["unitCost"] = {"costResArray": [{"name": "gold", "cost": int(catalog_stats["gold"])}]}
    if profile == "hand_authored":
        return lang_rows

    keep_passives = kit.get("keepDonorPassives") is True
    mechanics = [m for m in kit.get("mechanics") or [] if isinstance(m, dict)]
    mech_names = {str(m.get("mech")) for m in mechanics}
    unknown = mech_names - set(HOMM3_NEUTRAL_KIT_MECHANICS)
    if unknown:
        raise RuntimeError(f"homm3_neutral {sid}: unknown oeKit mechanics {sorted(unknown)}")

    view_passives_src = view_row.get("passives") if isinstance(view_row.get("passives"), list) else []
    if profile != "native_donor":
        for key in HOMM3_NEUTRAL_KIT_STRIP_STAT_KEYS:
            stats.pop(key, None)
        stats["inDmgMods"] = {"list": []}
        stats["outDmgMods"] = {"list": []}
        if profile in ("undead", "construct"):
            stats.update({"moral": 0, "moralMin": 0, "moralMax": 0})
        else:
            stats.update({"moral": 0, "moralMin": -5, "moralMax": 5})
        if profile == "construct":
            stats.update({"luck": 0, "luckMin": 0, "luckMax": 0})
        else:
            stats.update({"luck": 0, "luckMin": -3, "luckMax": 3})
    if not keep_passives:
        logic_row.pop("aura", None)
        passives: list[Any] = []
        if profile == "living":
            passives.append({"data": {"immunities": [{"type": "cast", "tags": ["living_immunities"]}]}})
        elif profile == "undead":
            passives.extend([undead_profile_passive(), poison_blood_profile_passive()])
        elif profile == "construct":
            passives.extend([construct_profile_passive(), poison_blood_profile_passive()])
        elif profile == "dragon" and "magic_level_immunity" not in mech_names:
            passives.append({"data": {"immunities": [{"type": "cast", "tags": ["dragon_immunities"]}]}})
        logic_row["passives"] = passives
        view_passives = [
            dict(row)
            for row in view_passives_src
            if isinstance(row, dict)
            and (
                row.get("name") in HOMM3_NEUTRAL_KIT_SHELL_VIEW_PASSIVES
                or (row.get("name") == "base_passive_sharpshooter_name" and _homm3_neutral_shell_has_no_range_penalty(logic_row))
            )
        ]
        attack_names = {"base_passive_melee_attack_name", "base_passive_ranged_attack_name", "h3_common_melee_attack_name", "h3_common_ranged_attack_name"}
        if not any(row.get("name") in attack_names for row in view_passives):
            shooter = any(a.get("attackType_") == "shoot" for a in as_attack_list(logic_row.get("defaultAttacks")))
            kind = "ranged" if shooter else "melee"
            view_passives.insert(0, {"name": f"h3_common_{kind}_attack_name", "description": f"h3_common_{kind}_attack_description"})
    else:
        view_passives = [dict(row) for row in view_passives_src if isinstance(row, dict)]
    if sid == "h3_faerie_dragon" and profile == "native_donor":
        if catalog_stats.get("moveType") != "fly":
            raise RuntimeError("h3_faerie_dragon: catalog movement must remain flying")
        has_movement_card = False
        for passive in view_passives:
            if passive.get("name") in {"base_passive_blink_name", "base_passive_flyer_name"}:
                has_movement_card = True
            if passive.get("name") == "base_passive_blink_name":
                passive["name"] = "base_passive_flyer_name"
                passive["description"] = "base_passive_flyer_description"
        if not has_movement_card:
            raise RuntimeError("h3_faerie_dragon: native view has neither Blink nor Flying movement card")
    logic_passives = logic_row.setdefault("passives", [])

    if profile in ("living", "undead", "construct", "dragon"):
        # Class card follows the kit profile, never the donor (Ogre "magic creature",
        # Gold/Diamond Dragon "embodiment").
        view_row["baseClass"] = {"name": f"base_class_{profile}", "description": f"base_class_{profile}_description"}

    def own_view_passive(mech: dict[str, Any]) -> None:
        name_sid = homm3_neutral_kit_passive_sid(sid, str(mech["mech"]), "name")
        desc_sid = homm3_neutral_kit_passive_sid(sid, str(mech["mech"]), "description")
        extra = {"icon": str(mech["icon"])} if isinstance(mech.get("icon"), str) else {}
        append_unique_view_passive(view_passives, name_sid, desc_sid, **extra)
        lang_rows.append({"sid": name_sid, "text": str(mech["name"])})
        lang_rows.append({"sid": desc_sid, "text": str(mech["description"])})

    for mech in mechanics:
        name = str(mech["mech"])
        value = mech.get("value")
        if name in HOMM3_NEUTRAL_KIT_OWN_TEXT_MECHANICS and not (isinstance(mech.get("name"), str) and isinstance(mech.get("description"), str)):
            raise RuntimeError(f"homm3_neutral {sid}: mechanic {name} needs its own name and description")
        if name == "positive_luck":
            stats["luck"] = max(1, int(stats.get("luck") or 0))
            stats["luckMin"] = 1
            append_unique_view_passive(view_passives, "h3_common_passive_positive_luck_name", "h3_common_passive_positive_luck_description", icon="sub_skill_luck_1_icon")
        elif name == "no_retaliation":
            for attack in as_attack_list(logic_row.get("defaultAttacks")) + as_attack_list(logic_row.get("alternativeAttacks")):
                dealer = attack.get("damageDealer")
                if isinstance(dealer, dict):
                    dealer["triggerCounter"] = False
            append_unique_view_passive(view_passives, "base_passive_melee_attack_no_counter_name", "base_passive_melee_attack_no_counter_description")
            append_unique_view_passive(view_passives, "base_passive_noncounter_name", "base_passive_noncounter_description")
        elif name == "unlimited_retaliation":
            stats["numCounters"] = 999
            append_unique_view_passive(view_passives, "base_passive_aware_2_name", "base_passive_aware_2_description")
        elif name == "sharpshooter":
            stats["ignoreShootDmgBuff"] = True
            stats["ignoreShootingBlock"] = True
            set_ranged_no_distance_penalty(logic_row)
            append_unique_view_passive(view_passives, "base_passive_sharpshooter_name", "base_passive_sharpshooter_description")
        elif name == "free_shooting":
            stats["ignoreShootingBlock"] = True
            append_unique_view_passive(view_passives, "h3_common_passive_free_shooting_name", "h3_common_passive_free_shooting_description")
        elif name == "regeneration":
            append_unique_passive(logic_passives, fortress_start_turn_regeneration(float(value)))
            own_view_passive(mech)
        elif name == "magic_resistance":
            mods = stats.setdefault("inDmgMods", {"list": []})
            mods.setdefault("list", []).append({"t": "magic_damage", "v": -float(value)})
            own_view_passive(mech)
        elif name == "magic_level_immunity":
            level = int(value)
            append_unique_passive(logic_passives, magic_level_immunity_passive(level))
            append_unique_view_passive(view_passives, f"base_passive_immunity_magic_{level}_name", f"base_passive_immunity_magic_{level}_description_alt")
        elif name == "fearless":
            append_unique_passive(logic_passives, cove_fearless_passive())
            append_unique_view_passive(view_passives, "h3_common_passive_cove_fearless_name", "h3_common_passive_cove_fearless_description")
        elif name == "luck_aura":
            logic_row["aura"] = {
                "radius": 1,
                "tag": f"{sid}_aura",
                "target": "allynoself",
                "power": 1,
                "data": {"stats": {"luck": int(value)}},
            }
            own_view_passive(mech)
    view_row["passives"] = view_passives

    logic_abilities: list[Any] = []
    view_abilities: list[Any] = []
    if kit.get("donorActives") is True:
        if donor_logic_row is None or donor_view_row is None:
            raise RuntimeError(f"homm3_neutral {sid}: donorActives needs the donor rows")
        logic_abilities.extend(copy.deepcopy(donor_logic_row.get("abilities") or []))
        view_abilities.extend(copy.deepcopy(donor_view_row.get("abilities") or []))
        if len(logic_abilities) != len(view_abilities):
            raise RuntimeError(f"homm3_neutral {sid}: donor logic/view ability counts differ")
    for active in kit.get("actives") or []:
        kind = str(active["kind"])
        if kind not in STRONG_VANILLA_ACTIVE_SPECS:
            raise RuntimeError(f"homm3_neutral {sid}: unknown active kind {kind}")
        logic_abilities.append(make_strong_vanilla_active_ability(kind))
        view_ability = make_strong_vanilla_view_ability(kind)
        if isinstance(active.get("name"), str) and isinstance(active.get("description"), str):
            name_sid = homm3_neutral_kit_active_sid(sid, kind, "name")
            desc_sid = homm3_neutral_kit_active_sid(sid, kind, "description")
            view_ability["name"] = name_sid
            view_ability["description"] = desc_sid
            lang_rows.append({"sid": name_sid, "text": str(active["name"])})
            lang_rows.append({"sid": desc_sid, "text": str(active["description"])})
        view_abilities.append(view_ability)
    logic_row["abilities"] = logic_abilities
    view_row["abilities"] = view_abilities
    ensure_unit_view_card_icons(view_row)
    logic_row["xHomm3NeutralOeKit"] = {
        "source": f"tools/homm3_import/faction_concepts/homm3_neutral.json:{sid}.oeKit",
        "profile": profile,
        "actives": [str(a["kind"]) for a in kit.get("actives") or []],
        "mechanics": sorted(mech_names),
        "proof": "generated_artifact; balance and runtime casting unproven until played",
    }
    return lang_rows


def apply_homm3_neutral_oe_kits(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    from homm3_neutral_catalog import catalog_units, load_homm3_neutral_catalog, unit_logic_path, unit_view_path

    catalog = load_homm3_neutral_catalog()
    lang_rows: list[dict[str, str]] = []
    changed = 0
    needs_fortune = False
    for unit in catalog_units(catalog):
        sid = str(unit["sid"])
        logic_name = unit_logic_path(sid, catalog)
        view_name = unit_view_path(sid, catalog)
        logic_doc = json.loads(output[logic_name].decode("utf-8-sig")) if logic_name in output else read_json(release_zip, logic_name)
        view_doc = json.loads(output[view_name].decode("utf-8-sig")) if view_name in output else read_json(release_zip, view_name)
        logic_row = logic_doc["array"][0]
        view_row = view_doc["array"][0]
        donor_logic_row = donor_view_row = None
        if (unit.get("oeKit") or {}).get("donorActives") is True:
            donor_faction = str(unit["donorFactionSid"])
            donor_unit = str(unit["donorUnitSid"])
            donor_logic_row = read_json(release_zip, f"DB/units/units_logics/{donor_faction}/{donor_unit}_l.json")["array"][0]
            donor_view_row = read_json(release_zip, f"DB/units/units_views/{donor_faction}/{donor_unit}_v.json")["array"][0]
        lang_rows.extend(apply_homm3_neutral_oe_kit(unit, logic_row, view_row, donor_logic_row, donor_view_row))
        needs_fortune = needs_fortune or any(
            str(a.get("kind")) == "fortune_spell" for a in (unit.get("oeKit") or {}).get("actives") or []
        )
        output[logic_name] = write_json(logic_doc)
        output[view_name] = write_json(view_doc)
        changed += 1
    if needs_fortune:
        buffs_name = "DB/buffs/buffs_space_magics.json"
        buffs_doc = json.loads(output[buffs_name].decode("utf-8-sig")) if buffs_name in output else read_json(release_zip, buffs_name)
        if upsert_array_row(buffs_doc, make_homm3_neutral_fortune_buff_row()):
            output[buffs_name] = write_json(buffs_doc)
            notes.append("merge homm3_neutral Fortune luck buff")
        for lang_path in ("Lang/english/texts/magic_buff.json", "Lang/english/texts/unitsBuff.json"):
            add_lang_overlay_rows(
                release_zip,
                output,
                lang_path,
                [{"sid": f"{HOMM3_NEUTRAL_FORTUNE_BUFF_SID}_description", "text": "Fortune: +2 Luck."}],
                notes,
            )
    if lang_rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/unitsAbility.json", lang_rows, notes)
    notes.append(f"apply homm3_neutral OE kits ({changed})")


def add_strong_vanilla_ability_lang_rows(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    add_lang_overlay_rows(
        release_zip,
        output,
        "Lang/english/texts/unitsAbility.json",
        strong_vanilla_active_lang_rows() + stronghold_source_unit_lang_rows(),
        notes,
    )


def add_release_generic_units(release_zip: zipfile.ZipFile, manifest: dict[str, Any], output: dict[str, bytes], notes: list[str]) -> None:
    faction_sid = manifest["identity"]["factionSid"]
    if faction_sid == "homm3_tower":
        notes.append("preserve homm3_tower quality-pass unit logic/view rows")
        return
    variants = manifest_unit_variants(manifest)
    changed = 0
    for line in manifest_all_unit_lines(manifest):
        for suffix_index, suffix in enumerate(variants):
            donor_faction = manifest_donor_faction_sid_for_variant(line, suffix, manifest["identity"].get("donorFactionSid"))
            donor_sid = manifest_donor_unit_sid_for_variant(line, suffix)
            if not donor_faction or not donor_sid:
                notes.append(f"warn missing {faction_sid} donor mapping for {line.get('baseSid')} suffix {suffix}")
                continue
            custom_sid = manifest_unit_sid_for_variant(line, suffix)
            logic_name = f"DB/units/units_logics/{donor_faction}/{donor_sid}_l.json"
            view_name = f"DB/units/units_views/{donor_faction}/{donor_sid}_v.json"
            target_logic = f"DB/units/units_logics/{faction_sid}/{custom_sid}_l.json"
            target_view = f"DB/units/units_views/{faction_sid}/{custom_sid}_v.json"
            try:
                logic, is_shooter, is_flyer = normalize_generic_unit_logic(
                    read_json(release_zip, logic_name),
                    custom_sid,
                    line,
                    suffix_index,
                    variants,
                    manifest,
                )
                view = normalize_generic_unit_view(read_json(release_zip, view_name), custom_sid, line, is_shooter, is_flyer, manifest)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing {faction_sid} donor {donor_sid}: {ex}")
                continue
            output[target_logic] = write_json(logic)
            output[target_view] = write_json(view)
            changed += 2
    if changed:
        notes.append(f"generate {faction_sid} generic unit logic/view rows ({changed})")


