def homm3_rampart_avenger_buff_sid(key: str) -> str:
    return f"{HOMM3_RAMPART_AVENGER_ABILITY_SID}_{key}_effect"


def make_homm3_rampart_avenger_buff_row(key: str, damage_taken: float, description: str, *, hp_percent: float | None = None) -> dict[str, Any]:
    stats: dict[str, Any] = {"inAllDmgMod": damage_taken}
    if hp_percent is not None:
        stats["hpPerc"] = hp_percent
    data: dict[str, Any] = {"stats": stats}
    if hp_percent is not None:
        data["immunities"] = [
            {"type": "mechanic", "tags": ["heal"]},
            {"type": "mechanic", "tags": ["heal_percent"]},
            {"type": "mechanic", "tags": ["vampirism"]},
            {"type": "mechanic", "tags": ["revive"]},
        ]
    row = {
        "id": homm3_rampart_avenger_buff_sid(key),
        "aiValue": 7000,
        "aiValuePerDuration": 350,
        "icon": "magic_vulnerability_effect_icon",
        "name_": f"{HOMM3_RAMPART_AVENGER_ABILITY_SID}_name",
        "description_": f"{HOMM3_RAMPART_AVENGER_ABILITY_SID}_{key}_effect_description",
        "tags": ["negative"],
        "isPositive": False,
        "addition": "duration",
        "data": data,
        "xHomm3SourceEffect": description,
    }
    if hp_percent is not None:
        row["vfxList"] = ["effects/status/poisoning_unit"]
        row["keepOnDeath"] = True
    return row


def make_homm3_rampart_avenger_buff_rows() -> list[dict[str, Any]]:
    return [
        make_homm3_rampart_avenger_buff_row("rank_1", 0.20, "Rank-1 all-damage vulnerability"),
        make_homm3_rampart_avenger_buff_row("rank_2", 0.30, "Rank-2 all-damage vulnerability"),
        make_homm3_rampart_avenger_buff_row("rank_3", 0.50, "Rank-3 all-damage vulnerability"),
        make_homm3_rampart_avenger_buff_row("rank_2_decay", 0.30, "Rank-2 all-damage vulnerability plus rank-2 heal lock / max-HP loss", hp_percent=-0.20),
    ]


