def make_homm3_cove_treasure_hunting_magic_rows(release_zip: zipfile.ZipFile, output: dict[str, bytes]) -> list[dict[str, Any]]:
    source_doc = read_overlay_or_release_json(release_zip, output, HOMM3_COVE_GROUNDSIGHT_SOURCE_MAGIC_PATH)
    source_rows = source_doc.get("array") if isinstance(source_doc, dict) else None
    if not isinstance(source_rows, list):
        raise RuntimeError(f"malformed Cove Treasure Hunting magic source {HOMM3_COVE_GROUNDSIGHT_SOURCE_MAGIC_PATH}")
    base_row = next(
        (row for row in source_rows if isinstance(row, dict) and row.get("id") == HOMM3_COVE_GROUNDSIGHT_BASE_SID),
        None,
    )
    if not isinstance(base_row, dict):
        raise RuntimeError(f"missing Cove Treasure Hunting magic source {HOMM3_COVE_GROUNDSIGHT_BASE_SID}")
    rows: list[dict[str, Any]] = []
    for index, sid in enumerate(HOMM3_COVE_TREASURE_HUNTING_MAGIC_SIDS):
        row = copy.deepcopy(base_row)
        row["id"] = sid
        row["name"] = f"{sid}_name"
        row["description"] = [f"{sid}_description"] * 4
        row["bonusDescriptions"] = []
        row["upEffectDescription"] = ""
        row["manaCost"] = [0, 0, 0, 0]
        row["school_"] = "neutral"
        row["rank"] = 1
        row["usedOnMap"] = True
        row["xHomm3SkillGrantedOnly"] = True
        row.pop("learnCost", None)
        world_magic = row.get("worldMagic")
        if not isinstance(world_magic, dict):
            raise RuntimeError(f"malformed Cove Treasure Hunting worldMagic source {HOMM3_COVE_GROUNDSIGHT_BASE_SID}")
        world_magic["settingPerLevels"] = [index, index, index, index]
        rows.append(row)
    return rows



def homm3_castle_elite_strategem_magic_lang_rows() -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for mode in HOMM3_CASTLE_ELITE_STRATEGEM_MAGIC_MODES:
        sid = mode["sid"]
        rows.append({"sid": f"{sid}_name", "text": mode["name"]})
        rows.append({"sid": f"{sid}_description", "text": mode["description"]})
        rows.append({"sid": f"{sid}_cast", "text": mode["cast"]})
    return rows


def homm3_castle_elite_strategem_magic_arg_rows() -> list[dict[str, Any]]:
    sids: set[str] = set()
    for mode in HOMM3_CASTLE_ELITE_STRATEGEM_MAGIC_MODES:
        sid = mode["sid"]
        sids.add(f"{sid}_name")
        sids.add(f"{sid}_description")
        sids.add(f"{sid}_cast")
    return [{"sid": sid, "args": []} for sid in sorted(sids)]


def make_homm3_castle_elite_strategem_magic_rows(release_zip: zipfile.ZipFile, output: dict[str, bytes]) -> list[dict[str, Any]]:
    source_doc = read_overlay_or_release_json(release_zip, output, HOMM3_CASTLE_ELITE_STRATEGEM_MAGIC_PATH)
    source_rows = source_doc.get("array") if isinstance(source_doc, dict) else None
    if not isinstance(source_rows, list):
        raise RuntimeError(f"malformed Castle Elite Strategem magic source {HOMM3_CASTLE_ELITE_STRATEGEM_MAGIC_PATH}")
    base_row = next((row for row in source_rows if isinstance(row, dict) and row.get("id") == "change_use_necromancy"), None)
    if not isinstance(base_row, dict):
        raise RuntimeError("missing Castle Elite Strategem magic source change_use_necromancy")
    rows: list[dict[str, Any]] = []
    for mode in HOMM3_CASTLE_ELITE_STRATEGEM_MAGIC_MODES:
        sid = mode["sid"]
        row = copy.deepcopy(base_row)
        row["id"] = sid
        row["name"] = f"{sid}_name"
        row["icon"] = mode["icon"]
        row["description"] = [f"{sid}_description"] * 4
        row["bonusDescriptions"] = []
        row["upEffectDescription"] = ""
        row["manaCost"] = [0, 0, 0, 0]
        row["upgradeCost"] = [0]
        row["rank"] = 1
        row["school_"] = "neutral"
        row["usedOnMap"] = True
        row["xHomm3RuntimeHook"] = "Castle Elite Strategem reuses native Necromancer Will world-magic handler construction; Homm3CastleEliteStrategemRuntime intercepts these Castle-only parameter rows and owns the active placement mode."
        world_magic = row.get("worldMagic")
        if not isinstance(world_magic, dict):
            raise RuntimeError("malformed Castle Elite Strategem worldMagic source change_use_necromancy")
        magic_settings = world_magic.get("magicSettings")
        if not isinstance(magic_settings, list) or not magic_settings:
            raise RuntimeError("malformed Castle Elite Strategem magicSettings source change_use_necromancy")
        world_magic["settingPerLevels"] = [0, 0, 0, 0]
        for setting in magic_settings:
            if isinstance(setting, dict):
                setting["mechType"] = "change_use_necromancy"
                setting["parameters"] = [mode["mode"]]
                setting["castInfoSid"] = f"{sid}_cast"
        rows.append(row)
    return rows


def make_homm3_castle_elite_strategem_ambush_arena_doc(release_zip: zipfile.ZipFile, output: dict[str, bytes]) -> dict[str, Any]:
    source_doc = read_overlay_or_release_json(release_zip, output, "DB/arenas/arenas_logics_configs/battleArena_interactObject.json")
    source_rows = source_doc.get("array") if isinstance(source_doc, dict) else None
    if not isinstance(source_rows, list) or not source_rows or not isinstance(source_rows[0], dict):
        raise RuntimeError("malformed Castle Elite Strategem ambush arena source battleArena_interactObject")
    row = copy.deepcopy(source_rows[0])
    row["id"] = HOMM3_CASTLE_ELITE_STRATEGEM_AMBUSH_ARENA_SID
    row["tacticsPlacementSid"] = "battlePlacement_standart"
    row["blockTacticsPhase"] = False
    row["xHomm3RuntimeHook"] = "Castle Elite Strategem Ambush: native interact-object center/outside spawns with standard tactics placement so player redeploy legality does not include center tiles."
    return {"array": [row]}


