def make_homm3_bulwark_rune_level_buff_rows() -> list[dict[str, Any]]:
    """Incremental Rune Level threshold buffs (no removal API required).

    Crossing levels 1/4/7 grants +2 Offence each, 2/5/8 grants +2 Defence each,
    and 3/6/9 grants +1 Speed each. Runtime applies each newly crossed SID once.
    """

    def offence_bonus(level: int) -> int:
        return 2 if level in (1, 4, 7) else 0

    def defence_bonus(level: int) -> int:
        return 2 if level in (2, 5, 8) else 0

    def speed_bonus(level: int) -> int:
        return 1 if level in (3, 6, 9) else 0

    rows: list[dict[str, Any]] = []
    for level in range(1, 10):
        atk = offence_bonus(level)
        defense = defence_bonus(level)
        speed = speed_bonus(level)
        stats: dict[str, int] = {}
        if atk:
            stats["offence"] = atk
        if defense:
            stats["defence"] = defense
        if speed:
            stats["speed"] = speed
        # Speed thresholds need haste-family movement tags. Live-negative 2026-07-26:
        # custom speed rows with only ["positive", ...] verified present but did not
        # change combat Speed; haste / Factory Drive carry movementPositive.
        tags = ["positive", "homm3_bulwark_runes", f"homm3_bulwark_rune_level_{level}"]
        if speed:
            tags = [
                "positive",
                "movementPositive",
                "hasteEffect",
                "haste",
                "homm3_bulwark_runes",
                f"homm3_bulwark_rune_level_{level}",
            ]
        rows.append(
            {
                "id": f"homm3_bulwark_rune_level_{level}",
                "aiValue": 4000 + level * 100,
                "aiValuePerDuration": 40,
                "infinite": True,
                "icon": "magic_radiant_armor_effect_icon",
                "name_": f"homm3_bulwark_rune_level_{level}_name",
                "description_": f"homm3_bulwark_rune_level_{level}_desc",
                "tags": tags,
                "isPositive": True,
                "addition": "data",
                "data": {
                    "stats": stats,
                },
            }
        )
    return rows


def make_homm3_factory_split_assembly_buff_rows() -> list[dict[str, Any]]:
    # Battle-long: infinite+addition=data like Bulwark Runes. Live-neg: addition=duration decayed immediately.
    rows: list[dict[str, Any]] = []
    magnitudes = (
        (1, 0.05, 1),
        (2, 0.10, 1),
        (3, 0.15, 2),
    )
    for magnitude, damage, tempo in magnitudes:
        rows.append(
            {
                "id": f"homm3_factory_split_assembly_ranged_{magnitude}",
                "aiValue": 5000,
                "aiValuePerDuration": 50,
                "infinite": True,
                "icon": "magic_favorable_wind_effect_icon",
                "name_": f"homm3_factory_split_assembly_ranged_{magnitude}_name",
                "description_": f"homm3_factory_split_assembly_ranged_{magnitude}_desc",
                "tags": ["positive", "homm3_factory_split_assembly"],
                "isPositive": True,
                "addition": "data",
                "canDispel": False,
                "vfxList": ["magic/Prefabs_vfx/magic_favorable_wind_unit"],
                "data": {
                    "stats": {
                        "outDmgMods": {
                            "list": [
                                {"t": "shoot_attack", "v": damage},
                                {"t": "range_attack", "v": damage},
                            ]
                        }
                    }
                },
            }
        )
        rows.append(
            {
                "id": f"homm3_factory_split_assembly_mitigation_{magnitude}",
                "aiValue": 5000,
                "aiValuePerDuration": 50,
                "infinite": True,
                "icon": "magic_radiant_armor_effect_icon",
                "name_": f"homm3_factory_split_assembly_mitigation_{magnitude}_name",
                "description_": f"homm3_factory_split_assembly_mitigation_{magnitude}_desc",
                "tags": ["positive", "homm3_factory_split_assembly"],
                "isPositive": True,
                "addition": "data",
                "canDispel": False,
                "vfxList": ["magic/Prefabs_vfx/magic_radiant_armor_unit"],
                "data": {"stats": {"inAllDmgMod": -damage}},
            }
        )
        rows.append(
            {
                "id": f"homm3_factory_split_assembly_melee_{magnitude}",
                "aiValue": 5000,
                "aiValuePerDuration": 50,
                "infinite": True,
                "icon": "magic_sharp_edge_effect_icon",
                "name_": f"homm3_factory_split_assembly_melee_{magnitude}_name",
                "description_": f"homm3_factory_split_assembly_melee_{magnitude}_desc",
                "tags": ["positive", "homm3_factory_split_assembly"],
                "isPositive": True,
                "addition": "data",
                "canDispel": False,
                "vfxList": ["magic/Prefabs_vfx/magic_sharp_edge_unit"],
                "data": {
                    "stats": {
                        "outDmgMods": {
                            "list": [
                                {"t": "melee_attack", "v": damage},
                                {"t": "basic_attack", "v": damage},
                            ]
                        }
                    }
                },
            }
        )
        rows.append(
            {
                "id": f"homm3_factory_split_assembly_speed_{magnitude}",
                "aiValue": 4500,
                "aiValuePerDuration": 45,
                "infinite": True,
                "icon": "magic_haste_effect_icon",
                "name_": f"homm3_factory_split_assembly_speed_{magnitude}_name",
                "description_": f"homm3_factory_split_assembly_speed_{magnitude}_desc",
                # Clone haste donor movement tags. Live-negative 2026-07-26: custom
                # speed rows with only ["positive", faction] verified present in dzv
                # but did not change UI/combat Speed; haste/web/frostbound all carry
                # movementPositive/movementNegative.
                "tags": [
                    "positive",
                    "movementPositive",
                    "hasteEffect",
                    "haste",
                    "homm3_factory_split_assembly",
                ],
                "isPositive": True,
                "addition": "data",
                "canDispel": False,
                "vfxList": ["magic/Prefabs_vfx/magic_haste_unit"],
                "data": {"stats": {"speed": tempo}},
            }
        )
        rows.append(
            {
                "id": f"homm3_factory_split_assembly_initiative_{magnitude}",
                "aiValue": 4500,
                "aiValuePerDuration": 45,
                "infinite": True,
                "icon": "magic_early_start_effect_icon",
                "name_": f"homm3_factory_split_assembly_initiative_{magnitude}_name",
                "description_": f"homm3_factory_split_assembly_initiative_{magnitude}_desc",
                "tags": ["positive", "homm3_factory_split_assembly"],
                "isPositive": True,
                "addition": "data",
                "canDispel": False,
                "data": {"stats": {"initiative": tempo}},
            }
        )
    return rows


