def normalize_generic_squad_doc(value: Any, replacements: dict[str, str], donor_faction_sid: str, faction_sid: str) -> Any:
    if isinstance(value, str):
        if value in replacements:
            return replacements[value]
        if value == donor_faction_sid:
            return faction_sid
        return value.replace(f"squad_{donor_faction_sid}", f"squad_{faction_sid}").replace(
            f"squads_{donor_faction_sid}",
            f"squads_{faction_sid}",
        )
    if isinstance(value, list):
        return [normalize_generic_squad_doc(item, replacements, donor_faction_sid, faction_sid) for item in value]
    if isinstance(value, dict):
        return {key: normalize_generic_squad_doc(item, replacements, donor_faction_sid, faction_sid) for key, item in value.items()}
    return value


def add_release_generic_squads(release_zip: zipfile.ZipFile, manifest: dict[str, Any], output: dict[str, bytes], notes: list[str]) -> None:
    identity = manifest["identity"]
    donor_faction_sid = manifest_donor_fraction_sid(manifest)
    faction_sid = identity["factionSid"]
    replacements = manifest_squad_unit_replacements(manifest)
    source_prefix = f"DB/squads/squads_{donor_faction_sid}/"
    target_prefix = manifest_core_member(manifest, "squadTree")
    changed = 0
    for info in release_zip.infolist():
        source_name = normalize_name(info.filename)
        if info.is_dir() or not source_name.startswith(source_prefix) or not source_name.endswith(".json"):
            continue
        target_name = target_prefix + source_name[len(source_prefix) :].replace(
            f"squad_{donor_faction_sid}",
            f"squad_{faction_sid}",
        )
        try:
            doc = normalize_generic_squad_doc(read_json(release_zip, source_name), replacements, donor_faction_sid, faction_sid)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing {faction_sid} squad donor {source_name}: {ex}")
            continue
        output[target_name] = write_json(doc)
        changed += 1
    if changed:
        notes.append(f"generate {faction_sid} squad tree from {donor_faction_sid} donor ({changed})")


def make_generic_skill_row(manifest: dict[str, Any]) -> dict[str, Any] | None:
    skill_sid = manifest_faction_skill_sid(manifest)
    if not skill_sid.startswith("skill_faction_homm3_"):
        return None
    specialized = make_specialized_generic_skill_row(manifest, skill_sid)
    if specialized is not None:
        return specialized
    row = {
        "id": skill_sid,
        "name": f"{skill_sid}_name",
        "desc": f"{skill_sid}_desc",
        "skillType": "Faction",
        "parametersPerLevel": [
            {
                "icon": skill_sid if index == 1 else f"{skill_sid}_{index}",
                "name": f"{skill_sid}_name_{index}",
                "desc": f"{skill_sid}_desc",
                "bonuses": [],
                "subSkills": [],
            }
            for index in range(1, 4)
        ],
    }
    return row


def unit_stat_bonus(receivers: list[str], stat: str, value: str) -> dict[str, Any]:
    return {"type": "unitStat", "receivers": receivers, "parameters": [stat, value]}


def unit_bool_stat_bonus(stat: str, value: str = "true") -> dict[str, Any]:
    return {"type": "unitBoolStat", "parameters": [stat, value]}


def hero_stat_bonus(stat: str, *values: str) -> dict[str, Any]:
    return {"type": "heroStat", "parameters": [stat, *values]}


def unit_modifier_bonus(receivers: list[str], modifier: str, tag: str, value: str) -> dict[str, Any]:
    return {"type": "unitStat", "receivers": receivers, "parameters": ["modifierSet", modifier, tag, value]}


def manifest_line_receivers(manifest: dict[str, Any], tier: int) -> list[str]:
    variants = manifest_unit_variants(manifest)
    for line in manifest.get("unitLines", []):
        if int(line.get("tier") or 0) == tier:
            return [manifest_unit_sid_for_variant(line, suffix) for suffix in variants]
    return []


def manifest_all_unit_receivers(manifest: dict[str, Any]) -> list[str]:
    variants = manifest_unit_variants(manifest)
    return [
        manifest_unit_sid_for_variant(line, suffix)
        for line in manifest_all_unit_lines(manifest)
        for suffix in variants
    ]


