def custom_law_profile(manifest: dict[str, Any]) -> dict[str, Any]:
    faction_sid = manifest["identity"]["factionSid"]
    return CUSTOM_LAW_PROFILES.get(
        faction_sid,
        {
            "display": faction_sid.removeprefix("homm3_").title(),
            "mine": ("crystals", "Crystals"),
            "school": ("primal", "Primal"),
            "scout": "Frontier Scouts",
            "theme": [],
        },
    )


def custom_unit_law_indices(manifest: dict[str, Any]) -> tuple[int, ...]:
    donor_fraction_sid = manifest_donor_fraction_sid(manifest)
    return DONOR_UNIT_LAW_INDICES.get(donor_fraction_sid, DONOR_UNIT_LAW_INDICES["human"])


def law_bonus(kind: str, args: list[Any], manifest: dict[str, Any]) -> dict[str, Any]:
    if kind == "sideRes":
        return {"type": "sideRes", "parameters": args}
    if kind == "sideStat":
        return {"type": "sideStat", "parameters": args}
    if kind == "sideOneTimeAddRes":
        return {"type": "sideOneTimeAddRes", "parameters": args}
    if kind == "heroStat":
        return {"type": "heroStat", "parameters": args}
    if kind == "heroStatBattle":
        return {"type": "heroStatBattle", "parameters": args}
    if kind == "heroStatBattleEnemy":
        # BonusConfig.receiverAllegiance defaults to "ally": enemy-hero effects must say so.
        return {"type": "heroStatBattle", "receiverAllegiance": "enemy", "parameters": args}
    if kind == "cityUnitsIncrement":
        return {"type": "cityUnitsIncrement", "parameters": args}
    if kind == "constructionDiscount":
        return {"type": "constructionDiscount", "parameters": args}
    if kind == "constructionDailyLimit":
        return {"type": "constructionDailyLimit", "parameters": args}
    if kind == "unitHiringDiscount":
        return {"type": "unitHiringDiscount", "parameters": args}
    if kind == "astrologyExp":
        return {"type": "astrologyExp", "parameters": args}
    if kind == "unitStatEnemy":
        return {"type": "unitStat", "receiverAllegiance": "enemy", "parameters": args}
    if kind == "unitStat":
        return {"type": "unitStat", "parameters": args}
    if kind == "unitStatReceivers":
        receivers = args[0]
        if not isinstance(receivers, list):
            raise ValueError(f"unitStatReceivers requires receiver list, got {receivers!r}")
        return unit_stat_bonus([str(receiver) for receiver in receivers], str(args[1]), str(args[2]))
    if kind == "unitStatAll":
        return unit_modifier_bonus(manifest_all_unit_receivers(manifest), str(args[0]), str(args[1]), str(args[2]))
    if kind == "unitStatAllSimple":
        return unit_stat_bonus(manifest_all_unit_receivers(manifest), str(args[0]), str(args[1]))
    if kind == "unitStatNative":
        return {
            "type": "unitStat",
            "biomeType": "native",
            "fraction": manifest["identity"]["factionSid"],
            "parameters": args,
        }
    if kind == "unitStatTier":
        tier = int(args[0])
        stat_args = [str(item) for item in args[1:]]
        if stat_args[0] == "modifierSet":
            return unit_modifier_bonus(manifest_line_receivers(manifest, tier), stat_args[1], stat_args[2], stat_args[3])
        return unit_stat_bonus(manifest_line_receivers(manifest, tier), stat_args[0], stat_args[1])
    if kind == "unitStatTiers":
        tiers = [int(tier) for tier in args[0]]
        receivers = [sid for tier in tiers for sid in manifest_line_receivers(manifest, tier)]
        stat_args = [str(item) for item in args[1:]]
        if stat_args[0] == "modifierSet":
            return unit_modifier_bonus(receivers, stat_args[1], stat_args[2], stat_args[3])
        return unit_stat_bonus(receivers, stat_args[0], stat_args[1])
    if kind == "battleSubskillBonus":
        return {"type": "battleSubskillBonus", "parameters": args}
    raise ValueError(f"unknown law bonus kind {kind}")


def law_level(cost: int, specs: list[tuple[Any, ...]], manifest: dict[str, Any]) -> dict[str, Any]:
    bonuses: list[dict[str, Any]] = []
    for spec in specs:
        kind = str(spec[0])
        args = spec[1] if len(spec) == 2 and isinstance(spec[1], list) else list(spec[1:])
        bonuses.append(law_bonus(kind, args, manifest))
    return {"cost": cost, "bonuses": bonuses}


def custom_resource_riches_law(manifest: dict[str, Any], index: int) -> tuple[str, str, list[dict[str, Any]]] | None:
    if index == 3:
        return (
            "Resource Riches I",
            "Provides 2500 Gold, 5 Wood, and 5 Ore when enacted.",
            [law_level(1, [("sideOneTimeAddRes", ["gold", 2500]), ("sideOneTimeAddRes", ["wood", 5]), ("sideOneTimeAddRes", ["ore", 5])], manifest)],
        )
    if index == 16:
        return (
            "Resource Riches II",
            "Provides 5000 Gold, 10 Wood, and 10 Ore when enacted.",
            [law_level(2, [("sideOneTimeAddRes", ["gold", 5000]), ("sideOneTimeAddRes", ["wood", 10]), ("sideOneTimeAddRes", ["ore", 10])], manifest)],
        )
    if index == 29:
        return (
            "Resource Riches III",
            "Provides 7500 Gold, 15 Wood, and 15 Ore when enacted.",
            [law_level(3, [("sideOneTimeAddRes", ["gold", 7500]), ("sideOneTimeAddRes", ["wood", 15]), ("sideOneTimeAddRes", ["ore", 15])], manifest)],
        )
    return None


