def custom_unit_law(manifest: dict[str, Any], tier: int, index: int) -> tuple[str, str, list[dict[str, Any]]]:
    line = next((row for row in manifest.get("unitLines", []) if int(row.get("tier") or 0) == tier), None)
    if not isinstance(line, dict):
        faction_sid = manifest["identity"]["factionSid"]
        raise RuntimeError(f"{faction_sid}: missing unit line for law index {index}, tier {tier}")
    names = line.get("names") if isinstance(line.get("names"), list) else []
    base_name = str(names[0] if names else line.get("baseSid") or f"Tier {tier}")
    family_name = base_name + ("es" if base_name.endswith(("x", "s")) else "s")
    base_sid = manifest_unit_sid_for_variant(line, manifest_unit_variants(manifest)[0])
    receivers = manifest_line_receivers(manifest, tier)
    growth = UNIT_LAW_GROWTH.get(tier, 1)
    if tier == 1:
        stat, first, second = "damageMax", "1", "2"
        desc = f"{base_name} growth increases by {growth}. The line gains +1/+2 maximum Damage by rank."
    elif tier == 2:
        stat, first, second = "damageMin", "1", "2"
        desc = f"{base_name} growth increases by {growth}. The line gains +1/+2 minimum Damage by rank."
    elif tier in (3, 4):
        stat, first, second = "hp", "5", "10"
        desc = f"{base_name} growth increases by {growth}. The line gains +5/+10 HP by rank."
    elif tier in (5, 6):
        stat, first, second = "offence", "2", "4"
        desc = f"{base_name} growth increases by {growth}. The line gains +2/+4 Attack by rank."
    else:
        stat, first, second = "outAllDmgMod", "0.05", "0.10"
        desc = f"{base_name} growth increases by {growth}. The line deals 5%/10% more damage by rank."
    return (
        f"{base_name} Muster",
        desc,
        [
            {"cost": 3, "bonuses": [{"type": "cityUnitsIncrement", "parameters": [base_sid, growth]}, unit_stat_bonus(receivers, stat, first)]},
            {"cost": 2, "bonuses": [{"type": "cityUnitsIncrement", "parameters": [base_sid, growth]}, unit_stat_bonus(receivers, stat, second)]},
        ],
    )


def custom_law_definition(manifest: dict[str, Any], index: int) -> tuple[str, str, list[dict[str, Any]]]:
    profile = custom_law_profile(manifest)
    display = str(profile["display"])
    mine_resource, mine_label = profile["mine"]
    school_key, school_label = profile["school"]
    theme = list(profile.get("theme") or [])
    def theme_entry(position: int) -> tuple[str, str, list[tuple[str, Any]]] | None:
        if position >= len(theme):
            return None
        entry = theme[position]
        if not isinstance(entry, tuple) or len(entry) != 3:
            return None
        name, desc, bonuses = entry
        if not isinstance(name, str) or not isinstance(desc, str) or not isinstance(bonuses, list):
            return None
        return name, desc, bonuses

    resource_riches = custom_resource_riches_law(manifest, index)
