def custom_law_indices_to_emit(manifest: dict[str, Any], count: int) -> tuple[tuple[int, ...], tuple[int, ...]]:
    faction_sid = manifest["identity"]["factionSid"]
    omitted_allowed = set(CUSTOM_LAW_EXPLICITLY_OMITTED_INDICES.get(faction_sid, ()))
    emitted: list[int] = []
    omitted: list[int] = []
    for index in custom_law_candidate_indices(manifest, count):
        if custom_law_override_definition(manifest, index) is not None:
            emitted.append(index)
            continue
        try:
            custom_law_definition(manifest, index)
            emitted.append(index)
        except RuntimeError:
            if index in omitted_allowed:
                omitted.append(index)
                continue
            raise
    return tuple(emitted), tuple(omitted)



def custom_law_levels_direct_resource_icon(levels: list[dict[str, Any]], index: int) -> str | None:
    bonuses: list[dict[str, Any]] = []
    for level in levels:
        if not isinstance(level, dict):
            continue
        level_bonuses = level.get("bonuses")
        if not isinstance(level_bonuses, list):
            continue
        bonuses.extend(bonus for bonus in level_bonuses if isinstance(bonus, dict))
    if not bonuses:
        return None

    if all(bonus.get("type") == "astrologyExp" for bonus in bonuses):
        return ASTROLOGY_LAW_ICON

    if all(bonus.get("type") == "sideRes" for bonus in bonuses):
        resources: set[str] = set()
        for bonus in bonuses:
            parameters = bonus.get("parameters")
            if isinstance(parameters, list) and parameters and isinstance(parameters[0], str):
                resources.add(parameters[0])
        if len(resources) == 1:
            return DIRECT_RESOURCE_LAW_ICONS.get(next(iter(resources)))

    if all(bonus.get("type") == "sideOneTimeAddRes" for bonus in bonuses):
        resources: set[str] = set()
        for bonus in bonuses:
            parameters = bonus.get("parameters")
            if isinstance(parameters, list) and parameters and isinstance(parameters[0], str):
                resources.add(parameters[0])
        if {"gold", "wood", "ore"}.issubset(resources):
            return RESOURCE_RICHES_LAW_ICONS.get(index)
    return None


def custom_law_levels_unit_increment_icon(levels: list[dict[str, Any]]) -> str | None:
    expected_icon: str | None = None
    for level in levels:
        if not isinstance(level, dict):
            continue
        bonuses = level.get("bonuses")
        if not isinstance(bonuses, list):
            continue
        for bonus in bonuses:
            if not isinstance(bonus, dict) or bonus.get("type") != "cityUnitsIncrement":
                continue
            parameters = bonus.get("parameters")
            if not isinstance(parameters, list) or not parameters:
                continue
            unit_sid = parameters[0]
            if not isinstance(unit_sid, str) or not unit_sid.startswith("h3_"):
                continue
            if expected_icon is None:
                expected_icon = unit_sid
            elif expected_icon != unit_sid:
                return None
    return expected_icon

def custom_law_icon(manifest: dict[str, Any], donor_rows: list[Any], index: int) -> str:
    try:
        override_definition = custom_law_override_definition(manifest, index)
        _name, _desc, levels = override_definition or custom_law_definition(manifest, index)
    except RuntimeError:
        override_definition = None
        levels = []

    resource_icon = custom_law_levels_direct_resource_icon(levels, index)
    if isinstance(resource_icon, str) and resource_icon:
        return resource_icon

    faction_sid = manifest["identity"]["factionSid"]
    override = custom_law_override_entry(manifest, index)
    if isinstance(override, dict) and override.get("enabled") is not False:
        homm4_icon_path = override.get("homm4IconPath")
        icon = override.get("iconKey")
        if isinstance(homm4_icon_path, str) and homm4_icon_path.strip() and isinstance(icon, str) and icon.strip():
            return icon.strip()
        portrait_icon = override.get("portraitIconSid")
        if isinstance(portrait_icon, str) and portrait_icon.strip():
            return portrait_icon.strip()

    if override_definition is None:
        unit_law_by_index = {law_index: tier for tier, law_index in enumerate(custom_unit_law_indices(manifest), start=1)}
        tier = unit_law_by_index.get(index)
        if tier is not None:
            for line in manifest.get("unitLines", []):
                if int(line.get("tier") or 0) == tier:
                    base_sid = str(line.get("baseSid") or "").strip()
                    if base_sid:
                        return base_sid
    if levels:
        unit_icon = custom_law_levels_unit_increment_icon(levels)
        if isinstance(unit_icon, str) and unit_icon:
            return unit_icon
    explicit_icon = CUSTOM_LAW_EXPLICIT_INDEX_ICONS.get(index)
    if isinstance(explicit_icon, str) and explicit_icon:
        return explicit_icon

    if isinstance(override, dict) and override.get("enabled") is not False:
        icon = override.get("iconKey")
        if isinstance(icon, str) and icon.strip():
            return icon.strip()

    creature_icon = CUSTOM_LAW_CREATURE_PORTRAIT_ICONS.get(faction_sid, {}).get(index)
    if isinstance(creature_icon, str) and creature_icon.strip():
        return creature_icon.strip()

    raise RuntimeError(f"{faction_sid}: missing explicit icon contract for law index {index}")


def make_release_custom_laws_doc(release_zip: zipfile.ZipFile, manifest: dict[str, Any]) -> dict[str, Any]:
    donor_fraction_sid = manifest_donor_fraction_sid(manifest)
    law_prefix = manifest_law_prefix(manifest)
    donor_doc = read_json(release_zip, f"DB/fractions_laws/fractions_laws_table_{donor_fraction_sid}.json")
    rows = donor_doc.get("array") if isinstance(donor_doc, dict) else None
    if not isinstance(rows, list):
        faction_sid = manifest["identity"]["factionSid"]
        raise RuntimeError(f"{faction_sid}: donor law table {donor_fraction_sid} is missing array rows")
    count = len(rows)
    indices, _omitted_indices = custom_law_indices_to_emit(manifest, count)
    output_rows: list[dict[str, Any]] = []
    for index in indices:
        override_definition = None if index in RESOURCE_RICHES_LAW_ICONS else custom_law_override_definition(manifest, index)
        name, desc, levels = override_definition or custom_law_definition(manifest, index)
        row = {
            "id": f"{law_prefix}{index}",
            "icon": custom_law_icon(manifest, rows if isinstance(rows, list) else [], index),
            "name": f"{law_prefix}{index}_name",
            "desc": f"{law_prefix}{index}_desc",
            "parametersPerLevel": levels,
        }
        stamp_no_compromise_law_target_metadata(row, row["id"])
        override = custom_law_override_entry(manifest, index)
        if isinstance(override, dict) and override.get("enabled") is not False:
            # custom_law_icon centralizes standard Resource Riches icons and
            # creature portrait icons. Do not reapply override iconKey here, or
            # donor-law icons will silently override those source-of-truth rules.
            # Source override notes are planning metadata. Final Core rows must
            # not carry design-debt text; validators enforce that this stays out
            # of generated gameplay data.
            row["xHomm3LawOverride"] = True
        output_rows.append(row)
    return {"array": output_rows}


def custom_law_lang_rows(manifest: dict[str, Any], release_zip: zipfile.ZipFile | None = None) -> list[dict[str, str]]:
    donor_fraction_sid = manifest_donor_fraction_sid(manifest)
    if release_zip is not None:
        donor_doc = read_json(release_zip, f"DB/fractions_laws/fractions_laws_table_{donor_fraction_sid}.json")
    else:
        core = Path("Heroes of Might & Magic Olden Era Playtest") / "HeroesOE_Data" / "StreamingAssets" / "Core.zip"
        with zipfile.ZipFile(core) as zf:
            donor_doc = read_json(zf, f"DB/fractions_laws/fractions_laws_table_{donor_fraction_sid}.json")
    rows_value = donor_doc.get("array") if isinstance(donor_doc, dict) else None
    if not isinstance(rows_value, list):
        faction_sid = manifest["identity"]["factionSid"]
        raise RuntimeError(f"{faction_sid}: donor law table {donor_fraction_sid} is missing array rows for language sync")
    count = len(rows_value)
    law_prefix = manifest_law_prefix(manifest)
    rows: list[dict[str, str]] = []
    indices, _omitted_indices = custom_law_indices_to_emit(manifest, count)
    for index in indices:
        override_definition = custom_law_override_definition(manifest, index)
        name, desc, _levels = override_definition or custom_law_definition(manifest, index)
        rows.append({"sid": f"{law_prefix}{index}_name", "text": name})
        rows.append({"sid": f"{law_prefix}{index}_desc", "text": desc})
    return rows


