def custom_hero_specialization_override_text(faction_sid: str, hero_sid: str) -> tuple[str | None, str | None]:
    override = load_hero_override(faction_sid)
    hero_overrides = override.get("heroOverrides") if isinstance(override, dict) else None
    if not isinstance(hero_overrides, dict):
        return None, None
    entry = hero_overrides.get(hero_sid)
    if not isinstance(entry, dict):
        return None, None
    spec_override = entry.get("specialization")
    if not isinstance(spec_override, dict):
        return None, None
    name = spec_override.get("nameText")
    description = spec_override.get("descriptionText")
    return (
        name.strip() if isinstance(name, str) and name.strip() else None,
        description.strip() if isinstance(description, str) and description.strip() else None,
    )


def add_custom_hero_specialization_lang_rows_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    hero_rows: list[dict[str, str]] = []
    hero_info_rows: list[dict[str, str]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        if faction_sid == "homm3_stronghold":
            continue
        for index in range(1, custom_hero_specialization_count(manifest) + 1):
            hero_sid = manifest_hero_sid(manifest, index)
            spec_name, spec_description = custom_hero_specialization_text(manifest, index)
            override_name, override_description = custom_hero_specialization_override_text(faction_sid, hero_sid)
            if override_name:
                spec_name = override_name
            if override_description:
                spec_description = override_description
            hero_rows.append({"sid": f"{hero_sid}_specialization", "text": spec_name})
            hero_info_rows.append({"sid": f"{hero_sid}_spec_name", "text": spec_name})
            hero_info_rows.append({"sid": f"{hero_sid}_spec_description", "text": spec_description})
    if hero_rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroes.json", hero_rows, notes)
    if hero_info_rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroInfo.json", hero_info_rows, notes)


def format_bonus_percent(value: str | int | float | None) -> str:
    try:
        percent = float(value) * 100.0
    except (TypeError, ValueError):
        return str(value)
    if abs(percent - round(percent)) < 0.0001:
        return f"{int(round(percent))}%"
    return f"{percent:.1f}".rstrip("0").rstrip(".") + "%"


def signed_bonus_value(value: str | int | float | None, percent: bool = False) -> str:
    try:
        number = float(value)
    except (TypeError, ValueError):
        text = str(value)
        return text if text.startswith("-") else "+" + text
    if percent:
        return ("+" if number >= 0 else "") + format_bonus_percent(number)
    if abs(number - round(number)) < 0.0001:
        return f"{int(round(number)):+d}"
    return f"{number:+g}"


def humanize_resource_sid(resource_sid: str) -> str:
    labels = {"gold": "Gold", "gemstones": "Gemstones", "mercury": "Mercury", "crystals": "Crystals"}
    return labels.get(resource_sid, humanize_custom_sid(resource_sid))


def humanize_magic_sid(magic_sid: str) -> str:
    for base_sid, variant in MASTERFUL_MAGIC_VARIANTS.items():
        if magic_sid in {base_sid, masterful_magic_special_sid(base_sid)}:
            prefix = "Masterful " if magic_sid.endswith("_special") else ""
            return prefix + str(variant["displayName"])
    text = re.sub(r"^(day|night|space|primal)_\d+_magic_", "", magic_sid)
    text = text.removesuffix("_special")
    return humanize_custom_sid(text)


def humanize_damage_modifier_sid(value: str) -> str:
    labels = {
        "basic_attack": "basic attack",
        "range_attack": "ranged attack",
        "shoot_attack": "shooting attack",
        "magic_damage": "spell damage",
    }
    return labels.get(value, humanize_custom_sid(value).lower())


def describe_custom_specialization_bonus_row(row: dict[str, Any]) -> str | None:
    if row.get("xHomm3ChangeDisposition") == "explicit_masterful_spell_variant":
        base_sid = row.get("xHomm3MasterfulSpellBaseSid")
        variant = MASTERFUL_MAGIC_VARIANTS.get(base_sid) if isinstance(base_sid, str) else None
        if isinstance(variant, dict):
            return masterful_magic_specialization_description(base_sid)

    bonuses = [bonus for bonus in row.get("bonuses", []) if isinstance(bonus, dict)]
    meaningful = [
        bonus
        for bonus in bonuses
        if bonus.get("type") != "heroBattleAbility"
        and not (bonus.get("type") == "heroStat" and (bonus.get("parameters") or [None])[0] == "magicSchoolSet")
    ]
    if not meaningful:
        return None

    def first_bonus(bonus_type: str, stat: str | None = None) -> dict[str, Any] | None:
        for bonus in meaningful:
            params = bonus.get("parameters") or []
            if bonus.get("type") == bonus_type and (stat is None or (params and params[0] == stat)):
                return bonus
        return None

    city_growth = first_bonus("cityUnitsIncrement")
    if city_growth:
        params = city_growth.get("parameters") or []
        unit = humanize_custom_sid(str(params[0])) if params else "the specialized unit"
        growth = signed_bonus_value(params[1] if len(params) > 1 else "1")
        parts = [f"{unit} growth in each owned city is {growth} per week."]
        stat_bits: list[str] = []
        for stat, label, is_percent in (("speed", "Speed", False), ("initiative", "Initiative", False), ("hpPerc", "Health", True)):
            bonus = first_bonus("unitStat", stat)
            if bonus:
                bonus_params = bonus.get("parameters") or []
                stat_bits.append(signed_bonus_value(bonus_params[1] if len(bonus_params) > 1 else "0", is_percent) + f" {label}")
        for stat, label in (("offence", "Attack"), ("defence", "Defense")):
            bonus = first_bonus("unitStat", stat)
            if bonus and isinstance(bonus.get("upgrade"), dict):
                upgrade = bonus["upgrade"]
                stat_bits.append(f"{signed_bonus_value(upgrade.get('increment'))} {label} per {upgrade.get('levelStep')} hero levels")
        if stat_bits:
            parts.append(f"Friendly {unit} lines gain " + ", ".join(stat_bits) + ".")
        enemy_offence = next(
            (
                bonus
                for bonus in meaningful
                if bonus.get("type") == "unitStat"
                and bonus.get("receiverAllegiance") == "enemy"
                and (bonus.get("parameters") or [None])[0] == "offence"
            ),
            None,
        )
        enemy_defence = next(
            (
                bonus
                for bonus in meaningful
                if bonus.get("type") == "unitStat"
                and bonus.get("receiverAllegiance") == "enemy"
                and (bonus.get("parameters") or [None])[0] == "defence"
            ),
            None,
        )
        if enemy_offence and enemy_defence and isinstance(enemy_offence.get("upgrade"), dict):
            parts.append(f"Enemy {unit} lines get -1 Attack and -1 Defense per {enemy_offence['upgrade'].get('levelStep')} hero levels.")
        return " ".join(parts)

    magic_replace = first_bonus("heroMagicReplace")
    if magic_replace:
        params = magic_replace.get("parameters") or []
        source = humanize_magic_sid(str(params[0])) if params else "the base spell"
        target = humanize_magic_sid(str(params[1])) if len(params) > 1 else "the specialized spell"
        spell_power = first_bonus("heroStat", "spellPowerSidSet")
        replace_text = f"Replaces {source} with specialized {target}" if source == target else f"Replaces {source} with {target}"
        if spell_power and isinstance(spell_power.get("upgrade"), dict):
            upgrade = spell_power["upgrade"]
            return f"{replace_text}. {target} gets {signed_bonus_value(upgrade.get('increment'))} effective Spell Power per {upgrade.get('levelStep')} hero levels."
        return replace_text + "."

    heroic = [bonus for bonus in meaningful if bonus.get("type") == "battleSubskillBonus"]
    if heroic:
        levels = [str(bonus.get("activationLevel")) for bonus in heroic if bonus.get("activationLevel") is not None]
        if levels:
            return "Improves Heroic Strike at battle start and again at hero levels " + ", ".join(levels) + "."
        return "Improves Heroic Strike."

    side_res = first_bonus("sideRes")
    if side_res:
        params = side_res.get("parameters") or []
        resource = humanize_resource_sid(str(params[0])) if params else "resource"
        amount = params[1] if len(params) > 1 else "0"
        text = f"Produces {signed_bonus_value(amount)} {resource} per day."
        if isinstance(side_res.get("upgrade"), dict):
            upgrade = side_res["upgrade"]
            text += f" Production increases by {signed_bonus_value(upgrade.get('increment'))} every {upgrade.get('levelStep')} hero levels."
        res_percent = first_bonus("heroStat", "heroResPercentSet")
        if res_percent:
            pct_params = res_percent.get("parameters") or []
            if len(pct_params) > 2:
                text += f" Also applies a {format_bonus_percent(pct_params[2])} {resource} income modifier."
        return text

    movement = first_bonus("heroStat", "movementPerBonus")
    if movement:
        params = movement.get("parameters") or []
        text = f"Adventure movement is {signed_bonus_value(params[1] if len(params) > 1 else '0', percent=True)}"
        if movement.get("activationLevel") is not None:
            text += f" starting at hero level {movement.get('activationLevel')}"
        if isinstance(movement.get("upgrade"), dict):
            upgrade = movement["upgrade"]
            text += f", then {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
        text += "."
        road = first_bonus("heroStat", "roadPerBonus")
        if road:
            road_params = road.get("parameters") or []
            text += f" Road movement is {signed_bonus_value(road_params[1] if len(road_params) > 1 else '0', percent=True)}."
        return text

    view = first_bonus("heroStat", "viewRadius")
    if view:
        params = view.get("parameters") or []
        text = f"View radius is {signed_bonus_value(params[1] if len(params) > 1 else '0')}"
        if isinstance(view.get("upgrade"), dict):
            upgrade = view["upgrade"]
            text += f", plus {signed_bonus_value(upgrade.get('increment'))} every {upgrade.get('levelStep')} hero levels"
        text += "."
        if first_bonus("heroStat", "enableEnemyHeroInfo"):
            text += " Enemy hero details are revealed."
        if first_bonus("heroStat", "enableSquadCounts"):
            text += " Enemy army stack counts are revealed."
        landscape = first_bonus("heroStat", "landscapePenaltyPerBonus")
        if landscape:
            land_params = landscape.get("parameters") or []
            text += f" Rough-terrain movement penalty modifier is {signed_bonus_value(land_params[1] if len(land_params) > 1 else '0', percent=True)}."
        after_battle = first_bonus("heroStat", "movementAfterBattleBonus")
        if after_battle:
            after_params = after_battle.get("parameters") or []
            text += f" Restores {signed_bonus_value(after_params[1] if len(after_params) > 1 else '0')} movement after battles."
        return text

    landscape = first_bonus("heroStat", "landscapePenaltyPerBonus")
    if landscape:
        land_params = landscape.get("parameters") or []
        text = f"Rough-terrain movement penalty modifier is {signed_bonus_value(land_params[1] if len(land_params) > 1 else '0', percent=True)}."
        after_battle = first_bonus("heroStat", "movementAfterBattleBonus")
        if after_battle:
            after_params = after_battle.get("parameters") or []
            text += f" Restores {signed_bonus_value(after_params[1] if len(after_params) > 1 else '0')} movement after battles."
        return text

    moral = first_bonus("heroStat", "moral")
    if moral:
        params = moral.get("parameters") or []
        action = first_bonus("unitStat", "additionalActionChanceModifier")
        text = f"Army Morale is {signed_bonus_value(params[1] if len(params) > 1 else '0')}."
        if action:
            action_params = action.get("parameters") or []
            text += f" Friendly units have {signed_bonus_value(action_params[1] if len(action_params) > 1 else '0', percent=True)} additional action chance"
            if isinstance(action.get("upgrade"), dict):
                upgrade = action["upgrade"]
                text += f", plus {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
            text += "."
        return text

    luck = first_bonus("heroStat", "luck")
    if luck:
        params = luck.get("parameters") or []
        crit = first_bonus("unitStat", "critChanceModifier")
        text = f"Army Luck is {signed_bonus_value(params[1] if len(params) > 1 else '0')}."
        if crit:
            crit_params = crit.get("parameters") or []
            text += f" Friendly units have {signed_bonus_value(crit_params[1] if len(crit_params) > 1 else '0', percent=True)} critical chance"
            if isinstance(crit.get("upgrade"), dict):
                upgrade = crit["upgrade"]
                text += f", plus {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
            text += "."
        return text

    mana = first_bonus("heroStat", "manaBonusPercent")
    if mana:
        params = mana.get("parameters") or []
        text = f"Maximum Mana is {signed_bonus_value(params[1] if len(params) > 1 else '0', percent=True)}"
        if isinstance(mana.get("upgrade"), dict):
            upgrade = mana["upgrade"]
            text += f", plus {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
        text += "."
        magic_limit = first_bonus("heroStat", "magicUsageLimitBonus")
        if magic_limit:
            limit_params = magic_limit.get("parameters") or []
            text += f" Spell uses per round are {signed_bonus_value(limit_params[1] if len(limit_params) > 1 else '0')}."
        return text

    spell_power = first_bonus("heroStat", "spellPowerSidSet")
    if spell_power:
        params = spell_power.get("parameters") or []
        spell = humanize_magic_sid(str(params[1])) if len(params) > 1 else "the specialized spell"
        if isinstance(spell_power.get("upgrade"), dict):
            upgrade = spell_power["upgrade"]
            return f"{spell} gets {signed_bonus_value(upgrade.get('increment'))} effective Spell Power per {upgrade.get('levelStep')} hero levels."
        return f"{spell} uses the specialized spell-power override."

    magic_attack = first_bonus("heroStat", "magicAttackPerBonus")
    if magic_attack:
        params = magic_attack.get("parameters") or []
        text = f"Hero spell damage is {signed_bonus_value(params[1] if len(params) > 1 else '0', percent=True)}"
        if isinstance(magic_attack.get("upgrade"), dict):
            upgrade = magic_attack["upgrade"]
            text += f", plus {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
        text += "."
        enemy_magic = first_bonus("heroStatBattle", "magicAttackPerBonus")
        if enemy_magic:
            enemy_params = enemy_magic.get("parameters") or []
            text += f" Enemy hero spell damage is {signed_bonus_value(enemy_params[1] if len(enemy_params) > 1 else '0', percent=True)}"
            if isinstance(enemy_magic.get("upgrade"), dict):
                upgrade = enemy_magic["upgrade"]
                text += f", plus {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
            text += "."
        return text

    tactics = first_bonus("heroStat", "enableTactics")
    if tactics:
        text = "Enables Tactics deployment."
        placement = first_bonus("heroStat", "tacticsPlacementSize")
        if placement:
            placement_params = placement.get("parameters") or []
            text += f" Friendly deployment size is {signed_bonus_value(placement_params[1] if len(placement_params) > 1 else '0')}."
        enemy_placement = first_bonus("heroStatBattle", "tacticsPlacementSize")
        if enemy_placement:
            enemy_params = enemy_placement.get("parameters") or []
            text += f" Enemy deployment size is {signed_bonus_value(enemy_params[1] if len(enemy_params) > 1 else '0')}."
        return text

    modifier_bonuses = [
        bonus
        for bonus in meaningful
        if bonus.get("type") == "unitStat" and (bonus.get("parameters") or [None])[0] == "modifierSet"
    ]
    if modifier_bonuses:
        fragments: list[str] = []
        for bonus in modifier_bonuses:
            params = bonus.get("parameters") or []
            if len(params) < 4:
                continue
            direction = "dealt" if params[1] == "outDmgMods" else "taken"
            damage_type = humanize_damage_modifier_sid(str(params[2]))
            fragment = f"{damage_type} {direction} {signed_bonus_value(params[3], percent=True)}"
            if bonus.get("activationLevel") is not None:
                fragment += f" from hero level {bonus.get('activationLevel')}"
            if isinstance(bonus.get("upgrade"), dict):
                upgrade = bonus["upgrade"]
                fragment += f", plus {signed_bonus_value(upgrade.get('increment'), percent=True)} every {upgrade.get('levelStep')} hero levels"
            fragments.append(fragment)
        if fragments:
            return "Friendly units have " + "; ".join(fragments) + "."

    return None


def normalize_custom_hero_specialization_text_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    rows: list[dict[str, str]] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        spec_name = manifest_core_member(manifest, "heroSpecializations")
        try:
            spec_doc = read_overlay_or_release_json(release_zip, output, spec_name)
        except Exception:
            continue
        spec_rows = spec_doc.get("array") if isinstance(spec_doc, dict) else None
        if not isinstance(spec_rows, list):
            continue
        for row in spec_rows:
            if not isinstance(row, dict):
                continue
            desc = row.get("desc")
            if not isinstance(desc, str) or not desc.endswith("_spec_description"):
                continue
            text = describe_custom_specialization_bonus_row(row)
            if text:
                rows.append({"sid": desc, "text": text})
    if rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroInfo.json", rows, notes)
        notes.append(f"normalize custom hero specialization text ({len(rows)} rows)")


def add_custom_hero_bio_lang_rows_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    bios = load_homm3_source_hero_bios()
    hero_info_doc = read_overlay_or_release_json(release_zip, output, "Lang/english/texts/heroInfo.json")
    hero_info_text: dict[str, str] = {}
    if isinstance(hero_info_doc, dict):
        for token_row in hero_info_doc.get("tokens") or []:
            if isinstance(token_row, dict) and isinstance(token_row.get("sid"), str) and isinstance(token_row.get("text"), str):
                hero_info_text[token_row["sid"]] = token_row["text"]
    rows: list[dict[str, str]] = []
    updated_heroes = 0
    updated_mottos = 0
    missing_bios: list[str] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        count = int((manifest.get("heroes") or {}).get("count") or len(manifest_hero_names(manifest)) or 0)
        if count <= 0:
            continue
        for index in range(1, count + 1):
            hero_sid = manifest_hero_sid(manifest, index)
            description_token = f"{hero_sid}_description"
            motto_token = f"{hero_sid}_motto"
            entry = custom_hero_override_entry(faction_sid, hero_sid)
            override_text = entry.get("descriptionText") if isinstance(entry, dict) else None
            if isinstance(override_text, str) and override_text.strip():
                bio = override_text.strip()
            else:
                hero_name = custom_hero_display_name(manifest, index)
                bio = bios.get(hero_bio_key(hero_name)) if hero_name else None
                if not bio:
                    missing_bios.append(hero_sid)
                    continue
            rows.append({"sid": description_token, "text": bio})

            motto_text = entry.get("mottoText") if isinstance(entry, dict) else None
            if isinstance(motto_text, str) and motto_text.strip():
                rows.append({"sid": motto_token, "text": motto_text.strip()})
            elif not hero_info_text.get(motto_token):
                rows.append({"sid": motto_token, "text": ""})

            member = f"DB/heroes/{faction_sid}/{hero_sid}.json"
            try:
                doc = read_overlay_or_release_json(release_zip, output, member)
            except Exception as ex:
                notes.append(f"warn missing custom hero bio target {member}: {ex}")
                continue
            hero = first_array_item(doc)
            if not isinstance(hero, dict):
                continue
            current = hero.get("description")
            if not isinstance(current, str) or not current.startswith(hero_sid + "_"):
                hero["description"] = description_token
                output[member] = write_json(doc)
                updated_heroes += 1
            current_motto = hero.get("motto")
            if not isinstance(current_motto, str) or not current_motto.startswith(hero_sid + "_"):
                hero["motto"] = motto_token
                output[member] = write_json(doc)
                updated_mottos += 1

    if rows:
        add_lang_overlay_rows(release_zip, output, "Lang/english/texts/heroInfo.json", rows, notes)
        notes.append(f"merge custom hero biography/motto text ({len(rows)} rows, {updated_heroes} description refs, {updated_mottos} motto refs)")
    if missing_bios:
        raise RuntimeError("missing source hero biographies: " + ", ".join(missing_bios))


def add_release_generic_custom_faction_core_rows(
    release_zip: zipfile.ZipFile,
    manifest: dict[str, Any],
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    if not manifest_core_overlay_enabled(manifest):
        return
    faction_sid = manifest["identity"]["factionSid"]
    if faction_sid in DEDICATED_CORE_GENERATOR_FACTION_SIDS:
        return
    identity = manifest["identity"]
    output[manifest_core_member(manifest, "factionJson")] = write_json(make_generic_fraction_doc(release_zip, manifest))
    notes.append(f"generate {faction_sid} generic faction config from {manifest_donor_fraction_sid(manifest)} donor")
    try:
        output[manifest_core_member(manifest, "cityLogic")] = write_json(
            normalize_generic_city_doc(read_json(release_zip, f"DB/objects_logic/cities/{identity['donorCitySid']}.json"), manifest)
        )
        notes.append(f"generate {faction_sid} generic city config from donor")
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append(f"warn missing {faction_sid} city donor: {ex}")
    try:
        output[manifest_core_member(manifest, "lawsTable")] = write_json(make_generic_laws_doc(release_zip, manifest))
        notes.append(f"generate {faction_sid} generic law table")
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        raise RuntimeError(f"{faction_sid}: failed to generate generic law table") from ex
    add_release_generic_units(release_zip, manifest, output, notes)
    add_release_generic_mechanic_support_rows(release_zip, manifest, output, notes)
    add_release_generic_squads(release_zip, manifest, output, notes)
    skill_row = make_generic_skill_row(manifest)
    if skill_row is not None:
        skill_names = ["DB/heroes_skills/skills/skills.json"]
        if faction_sid == "homm3_tower":
            skill_names.append("DB/heroes_skills/skills/skills_arena.json")
        for skill_name in skill_names:
            try:
                skill_doc = json.loads(output[skill_name].decode("utf-8-sig")) if skill_name in output else read_json(release_zip, skill_name)
                if isinstance(skill_doc, dict):
                    changed = upsert_array_row(skill_doc, skill_row)
                    changed = dedupe_array_rows_by_id(skill_doc) or changed
                    if changed:
                        output[skill_name] = write_json(skill_doc)
                        note = f"merge {faction_sid} faction skill " + skill_name
                        if not skill_row.get("xHomm3ImplementedMechanics"):
                            note += " scaffold"
                        notes.append(note)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing {faction_sid} skill target {skill_name}: {ex}")
    if faction_sid == "homm3_rampart":
        ability_bonuses_name = "DB/heroes_abilities/heroes_abilities_bonuses/hero_abilities_bonuses.json"
        try:
            ability_bonuses_doc = json.loads(output[ability_bonuses_name].decode("utf-8-sig")) if ability_bonuses_name in output else read_json(release_zip, ability_bonuses_name)
            if isinstance(ability_bonuses_doc, dict):
                changed = remove_array_rows_by_id(ability_bonuses_doc, {f"{HOMM3_RAMPART_AVENGER_ABILITY_SID}_focus_efficiency_delta"})
                changed = dedupe_array_rows_by_id(ability_bonuses_doc) or changed
                if changed:
                    output[ability_bonuses_name] = write_json(ability_bonuses_doc)
                    notes.append("remove stale homm3_rampart Avenger focus-cost delta")
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing {faction_sid} stale Avenger hero ability delta target: {ex}")

        ability_infos_name = "DB/heroes_abilities/heroes_abilities_infos/hero_abilities_infos.json"
        try:
            ability_infos_doc = json.loads(output[ability_infos_name].decode("utf-8-sig")) if ability_infos_name in output else read_json(release_zip, ability_infos_name)
            if isinstance(ability_infos_doc, dict):
                changed = remove_array_rows_by_id(ability_infos_doc, {HOMM3_RAMPART_AVENGER_FOCUS_EFFICIENCY_INFO_SID})
                changed = dedupe_array_rows_by_id(ability_infos_doc) or changed
                if changed:
                    output[ability_infos_name] = write_json(ability_infos_doc)
                    notes.append("remove stale homm3_rampart Avenger focus-cost info row")
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing {faction_sid} stale Avenger hero ability info target: {ex}")

        subskills_name = "DB/heroes_skills/sub_skills/sub_skills.json"
        try:
            subskills_doc = json.loads(output[subskills_name].decode("utf-8-sig")) if subskills_name in output else read_json(release_zip, subskills_name)
            if isinstance(subskills_doc, dict):
                changed = False
                for row in make_homm3_rampart_avenger_subskills():
                    changed = upsert_array_row(subskills_doc, row) or changed
                changed = dedupe_array_rows_by_id(subskills_doc) or changed
                if changed:
                    output[subskills_name] = write_json(subskills_doc)
                    notes.append("merge homm3_rampart Avenger subskills")
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing {faction_sid} Avenger subskill target: {ex}")
    add_release_generic_map_objects(release_zip, manifest, output, notes)
    add_release_generic_heroes_and_tables(release_zip, manifest, output, notes)
    add_release_generic_lang(release_zip, manifest, output, notes)


def add_release_generic_custom_faction_core_rows_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    for manifest in CUSTOM_FACTION_MANIFESTS:
        add_release_generic_custom_faction_core_rows(release_zip, manifest, output, notes)
    ensure_homm3_custom_town_buildings_construction_preset(release_zip, output, notes)
    ensure_additional_recruitment_buildings_in_construction_presets(release_zip, output, notes)
    ensure_homm3_city_audio_rows_for_all(release_zip, output, notes)


def faction_has_city_music_sidecar(faction_sid: str) -> bool:
    """True when tools/homm3_import/build_out ships `<faction>_city_music` for sidecar playback."""
    if not isinstance(faction_sid, str) or not faction_sid:
        return False
    return (REPO_ROOT / "tools" / "homm3_import" / "build_out" / f"{faction_sid}_city_music").is_file()


def city_music_sound_set_name_for_faction(faction_sid: str) -> str:
    """SessionCity music key used when a faction owns a town-music sidecar.

    Matches the Stronghold pattern (`sounds/city/music/homm3_stronghold`). The retired
    sound-registry inject no longer registers that key into native Resources, so native
    SessionCity stays silent while Homm3StrongholdCityMusic owns playback. Pointing at a
    donor set (human/nature/…) while the sidecar also plays causes overlapping music.
    """
    return f"sounds/city/music/{faction_sid}"


def ensure_homm3_city_audio_rows_for_all(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Register SessionCity music/ambient keys for every core-overlay HoMM3 faction.

    Native SessionCity looks up DB/city_music_sounds.json and DB/city_ambient_sounds.json by
    faction SID. Missing rows produce Player.log Config Error spam and silent city music.

    When a faction-specific `<faction>_city_music` sidecar bundle exists, music rows must
    use `sounds/city/music/<faction_sid>` (Stronghold pattern) — never a vanilla donor set —
    so native donor town music does not layer under Homm3StrongholdCityMusic. Ambient may
    still reuse donor rows. Without a sidecar, donor music is kept so towns are not silent.
    """
    music_name = "DB/city_music_sounds.json"
    ambient_name = "DB/city_ambient_sounds.json"
    try:
        music_doc = read_overlay_or_release_json(release_zip, output, music_name)
        ambient_doc = read_overlay_or_release_json(release_zip, output, ambient_name)
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append(f"warn missing city audio tables: {ex}")
        return

    music_rows = ((music_doc.get("array") or {}).get("data")) if isinstance(music_doc, dict) else None
    ambient_rows = ((ambient_doc.get("array") or {}).get("data")) if isinstance(ambient_doc, dict) else None
    if not isinstance(music_rows, list) or not isinstance(ambient_rows, list):
        notes.append("warn city audio tables missing array.data")
        return

    donor_music = {row.get("key"): row.get("val") for row in music_rows if isinstance(row, dict)}
    donor_ambient = {row.get("key"): row.get("val") for row in ambient_rows if isinstance(row, dict)}
    changed_music = False
    changed_ambient = False
    added: list[str] = []
    sidecar_music_routed: list[str] = []

    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        donor_key = manifest_donor_fraction_sid(manifest)
        music_val = copy.deepcopy(donor_music.get(donor_key) or donor_music.get("human"))
        ambient_val = copy.deepcopy(donor_ambient.get(donor_key) or donor_ambient.get("human"))
        if music_val is None or ambient_val is None:
            notes.append(f"warn missing city audio donor for {faction_sid} (donor={donor_key})")
            continue

        has_sidecar = faction_has_city_music_sidecar(faction_sid)
        if has_sidecar:
            if not isinstance(music_val, dict):
                music_val = {}
            else:
                music_val = copy.deepcopy(music_val)
            music_val["soundSetName"] = city_music_sound_set_name_for_faction(faction_sid)

        existing_music = next((row for row in music_rows if isinstance(row, dict) and row.get("key") == faction_sid), None)
        if existing_music is None:
            music_rows.append({"key": faction_sid, "val": music_val})
            changed_music = True
            added.append(faction_sid)
            if has_sidecar:
                sidecar_music_routed.append(faction_sid)
        else:
            existing_val = existing_music.get("val") if isinstance(existing_music.get("val"), dict) else {}
            existing_set = existing_val.get("soundSetName") if isinstance(existing_val, dict) else None
            desired_set = music_val.get("soundSetName") if isinstance(music_val, dict) else None
            if (
                not isinstance(existing_music.get("val"), dict)
                or not existing_set
                or (has_sidecar and existing_set != desired_set)
            ):
                existing_music["val"] = music_val
                changed_music = True
                if has_sidecar:
                    sidecar_music_routed.append(faction_sid)

        existing_ambient = next((row for row in ambient_rows if isinstance(row, dict) and row.get("key") == faction_sid), None)
        if existing_ambient is None:
            ambient_rows.append({"key": faction_sid, "val": ambient_val})
            changed_ambient = True
        elif not isinstance(existing_ambient.get("val"), dict) or not existing_ambient["val"].get("commonSound"):
            existing_ambient["val"] = ambient_val
            changed_ambient = True

    if changed_music:
        output[music_name] = write_json(music_doc)
    if changed_ambient:
        output[ambient_name] = write_json(ambient_doc)
    if added:
        notes.append("merge city music/ambient rows for " + ", ".join(added))
    elif changed_music or changed_ambient:
        notes.append("refresh city music/ambient rows for core-overlay HoMM3 factions")
    if sidecar_music_routed:
        notes.append(
            "route sidecar town music away from donor sets for "
            + ", ".join(sidecar_music_routed)
        )

def ensure_homm3_custom_town_buildings_construction_preset(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Provide the constructed wall state consumed by native siege setup."""
    target_name = "DB/buildings_constructions/custom_maps_buildings_presets.json"
    general_doc = read_overlay_or_release_json(
        release_zip, output, "DB/buildings_constructions/general_buildings_presets.json"
    )
    custom_doc = read_overlay_or_release_json(release_zip, output, target_name)
    if not isinstance(general_doc, dict) or not isinstance(general_doc.get("array"), list):
        raise RuntimeError("general building construction presets must contain an array")
    if not isinstance(custom_doc, dict) or not isinstance(custom_doc.get("array"), list):
        raise RuntimeError("custom-map building construction presets must contain an array")

    rich_rows = [
        row
        for row in general_doc["array"]
        if isinstance(row, dict) and row.get("id") == "rich_buildings_construction"
    ]
    if len(rich_rows) != 1:
        raise RuntimeError("expected exactly one rich_buildings_construction preset")
    rich_buildings = rich_rows[0].get("buildings")
    if not isinstance(rich_buildings, list):
        raise RuntimeError("rich_buildings_construction must contain a buildings list")
    if len(
        [row for row in rich_buildings if isinstance(row, dict) and row.get("sid") == "Build_Wall"]
    ) != 1:
        raise RuntimeError("rich_buildings_construction must contain exactly one Build_Wall row")

    rows = custom_doc["array"]
    target_rows = [
        row
        for row in rows
        if isinstance(row, dict) and row.get("id") == HOMM3_CUSTOM_TOWN_BUILDINGS_CONSTRUCTION_SID
    ]
    if len(target_rows) > 1:
        raise RuntimeError(
            f"duplicate {HOMM3_CUSTOM_TOWN_BUILDINGS_CONSTRUCTION_SID} construction presets"
        )
    changed = False
    if not target_rows:
        target_row = copy.deepcopy(rich_rows[0])
        target_row["id"] = HOMM3_CUSTOM_TOWN_BUILDINGS_CONSTRUCTION_SID
        rows.append(target_row)
        changed = True
    else:
        target_row = target_rows[0]

    buildings = target_row.get("buildings") if isinstance(target_row, dict) else None
    if not isinstance(buildings, list):
        raise RuntimeError(
            f"{HOMM3_CUSTOM_TOWN_BUILDINGS_CONSTRUCTION_SID} must contain a buildings list"
        )
    wall_rows = [
        row for row in buildings if isinstance(row, dict) and row.get("sid") == "Build_Wall"
    ]
    if len(wall_rows) != 1:
        raise RuntimeError(
            f"{HOMM3_CUSTOM_TOWN_BUILDINGS_CONSTRUCTION_SID} must contain exactly one Build_Wall row"
        )
    wall = wall_rows[0]
    if wall.get("isConstructed") is not True:
        wall["isConstructed"] = True
        changed = True
    if wall.get("level") != 3:
        wall["level"] = 3
        changed = True
    if changed:
        output[target_name] = write_json(custom_doc)
        notes.append(
            "add constructed-wall preset for custom HoMM3 towns: "
            + HOMM3_CUSTOM_TOWN_BUILDINGS_CONSTRUCTION_SID
        )


def ensure_additional_recruitment_buildings_in_construction_presets(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    """Additional city buildings (e.g. Factory Gantry) must appear in construction presets.

    Working unique buildings such as Build_Well_Of_Souls / Build_Mother_Nature are listed in
    every buildings_constructions preset. Factory's Build_Factory_Gantry was only added to the
    city hires list; map load then fails closed with:
    Can't find building: Build_Factory_Gantry in construction config: default_buildings_construction
    """
    # Pin the known Factory additional building for validators / grep contracts.
    _ = "Build_Factory_Gantry"
    required: list[str] = []
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        for line in manifest_additional_recruitment_lines(manifest):
            building_sid = line.get("cityBuildingSid")
            if isinstance(building_sid, str) and building_sid and building_sid not in required:
                required.append(building_sid)
    if not required:
        return

    members = [
        name
        for name in release_zip.namelist()
        if normalize_name(name).startswith("DB/buildings_constructions/")
        and normalize_name(name).endswith(".json")
    ]
    for name in sorted(set(members) | {key for key in output if key.startswith("DB/buildings_constructions/") and key.endswith(".json")}):
        member = normalize_name(name)
        try:
            doc = json.loads(output[member].decode("utf-8-sig")) if member in output else read_json(release_zip, member)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
            notes.append(f"warn missing construction preset {member}: {ex}")
            continue
        if not isinstance(doc, dict) or not isinstance(doc.get("array"), list):
            continue
        changed = False
        for row in doc["array"]:
            if not isinstance(row, dict):
                continue
            buildings = row.get("buildings")
            if not isinstance(buildings, list):
                continue
            existing = {entry.get("sid") for entry in buildings if isinstance(entry, dict)}
            preset_id = str(row.get("id") or "")
            for building_sid in required:
                if building_sid in existing:
                    continue
                # Match working unique-building rows (e.g. Build_Well_Of_Souls).
                buildings.append(
                    {
                        "sid": building_sid,
                        "isConstructed": preset_id == "full_buildings_construction",
                        "level": 1,
                    }
                )
                existing.add(building_sid)
                changed = True
        if changed:
            output[member] = write_json(doc)
            notes.append(
                "merge additional recruitment buildings into construction presets: "
                + ", ".join(required)
                + f" ({member})"
            )


def normalize_custom_faction_native_biomes(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    changed_units = 0
    changed_heroes = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        biome = manifest_release_scaffold(manifest)["biome"]
        for custom_sid in manifest_unit_sids(manifest):
            member = f"DB/units/units_logics/{faction_sid}/{custom_sid}_l.json"
            try:
                doc = json.loads(output[member].decode("utf-8-sig")) if member in output else read_json(release_zip, member)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing native-biome unit row {member}: {ex}")
                continue
            item = first_array_item(doc)
            if isinstance(item, dict) and item.get("nativeBiome") != biome:
                item["nativeBiome"] = biome
                output[member] = write_json(doc)
                changed_units += 1

        heroes = manifest.get("heroes") or {}
        hero_count = heroes.get("count")
        if not isinstance(hero_count, int):
            continue
        for index in range(1, hero_count + 1):
            hero_sid = manifest_hero_sid(manifest, index)
            member = f"DB/heroes/{faction_sid}/{hero_sid}.json"
            try:
                doc = json.loads(output[member].decode("utf-8-sig")) if member in output else read_json(release_zip, member)
            except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
                notes.append(f"warn missing native-biome hero row {member}: {ex}")
                continue
            item = first_array_item(doc)
            if isinstance(item, dict) and item.get("nativeBiome") != biome:
                item["nativeBiome"] = biome
                output[member] = write_json(doc)
                changed_heroes += 1
    if changed_units or changed_heroes:
        notes.append(f"normalize custom faction nativeBiome rows ({changed_units} units, {changed_heroes} heroes)")


def add_release_fortress_core_rows(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    manifest = load_custom_faction_manifest("homm3_fortress")
    identity = manifest["identity"]
    output[manifest_core_member(manifest, "factionJson")] = write_json(make_fortress_fraction_doc(release_zip, manifest))
    notes.append("generate Fortress faction config from Nature donor")
    try:
        output[manifest_core_member(manifest, "cityLogic")] = write_json(
            normalize_fortress_city_doc(read_json(release_zip, f"DB/objects_logic/cities/{identity['donorCitySid']}.json"), manifest)
        )
        notes.append("generate Fortress city config from Nature donor")
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append("warn missing Fortress city donor: " + str(ex))
    try:
        output[manifest_core_member(manifest, "lawsTable")] = write_json(make_fortress_laws_doc(release_zip, manifest))
        notes.append("generate Fortress law table from Nature donor")
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append("warn missing Fortress laws donor: " + str(ex))
    add_release_fortress_units(release_zip, output, notes)
    add_release_fortress_squads(release_zip, output, notes)
    skill_name = "DB/heroes_skills/skills/skills.json"
    try:
        skill_doc = json.loads(output[skill_name].decode("utf-8-sig")) if skill_name in output else read_json(release_zip, skill_name)
        if isinstance(skill_doc, dict):
            changed = upsert_array_row(skill_doc, make_fortress_skill_row(manifest))
            changed = dedupe_array_rows_by_id(skill_doc) or changed
            if changed:
                output[skill_name] = write_json(skill_doc)
                notes.append("merge Fortress Hunting Grounds faction skill")
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append("warn missing Fortress skill target: " + str(ex))
    subskills_name = "DB/heroes_skills/sub_skills/sub_skills.json"
    try:
        subskills_doc = json.loads(output[subskills_name].decode("utf-8-sig")) if subskills_name in output else read_json(release_zip, subskills_name)
        if isinstance(subskills_doc, dict):
            changed = False
            for row in make_fortress_swamp_tactics_subskills(manifest):
                changed = upsert_array_row(subskills_doc, row) or changed
            changed = dedupe_array_rows_by_id(subskills_doc) or changed
            if changed:
                output[subskills_name] = write_json(subskills_doc)
                notes.append("merge Fortress Hunting Grounds subskills")
    except (json.JSONDecodeError, UnicodeDecodeError, KeyError) as ex:
        notes.append("warn missing Fortress subskill target: " + str(ex))
    hero_buffs_doc = read_overlay_or_release_json(release_zip, output, HOMM3_FORTRESS_HUNTING_GROUNDS_HERO_BUFFS_PATH)
    if not isinstance(hero_buffs_doc, dict) or not isinstance(hero_buffs_doc.get("array"), list):
        raise RuntimeError(f"malformed Fortress Hunting Grounds hero buff target {HOMM3_FORTRESS_HUNTING_GROUNDS_HERO_BUFFS_PATH}")
    changed = False
    for row in make_fortress_hunting_grounds_hero_buff_rows():
        changed = upsert_array_row(hero_buffs_doc, row) or changed
    changed = dedupe_array_rows_by_id(hero_buffs_doc) or changed
    if changed:
        output[HOMM3_FORTRESS_HUNTING_GROUNDS_HERO_BUFFS_PATH] = write_json(hero_buffs_doc)
        notes.append("merge Fortress Hunting Grounds trophy hero buffs")
    add_release_fortress_map_objects(release_zip, output, notes)
    add_release_fortress_heroes_and_tables(release_zip, output, notes)
    add_release_fortress_lang(release_zip, output, notes)


def strip_nonfinal_no_compromise_law_bonuses_from_node(
    node: Any,
    targets_by_sid: dict[str, dict[str, Any]],
    stripped_sids: set[str],
) -> int:
    changed_rows = 0
    if isinstance(node, dict):
        sid = node.get("id")
        target = targets_by_sid.get(sid) if isinstance(sid, str) else None
        if isinstance(target, dict) and target.get("implementationStatus") in STRICT_NO_COMPROMISE_NONFINAL_STATUSES:
            row_changed = False
            levels = node.get("parametersPerLevel")
            if isinstance(levels, list):
                for level in levels:
                    if not isinstance(level, dict):
                        continue
                    bonuses = level.get("bonuses")
                    if isinstance(bonuses, list) and bonuses:
                        level["bonuses"] = []
                        row_changed = True
            if row_changed:
                node["xHomm3NoCompromiseStrictRows"] = "concrete bonuses stripped; pending native-exact or packet-backed implementation"
                stripped_sids.add(sid)
                changed_rows += 1
        for value in node.values():
            changed_rows += strip_nonfinal_no_compromise_law_bonuses_from_node(value, targets_by_sid, stripped_sids)
    elif isinstance(node, list):
        for item in node:
            changed_rows += strip_nonfinal_no_compromise_law_bonuses_from_node(item, targets_by_sid, stripped_sids)
    return changed_rows


def strict_no_compromise_pending_description(target: dict[str, Any]) -> str:
    packet = target.get("packet")
    mechanic = target.get("targetMechanic")
    if not isinstance(packet, str) or not packet:
        raise RuntimeError(f"strict stripped law target is missing packet: {target.get('lawSid')}")
    if not isinstance(mechanic, str) or not mechanic.strip():
        raise RuntimeError(f"strict stripped law target is missing targetMechanic: {target.get('lawSid')}")
    return (
        "Pending no-compromise implementation. "
        f"Target mechanic: {mechanic.strip()} "
        f"This strict candidate row has no gameplay effect until the {packet} packet is runtime-proven and implemented."
    )


def update_strict_no_compromise_law_lang_rows(
    output: dict[str, bytes],
    stripped_sids: set[str],
    targets_by_sid: dict[str, dict[str, Any]],
) -> int:
    if not stripped_sids:
        return 0
    target_name = "Lang/english/texts/factionLaws.json"
    if target_name not in output:
        raise RuntimeError(f"strict strip expected generated law language member: {target_name}")
    try:
        doc = json.loads(output[target_name].decode("utf-8-sig"))
    except (UnicodeDecodeError, json.JSONDecodeError) as ex:
        raise RuntimeError(f"cannot inspect generated law language JSON for strict strip: {target_name}: {ex}") from ex
    rows = [
        {"sid": f"{sid}_desc", "text": strict_no_compromise_pending_description(targets_by_sid[sid])}
        for sid in sorted(stripped_sids)
    ]
    if upsert_lang_rows(doc, rows):
        output[target_name] = write_json(doc)
    return len(rows)


def strip_nonfinal_no_compromise_law_bonuses_from_overlay(output: dict[str, bytes], notes: list[str]) -> None:
    try:
        with CUSTOM_LAW_TARGETS_PATH.open("r", encoding="utf-8-sig") as target_file:
            targets_doc = json.load(target_file)
    except Exception as ex:
        raise RuntimeError(f"cannot load no-compromise law targets for strict strip: {CUSTOM_LAW_TARGETS_PATH}: {ex}") from ex
    targets = targets_doc.get("targets") if isinstance(targets_doc, dict) else None
    if not isinstance(targets, list):
        raise RuntimeError(f"no-compromise law target file has no targets list: {CUSTOM_LAW_TARGETS_PATH}")
    families = targets_doc.get("families") if isinstance(targets_doc, dict) else None
    if not isinstance(families, dict):
        raise RuntimeError(f"no-compromise law target file has no families object: {CUSTOM_LAW_TARGETS_PATH}")
    targets_by_sid: dict[str, dict[str, Any]] = {}
    for item in targets:
        if not isinstance(item, dict) or not isinstance(item.get("lawSid"), str):
            continue
        law_index = item.get("lawIndex")
        family = families.get(str(law_index)) if isinstance(law_index, int) else None
        if not isinstance(family, dict) or not isinstance(family.get("packet"), str):
            raise RuntimeError(f"no-compromise law target is missing family packet: {item.get('lawSid')}")
        target = dict(item)
        target["packet"] = family["packet"]
        targets_by_sid[target["lawSid"]] = target
    changed_members = 0
    changed_rows = 0
    stripped_sids: set[str] = set()
    for member, data in list(output.items()):
        lowered = member.lower()
        if not lowered.endswith(".json") or "law" not in lowered:
            continue
        try:
            doc = json.loads(data.decode("utf-8-sig"))
        except (UnicodeDecodeError, json.JSONDecodeError) as ex:
            raise RuntimeError(f"cannot inspect generated law JSON for strict strip: {member}: {ex}") from ex
        member_changed_rows = strip_nonfinal_no_compromise_law_bonuses_from_node(doc, targets_by_sid, stripped_sids)
        if member_changed_rows:
            output[member] = write_json(doc)
            changed_members += 1
            changed_rows += member_changed_rows
    changed_lang_rows = update_strict_no_compromise_law_lang_rows(output, stripped_sids, targets_by_sid)
    notes.append(
        "strict no-compromise law row strip "
        f"removed concrete bonuses from {changed_rows} non-final row(s) in {changed_members} Core member(s) "
        f"and rewrote {changed_lang_rows} law description token(s) as pending"
    )


def normalize_primal_magic_tiers(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    member = "DB/magics/battle_primal_magics.json"
    doc = json.loads(output[member].decode("utf-8-sig")) if member in output else read_json(release_zip, member)
    if not isinstance(doc, dict) or not isinstance(doc.get("array"), list):
        raise RuntimeError(f"malformed Primal magic tier table {member}")
    changed = False
    for row in doc["array"]:
        if isinstance(row, dict) and row.get("id") == "primal_3_magic_wean":
            if row.get("rank") != 1:
                row["rank"] = 1
                changed = True
            break
    else:
        raise RuntimeError("missing vanilla Primal spell primal_3_magic_wean")
    if changed:
        output[member] = write_json(doc)
        notes.append("normalize vanilla Primal Magic tier contract: Wean is tier 1")

def build_overlay(
    release_core: Path,
    strip_nonfinal_no_compromise_law_bonuses: bool = False,
    law_override_dir: Path = LAW_OVERRIDE_DIR,
) -> tuple[dict[str, bytes], list[str]]:
    global _ACTIVE_LAW_OVERRIDE_DIR
    previous_law_override_dir = _ACTIVE_LAW_OVERRIDE_DIR
    _ACTIVE_LAW_OVERRIDE_DIR = law_override_dir
    output: dict[str, bytes] = {}
    notes: list[str] = []

    try:
        if law_override_dir != LAW_OVERRIDE_DIR:
            notes.append(f"using law override directory {law_override_dir.relative_to(REPO_ROOT)}")

        with zipfile.ZipFile(release_core) as release_zip:
            data_member = "DB/data.json"
            output[data_member] = write_json(merge_data_json(read_json(release_zip, data_member)))
            notes.append("merge core-enabled custom factions into DB/data.json")
            add_release_fortress_core_rows(release_zip, output, notes)
            add_release_castle_core_rows(release_zip, output, notes)
            add_release_generic_custom_faction_core_rows_for_all(release_zip, output, notes)
            normalize_primal_magic_tiers(release_zip, output, notes)
            add_custom_masterful_magic_variants(release_zip, output, notes)
            add_custom_law_visual_marker_buffs(release_zip, output, notes)
            add_custom_hero_specializations_for_all(output, notes)
            normalize_release_tower_unit_views(release_zip, output, notes)
            apply_strong_vanilla_mechanics_to_custom_unit_rows(release_zip, output, notes)
            apply_custom_ability_overrides_to_custom_unit_rows(release_zip, output, notes)
            normalize_custom_unit_logic_redundant_flags(release_zip, output, notes)
            normalize_custom_unit_view_map_meshes(release_zip, output, notes)
            normalize_custom_unit_view_unsafe_donor_meshes(release_zip, output, notes)
            normalize_cyclops_shooter_battle_shells(release_zip, output, notes)
            normalize_custom_unit_view_skinned_preview_meshes(release_zip, output, notes)
            apply_vanilla_death_fade_to_custom_unit_views(release_zip, output, notes)
            prune_release_tower_unimplemented_passive_cards(release_zip, output, notes)
            ensure_custom_unit_view_icons_for_all(release_zip, output, notes)
            add_strong_vanilla_ability_lang_rows(release_zip, output, notes)
            add_custom_hero_specialization_lang_rows_for_all(release_zip, output, notes)
            add_custom_external_dwelling_creature_lang_rows_for_all(release_zip, output, notes)
            add_city_building_mechanics_lang_rows_for_all(release_zip, output, notes)
            stamp_source_mechanics_on_custom_city_rows(release_zip, output, notes)
            apply_custom_hero_overrides(release_zip, output, notes)
            ensure_manifest_hero_display_name_lang_for_all(release_zip, output, notes)
            apply_masterful_hero_specialization_assignments(release_zip, output, notes)
            add_custom_hero_bio_lang_rows_for_all(release_zip, output, notes)
            normalize_custom_hero_specialization_text_for_all(release_zip, output, notes)
            normalize_custom_faction_native_biomes(release_zip, output, notes)
            # Neutrals clone their donor's view row from the pending output, so the
            # donors' normalized moveSpeed must already be written; otherwise a
            # neutral inherits the donor's raw speed on a vanilla Core and the
            # previous install's normalized speed on an installed one. Only the
            # donors: the neutral rows themselves do not exist yet on vanilla.
            normalize_custom_unit_view_move_speeds(
                release_zip, output, notes, only_sids=homm3_neutral_donor_unit_sids()
            )
            # Neutrals + landon loc must land in English tokens before multilingual
            # sync, otherwise land-on visits resolve blank title/description.
            add_homm3_neutral_core_overlay(
                release_zip,
                output,
                notes,
                faction_unit_sids=CORE_ENABLED_GAME_UNIT_SIDS,
                import_view_meshes=load_homm3_import_skinned_preview_meshes(),
            )
            apply_homm3_neutral_oe_kits(release_zip, output, notes)
            # After the neutral rows: they rewrite neutral view rows (moveSpeed included) from their own catalog.
            normalize_custom_unit_view_move_speeds(release_zip, output, notes)
            # After every city-row mutation that feeds tooltip text, before multilingual sync.
            apply_homm3_city_building_descriptions(release_zip, output, notes)
            mirror_landon_barracks_lang_rows(
                release_zip,
                output,
                notes,
                read_json,
                write_json,
                upsert_lang_rows,
            )
            add_homm3_stronghold_warcries_lang_rows(release_zip, output, notes)
            add_homm3_missing_custom_lang_rows(release_zip, output, notes)
            sync_multilingual_custom_lang_rows(release_zip, output, notes, read_json, write_json, upsert_lang_rows)
            # Prefer donor-locale text for any landon keys still missing after sync.
            mirror_landon_barracks_lang_rows(
                release_zip,
                output,
                notes,
                read_json,
                write_json,
                upsert_lang_rows,
            )
            # After sync: the derived city building rows own their 15 locale translations.
            apply_homm3_city_building_description_locales(release_zip, output, notes)
            clean_multilingual_custom_ability_debt_text(release_zip, output, notes)
            add_custom_active_ability_localization_rows(release_zip, output, notes)
            stamp_source_mechanics_on_custom_faction_skill_rows(release_zip, output, notes)
            add_custom_law_visual_marker_buffs(release_zip, output, notes)
            apply_homm3_unit_balance_adjustments_to_output(release_zip, output, notes)
            assign_homm3_battle_ai_types(release_zip, output, notes)
            assign_homm3_attack_animation_slots(output, notes)
            # After every unit logic row (incl. balance squadValue) is final:
            # native Pandora/chest unit boxes only draw from reward_units_container.
            add_custom_faction_reward_units(
                release_zip, output, notes, CORE_ENABLED_FACTION_SIDS, write_json
            )
            normalize_homm3_town_city_bottom_center_gates(release_zip, output, notes)
            merge_homm3_artifacts_into_overlay(release_zip, output, notes)
            refresh_homm3_derived_city_docs(release_zip, output, notes)
            # Last Lang writer: after the artifact English rows and after multilingual
            # sync, so translations win over sync drafts and English fallbacks.
            add_custom_lang_translations(release_zip, output, notes)

        if strip_nonfinal_no_compromise_law_bonuses:
            strip_nonfinal_no_compromise_law_bonuses_from_overlay(output, notes)
    finally:
        _ACTIVE_LAW_OVERRIDE_DIR = previous_law_override_dir

    return output, notes


