def run_custom_faction_validation(stage: str, core: Path | None = None) -> None:
    cmd = [sys.executable, str(CUSTOM_FACTION_VALIDATOR)]
    if core is not None:
        cmd += ["--core", str(core)]
        cmd += ["--neutral-band-target", GAME_TARGET]
        cmd += ["--source-mechanics-dir", str(SOURCE_MECHANICS_DIR)]
        cmd += ["--no-design-debt"]
    print("Running custom faction validation (" + stage + ")...", flush=True)
    try:
        result = subprocess.run(cmd, cwd=REPO_ROOT, timeout=VALIDATION_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired as ex:
        raise RuntimeError(
            f"custom faction validation timed out during {stage} after {VALIDATION_TIMEOUT_SECONDS}s"
        ) from ex
    if result.returncode != 0:
        raise RuntimeError("custom faction validation failed during " + stage)


