def run_custom_biome_pack(core: Path, out_dir: Path) -> dict[str, Any]:
    cmd = [
        sys.executable,
        str(CUSTOM_BIOME_PACKER),
        "--core",
        str(core),
        "--out-dir",
        str(out_dir),
        "--clean",
    ]
    log_overlay_phase("custom biome pack start")
    try:
        result = subprocess.run(
            cmd,
            cwd=REPO_ROOT,
            timeout=BIOME_PACK_TIMEOUT_SECONDS,
            capture_output=True,
            text=True,
        )
    except subprocess.TimeoutExpired as ex:
        raise RuntimeError(f"custom biome pack timed out after {BIOME_PACK_TIMEOUT_SECONDS}s") from ex
    if result.returncode != 0:
        if result.stdout.strip():
            print(result.stdout, flush=True)
        if result.stderr.strip():
            print(result.stderr, file=sys.stderr, flush=True)
        raise RuntimeError("custom biome pack failed")
    report_path = out_dir / "custom_biome_pack_report.json"
    if not report_path.is_file():
        raise RuntimeError(f"custom biome pack did not write report: {report_path}")
    log_overlay_phase("custom biome pack complete")
    return json.loads(report_path.read_text(encoding="utf-8-sig"))


def stamp_source_mechanics_on_custom_city_rows(release_zip: zipfile.ZipFile, output: dict[str, bytes], notes: list[str]) -> None:
    changed = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        overlay = manifest.get("coreOverlay") or {}
        member = overlay.get("cityLogic")
        if not isinstance(member, str):
            continue
        try:
            if member in output:
                doc = json.loads(output[member].decode("utf-8-sig"))
            else:
                doc = read_json(release_zip, member)
        except (json.JSONDecodeError, UnicodeDecodeError, KeyError):
            continue
        before = json.dumps(doc, sort_keys=True, ensure_ascii=False)
        stamp_city_building_source_mechanics_metadata(doc, manifest)
        after = json.dumps(doc, sort_keys=True, ensure_ascii=False)
        if after != before:
            output[member] = write_json(doc)
            changed += 1
    if changed:
        notes.append(f"stamp source mechanics metadata on custom city rows ({changed})")


def stamp_source_mechanics_on_custom_faction_skill_rows(
    release_zip: zipfile.ZipFile,
    output: dict[str, bytes],
    notes: list[str],
) -> None:
    skill_name = "DB/heroes_skills/skills/skills.json"
    try:
        skill_doc = read_overlay_or_release_json(release_zip, output, skill_name)
    except Exception:
        return
    rows = skill_doc.get("array") if isinstance(skill_doc, dict) else None
    if not isinstance(rows, list):
        return
    changed = 0
    for manifest in CUSTOM_FACTION_MANIFESTS:
        if not manifest_core_overlay_enabled(manifest):
            continue
        faction_sid = manifest["identity"]["factionSid"]
        skill_sid = manifest_faction_skill_sid(manifest)
        source_mechanic = source_mechanic_for_surface_row(faction_sid, "faction_skill", skill_sid)
        if source_mechanic is None:
            continue
        row = next((item for item in rows if isinstance(item, dict) and item.get("id") == skill_sid), None)
        if not isinstance(row, dict):
            continue
        before = (row.get("xHomm3SourceMechanic"), row.get("xHomm3MechanicsStatus"))
        row["xHomm3SourceMechanic"] = source_mechanic.get("id")
        row["xHomm3MechanicsStatus"] = source_mechanic.get("status")
        after = (row.get("xHomm3SourceMechanic"), row.get("xHomm3MechanicsStatus"))
        if after != before:
            changed += 1
    if changed:
        output[skill_name] = write_json(skill_doc)
        notes.append(f"stamp source mechanics metadata on custom faction skill rows ({changed})")


DEFAULT_OVERLAY_WORK_DIR = REPO_ROOT / "artifacts" / "core_overlay_work"
# rewrite_zip() deletes the work directory before every run, so it must be a
# dedicated overlay scratch folder: the historical default under artifacts/,
# or an explicit caller directory named *core_overlay_work* that is not inside
# any Steam game install (tools/port_current/rebuild_core_from_vanilla.py).
OVERLAY_WORK_DIR_NAME_TOKEN = "core_overlay_work"


def require_safe_overlay_work_dir(work_dir: Path) -> Path:
    work_dir = work_dir.resolve()
    artifacts_dir = (REPO_ROOT / "artifacts").resolve()
    if work_dir == DEFAULT_OVERLAY_WORK_DIR.resolve() and artifacts_dir in work_dir.parents:
        return work_dir
    if OVERLAY_WORK_DIR_NAME_TOKEN not in work_dir.name:
        raise RuntimeError(
            f"refusing unsafe overlay work directory {work_dir}: an explicit --work-dir is deleted "
            f"before use, so its folder name must contain '{OVERLAY_WORK_DIR_NAME_TOKEN}'"
        )
    lowered = str(work_dir).replace("\\", "/").lower()
    if "steamapps/common/" in lowered:
        raise RuntimeError(f"refusing overlay work directory inside a Steam game install: {work_dir}")
    if work_dir == REPO_ROOT.resolve() or work_dir in REPO_ROOT.resolve().parents:
        raise RuntimeError(f"refusing overlay work directory that contains the repo: {work_dir}")
    return work_dir


def require_existing_path(label: str, path: Path, is_dir: bool = False) -> None:
    exists = path.is_dir() if is_dir else path.is_file()
    if not exists:
        kind = "directory" if is_dir else "file"
        raise RuntimeError(f"{label} {kind} does not exist: {path}")


def rewrite_zip(
    release_core: Path,
    overlay: dict[str, bytes],
    dry_run: bool,
    validate_law_core_metadata: bool,
    strict_no_compromise_law_rows: bool,
    work_dir: Path = DEFAULT_OVERLAY_WORK_DIR,
) -> Path | None:
    drop_members = STALE_RELEASE_MEMBERS_TO_DROP | removed_custom_hero_members()
    work_dir = require_safe_overlay_work_dir(work_dir)
    release_core = release_core.resolve()
    if release_core == work_dir or work_dir in release_core.parents:
        raise RuntimeError(f"refusing to use release Core inside overlay work directory: {release_core}")
    if work_dir.exists():
        shutil.rmtree(work_dir)
    work_dir.mkdir(parents=True, exist_ok=True)
    tmp_zip = work_dir / release_core.name
    log_overlay_phase(f"candidate Core.zip write start ({len(overlay)} overlay member(s))")
    with zipfile.ZipFile(release_core, "r") as src, zipfile.ZipFile(
        tmp_zip, "w", compression=zipfile.ZIP_DEFLATED
    ) as dst:
        written = set()
        for info in src.infolist():
            name = normalize_name(info.filename)
            if name in drop_members:
                continue
            if info.is_dir():
                dst.writestr(info, b"")
                continue
            if name in overlay:
                dst.writestr(name, overlay[name])
            else:
                dst.writestr(info, src.read(info.filename))
            written.add(name)

        for name, data in sorted(overlay.items()):
            if name not in written:
                dst.writestr(name, data)
    log_overlay_phase("candidate Core.zip write complete")

    biome_report = run_custom_biome_pack(tmp_zip, work_dir / "custom-biome-pack")
    tmp_zip = Path(str(biome_report["outputCore"]))
    if validate_law_core_metadata:
        run_custom_law_core_metadata_validation("candidate Core.zip", tmp_zip)
    if strict_no_compromise_law_rows:
        run_custom_law_strict_row_validation("candidate Core.zip", tmp_zip)
    log_overlay_phase("candidate validation start")
    run_custom_faction_validation("candidate Core.zip", tmp_zip)
    run_homm3_attack_animation_slot_validation("candidate Core.zip", tmp_zip)
    run_city_construction_tree_layout_validation("candidate Core.zip", tmp_zip)
    log_overlay_phase("candidate validation complete")
    if dry_run:
        return None

    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = release_core.with_name(release_core.name + ".backup-" + timestamp)
    log_overlay_phase("backup start")
    shutil.copy2(release_core, backup)
    log_overlay_phase("replace release Core.zip start")
    shutil.move(str(tmp_zip), release_core)
    log_overlay_phase("replace release Core.zip complete")

    return backup


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def deploy_custom_biome_runtime_assets(
    source_plugin_root: Path,
    target_plugin_root: Path,
    dry_run: bool,
) -> list[str]:
    notes: list[str] = []
    for folder_name, label in (
        ("homm3_runtime_assets/custom_biomes", "HoMM3 custom biome runtime assets"),
        ("homm3_runtime_assets/terrain_tint_proofs", "HoMM3 terrain tint proof runtime assets"),
    ):
        notes.extend(
            deploy_plugin_asset_folder(
                source_plugin_root=source_plugin_root,
                target_plugin_root=target_plugin_root,
                folder_name=folder_name,
                label=label,
                dry_run=dry_run,
            )
        )
    return notes

def deploy_plugin_asset_folder(
    source_plugin_root: Path,
    target_plugin_root: Path,
    folder_name: str,
    label: str,
    dry_run: bool,
) -> list[str]:
    src = (source_plugin_root / folder_name).resolve()
    dst = (target_plugin_root / folder_name).resolve()
    require_existing_path(f"source {label}", src, is_dir=True)
    require_existing_path("target OfflineUnlockMod plugin root", target_plugin_root, is_dir=True)
    if src == dst:
        raise RuntimeError(f"refusing to deploy {label} onto itself: {src}")

    notes: list[str] = []
    if dry_run:
        notes.append(f"dry-run skip deploy {src} -> {dst}")
        return notes

    shutil.copytree(src, dst, dirs_exist_ok=True)

    source_files = sorted(path for path in src.rglob("*") if path.is_file())
    if not source_files:
        raise RuntimeError(f"source {label} folder is empty: {src}")

    for source_path in source_files:
        rel = source_path.relative_to(src)
        target_path = dst / rel
        if not target_path.is_file():
            raise RuntimeError(f"{label} deploy missing target file: {target_path}")
        if file_sha256(source_path) != file_sha256(target_path):
            raise RuntimeError(
                f"{label} deploy hash mismatch for "
                f"{rel}: source={source_path} target={target_path}"
            )

    notes.append(
        f"deploy {label} {src} -> {dst} "
        f"({len(source_files)} file(s), hash-verified)"
    )
    return notes


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--release-core", type=Path, default=DEFAULT_RELEASE_CORE)
    parser.add_argument("--source-plugin-root", type=Path, default=DEFAULT_SOURCE_PLUGIN_ROOT)
    parser.add_argument("--release-plugin-root", type=Path, default=None)
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument(
        "--game-target",
        choices=GAME_TARGETS,
        default="golden_era",
        help=(
            "Game build --release-core belongs to. Selects target-pinned Core readbacks (native neutral "
            "tier bands). Default golden_era (the active modded install); the port rebuild passes "
            "steam_25672315."
        ),
    )
    parser.add_argument(
        "--work-dir",
        type=Path,
        default=DEFAULT_OVERLAY_WORK_DIR,
        help=(
            "Candidate Core.zip scratch directory (deleted before each run). Default "
            "artifacts/core_overlay_work; an explicit directory must be named *core_overlay_work* "
            "and must not sit inside a Steam game install."
        ),
    )
    parser.add_argument(
        "--require-no-compromise-law-static",
        action="store_true",
        help=(
            "Run tools/release_port/check_custom_law_no_compromise_static.py before building overlay output. "
            "This is a fail-closed static law hygiene gate only; it does not prove runtime behavior."
        ),
    )
    parser.add_argument(
        "--validate-no-compromise-law-core-metadata",
        action="store_true",
        help=(
            "After writing the candidate Core.zip and applying custom biome packing, validate that generated "
            "custom law rows carry xHomm3NoCompromise* metadata from custom_law_targets.json. This is "
            "traceability validation only; it does not prove law behavior or runtime packet readiness."
        ),
    )
    parser.add_argument(
        "--strict-no-compromise-law-rows",
        action="store_true",
        help=(
            "Fail if non-native-exact no-compromise target laws still carry concrete source or candidate "
            "Core bonuses. This is intended for strict candidate work and is expected to fail while "
            "temporary donor compromises remain."
        ),
    )
    parser.add_argument(
        "--strip-nonfinal-no-compromise-law-bonuses",
        action="store_true",
        help=(
            "For strict candidate overlays, remove concrete bonuses from generated non-native-exact target law "
            "rows and stamp them as pending native-exact or packet-backed implementation. This preserves the "
            "playable source overrides but prevents donor effects from surviving in the strict candidate Core."
        ),
    )
    parser.add_argument(
        "--use-strict-no-compromise-law-overrides",
        action="store_true",
        help=(
            "Build the overlay from artifacts/custom_law_static/strict_law_overrides instead of the playable "
            "custom_factions/law_overrides source. This is an explicit strict candidate mode: it keeps "
            "non-native-exact target rows pending/no-effect and automatically validates source and candidate rows. "
            "It does not prove runtime behavior or promote packet gameplay."
        ),
    )
    return parser.parse_args()


def main() -> int:
    global GAME_TARGET
    args = parse_args()
    GAME_TARGET = args.game_target
    print(f"Game target: {GAME_TARGET}", flush=True)
    release_core = args.release_core.resolve()
    source_plugin_root = args.source_plugin_root.resolve()
    release_plugin_root = (
        args.release_plugin_root.resolve()
        if args.release_plugin_root is not None
        else release_core.parents[2] / "BepInEx" / "plugins" / "OfflineUnlockMod"
    )
    law_override_dir = STRICT_LAW_OVERRIDE_DIR if args.use_strict_no_compromise_law_overrides else LAW_OVERRIDE_DIR
    strict_law_row_validation = (
        args.strict_no_compromise_law_rows
        or args.strip_nonfinal_no_compromise_law_bonuses
        or args.use_strict_no_compromise_law_overrides
    )
    try:
        require_existing_path("release Core", release_core)
        require_existing_path("source plugin root", source_plugin_root, is_dir=True)
        if args.use_strict_no_compromise_law_overrides:
            require_existing_path("strict no-compromise law override directory", law_override_dir, is_dir=True)
        run_custom_faction_validation("source manifests and plugin payload")
        if args.require_no_compromise_law_static:
            run_custom_law_no_compromise_static_check("source no-compromise law preflight")
        if args.use_strict_no_compromise_law_overrides or (
            args.strict_no_compromise_law_rows and not args.strip_nonfinal_no_compromise_law_bonuses
        ):
            run_custom_law_strict_row_validation("source law overrides", override_dir=law_override_dir)
        overlay, notes = build_overlay(
            release_core,
            args.strip_nonfinal_no_compromise_law_bonuses,
            law_override_dir=law_override_dir,
        )
        print(f"Prepared {len(overlay)} Core.zip member update(s).")
        for note in notes[:120]:
            print(note)
        if len(notes) > 120:
            print(f"... {len(notes) - 120} more")

        backup = rewrite_zip(
            release_core,
            overlay,
            args.dry_run,
            args.validate_no_compromise_law_core_metadata,
            strict_law_row_validation,
            work_dir=args.work_dir,
        )
        if args.dry_run:
            print("Dry run only; Core.zip was not modified.")
        else:
            deploy_notes = deploy_custom_biome_runtime_assets(
                source_plugin_root=source_plugin_root,
                target_plugin_root=release_plugin_root,
                dry_run=False,
            )
            deploy_notes.extend(
                deploy_plugin_asset_folder(
                    source_plugin_root=source_plugin_root,
                    target_plugin_root=release_plugin_root,
                    folder_name="homm3_law_icons",
                    label="HoMM3 custom law icons",
                    dry_run=False,
                )
            )
            deploy_notes.extend(
                deploy_plugin_asset_folder(
                    source_plugin_root=source_plugin_root,
                    target_plugin_root=release_plugin_root,
                    folder_name="homm3_runtime_assets/artifacts",
                    label="HoMM3 artifact icons and map frames",
                    dry_run=False,
                )
            )
            for note in deploy_notes:
                print(note)
            print(f"Updated {release_core}")
            print(f"Backup: {backup}")
            run_custom_faction_validation("updated release Core.zip", release_core)
            run_custom_faction_reward_units_validation(release_core)
            run_homm3_attack_animation_slot_validation("updated release Core.zip", release_core)
            run_city_construction_tree_layout_validation("updated release Core.zip", release_core)
        return 0
    except RuntimeError as ex:
        print("ERROR: " + str(ex))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
